INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-01-heuer-psychology-p206-3', 'doc-01-heuer-psychology', '', 206, 'More training time should be devoted to the thinking and reason - ing processes involved in making intelligence judgments, and to the tools of the trade that are available to alleviate or compensate for the known cognitive problems encountered in analysis. Tis book is intended to support such training.', 'kb-doc-01-heuer-psychology-p206-3', 1, 49, '01-heuer-psychology', 'retrieved', '051C15E82106FEFB453E475A477FE1B83ADD5920F33C80AC955DE6907F619468', 'v1', '{"source_id": "01-heuer-psychology", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-01-heuer-psychology-p206-4', 'doc-01-heuer-psychology', '', 206, 'T raining will be more efective if supplemented with ongoing ad - vice and assistance. An experienced coach who can monitor and guide ongoing performance is a valuable supplement to classroom instruction 156. Graham Allison’s work on the Cuban missile crisis (Essence of Decision, Little, Brown & Co ., 1971) is an example of what I have in mind. Allison identifed three alternative assump - tions about how governments work--the rational actor model, organizational process model, and bur eaucratic politics model. He then showed how an analystÍs implicit assumptions about the most appropriate model for analyzing a foreign government’s behavior cause him or her to focus on diferent evidence and arrive at diferent conclusions. Another example is my own analysis of fve alternative paths for making counterintelligence judgments in the contro - versial case of KGB defector Yuriy Nosenko. Richards J. Heuer, Jr., “Nosenko: Five Paths to J udgment,” Studies in Intelligence, Vol. 31, No. 3 (Fall 1987), originally classifed Secret but de- classifed and published in H. Bradford Westerfeld, ed., Inside CIA’s Private World: Declassifed A rticles from the Agency Internal Journal 1955-1992 (New Haven: Yale University Press, 1995).', 'kb-doc-01-heuer-psychology-p206-4', 1, 190, '01-heuer-psychology', 'retrieved', '896AF2D2B50E29B1685B8BA453758AA7C47952FAAD5EA9D7B2601AF247DDE871', 'v1', '{"source_id": "01-heuer-psychology", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-01-heuer-psychology-p207-2', 'doc-01-heuer-psychology', '', 207, 'in many felds, probably including intelligence analysis. Tis is supposed to be the job of the branch chief or senior analyst, but these ofcers are often too busy responding to other pressing demands on their time.', 'kb-doc-01-heuer-psychology-p207-2', 1, 36, '01-heuer-psychology', 'retrieved', '0C4AF9E934F12FB87A2581F15BA541D274199D120513D64678D0BBFE7DC542B6', 'v1', '{"source_id": "01-heuer-psychology", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-01-heuer-psychology-p207-3', 'doc-01-heuer-psychology', '', 207, 'It would be worthwhile to consider how an analytical coaching staf might be formed to mentor new analysts or consult with analysts working particularly difcult issues. One possible model is the SCORE organiza - tion that exists in many communities. SCORE stands for Senior Corps of Retired Executives. It is a national organization of retired executives who volunteer their time to counsel young entrepreneurs starting their own businesses. It should be possible to form a small group of retired analysts who possess the skills and values that should be imparted to new analysts, and who would be willing to volunteer (or be hired) to come in several days a week to counsel junior analysts.', 'kb-doc-01-heuer-psychology-p207-3', 1, 114, '01-heuer-psychology', 'retrieved', '04899D01320F562D2FA58816147B0D8C549A9D2E3CD4D3B2F5E0CC887CD119D1', 'v1', '{"source_id": "01-heuer-psychology", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-01-heuer-psychology-p207-4', 'doc-01-heuer-psychology', '', 207, 'New analysts could be required to read a specifed set of books or ar- ticles relating to analysis, and to attend a half-day meeting once a month to discuss the reading and other experiences related to their development as analysts. A comparable voluntary program could be conducted for ex- perienced analysts. Tis would help make analysts more conscious of the pr ocedures they use in doing analysis. In addition to their educational value, the required readings and discussion would give analysts a com - mon experience and vocabulary for communicating with each other, and with management, about the pr oblems of doing analysis.', 'kb-doc-01-heuer-psychology-p207-4', 1, 103, '01-heuer-psychology', 'retrieved', '8BC83FED7D4788D97A915A499E4979BECFB1248345994DCFD837CD76AA0731DC', 'v1', '{"source_id": "01-heuer-psychology", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-01-heuer-psychology-p207-5', 'doc-01-heuer-psychology', '', 207, 'My suggestions for writings that would qualify for a mandatory r eading program include: Robert Jervis’ Perception and Misperception in International Politics (Princeton University Press, 1977); Graham Allison’s Essence of Decision: Explaining the Cuban Missile Crisis (Little, Brown, 1971); Ernest May’s “Lessons” of the Past: Te Use and Misuse of History in American Foreign Policy (Oxford University Press, 1973); Ephraim Kam’s, Surprise Attack (Harvard University Press, 1988); Richard Betts’ “Analysis, War and Decision: Why Intelligence Failures Are Inevitable,” World Politics, Vol. 31, No. 1 (October 1978); Tomas Kuhn’s Te Structure of Scientifc Revolutions (University of Chicago Press, 1970); and Robin Hogarth’s Judgement and Choice (John Wiley, 1980). Although these were all written many years ago, they are classics of permanent value. Current analysts will doubtless have other works to recommend.', 'kb-doc-01-heuer-psychology-p207-5', 1, 130, '01-heuer-psychology', 'retrieved', 'A5442C5AD7A80D35724F1BF804671868884A433A2772CDE13D23D39726ED5376', 'v1', '{"source_id": "01-heuer-psychology", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-01-heuer-psychology-p207-6', 'doc-01-heuer-psychology', '', 207, 'CIA and Intelligence Community postmortem analyses of intelligence failure should also be part of the reading program.', 'kb-doc-01-heuer-psychology-p207-6', 1, 17, '01-heuer-psychology', 'retrieved', 'A2F3486C3BADF151284E838347DDB77A34412E3645D10A2253FCC04F47262C1A', 'v1', '{"source_id": "01-heuer-psychology", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-01-heuer-psychology-p208-1', 'doc-01-heuer-psychology', '', 208, 'T o facilitate institutional memory and learning, thorough postmor- tem analyses should be conducted on all signifcant intelligence failures.', 'kb-doc-01-heuer-psychology-p208-1', 1, 19, '01-heuer-psychology', 'retrieved', '75A26B89FC7CE01D9F4812BC907F808C90A1065EECE3812C2C5C8EE7AF145A59', 'v1', '{"source_id": "01-heuer-psychology", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-01-heuer-psychology-p208-3', 'doc-01-heuer-psychology', '', 208, 'Tese analyses should be collated and maintained in a central location, available for review to identify the common characteristics of analytical failure and success. A meta-analysis of the causes and consequences of analytical success and failure should be widely distributed and used in training programs to heighten awareness of analytical problems.', 'kb-doc-01-heuer-psychology-p208-3', 1, 51, '01-heuer-psychology', 'retrieved', 'AD5B35D7A277938E5B32B2A4A91DC4A5D5308001E19F71E1683D72638138E94F', 'v1', '{"source_id": "01-heuer-psychology", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-01-heuer-psychology-p208-4', 'doc-01-heuer-psychology', '', 208, 'T o encourage learning from experience, even in the absence of a high-pr ofle failure, management should require more frequent and sys - tematic retrospective evaluation of analytical performance. One ought not generalize from any single instance of a correct or incorrect judg - ment, but a series of related judgments that are, or are not, borne out by subsequent events can reveal the accuracy or inaccuracy of the analyst’s mental model. Obtaining systematic feedback on the accuracy of past judgments is frequently difcult or impossible, especially in the political intelligence feld. Political judgments are normally couched in imprecise terms and are generally conditional upon other developments. Even in retrospect, there are no objective criteria for evaluating the accuracy of most political intelligence judgments as they are presently written.', 'kb-doc-01-heuer-psychology-p208-4', 1, 129, '01-heuer-psychology', 'retrieved', 'D4D695703F01E879C40A5F1B6C9FB77066931E64F273D2689963C923280B6DC7', 'v1', '{"source_id": "01-heuer-psychology", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-01-heuer-psychology-p208-5', 'doc-01-heuer-psychology', '', 208, 'In the economic and military felds, however, where estimates are fr equently concerned with numerical quantities, systematic feedback on analytical performance is feasible. Retrospective evaluation should be standard procedure in those felds in which estimates are routinely updated at periodic intervals. Te goal of learning from retrospective evaluation is achieved, however, only if it is accomplished as part of an objective search for improved understanding, not to identify scapegoats or assess blame. Tis requirement suggests that retrospective evaluation should be done routinely within the organizational unit that prepared the report, even at the cost of some loss of objectivity.', 'kb-doc-01-heuer-psychology-p208-5', 1, 99, '01-heuer-psychology', 'retrieved', 'CAB49BC0B0579DD64959FB830F52192B5F51298E1B59D1E57A1ADFAFAB27F5FD', 'v1', '{"source_id": "01-heuer-psychology", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-01-heuer-psychology-p208-6', 'doc-01-heuer-psychology', '', 208, 'Exposure to Alternative Mind-Sets Te realities of bureaucratic life produce strong pressures for confor- mity. Management needs to make conscious eforts to ensure that well- r easoned competing views have the opportunity to surface within the Intelligence Community. Analysts need to enjoy a sense of security, so that partially developed new ideas may be expressed and bounced of 180', 'kb-doc-01-heuer-psychology-p208-6', 1, 59, '01-heuer-psychology', 'retrieved', '961FF9CBBB43DA0997C7CAFF3CCC2CC79B20C5265C3CD99751F0C24643F8038A', 'v1', '{"source_id": "01-heuer-psychology", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-01-heuer-psychology-p209-1', 'doc-01-heuer-psychology', '', 209, 'others as sounding boards with minimal fear of criticism for deviating from established orthodoxy.', 'kb-doc-01-heuer-psychology-p209-1', 1, 14, '01-heuer-psychology', 'retrieved', '0EFE93B246FE29143AF78D3FB9731AEB89182E12D937922993BFA4BBF0B890AC', 'v1', '{"source_id": "01-heuer-psychology", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-01-heuer-psychology-p209-2', 'doc-01-heuer-psychology', '', 209, 'Much of this book has dealt with ways of helping analysts remain more open to alternative views. Management can help by promoting the kinds of activities that confront analysts with alternative perspec - tives—consultation with outside experts, analytical debates, competitive analysis, devil ’s advocates, gaming, and interdisciplinary brainstorming.', 'kb-doc-01-heuer-psychology-p209-2', 1, 48, '01-heuer-psychology', 'retrieved', '9C668B0BC4124ADC4B754D0C8C4F820188A4D87CF57E1BF67A875366F98278EE', 'v1', '{"source_id": "01-heuer-psychology", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-01-heuer-psychology-p209-3', 'doc-01-heuer-psychology', '', 209, 'Consultation with outside experts is especially important as a means of avoiding what Adm. David Jeremiah called the “everybody-thinks- like-us mindset” when making signifcant judgments that depend upon kno wledge of a foreign culture. Intelligence analysts have often spent less time living in and absorbing the culture of the countries they are working on than outside experts on those countries. If analysts fail to understand the foreign culture, they will not see issues as the foreign government sees them. Instead, they may be inclined to mirror-image—that is, to assume that the other country’s leaders think like we do. Te analyst assumes that the other country will do what we would do if we were in their shoes.', 'kb-doc-01-heuer-psychology-p209-3', 1, 117, '01-heuer-psychology', 'retrieved', 'EEADE89570C4051E9F412C09A830071BCBC717907BD0A33906D508767407528F', 'v1', '{"source_id": "01-heuer-psychology", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-01-heuer-psychology-p209-4', 'doc-01-heuer-psychology', '', 209, 'Mirror-imaging is a common source of analytical error, and one that reportedly played a role in the Intelligence Community failure to warn of imminent Indian nuclear weapons testing in 1998. After lead - ing a US Government team that analyzed this episode, Adm. Jeremiah r ecommended more systematic use of outside expertise whenever there is a major transition that may lead to policy changes, such as the Hindu nationalists’ 1998 election victory and ascension to power in India. 157 Pre-publication review of analytical reports ofers another opportu - nity to bring alternative perspectives to bear on an issue. Review proce - dures should explicitly question the mental model employed by the ana- lyst in searching for and examining evidence. What assumptions has the analyst made that are not discussed in the draft itself, but that underlie the principal judgments? What alternative hypotheses have been consid- ered but rejected, and for what reason? What could cause the analyst to change his or her mind? Ideally, the review process should include analysts from other ar - eas who are not specialists in the subject matter of the report. Analysts within the same branch or division often share a similar mind-set. Past experience with review by analysts from other divisions or ofces indi - 157. T ranscript of Adm. David Jeremiah’s news conference at CIA, 2 June 1998.', 'kb-doc-01-heuer-psychology-p209-4', 1, 225, '01-heuer-psychology', 'retrieved', 'B80DB5740B7BBFD0DFCEE85AF563A819CC7A244E70E31926B3D34C4741741FB4', 'v1', '{"source_id": "01-heuer-psychology", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-01-heuer-psychology-p210-1', 'doc-01-heuer-psychology', '', 210, 'cates that critical thinkers whose expertise is in other areas make a signif- cant contribution. Tey often see things or ask questions that the author has not seen or asked. Because they are not so absorbed in the substance, they are better able to identify the assumptions and assess the argumenta- tion, internal consistency, logic, and relationship of the evidence to the conclusion.', 'kb-doc-01-heuer-psychology-p210-1', 1, 63, '01-heuer-psychology', 'retrieved', '1E45FD6F32967A38AFEB9311A2755C22738E9F169A0FF35EC99FF8853B1A054D', 'v1', '{"source_id": "01-heuer-psychology", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-01-heuer-psychology-p210-2', 'doc-01-heuer-psychology', '', 210, 'Te reviewers also proft from the experience by learning standards for good analysis that are independent of the subject matter of the analysis.', 'kb-doc-01-heuer-psychology-p210-2', 1, 23, '01-heuer-psychology', 'retrieved', '633FA6F00CA594DC13FFE6517739B2DFF1DBDD4E2B17B07B7939DCB9E5446F6F', 'v1', '{"source_id": "01-heuer-psychology", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-01-heuer-psychology-p210-3', 'doc-01-heuer-psychology', '', 210, 'Guiding Analytical Products On key issues, management should reject most single-outcome analysis—that is, the single-minded focus on what the analyst believes is probably happening or most likely will happen. When we cannot af - ford to get it wrong, or when deception is a serious possibility, manage - ment should consider mandating a systematic analytical process such as the one described in Chapter 8, “Analysis of Competing Hypotheses.” Analysts should be required to identify alternatives that were considered, justify why the alternatives are deemed less likely, and clearly express the degree of likelihood that events may not turn out as expected.', 'kb-doc-01-heuer-psychology-p210-3', 1, 101, '01-heuer-psychology', 'retrieved', '0EA745C9F4F68EAD9FF1FB89A8C7D56F9727CA8C589678F7E5C21EFF0CACFC51', 'v1', '{"source_id": "01-heuer-psychology", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-01-heuer-psychology-p210-4', 'doc-01-heuer-psychology', '', 210, 'Even if the analyst frmly believes the odds are, say, three-to-one against something happening, that leaves a 25-percent chance that it will occur. Making this explicit helps to better defne the problem for the policymaker. Does that 25-percent chance merit some form of contin - gency planning? If the less likely hypothesis happens to be, for example, that a new I ndian Government will actually follow through on its election cam - paign promise to conduct nuclear weapons testing, as recently occurred, ev en a 25-percent chance might be sufcient to put technical collection systems on increased alert.', 'kb-doc-01-heuer-psychology-p210-4', 1, 98, '01-heuer-psychology', 'retrieved', '5578209BB70D90FBB8120CF8304CD16613B0D77B1BEC7C997A4175A8DF2C19C8', 'v1', '{"source_id": "01-heuer-psychology", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-01-heuer-psychology-p210-5', 'doc-01-heuer-psychology', '', 210, 'Verbal expressions of uncertainty—such as possible, probable, un - likely, may, and could—have long been recognized as sources of ambi - guity and misunderstanding. By themselves, most verbal expressions of uncer tainty are empty shells. Te reader or listener flls them with mean - ing through the context in which they are used and what is already in the r eader’s or listener’s mind about that subject. An intelligence consumer’s interpretation of imprecise probability judgments will always be biased in favor of consistency with what the reader already believes. Tat means the intelligence reports will be undervalued and have little impact on the 182', 'kb-doc-01-heuer-psychology-p210-5', 1, 104, '01-heuer-psychology', 'retrieved', '99010475B4CFDCA0361390CA2574F49BD66755990B3D111D1BB3D85D49E4592E', 'v1', '{"source_id": "01-heuer-psychology", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
