INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-01-heuer-psychology-p211-1', 'doc-01-heuer-psychology', '', 211, 'consumer’s judgment. Tis ambiguity can be especially troubling when dealing with low-probability, high-impact dangers against which policy- makers may wish to make contingency plans.', 'kb-doc-01-heuer-psychology-p211-1', 1, 24, '01-heuer-psychology', 'retrieved', '026039D3A262909F539C59ACFCE9C0FE3AF0D154BD0C13564BFFD5BFFCBF2F9F', 'v1', '{"source_id": "01-heuer-psychology", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-01-heuer-psychology-p211-2', 'doc-01-heuer-psychology', '', 211, 'Managers of intelligence analysis need to convey to analysts that it is okay to be uncertain, as long as they clearly inform readers of the degree of uncertainty, sources of uncertainty, and what milestones to watch for that might clarify the situation. Inserting odds ratios or numerical prob- ability ranges in parentheses to clarify key points of an analysis should be standar d practice.', 'kb-doc-01-heuer-psychology-p211-2', 1, 64, '01-heuer-psychology', 'retrieved', '067D8AEB98919B11B55A4AEA6BB3E7B4B7220CAA913ECA8CB0CB9817C16D8DC6', 'v1', '{"source_id": "01-heuer-psychology", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-01-heuer-psychology-p211-3', 'doc-01-heuer-psychology', '', 211, 'Te likelihood of future surprises can be reduced if management assigns more resources to monitoring and analyzing seemingly low-prob- ability events that will have a signifcant impact on US policy if they do occur . Analysts are often reluctant, on their own initiative, to devote time to studying things they do not believe will happen. Tis usually does not further an analyst’s career, although it can ruin a career when the unex- pected does happen. Given the day-to-day pressures of current events, it is necessary for managers and analysts to clearly identify which unlikely but high-impact events need to be analyzed and to allocate the resources to cover them.', 'kb-doc-01-heuer-psychology-p211-3', 1, 109, '01-heuer-psychology', 'retrieved', 'F28A1206781767B3329A9CBC94A60E29315E69EC64BDCE5DDABB509F0E5AA942', 'v1', '{"source_id": "01-heuer-psychology", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-01-heuer-psychology-p211-4', 'doc-01-heuer-psychology', '', 211, 'One guideline for identifying unlikely events that merit the specifc allocation of resources is to ask the following question: Are the chances of this happening, however small, sufcient that if policymakers fully understood the risks, they might want to make contingency plans or take some form of preventive or preemptive action? If the answer is yes, resources should be committed to analyze even what appears to be an unlikely outcome.', 'kb-doc-01-heuer-psychology-p211-4', 1, 70, '01-heuer-psychology', 'retrieved', 'BD0762075D357AF5DF6E22FC9A348A05AA8F055A7E9A92B8A8AEBBD3427B4DB6', 'v1', '{"source_id": "01-heuer-psychology", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-01-heuer-psychology-p211-5', 'doc-01-heuer-psychology', '', 211, 'Managers of intelligence should support analyses that periodically r e-examine key problems from the ground up in order to avoid the pit - falls of the incremental approach. Receipt of information in small incre- ments over time facilitates assimilation of this information to the analyst’s existing views. No one item of information may be sufcient to prompt the analyst to change a previous view. Te cumulative message inherent in many pieces of information may be signifcant but is attenuated when this information is not examined as a whole.', 'kb-doc-01-heuer-psychology-p211-5', 1, 88, '01-heuer-psychology', 'retrieved', '94F576AE5B04B93E8E41C105EE747D7A4B8994025028D5CE431CB2B7D9C5519D', 'v1', '{"source_id": "01-heuer-psychology", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-01-heuer-psychology-p211-6', 'doc-01-heuer-psychology', '', 211, 'Finally, management should educate consumers concerning the limitations as well as the capabilities of intelligence analysis and should defne a set of realistic expectations as a standard against which to judge analytical performance.', 'kb-doc-01-heuer-psychology-p211-6', 1, 33, '01-heuer-psychology', 'retrieved', '19139584DB29FA2C87CCFB335C4B321D1C6CD4F3BFA5124E03111A983ABC7FE9', 'v1', '{"source_id": "01-heuer-psychology", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-01-heuer-psychology-p212-1', 'doc-01-heuer-psychology', '', 212, 'Te Bottom Line Analysis can be improved! None of the measures discussed in this book will guarantee that accurate conclusions will be drawn from the in- complete and ambiguous information that intelligence analysts typically wor k with. Occasional intelligence failures must be expected. Collectively, however, the measures discussed here can certainly improve the odds in the analysts’ favor.', 'kb-doc-01-heuer-psychology-p212-1', 1, 58, '01-heuer-psychology', 'retrieved', '41844DE517747ABA61809DB25AFA0A8791FA728FE6E021DC23430478B2225340', 'v1', '{"source_id": "01-heuer-psychology", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p3-1', 'doc-03-nist-sp-800-150', '', 3, 'i Authority This publication has been developed by NIST in accordance with its statutory responsibilities under the Federal Information Security Modernization Act (FISMA) of 2014, 44 U.S.C. § 3551 et seq., Public Law (P.L.) 113-283. NIST is responsible for developing information security standards and guidelines, including minimum requirements for federal information systems, but such standards and guidelines shall not apply to national security systems without the express approval of appropriate federal officials exercising policy authority over such systems. This guideline is consistent with the requirements of the Office of Management and Budget (OMB) Circular A-130.', 'kb-doc-03-nist-sp-800-150-p3-1', 0, 95, '03-nist-sp-800-150', 'retrieved', '0C0201E3E18C8683EAF7B6FEFEA6C1E204523B8AF35A4A271A38337B12D62E78', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p3-2', 'doc-03-nist-sp-800-150', '', 3, 'Nothing in this publication should be taken to contradict the standards and guidelines made mandatory and binding on federal agencies by the Secretary of Commerce under statutory authority. Nor should these guidelines be interpreted as altering or superseding the existing authorities of the Secretary of Commerce, Director of the OMB, or any other f ederal official. This publication may be used by nongovernmental organizations on a voluntary basis and is not subject to copyright in the United States. Attribution would, however, be appreciated by NIST.', 'kb-doc-03-nist-sp-800-150-p3-2', 0, 85, '03-nist-sp-800-150', 'retrieved', 'F410F81C1700A8E4AB19D1E276EC6A1CC33FC3311FB45F5FDC8A3235C98FBD9E', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
