INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p3-3', 'doc-03-nist-sp-800-150', '', 3, 'National Institute of Standards and Technology Special Publication 800-150 Natl. Inst. Stand. Technol. Spec. Publ. 800-150, 35 pages (October 2016) CODEN: NSPUE2 This publication is available free of charge from: http://dx.doi.org/10.6028/NIST.SP.800-150 Certain commercial entities, equipment, or materials may be identified in this document in order to describe an experimental procedure or concept adequately. Such identification is not intended to imply recommendation or endorsement by NIST, nor is it inte nded to imply that the entities, materials, or equipment are necessarily the best available for the purpose.', 'kb-doc-03-nist-sp-800-150-p3-3', 0, 86, '03-nist-sp-800-150', 'retrieved', 'D08084B86B3AFA1CED029AB82895B7125DF96D99FB5C40B347178BE58D057A8F', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
