INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p3-4', 'doc-03-nist-sp-800-150', '', 3, 'There may be references in this publication to other publications currently under development by NIST in accordance with its assigned statutory responsibilities. The information in this publication, including concepts and methodologies, may be used by federal agencies even before the completion of such companion publications. Thus, until each publication is completed, current requirements, guideline s, and procedures, where they exist, remain operative. For planning and transition purposes, federal agencies may wish to closely follow the development of t hese new publications by NIST.', 'kb-doc-03-nist-sp-800-150-p3-4', 0, 83, '03-nist-sp-800-150', 'retrieved', '4552E0710B0A92C79B7E6DFFD71A73F71B3FC8D3D930CF3C484EF57EE22ED000', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
