INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p3-5', 'doc-03-nist-sp-800-150', '', 3, 'Organizations are encouraged to review all draft publications during public comment periods and provide feedback to NIST. Many NIST cybersecurity publications, ot her than the ones noted above, are available at http://csrc.nist.gov/publications.', 'kb-doc-03-nist-sp-800-150-p3-5', 0, 32, '03-nist-sp-800-150', 'retrieved', '5A4923F696E839570E58984B6E07221579F1571087CA0B27A2C37ECA68D2E164', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p3-6', 'doc-03-nist-sp-800-150', '', 3, 'Comments on this publication may be submitted to: National Institute of Standards and Technology Attn: Computer Security Division, Information Technology Laboratory 100 Bureau Drive (Mail Stop 8930) Gaithersburg, MD 20899-8930 Email: sp800-150comments@nist.gov All comments are subject to release under the Freedom of Information Act (FOIA).', 'kb-doc-03-nist-sp-800-150-p3-6', 0, 45, '03-nist-sp-800-150', 'retrieved', 'E16E940E74872EC6D4FA390F274AD8F2D47127F6FA543AE1E05BC957A20A95B9', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p4-4', 'doc-03-nist-sp-800-150', '', 4, 'Cyber threat information is any information that can help an organization identify, assess, monitor, and respond to cyber threats. Cyber threat information includes indicators of compromise; tactics, techniques, and procedures used by threat actors; suggested actions to detect, contain, or prevent attacks; and the findings from the analyses of incidents. Organizations that share cyber threat information can improve their own security postures as well as those of other organizations.', 'kb-doc-03-nist-sp-800-150-p4-4', 0, 69, '03-nist-sp-800-150', 'retrieved', 'D9F4DB939D44B2A99CEBC3D18AE32CCCAAF581173FC5B2C70E03F8C9AC9600DB', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p4-5', 'doc-03-nist-sp-800-150', '', 4, 'This publication provides guidelines for establishing and participating in cyber threat information sharing relationships. This guidance helps organizations establish information sharing goals, identify cyber threat information sources, scope information sharing activities, develop rules that control the publication and distribution of threat information, engage with existing sharing communities, and make effective use of threat information in support of the organization’s overall cybersecurity practices.', 'kb-doc-03-nist-sp-800-150-p4-5', 0, 62, '03-nist-sp-800-150', 'retrieved', '2E06AB3DFE06128C94D41EF9F2EA30419AB9A8E77D1514A8858A6AE57DF2D53F', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p5-2', 'doc-03-nist-sp-800-150', '', 5, 'Executive Summary Cyber attacks have increased in frequency and sophistication, presenting significant challenges for organizations that must defend their data and systems from capable threat actors. These actors range from individual, autonomous attackers to well-resourced groups operating in a coordinated manner as part of a criminal enterprise or on behalf of a nation-state. Threat actors can be persistent, motivated, and agile, and they use a variety of tactics, techniques, and procedures (TTPs) to compromise systems, disrupt services, commit financial fraud, and expose or steal intellectual property and other sensitive information. Given the risks these threats present, it is increasingly important that organizations share cyber threat information and use it to improve their security posture.', 'kb-doc-03-nist-sp-800-150-p5-2', 0, 114, '03-nist-sp-800-150', 'retrieved', 'A33789DCDEAA43D895E544493E349CF4E07914011CB4AD7FFD5562C612621668', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p5-3', 'doc-03-nist-sp-800-150', '', 5, 'Cyber threat information is any information that can help an organization identify, assess, monitor, and respond to cyber threats. Examples of cyber threat information include indicators (system artifacts or observables associated with an attack), TTPs, security alerts, threat intelligence reports, and recommended security tool configurations. Most organizations already produce multiple types of cyber threat information that are available to share internally as part of their information technology and security operations efforts.', 'kb-doc-03-nist-sp-800-150-p5-3', 0, 71, '03-nist-sp-800-150', 'retrieved', '23ADB5BB1214D4BBE6835207AC949773BED61617BCCBFC3CF422F141DB3A5D5A', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p5-4', 'doc-03-nist-sp-800-150', '', 5, 'By exchanging cyber threat information within a sharing community, organizations can leverage the collective knowledge, experience, and capabilities of that sharing community to gain a more complete understanding of the threats the organization may face. Using this knowledge, an organization can make threat-informed decisions regarding defensive capabilities, threat detection techniques, and mitigation strategies. By correlating and analyzing cyber threat information from multiple sources, an organization can also enrich existing information and make it more actionable. This enrichment may be achieved by independently confirming the observations of other community members, and by improving the overall quality of the threat information through the reduction of ambiguity and errors. Organizations that receive threat information and subsequently use this information to remediate a threat confer a degree of protection to other organizations by impeding the threat’s ability to spread. Additionally, sharing of cyber threat information allows organizations to better detect campaigns that target particular industry sectors, business entities, or institutions.', 'kb-doc-03-nist-sp-800-150-p5-4', 0, 156, '03-nist-sp-800-150', 'retrieved', 'FA4F8B22EE14518DF5864F2C19409B9A8B87DCA83B31D2F6E70696E31B2ACA4F', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p5-5', 'doc-03-nist-sp-800-150', '', 5, 'This publication assists organizations in establishing and participating in cyber threat information sharing relationships. The publication describes the benefits and challenges of sharing, clarifies the importance of trust, and introduces specific data handling considerations. The goal of the publication is to provide guidelines that improve cybersecurity operations and risk management activities through safe and effective information sharing practices, and that help organizations plan, implement, and maintain information sharing.', 'kb-doc-03-nist-sp-800-150-p5-5', 0, 68, '03-nist-sp-800-150', 'retrieved', '2FCCEF538F52AFBB962029E0A73B1E5E0CF3143E12B740088767B80DD01B10A1', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p5-6', 'doc-03-nist-sp-800-150', '', 5, 'NIST encourages greater sharing of cyber threat information among organizations, both in acquiring threat information from other organizations and in providing internally-generated threat information to other organizations. Implementing the following recommendations enables organizations to make more efficient and effective use of information sharing capabilities.', 'kb-doc-03-nist-sp-800-150-p5-6', 0, 44, '03-nist-sp-800-150', 'retrieved', '181F2313CC4E3FB170174EBFC9F3C4B5B927480526956D23EB6902040472CD49', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p5-7', 'doc-03-nist-sp-800-150', '', 5, 'Establish information sharing goals and objectives that support business processes and security policies.', 'kb-doc-03-nist-sp-800-150-p5-7', 0, 13, '03-nist-sp-800-150', 'retrieved', '8BE8656FBFA3412C43BF0595847AACC7A4310870B42F9134BC41881C079A8ABC', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p5-8', 'doc-03-nist-sp-800-150', '', 5, 'An organization’s information sharing goals and objectives should advance its overall cybersecurity strategy and help an organization more effectively manage cyber-related risk. An organization should use the combined knowledge and experience of its own personnel and others, such as members of cyber threat information sharing organizations, to share threat information while operating per its security, privacy, regulatory, and legal compliance requirements.', 'kb-doc-03-nist-sp-800-150-p5-8', 0, 61, '03-nist-sp-800-150', 'retrieved', 'F563EDFEFCC704BEBCE09643AE842ED4645E0A00D66B1C0E5D637EA64B141481', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p6-3', 'doc-03-nist-sp-800-150', '', 6, 'Organizations should identify tools, sensors, and repositories that collect, produce, or store cyber threat information, threat analytics platforms, and delivery mechanisms that support the exchange of cyber threat information. As internal cyber threat information sources and capabilities are identified, organizations should determine how information from these sources currently support cybersecurity and risk management activities. Organizations should also document observed knowledge gaps and consider acquiring additional threat information from other (possibly external) sources or through the deployment of other tools or sensors. Finally, organizations should identify threat information that is available and suitable for sharing with outside parties.', 'kb-doc-03-nist-sp-800-150-p6-3', 0, 97, '03-nist-sp-800-150', 'retrieved', 'B21E943EA680A3710DAAA823135D1A9E0DF7EC4A1A197B5857965DEEEA370CE2', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p6-5', 'doc-03-nist-sp-800-150', '', 6, 'The breadth of an organization’s information sharing activities should be consistent with its resources, abilities, and objectives. Information sharing efforts should focus on activities that provide the greatest value to an organization and its sharing partners. The scoping activity should identify types of information that an organization’s key stakeholders authorize for sharing, the circumstances under which sharing of this information is permitted, and those with whom the information can and should be shared.', 'kb-doc-03-nist-sp-800-150-p6-5', 0, 73, '03-nist-sp-800-150', 'retrieved', '6D0FAEDBFD305C7C28ABB221A84BD0C679AA00E918C4C82C59A8BF4BF90DA482', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p6-7', 'doc-03-nist-sp-800-150', '', 6, 'Sharing rules are intended to control the publication and distribution of threat information, and consequently help to prevent the dissemination of information that, if improperly disclosed, may have adverse consequences for an organization, its customers, or its business partners. Information sharing rules should take into consideration the trustworthiness of the recipient, the sensitivity of the shared information, and the potential impact of sharing (or not sharing) specific types of information.', 'kb-doc-03-nist-sp-800-150-p6-7', 0, 70, '03-nist-sp-800-150', 'retrieved', '46B716260B4C4BCEB43B09B5106648A08D84756905508CD49BCF70EADE377D20', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p6-9', 'doc-03-nist-sp-800-150', '', 6, 'An organization should identify and participate in sharing activities that complement its existing threat information capabilities. An organization may need to participate in multiple information sharing forums to meet its operational needs. Organizations should consider public and private sharing communities, government repositories, commercial cyber threat information feeds, and open sources such as public websites, blogs, and data feeds.', 'kb-doc-03-nist-sp-800-150-p6-9', 0, 58, '03-nist-sp-800-150', 'retrieved', '5CACBE5EC0247FBE0E6BFDFA5FD0893FD54F0F1C50B6A4AB66CD62B1E19711F0', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p6-10', 'doc-03-nist-sp-800-150', '', 6, 'Actively seek to enrich indicators by providing additional context, corrections, or suggested improvements.', 'kb-doc-03-nist-sp-800-150-p6-10', 0, 13, '03-nist-sp-800-150', 'retrieved', '9F0B30A776375FA1FB8FB078FCD55071D4E22971C56095FDC34CA1535CB9A3CD', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p6-11', 'doc-03-nist-sp-800-150', '', 6, 'When possible, organizations should increase the usefulness and effectiveness of threat information by producing metadata for each indicator that is generated. Such metadata can provide context regarding the indicator by describing the intended use of the indicator, how it is to be interpreted, and how it relates to other indicators. Additionally, sharing processes should include mechanisms for publishing indicators, updating indicators and associated metadata, and retracting submissions that are incorrect or perhaps inadvertently shared. Such feedback plays an important role in the enrichment, maturation, and quality of the indicators shared within a community.', 'kb-doc-03-nist-sp-800-150-p6-11', 0, 93, '03-nist-sp-800-150', 'retrieved', '5D478DB2860660E31FD1C82C977B76DAA85222AFDDE6B676C62AF8B67BEA45EA', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p6-12', 'doc-03-nist-sp-800-150', '', 6, 'Use secure, automated workflows to publish, consume, analyze, and act upon cyber threat information.', 'kb-doc-03-nist-sp-800-150-p6-12', 0, 14, '03-nist-sp-800-150', 'retrieved', '4C49C6EFE0C477C5555D3CFE3F8188B64E319C7AE12C1BF6E999210B0033019F', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p6-13', 'doc-03-nist-sp-800-150', '', 6, 'The use of standardized data formats and transport protocols to share cyber threat information makes it easier to automate threat information processing. The use of automation enables cyber threat information', 'kb-doc-03-nist-sp-800-150-p6-13', 0, 30, '03-nist-sp-800-150', 'retrieved', '907644D1EE3E8547575399CADDEA758D062AFCE288E4D8C983C3CF5B4E1E7BC4', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p7-1', 'doc-03-nist-sp-800-150', '', 7, 'NIST SP 800-150 GUIDE TO CYBER THREAT INFORMATION SHARING v This publication is available free of charge from: http://dx.doi.org/10.6028/NIST.SP.800-150 to be rapidly shared, transformed, enriched, analyzed, and acted upon with less need for manual intervention.', 'kb-doc-03-nist-sp-800-150-p7-1', 0, 35, '03-nist-sp-800-150', 'retrieved', 'C9F91F01D4D7005E5C972FF14E69EF76336068CB63A1AD4AC77291AEB1FD1A98', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p7-3', 'doc-03-nist-sp-800-150', '', 7, 'Rather than attempting to establish sharing agreements during an active cyber incident, organizations should plan ahead and have agreements in place before incidents occur. Such advanced planning helps ensure that participating organizations establish trusted relationships and understand their roles, responsibilities, and information handling requirements.', 'kb-doc-03-nist-sp-800-150-p7-3', 0, 44, '03-nist-sp-800-150', 'retrieved', '9C711C17FB1FA0A16147A5CF5604FBDE5166C3BAD3CA8CA9EAFF43E6510B1A95', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p7-5', 'doc-03-nist-sp-800-150', '', 7, 'Sensitive information such as controlled unclassified information (CUI) [16] and personally identifiable information (PII) may be encountered when handling cyber threat information. The improper disclosure of such information could cause financial loss; violate laws, regulations, and contracts; be cause for legal action; or damage an organization’s or individual’s reputation. Accordingly, organizations should implement the necessary security and privacy controls and handling procedures to protect this information from unauthorized disclosure or modification.', 'kb-doc-03-nist-sp-800-150-p7-5', 0, 71, '03-nist-sp-800-150', 'retrieved', '7BC7EA3DB4FC22D0494029FD9D9DE1048E2364DCA5F3FB4E945F5C9FBAB18F2F', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p7-7', 'doc-03-nist-sp-800-150', '', 7, 'Each organization should establish an information sharing plan that provides for ongoing infrastructure maintenance and user support. The plan should address the collection and analysis of threat information from both internal and external sources and the use of this information in the development and deployment of protective measures. A sustainable approach is necessary to ensure that resources are available for the ongoing collection, storage, analysis, and dissemination of cyber threat information.', 'kb-doc-03-nist-sp-800-150-p7-7', 0, 71, '03-nist-sp-800-150', 'retrieved', 'F6B6BCB7D15268B5BB07BCE586DF709C743243041DBCEE7767C0E9B2A26D2B86', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
