INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p8-3', 'doc-03-nist-sp-800-150', '', 8, '3 2.3 Challenges to Information Sharing ............................................................................. 4 3. Establishing Sharing Relationships................................................................................. 6 3.1 Define Information Sharing Goals and Objectives ..................................................... 6 3.2 Identify Internal Sources of Cyber Threat Information ................................................ 6 3.3 Define the Scope of Information Sharing Activities .................................................... 9 3.4 Establish Information Sharing Rules .......................................................................... 9 3.4.1 Information Sensitivity and Privacy ...............................................................11 3.4.2 Sharing Designations ...................................................................................14 3.4.3 Cyber Threat Information Sharing and Tracking Procedures ........................16 3.5 Join a Sharing Community ....................................................................................... 16 3.6 Plan to Provide Ongoing Support for Information Sharing Activities ......................... 18 4. Participating in Sharing Relationships ...........................................................................20 4.1 Engage in Ongoing Communication ........................................................................ 20 4.2 Consume and Respond to Security Alerts ............................................................... 21 4.3 Consume and Use Indicators .................................................................................. 21 4.4 Organize and Store Cyber Threat Information ......................................................... 23 4.5 Produce and Publish Indicators ............................................................................... 25 4.5.1 Indicator Enrichment ....................................................................................25 4.5.2 Standard Data Formats ................................................................................25 4.5.3 Protection of Sensitive Data .........................................................................26 List of Appendices Appendix A— Cyber Threat Information Sharing Scenarios ...............................................27 A ppendix B— Glossary ..........................................................................................................30 Appendix C— Acronyms ........................................................................................................32 Appendix D— References ......................................................................................................34 List of Tables Table 3-1: Selected Internal Information Sources ...................................................................... 7 Table 3-2: Handling Recommendations for Selected Types of Sensitive Data .........................12 Table 3-3: Traffic Light Protocol, Version 1.0 ...........................................................................15', 'kb-doc-03-nist-sp-800-150-p8-3', 0, 201, '03-nist-sp-800-150', 'retrieved', '20C2E005BCC2563E7536E34FAB3AE0765C5EF1149EE2F676B159D4FBF05558D1', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
