INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p9-1', 'doc-03-nist-sp-800-150', '', 9, 'NIST SP 800-150 GUIDE TO CYBER THREAT INFORMATION SHARING 1 This publication is available free of charge from: http://dx.doi.org/10.6028/NIST.SP.800-150 1. Introduction 1.1 Purpose and Scope This publication provides guidance to help organizations exchange cyber threat information. The guidance addresses sharing of cyber threat information within an organization, consuming and using cyber threat information received from external sources, and producing cyber threat information that can be shared with other organizations. The document also presents specific considerations for participation in information sharing communities.', 'kb-doc-03-nist-sp-800-150-p9-1', 0, 81, '03-nist-sp-800-150', 'retrieved', '08BBDEAA3067A92D77762C1D0DC4AAE659B1746903315AC71FF7111014E5E7CC', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p9-2', 'doc-03-nist-sp-800-150', '', 9, 'This publication expands upon the information sharing concepts introduced in Section 4, Coordination and Information Sharing, of NIST Special Publication (SP) 800-61[1].', 'kb-doc-03-nist-sp-800-150-p9-2', 0, 22, '03-nist-sp-800-150', 'retrieved', '6BF21075C1B00722D7E71F09EB78D4967857A5DE94DD3B69EE25CB8B3048E9F5', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p9-3', 'doc-03-nist-sp-800-150', '', 9, '1.2 Audience This publication is intended for computer security incident response teams (CSIRTs), system and network administrators, cybersecurity specialists, privacy officers, technical support staff, chief information security officers (CISOs), chief information officers (CIOs), computer security program managers, and others who are key stakeholders in cyber threat information sharing activities.', 'kb-doc-03-nist-sp-800-150-p9-3', 0, 49, '03-nist-sp-800-150', 'retrieved', 'AC812BB9A7377E55BF782C544E5B99FE73E3CC93F71724CAF364113B68E19D16', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p9-4', 'doc-03-nist-sp-800-150', '', 9, 'Although this guidance is written primarily for federal agencies, it is intended to be applicable to a wide variety of governmental and non-governmental organizations.', 'kb-doc-03-nist-sp-800-150-p9-4', 0, 24, '03-nist-sp-800-150', 'retrieved', 'FE59585FD47A6F5ECC57DC4EA4AB762DCE397F8D50A794E2916F70F68CE046CA', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p9-5', 'doc-03-nist-sp-800-150', '', 9, '1.3 Document Structure The remainder of this document is organized into the following sections and appendices: • Section 2 introduces basic cyber threat information sharing concepts, describes the benefits of sharing information, and discusses the challenges faced by organizations as they implement sharin g cap abilities. • Section 3 provides guidelines on establishing sharing relationships with other organizations. • Section 4 discusses considerations for effectively participating in sharing relationships. • A ppendix A contains scenarios that show how organizations can enhance their network defenses by sharing cyber threat information and by leveraging the cyber experience and capabilities of their partners. • Appendix B contains a list of terms used in the document and their associated definitions. • Appendix C provides a list of acronyms used in the document. • Appendix D identifies resources referenced in the document.', 'kb-doc-03-nist-sp-800-150-p9-5', 0, 137, '03-nist-sp-800-150', 'retrieved', '7CA3CBD4F23D1584718F5AE247A980894B984FD3C15C29584C0E5695D11E5015', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p10-2', 'doc-03-nist-sp-800-150', '', 10, '2. Basics of Cyber Threat Information Sharing This section introduces basic cyber threat information sharing concepts including types of cyber threat information and common terminology. The section also examines potential uses for shared cyber threat information and explores the benefits and challenges of threat information sharing.', 'kb-doc-03-nist-sp-800-150-p10-2', 0, 46, '03-nist-sp-800-150', 'retrieved', 'A0124369041E2B06FCA54D6A8323AF413B910DD912BDD44D7F6F0213C968568E', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p10-3', 'doc-03-nist-sp-800-150', '', 10, '2.1 Threat Information Types A cyber threat is “any circumstance or event with the potential to adversely impact organizational operations (including mission, functions, image, or reputation), organizational assets, individuals, other organizations, or the Nation through an information system via unauthorized access, destruction, disclosure, or modification of information, and/or denial of service.” [2] For brevity, this publication uses the term threat instead of “cyber threat”. The individuals and groups posing threats are known as “threat actors” or simply actors.', 'kb-doc-03-nist-sp-800-150-p10-3', 0, 78, '03-nist-sp-800-150', 'retrieved', 'DDEC5675C9DE28EF568BD0205BB185D2811D3386A9AA4B50292BFF007719F1D8', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p10-4', 'doc-03-nist-sp-800-150', '', 10, 'Threat information is any information related to a threat that might help an organization protect itself against a threat or detect the activities of an actor. Major types of threat information include the following: • Indicators are technical artifacts or observables1 that suggest an attack is imminent or is currently underway or that a compromise may have already occurred. Indicators can be used to detect and defend against potential threats. Examples of indicators include the Internet Protocol (IP) address of a suspected command and control server, a suspicious Domain Name System (DNS) domain name, a Uniform Resource Locator (URL) that references malicious content, a file hash for a malicious executable, or the subject line text of a malicious email message.', 'kb-doc-03-nist-sp-800-150-p10-4', 0, 120, '03-nist-sp-800-150', 'retrieved', '94026959F434B63AF7A0A92AE0DBFB6E697AF2595AD4944064473DCB18464B6B', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p10-5', 'doc-03-nist-sp-800-150', '', 10, '• Tactics, techniques, and procedures (TTPs) describe the behavior of an actor. Tactics are high-level descriptions of behavior, techniques are detailed descriptions of behavior in the context of a tactic, and procedures are even lower-level, highly detailed descriptions in the context of a technique. TTPs could describe an actor’s tendency to use a specific malware variant, order of operations, attack tool, delivery mechanism (e.g., phishing or watering hole attack), or exploit.', 'kb-doc-03-nist-sp-800-150-p10-5', 0, 71, '03-nist-sp-800-150', 'retrieved', '6582D002BA17EED98BF8A7E8C4BF2EDD79E1ED250EBAC95C5C7AFB239959EB27', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p10-6', 'doc-03-nist-sp-800-150', '', 10, '• Security alerts, also known as advisories, bulletins, and vulnerability notes, are brief, usually human- readable, technical notifications regarding current vulnerabilities, exploits, and other security issues.', 'kb-doc-03-nist-sp-800-150-p10-6', 0, 26, '03-nist-sp-800-150', 'retrieved', 'A73CCD4EE8F9C33D9045A0C36247FF812B96EBD8F52AEA401B8BC853CB7E09C4', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p10-7', 'doc-03-nist-sp-800-150', '', 10, 'Security alerts originate from sources such as the United States Computer Emergency Readiness Team (US-CERT), Information Sharing and Analysis Centers (ISACs), the National Vulnerability Database (NVD), Product Security Incident Response Teams (PSIRTs), commercial security service providers, and security researchers.', 'kb-doc-03-nist-sp-800-150-p10-7', 0, 39, '03-nist-sp-800-150', 'retrieved', '783507B48399D5E80E4BA0B1539890DB6B4F9884BBF0192AD62E1DC004660C02', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p10-8', 'doc-03-nist-sp-800-150', '', 10, '• Threat intelligence reports are generally prose documents that describe TTPs, actors, types of systems and information being targeted, and other threat-related information that provides greater situational awareness to an organization. Threat intelligence is threat information that has been aggregated, transformed, analyzed, interpreted, or enriched to provide the necessary context for decision-making processes.', 'kb-doc-03-nist-sp-800-150-p10-8', 0, 53, '03-nist-sp-800-150', 'retrieved', '670225DDFA975DB38E1EE4BA605AC2A83900B40AB63ABD8263D258A511391FE8', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p10-9', 'doc-03-nist-sp-800-150', '', 10, '• Tool configurations are recommendations for setting up and using tools (mechanisms) that support the automated collection, exchange, processing, analysis, and use of threat information. For example, tool configuration information could consist of instructions on how to install and use a rootkit', 'kb-doc-03-nist-sp-800-150-p10-9', 0, 42, '03-nist-sp-800-150', 'retrieved', 'E438DACC4E3022EA8477413AE9E3CB04874795F62409F251D87D6CEC669D04DC', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p11-2', 'doc-03-nist-sp-800-150', '', 11, 'detection and removal utility, or how to create and customize intrusion detection signatures, router access control lists (ACLs), firewall rules, or web filter configuration files.', 'kb-doc-03-nist-sp-800-150-p11-2', 0, 25, '03-nist-sp-800-150', 'retrieved', '22FF1EF3631D9479717CBCE728A4154530CDCA81A2731E29AD71EA5004ECD1C7', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p11-3', 'doc-03-nist-sp-800-150', '', 11, 'Many organizations already produce and share threat information internally. For example, an organization’s security team may identify malicious files on a compromised system when responding to an incident and produce an associated set of indicators (e.g., file names, sizes, hash values). These indicators might then be shared with system administrators who configure security tools, such as host- based intrusion detection systems, to detect the presence of these indicators on other systems. Likewise, the security team may launch an email security awareness initiative in response to an observed rise in phishing attacks within the organization. These practices demonstrate information sharing within an organization.', 'kb-doc-03-nist-sp-800-150-p11-3', 0, 102, '03-nist-sp-800-150', 'retrieved', 'A7F343B09E08F29590180364B9A02D9E02F5A5FF5C7F0A6407EE3D39C1301134', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p11-4', 'doc-03-nist-sp-800-150', '', 11, 'The primary goal of this publication is to foster similar threat information sharing practices across organizational boundaries – both acquiring threat information from other organizations, and providing internally-generated threat information to other organizations.', 'kb-doc-03-nist-sp-800-150-p11-4', 0, 33, '03-nist-sp-800-150', 'retrieved', '178D1ABE76F82CFF68A493804C979F8B0CF4FBA08C92BC00DB6FC92ADAF61EA4', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p11-5', 'doc-03-nist-sp-800-150', '', 11, '2.2 Benefits of Information Sharing Threat information sharing provides access to threat information that might otherwise be unavailable to an organization. Using shared resources, organizations can enhance their security posture by leveraging the knowledge, experience, and capabilities of their partners in a proactive way. Allowing “one organization’s detection to become another’s prevention”2 is a powerful paradigm that can advance the overall security of organizations that actively share threat information.', 'kb-doc-03-nist-sp-800-150-p11-5', 0, 69, '03-nist-sp-800-150', 'retrieved', 'C16F966E7B8DFEF54BF16CB1F9C508C453E1EEE58AFB48711D71CF2FDC3BA5EA', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p11-6', 'doc-03-nist-sp-800-150', '', 11, 'An organization can use shared threat information in many ways. Some uses are operationally oriented, such as updating enterprise security controls for continuous monitoring with new indicators and configurations to detect the latest attacks and compromises. Threat information may also be used strategically, such as using shared threat information as inputs when planning major changes to an organization’s security architecture.', 'kb-doc-03-nist-sp-800-150-p11-6', 0, 60, '03-nist-sp-800-150', 'retrieved', '48081A48700CEA32185C77F690D1CE50AB12E681A6256A58C2E28838944D0EBE', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p11-7', 'doc-03-nist-sp-800-150', '', 11, 'Threat information exchanged within communities organized around specific industries or sectors (or some other shared characteristic) can be particularly beneficial because the member organizations often face actors that use common TTPs that target the same types of systems and information. Cyber defense is most effective when organizations work together to deter and defend against well-organized, capable actors. Such collaboration helps to reduce risk and improve the organization’s security posture.', 'kb-doc-03-nist-sp-800-150-p11-7', 0, 69, '03-nist-sp-800-150', 'retrieved', 'C319B4AE9FED0C0B9CD47B336A1358D44183664227B00C920F80CC554DA087DC', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p11-8', 'doc-03-nist-sp-800-150', '', 11, 'Benefits of information sharing include: • Shared Situational Awareness. Information sharing enables organizations to leverage the collective knowledge, experience, and analytic capabilities of their sharing partners within a community of interest, thereby enhancing the defensive capabilities of multiple organizations. Even a single contribution—a new indicator or observation about an actor—can increase the awareness and security of an entire community.', 'kb-doc-03-nist-sp-800-150-p11-8', 0, 59, '03-nist-sp-800-150', 'retrieved', '9B2A63D5E5F429FAE849D4B97A08A912CFCC0471BB70A084DCAA28E03D4A69F2', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p11-9', 'doc-03-nist-sp-800-150', '', 11, '• Improved Security Posture. By developing and sharing threat information, organizations gain a better understanding of the threat environment and can use threat information to inform their cybersecurity and risk management practices. Using shared information, organizations can identify affected platforms or systems, implement protective measures, enhance detection capabilities, and more effectively respond and recover from incidents based on observed changes in the threat environment. As organizations share information and subsequently mitigate threats, those', 'kb-doc-03-nist-sp-800-150-p11-9', 0, 73, '03-nist-sp-800-150', 'retrieved', '03FBDCE9163AA055F3F1196B25D43AF9248EB6DA9A98FA489AE2B2F01719FCE2', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p12-2', 'doc-03-nist-sp-800-150', '', 12, 'organizations can improve their overall cybersecurity posture, even providing a degree of protection to other organizations, including those who may not have responded to the threat information, by reducing the number of viable attack vectors for actors.', 'kb-doc-03-nist-sp-800-150-p12-2', 0, 37, '03-nist-sp-800-150', 'retrieved', '9FD16B0D856E3A07DE06CE7892A5835A4B419BBCB973769EE5D68B57CFFA57DC', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p12-3', 'doc-03-nist-sp-800-150', '', 12, '• Knowledge Maturation. When seemingly unrelated observations are shared and analyzed by organizations, those observations can be correlated with data collected by others. This enrichment process increases the value of information by enhancing existing indicators and by developing knowledge of actor TTPs that are associated with a specific incident, threat, or threat campaign.', 'kb-doc-03-nist-sp-800-150-p12-3', 0, 53, '03-nist-sp-800-150', 'retrieved', 'E0E0CE082B3B139CC04DFE23036091C1B9014CB544F6B6193C056FB6DCB654E1', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p12-4', 'doc-03-nist-sp-800-150', '', 12, 'Correlation can also impart valuable insights into the relationships that exist between indicators.', 'kb-doc-03-nist-sp-800-150-p12-4', 0, 13, '03-nist-sp-800-150', 'retrieved', '178940F1C57E0425993C435F31F835B74AC79A183E712D7DF48FA7D3A6898941', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p12-5', 'doc-03-nist-sp-800-150', '', 12, '• Greater Defensive Agility. Actors continually adapt their TTPs to try to evade detection, circumvent security controls, and exploit new vulnerabilities. Organizations that share information are often better informed about changing TTPs and the need to rapidly detect and respond to threats. This awareness helps increase their operational tempo and reduce the probability of successful attack. Such agility also creates economies of scale for network defenders while increasing actors’ costs by forcing them to develop new TTPs.', 'kb-doc-03-nist-sp-800-150-p12-5', 0, 77, '03-nist-sp-800-150', 'retrieved', 'F7DAC20FDFA9BC46F62ECF342A46EF6ED7A251999BFE3A9E18D777239DFE6EBD', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p12-6', 'doc-03-nist-sp-800-150', '', 12, '2.3 Challenges to Information Sharing While sharing threat information clearly has benefits, certain challenges still remain. Some challenges that apply both to consuming and to producing threat information are: • Establishing Trust. Trust relationships form the basis for information sharing, but require effort to establish and maintain. Ongoing communication through regular in-person meetings, phone calls, or social media can help accelerate the process of building trust.', 'kb-doc-03-nist-sp-800-150-p12-6', 0, 66, '03-nist-sp-800-150', 'retrieved', '59E559E6C33B4F8DC15E441126B237AD9E8EDF633DA001DF364980F01FF37AB3', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p12-7', 'doc-03-nist-sp-800-150', '', 12, '• Achieving Interoperability and Automation. Standardized data formats and transport protocols are important building blocks for interoperability. The use of common formats and protocols enables automation and allows organizations, repositories, and tools to exchange threat information at machine speed. Adopting specific formats and protocols, however, can require significant time and resources, and the value of these investments can be substantially reduced if sharing partners require different formats or protocols. During the standards development process, early adopters need to accept the risk that it may be necessary to purchase new tools if significant changes to formats and protocols take place.', 'kb-doc-03-nist-sp-800-150-p12-7', 0, 99, '03-nist-sp-800-150', 'retrieved', 'B6A085CF621CE7A66FE0374D6C1FA3018056475C964D406959AEDC30CB146470', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p12-8', 'doc-03-nist-sp-800-150', '', 12, '• Safeguarding Sensitive Information. Disclosure of sensitive information, such as controlled unclassified information (CUI) and personally identifiable information (PII) can result in financial loss, violation of sharing agreements, legal action, and loss of reputation. Sharing security and event information, such as security logs or scan results, could expose the protective or detective capabilities of the organization and result in threat shifting by the actor.3 The unauthorized disclosure of information may impede or disrupt an ongoing investigation, jeopardize information needed for future legal proceedings, or disrupt response actions such as botnet takedown operations. Organizations should apply handling designations to shared information and implement policies, procedures, and technical controls to actively manage the risks of disclosure of sensitive information.', 'kb-doc-03-nist-sp-800-150-p12-8', 0, 117, '03-nist-sp-800-150', 'retrieved', '61FFE59D08E2DE2E320C271CF4046FA546BB28E1F5CDCCD0E466DC2F3344F494', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p14-2', 'doc-03-nist-sp-800-150', '', 14, '3. Establishing Sharing Relationships When launching a threat information sharing capability, the following planning and preparation activities are recommended:4 • Define the goals and objectives of information sharing (section 3.1).', 'kb-doc-03-nist-sp-800-150-p14-2', 0, 30, '03-nist-sp-800-150', 'retrieved', '8B14A699F2648C2871EF7913E9A6879A7C03871D048AC3BEC21B4713825E7231', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p14-7', 'doc-03-nist-sp-800-150', '', 14, '• Plan to provide ongoing support for information sharing activities (section 3.6).', 'kb-doc-03-nist-sp-800-150-p14-7', 0, 12, '03-nist-sp-800-150', 'retrieved', '6D44158633EF2AFA22C2352D2E4F21D5BD9E645CAFB7BECFC7F1FC9357E7F8C4', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p14-8', 'doc-03-nist-sp-800-150', '', 14, 'Throughout this process, organizations are encouraged to consult with subject matter experts both inside and outside their organization. Such sources include: • Experienced cybersecurity personnel, • Members and operators of established threat information sharing organizations, • Trusted business associates, supply chain partners, and industry peers, and • Personnel knowledgeable about legal issues, internal business processes, procedures, and systems.', 'kb-doc-03-nist-sp-800-150-p14-8', 0, 58, '03-nist-sp-800-150', 'retrieved', 'C7E6E8D37F5BE96C8F4A6FB682C7B831578060CE824321A48939D5BA6D0F1C4D', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p14-9', 'doc-03-nist-sp-800-150', '', 14, 'An organization should use the knowledge and experience from these experts to help shape a threat information sharing capability that supports its mission and operates under its security, privacy, regulatory, and legal compliance requirements. Due to constantly changing risks, requirements, priorities, technology, and/or regulations, this process will often be iterative. Organizations should reassess and adjust their information sharing capabilities as needed based on changing circumstances. Such a change may involve repeating some or all of the planning and preparation activities listed above.', 'kb-doc-03-nist-sp-800-150-p14-9', 0, 82, '03-nist-sp-800-150', 'retrieved', '32AD00A3FB002C009223FBFDF5161CCE468FBE5F680A24565EE28C7120F7A63B', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p14-10', 'doc-03-nist-sp-800-150', '', 14, '3.1 Define Information Sharing Goals and Objectives At the outset, an organization should establish goals and objectives that describe the desired outcomes of threat information sharing in terms of the organization’s business processes and security policies. These goals and objectives will help guide the organization through the process of scoping its information sharing efforts, selecting and joining sharing communities, and providing ongoing support for information sharing activities. Due to technological and/or resource constraints, it may be necessary to prioritize goals and objectives to ensure that the most important information sharing activities are performed.', 'kb-doc-03-nist-sp-800-150-p14-10', 0, 93, '03-nist-sp-800-150', 'retrieved', '7C551D6F9E6198393AC3869FE6F279021D603B74CA5A1BDE54724FDAE7ABC43F', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p14-11', 'doc-03-nist-sp-800-150', '', 14, '3.2 Identify Internal Sources of Cyber Threat Information A key step in any information sharing effort is to identify potential sources of threat information within an organization. By conducting an inventory of internal threat information sources, an organization is better able to identify knowledge gaps. These gaps can be addressed by deploying additional tools and sensors or by acquiring threat information from external threat information feeds or repositories. In large', 'kb-doc-03-nist-sp-800-150-p14-11', 0, 70, '03-nist-sp-800-150', 'retrieved', '40AC3792B46EAB16A806A0099ED3738761EA868F0C5234E086E9F530902618A1', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p15-1', 'doc-03-nist-sp-800-150', '', 15, 'NIST SP 800-150 GUIDE TO CYBER THREAT INFORMATION SHARING 7 This publication is available free of charge from: http://dx.doi.org/10.6028/NIST.SP.800-150 organizations, this inventory process is also a means of discovering information that is being collected and analyzed in business units across the organization that may not be currently shared within the organization.', 'kb-doc-03-nist-sp-800-150-p15-1', 0, 51, '03-nist-sp-800-150', 'retrieved', '46F2550ABDBCB5AC43366FC8BF8DE07C535637A4FAF1EAEB60520ED2A9009FEF', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p15-2', 'doc-03-nist-sp-800-150', '', 15, 'The process of identifying threat information sources includes the following steps: • Identify sensors, tools, data feeds, and repositories that produce threat information, and confirm that the information is produced at a frequency, precision, and accuracy to support cybersecurity decision- making. • Identify threat information that is collected and analyzed as part of an organization’s continuous monitoring strategy. • Locate threat information that is collected and stored, but not necessarily analyzed or reviewed on an ongoing basis. If an organization finds useful threat information that is being underutilized, methods of integrating this information into its cybersecurity and risk management practices should be explored. • Identify threat information that is suitable for sharing with outside parties and that could help them more effectively respond to threats. The owners and operators of threat information sources play an important role in the inventory process and should be consulted. These personnel understand what information is available and how it is natively stored; the data export formats that are supported; and the query languages, protocols, and services available for data retrieval. Some sources may store and publish structured, machine-readable data, while others may provide unstructured data with no fixed format (e.g., free text or images). Structured data that is expressed using open, machine-readable, standard formats can generally be more readily accessed, searched, and analyzed by a wider range of tools. Thus, the format of the information plays a significant role in determining the ease and efficiency of information use, analysis, and exchange.', 'kb-doc-03-nist-sp-800-150-p15-2', 0, 247, '03-nist-sp-800-150', 'retrieved', '2FD8F5286EB23235E6350CEB96BBE4700CC586E8FFFF3EED055DF96AC82B5D90', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p15-3', 'doc-03-nist-sp-800-150', '', 15, 'As part of the inventory process, organizations should take note of information gaps that may prevent realization of the organization’s goals and objectives. By identifying these gaps, an organization is better able to prioritize investments into new capabilities, and identify opportunities to fill gaps by acquiring threat information from other, possibly external, sources or through the deployment of additional tools or sensors.', 'kb-doc-03-nist-sp-800-150-p15-3', 0, 62, '03-nist-sp-800-150', 'retrieved', '7177997089CB33BBF309923240669B4AC43C3E1C6972A1530C894E6FC36769CE', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p15-4', 'doc-03-nist-sp-800-150', '', 15, 'Table 3-1 describes common sources of cybersecurity-related information and provides examples of data elements from these sources that may be of interest to security operations personnel.', 'kb-doc-03-nist-sp-800-150-p15-4', 0, 26, '03-nist-sp-800-150', 'retrieved', 'D7B4BD75235CC424D09DB2AC8A1949928AB3D3E65E29EE06ECA1B246C7D85BAB', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p15-5', 'doc-03-nist-sp-800-150', '', 15, 'Table 3-1: Selected Internal Information Sources Source Examples Network Data Sources Router, firewall, Wi-Fi, remote services (such as remote login or remote command execution), and Dynamic Host Configuration Protocol (DHCP) server logs Timestamp Source and destination IP address Domain name TCP/UDP port number Media Access Control (MAC) address Hostname Action (deny/allow) Status code Other protocol information', 'kb-doc-03-nist-sp-800-150-p15-5', 0, 56, '03-nist-sp-800-150', 'retrieved', 'BC97A644A608182EE4F57A8F273046B8A598B562E52E03AAAB1A59F1A6E532B0', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p17-3', 'doc-03-nist-sp-800-150', '', 17, 'Analysis reports and observations regarding: • TTPs • Campaigns • Affiliations • Motives • Exploit code and tools • Response and mitigation strategies • Recommended courses of action User screen captures (e.g., error messages or dialog boxes) Forensic toolkits and dynamic and/or virtual execution environments Malware samples System artifacts (network, file system, memory) Organizations should update the inventory when new sensors, repositories, or capabilities are deployed or when significant changes to a device’s configuration, ownership, or administrative point of contact occur.', 'kb-doc-03-nist-sp-800-150-p17-3', 0, 81, '03-nist-sp-800-150', 'retrieved', '89A65211C5DBFAB8F33B14BA233148EE8131F0C28BC0EADAF8134C780C8E3F4D', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p17-4', 'doc-03-nist-sp-800-150', '', 17, '3.3 Define the Scope of Information Sharing Activities Organizations should specify the scope of their information sharing activities by identifying the types of information available to share, the circumstances under which sharing this information is permitted, and those with whom the information can and should be shared. Organizations should review their information sharing goals and objectives while scoping information sharing activities to ensure that priorities are addressed. When defining these activities, organizations should ensure that the information sources and capabilities needed to support each activity are available. Organizations should also consider pursuing sharing activities that will address known information gaps. For example, an organization might not have an internal malware analysis capability, but it may gain access to malware indicators by participating in a sharing community.', 'kb-doc-03-nist-sp-800-150-p17-4', 0, 126, '03-nist-sp-800-150', 'retrieved', '5A720E6263E6060B85E7FA115DCB7D80CE90E7C3FBAB82ACC7AC12F0EFCA5699', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p17-5', 'doc-03-nist-sp-800-150', '', 17, 'The breadth of information sharing activities will vary based on an organization’s resources and abilities.', 'kb-doc-03-nist-sp-800-150-p17-5', 0, 15, '03-nist-sp-800-150', 'retrieved', '6981E3BC2981399F20CBF042A3CAD222FF32DE5085723FC22A6EC6429AF75862', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p17-6', 'doc-03-nist-sp-800-150', '', 17, 'By choosing a relatively narrow scope, an organization with limited resources can focus on a smaller set of activities that provides the greatest value to the organization and its sharing partners. An organization may be able to expand the scope as additional capabilities and resources become available. Such an incremental approach may help to ensure that information sharing activities support an organization’s information sharing goals and objectives, while at the same time fit within available resources.', 'kb-doc-03-nist-sp-800-150-p17-6', 0, 76, '03-nist-sp-800-150', 'retrieved', 'E7C3250C54FBB1DFC7F7D87DC26F160EBA7183D88BD62B4209CE91FB87B07C44', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p17-7', 'doc-03-nist-sp-800-150', '', 17, 'Organizations with greater resources and advanced capabilities may choose a larger initial scope that allows for a broader set of activities in support of their goals and objectives.', 'kb-doc-03-nist-sp-800-150-p17-7', 0, 28, '03-nist-sp-800-150', 'retrieved', '0E56A92387C6F0B08FA69FFF469D0229AA6A7B0186A54ACE348971068BA7DF32', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p18-4', 'doc-03-nist-sp-800-150', '', 18, '• Describe any requirements for redacting or sanitizing information to be shared.', 'kb-doc-03-nist-sp-800-150-p18-4', 0, 12, '03-nist-sp-800-150', 'retrieved', 'A2B4C2357886F4FACF02731273FCF2EA351363DA1376A4AD058EDB6A1DD5C45A', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p18-6', 'doc-03-nist-sp-800-150', '', 18, '• Apply information handling designations that describe recipient obligations for protecting information.', 'kb-doc-03-nist-sp-800-150-p18-6', 0, 12, '03-nist-sp-800-150', 'retrieved', 'F20F78595D38963C09B035FDEDD24431593D2949BD5C5FC4E0E8011EAA903B61', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p18-7', 'doc-03-nist-sp-800-150', '', 18, 'Sharing rules help control the publication and distribution of threat information, and consequently help to prevent the dissemination of information that, if improperly disclosed, may have adverse consequences for the organization or its customers or business partners. Information sharing rules should take into consideration the trustworthiness of the recipient, the sensitivity of the shared information, and the potential impacts of sharing (or not sharing). For example, an organization may establish rules that limit the exchange of highly sensitive information to internal individuals or groups, that allow the sharing of moderately sensitive information with specific trusted partners, that permit information having a low sensitivity to be published within a closed sharing community, and that allow for the free exchange of non-sensitive information within public information sharing forums.', 'kb-doc-03-nist-sp-800-150-p18-7', 0, 126, '03-nist-sp-800-150', 'retrieved', 'ABCF3BF0346C4056A695F8DAA18C30C8C8DE3858CA01DF683CEC3D69107BD06D', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p18-8', 'doc-03-nist-sp-800-150', '', 18, 'Large organizations that want to share internal threat information across business units may also need to establish rules governing the exchange of threat information between organizational elements. Business units within an organization that either collect or process threat information should participate in scoping what types of threat information will be shared and how that will be done. The steps for establishing information sharing rules apply to internal sharing of threat information within large organizations.', 'kb-doc-03-nist-sp-800-150-p18-8', 0, 74, '03-nist-sp-800-150', 'retrieved', 'BDAAC89D19CB6B20C46EAD179BF3074837925FF5AB97FDECE37470224C1B2CC3', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p18-9', 'doc-03-nist-sp-800-150', '', 18, 'Multinational corporations need to consider the differences in various nation’s privacy laws and how to address handling of classified information, which typically cannot be shared with foreign nationals.', 'kb-doc-03-nist-sp-800-150-p18-9', 0, 28, '03-nist-sp-800-150', 'retrieved', 'DB83CD5A8AE649B5057084800635A8A797CD43D06DD6BFE5A753EAE6962C8ADD', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p19-4', 'doc-03-nist-sp-800-150', '', 19, 'From a privacy perspective, one of the key challenges with threat information sharing is the potential for disclosure of PII6. Education and awareness activities are critical to ensure that individuals responsible for handling threat information understand how to recognize and safeguard PII.7 Internal sharing of information may result in disclosure of PII to people who, by virtue of their job functions, would not typically have routine access to such information. For example, a forensic analyst or incident responder may encounter PII while searching a hard drive for malware indicators, reviewing emails related to suspected phishing attacks, or inspecting packet captures. The analyst has a legitimate need to review this information to investigate an exploit, develop detection strategies, or develop defensive measures. If the result of such an analysis is shared with others, steps should be taken to protect the confidentiality of PII.', 'kb-doc-03-nist-sp-800-150-p19-4', 0, 142, '03-nist-sp-800-150', 'retrieved', 'B156E6EC7C3F9AFBC47255BF0CB96018CB0ADB6892E9D2A701865A495A4DFA93', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p19-5', 'doc-03-nist-sp-800-150', '', 19, 'An organization should have information sharing policies and procedures in place that provide guidance for the handling of PII. These policies and procedures should include steps for identifying incident data types that are likely to contain PII. Policies should describe proper safeguards for managing the privacy risks associated with sharing such data. A common practice is to focus on the exchange of indicators to the maximum extent possible. Some indicators, such as file hashes, network port numbers, registry key values, and other data elements, are largely free of PII. Where PII is identified, however, organizations should redact fields containing PII that are not relevant to investigating or addressing threats before sharing.8 The type and degree of protection applied should be based on the intended use of the information, the sensitivity of the information, and the intended recipient.', 'kb-doc-03-nist-sp-800-150-p19-5', 0, 137, '03-nist-sp-800-150', 'retrieved', '99D6400D7B9B61118A4C8F0C9F22F4D6D795235620D7DFAC3DCED7D81180A60C', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p19-6', 'doc-03-nist-sp-800-150', '', 19, '6 OMB Memorandum 07-16 [5] defines PII as “information which can be used to distinguish or trace an individual’s identity, such as their name, social security number, biometric records, etc. alone, or when combined with other personal or identifying information which is linked or linkable to a specific individual, such as date and place of birth, mother’s maiden name, etc.” OMB Memorandum 10-22 [6] further states that “the definition of PII is not anchored to any single category of information or technology. Rather, it demands a case-by-case assessment of the specific risk that an individual can be identified. In performing this assessment, it is important for an agency to recognize that non-PII can become PII whenever additional information is made publicly available — in any medium and from any source — that, when combined with other available information, could be used to identify an individual.” NIST SP 800-122 [7] includes a slightly different definition of PII that is focused on the security objective of confidentiality and not privacy in the broad sense. Definitions of PII established by organizations outside of the federal government may vary based on the consideration of additional regulatory requirements. The guidance in this document applies regardless of how organizations define PII.', 'kb-doc-03-nist-sp-800-150-p19-6', 0, 205, '03-nist-sp-800-150', 'retrieved', 'C8F98778421B25B71C55607F902982FAD1FFF7A952EC7E58D786B0E3E5816D3E', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p19-7', 'doc-03-nist-sp-800-150', '', 19, '7 For additional guidance and examples of privacy controls, see NIST SP 800-53 Rev. 4, Appendix J, “Privacy Control Catalog, Privacy Controls, Enhancements, and Supplemental Guidance” [8].', 'kb-doc-03-nist-sp-800-150-p19-7', 0, 27, '03-nist-sp-800-150', 'retrieved', 'BB15C6780F5E9F8A706D09B376575607F66733A157861F91AC9B455B11F78053', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p19-8', 'doc-03-nist-sp-800-150', '', 19, '8 NIST SP 800-122 [7] describes a process called “de-identification” which entails the removal or obfuscation of PII, such that the remaining information cannot be used to identify an individual.', 'kb-doc-03-nist-sp-800-150-p19-8', 0, 30, '03-nist-sp-800-150', 'retrieved', '73DF83758290A9888BF0FF7579CF6F551DB28B8E593614B6678B64F8B167AD74', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p20-2', 'doc-03-nist-sp-800-150', '', 20, 'Where practical, organizations are encouraged to use automated methods rather than human-oriented methods to identify and protect PII. Manual identification, extraction, and obfuscation of PII can be a slow, error-prone, and resource-intensive process. Automated methods may include field-level data validation using permitted values lists, searching for PII using pattern matching techniques such as regular expressions, and performing operations that de-identify, mask, and anonymize data containing PII.', 'kb-doc-03-nist-sp-800-150-p20-2', 0, 66, '03-nist-sp-800-150', 'retrieved', 'CB0CFC192DEF0A298AA0853F3C7E09B84BDBF0C64934A93040B9B2E023275AC2', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p20-3', 'doc-03-nist-sp-800-150', '', 20, 'The degree of automation that can be achieved will vary based on factors such as the structure, complexity, and sensitivity of the information.', 'kb-doc-03-nist-sp-800-150-p20-3', 0, 23, '03-nist-sp-800-150', 'retrieved', 'F068C6DC30BAC4F29C9718B6597FC02E437CFA0962B90450CD84E5009BAAFA3D', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p20-4', 'doc-03-nist-sp-800-150', '', 20, 'Organizations should also implement safeguards to protect intellectual property, trade secrets, and other proprietary information from unauthorized disclosure. The disclosure of such information could result in financial loss, violate NDAs or other sharing agreements, be cause for legal action, or damage an organization’s reputation. Organizations should have a plan in place to address the unauthorized or inadvertent disclosure of CUI. The plan should cover containment, control, and recovery procedures; breach notification requirements, and post-incident activities such as capturing lessons learned.', 'kb-doc-03-nist-sp-800-150-p20-4', 0, 80, '03-nist-sp-800-150', 'retrieved', 'CDDB2F61DA415C1F387DAA5AD11A3C4751D5AF5B38E429F5B0F410B5FDFABE71', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p20-5', 'doc-03-nist-sp-800-150', '', 20, 'Table 3-2 introduces selected types of threat information, provides examples of sensitive data that may be present in these types of threat information, and offers general recommendations for handling such data.', 'kb-doc-03-nist-sp-800-150-p20-5', 0, 31, '03-nist-sp-800-150', 'retrieved', 'E85E6544B547CA89AC0D5C7FAE2D13EFFA6FB78453BCB634FE685B8F241772AE', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p20-6', 'doc-03-nist-sp-800-150', '', 20, 'Table 3-2: Handling Recommendations for Selected Types of Sensitive Data Type of Threat Information Examples of Sensitive Data Elements9 Recommendations Network Indicators Any single network indicator can be sensitive, but network indicators in the aggregate are often more sensitive because they can reveal relationships between network entities. By studying these relationships it may be possible to infer the identity of users, gather information about the posture of devices, perform network reconnaissance, and characterize the security safeguards and tools that an organization uses.', 'kb-doc-03-nist-sp-800-150-p20-6', 0, 82, '03-nist-sp-800-150', 'retrieved', 'FD65E0896767F6EC00B3B44E929E14A56607604E834CFB9E2A68608619191A66', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p20-7', 'doc-03-nist-sp-800-150', '', 20, 'Focus on the exchange of network indicators such as destination IP addresses associated with an actor’s command and control infrastructure, malicious URLs/domains, and staging servers.', 'kb-doc-03-nist-sp-800-150-p20-7', 0, 25, '03-nist-sp-800-150', 'retrieved', 'AF44742752B69ACEC028FC38FFCFE10FE46917E6AED741A57AE6527FF1066B2C', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p20-8', 'doc-03-nist-sp-800-150', '', 20, 'Before sharing, anonymize or sanitize network indicators that contain IP or MAC addresses of target systems or addresses registered to your organization. Also anonymize or sanitize indicators that may reveal the structure of internal networks, or ports or protocols that identify particular products.', 'kb-doc-03-nist-sp-800-150-p20-8', 0, 43, '03-nist-sp-800-150', 'retrieved', 'A5029D49A30D587AEF1CC9F6E4C0717B01D1DD833E55383BE3E430B036DB6C73', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p21-1', 'doc-03-nist-sp-800-150', '', 21, 'NIST SP 800-150 GUIDE TO CYBER THREAT INFORMATION SHARING 13 This publication is available free of charge from: http://dx.doi.org/10.6028/NIST.SP.800-150 Type of Threat Information Examples of Sensitive Data Elements9 Recommendations Packet Capture (PCAP) In addition to the network indicators previously discussed, unencrypted or decrypted packets may contain authentication credentials and sensitive organization information, such as PII, CUI or other types of sensitive information.', 'kb-doc-03-nist-sp-800-150-p21-1', 0, 62, '03-nist-sp-800-150', 'retrieved', 'BFFCD6E0C5A197369425FA14566FAB5C774F1F23DC80E9875BE3D94274B92768', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p21-2', 'doc-03-nist-sp-800-150', '', 21, 'PCAP files can be challenging because network indicators may be present within both the packet header and the payload. For example, PCAP files may show protocols (e.g., DHCP, Address Resolution Protocol (ARP), File Transfer Protocol (FTP), DNS) and applications operating at multiple layers within the network stack. These protocols and applications generate network information that may be captured within PCAP files and may require sanitization or anonymization to prevent sensitive information leakage.', 'kb-doc-03-nist-sp-800-150-p21-2', 0, 72, '03-nist-sp-800-150', 'retrieved', 'E0957D024305DB023D5A7123E847EBF50368BC34BB4F8E8EA124FFCBE6C96FB9', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p21-3', 'doc-03-nist-sp-800-150', '', 21, 'Filter PCAP files before sharing by extracting only those packets that are related to the investigation of a specific incident or pattern of events: • Related to a particular network conversation (i.e., exchange of information between specific IP addresses of interest); • Occurring during a chosen time period; • Destined for, or originating from, a specific port; or • Use of a particular network protocol. Redact payload content that contains PII, CUI or other types of sensitive information that is not relevant for characterizing the incident or event of interest.', 'kb-doc-03-nist-sp-800-150-p21-3', 0, 90, '03-nist-sp-800-150', 'retrieved', '74284B42B9EBE4BFECCA4FDE35D40BCBC95704259F142F009737E876E9CFD582', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p21-4', 'doc-03-nist-sp-800-150', '', 21, 'When anonymizing or redacting network information, use a strategy that preserves enough information to support meaningful analysis of the resulting PCAP file contents.', 'kb-doc-03-nist-sp-800-150-p21-4', 0, 23, '03-nist-sp-800-150', 'retrieved', 'F5C11721224FE0DED551ACE421CAC6B2F23C08AF0894689457E0FAC996BAD846', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p21-5', 'doc-03-nist-sp-800-150', '', 21, 'Network Flow Data Network flow data contains information such as: • Source IP address (i.e., the sender), • Destination IP address (i.e., the recipient), • Port and protocol information, • Byte counts, and • Timestamps. If not effectively anonymized, network flow data may make identification of specific users possible, provide insights into user behavior (e.g., web sites visited), expose application and service usage patterns, or reveal network routing information and data volumes.', 'kb-doc-03-nist-sp-800-150-p21-5', 0, 72, '03-nist-sp-800-150', 'retrieved', 'BD549FC9F43BD8C4A2A968B423C5A1E0242547F9E14B813A6969B16F17D6F78A', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p21-6', 'doc-03-nist-sp-800-150', '', 21, 'Before sharing network flow data, organizations should consider redacting portions of session histories using cryptography-based, prefix- preserving, IP address anonymization techniques to prevent network identification or to conceal specific fields within the session trace (e.g., time stamps, ports, protocols, or byte counts). To gain the greatest value from the information, use a tool that transforms network flow data without breaking referential integrity. Network flow analysis and correlation operations often require that IP address replacement and transformation operations are performed consistently within and sometimes across multiple files. Anonymization techniques that do not use a consistent replacement strategy may reduce or eliminate the value of sharing this type of information.', 'kb-doc-03-nist-sp-800-150-p21-6', 0, 108, '03-nist-sp-800-150', 'retrieved', 'CA346DF7652487C91ECE3D6F05D9B927E82DA448BDDDDF9A089D04953BBD553C', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p22-2', 'doc-03-nist-sp-800-150', '', 22, 'Type of Threat Information Examples of Sensitive Data Elements9 Recommendations Phishing Email Samples Email headers may contain information such as: • Mail agent IP addresses, • Host or domain names, and • Email addresses.', 'kb-doc-03-nist-sp-800-150-p22-2', 0, 34, '03-nist-sp-800-150', 'retrieved', '890AE2E9DAC7DC1B23E4ECB488DF57EBA51068B9B2791F7DD26AC71228B35EB9', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p22-3', 'doc-03-nist-sp-800-150', '', 22, 'An email message body may also contain PII, CUI, or other types of sensitive information.', 'kb-doc-03-nist-sp-800-150-p22-3', 0, 15, '03-nist-sp-800-150', 'retrieved', 'B9BDB09B6BAD3D676700830ED544D1C9155704397603B0E0EFCDDD3C7F590C6F', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p22-4', 'doc-03-nist-sp-800-150', '', 22, 'Organizations should anonymize email samples and remove any sensitive information that is not necessary for describing an incident or event of interest.', 'kb-doc-03-nist-sp-800-150-p22-4', 0, 22, '03-nist-sp-800-150', 'retrieved', '6F3C32A5C6DDCB4A625763187F9552B0CCE43EBDB842145779DA5ED69268E3D9', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
