INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p22-5', 'doc-03-nist-sp-800-150', '', 22, 'System, Network, and Application Logs Log files may contain PII, CUI or other types of sensitive information. Log data may reveal IP addresses, ports, protocols, services, and URLs, as well as connection strings, logon credentials, portions of financial transactions, or other activities captured in URL parameters.', 'kb-doc-03-nist-sp-800-150-p22-5', 0, 46, '03-nist-sp-800-150', 'retrieved', '5948BAAEDACB92FB2A81DC911ED2467CF4C6776F957107D15271FB9BE6A83552', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p22-6', 'doc-03-nist-sp-800-150', '', 22, 'Organizations should perform IP address, timestamp, port, and protocol anonymization and remove any sensitive information that is not necessary for describing an incident or event of interest. Before sharing log data, it may also be necessary to sanitize URLs that contain identifying information such as session or user identifiers. Application logs may require redaction and anonymizing operations that are specific to particular application log formats.', 'kb-doc-03-nist-sp-800-150-p22-6', 0, 65, '03-nist-sp-800-150', 'retrieved', '66E440AC065E90A12CB096E99102896099BC98656FFD4470C31194B9913B19A5', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p22-7', 'doc-03-nist-sp-800-150', '', 22, 'Malware Indicators and Samples Although organizations are unlikely to encounter sensitive information in malware indicators or samples, sensitive information may be present depending on how targeted the malware is and what collection methods were used to gather a sample.', 'kb-doc-03-nist-sp-800-150-p22-7', 0, 39, '03-nist-sp-800-150', 'retrieved', '7687CC624115A13CE272101CF43DE0825F2DB1C2B34FCAE0849657E64D090EEB', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p22-8', 'doc-03-nist-sp-800-150', '', 22, 'Organizations should remove PII, CUI, and other types of sensitive information that is not necessary for describing an incident or event of interest.', 'kb-doc-03-nist-sp-800-150-p22-8', 0, 23, '03-nist-sp-800-150', 'retrieved', '248711764D35ED67FF14D9B035B2A39DC71150C2D3F8BA40AD9203F63544E7C5', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p22-9', 'doc-03-nist-sp-800-150', '', 22, '3.4.2 Sharing Designations A variety of methods exist to designate handling requirements for shared threat information. These designations identify unclassified information that may not be suitable for public release and that may require special handling. A designation applied to threat information can communicate specific handling requirements and identify data elements that are considered sensitive and should be redacted prior to sharing. Organizations are encouraged to provide clear handling guidance for any shared threat information. Likewise, recipients of threat information should observe the handling, attribution, dissemination, and storage requirements expressed in the source organization’s handling guidance.', 'kb-doc-03-nist-sp-800-150-p22-9', 0, 95, '03-nist-sp-800-150', 'retrieved', 'CF7CC1D11640D95B658F0D4152F000FB274B19D197F0AFD7C5FA99BB10DC13E3', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p22-10', 'doc-03-nist-sp-800-150', '', 22, 'The Traffic Light Protocol (TLP), depicted in Table 3-3, provides a framework for expressing sharing designations [9].', 'kb-doc-03-nist-sp-800-150-p22-10', 0, 17, '03-nist-sp-800-150', 'retrieved', 'DA06B853F345DCED9D702153982ED6376F00CAD6BA324C00EDA8A6903509C6A2', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p23-2', 'doc-03-nist-sp-800-150', '', 23, 'Table 3-3: Traffic Light Protocol, Version 1.0 Color When should it be used? How may it be shared? TLP:RED Not for disclosure, restricted to participants only.', 'kb-doc-03-nist-sp-800-150-p23-2', 0, 26, '03-nist-sp-800-150', 'retrieved', 'FD6E6FECF98F8224174563B8005AF61A7957E248117CC99CF52F991D5C34028C', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p23-3', 'doc-03-nist-sp-800-150', '', 23, 'Sources may use TLP:RED when information cannot be effectively acted upon by additional parties, and could lead to impacts on a party''s privacy, reputation, or operations if misused.', 'kb-doc-03-nist-sp-800-150-p23-3', 0, 28, '03-nist-sp-800-150', 'retrieved', 'EED6C337E930F837C544D0E9B6ADA5208A3948740F2E1211E2BA750AC8929960', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p23-4', 'doc-03-nist-sp-800-150', '', 23, 'Recipients may not share TLP:RED information with any parties outside of the specific exchange, meeting, or conversation in which it was originally disclosed. In the context of a meeting, for example, TLP:RED information is limited to those present at the meeting. In most circumstances, TLP:RED should be exchanged verbally or in person.', 'kb-doc-03-nist-sp-800-150-p23-4', 0, 52, '03-nist-sp-800-150', 'retrieved', 'FB0FB87C72DFCE8C419CC1E1F4E318C6BA57D58708FA5952A28CD3BC0E86B738', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p23-6', 'doc-03-nist-sp-800-150', '', 23, 'Sources may use TLP:AMBER when information requires support to be effectively acted upon, yet carries risks to privacy, reputation, or operations if shared outside of the organizations involved.', 'kb-doc-03-nist-sp-800-150-p23-6', 0, 28, '03-nist-sp-800-150', 'retrieved', '96127C13F642743D6D9709862796E8DB80DE492D41D610B9E56AEE4E8865C320', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p23-7', 'doc-03-nist-sp-800-150', '', 23, 'Recipients may only share TLP:AMBER information with members of their own organization, and with clients or customers who need to know the information to protect themselves or prevent further harm.', 'kb-doc-03-nist-sp-800-150-p23-7', 0, 30, '03-nist-sp-800-150', 'retrieved', 'E0B93244B1E598BBFB47F493C3FA33A840BD0888133C037C521522EFB6040CC1', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p23-8', 'doc-03-nist-sp-800-150', '', 23, 'Sources are at liberty to specify additional intended limits of the sharing: these must be adhered to.', 'kb-doc-03-nist-sp-800-150-p23-8', 0, 17, '03-nist-sp-800-150', 'retrieved', '5A6B113426C2A86090DDD9E9E1253B454823438767690877DAC738BBDCE70EB0', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p23-10', 'doc-03-nist-sp-800-150', '', 23, 'Sources may use TLP:GREEN when information is useful for the awareness of all participating organizations as well as with peers within the broader community or sector.', 'kb-doc-03-nist-sp-800-150-p23-10', 0, 26, '03-nist-sp-800-150', 'retrieved', '680FFE33E5A9D2DE1390835066402E8E9E5D0060FD96007A7D033B8D96616635', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p23-11', 'doc-03-nist-sp-800-150', '', 23, 'Recipients may share TLP:GREEN information with peers and partner organizations within their sector or community, but not via publicly accessible channels. Information in this category can be circulated widely within a particular community. TLP:GREEN information may not be released outside of the community.', 'kb-doc-03-nist-sp-800-150-p23-11', 0, 43, '03-nist-sp-800-150', 'retrieved', 'A023F6EF37467A2CA1A4E8D9FC6C48132A962AEAF6599B02AD7B380B2F4FB2B5', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p23-13', 'doc-03-nist-sp-800-150', '', 23, 'Sources may use TLP:WHITE when information carries minimal or no foreseeable risk of misuse, in accordance with applicable rules and procedures for public release. Subject to standard copyright rules.', 'kb-doc-03-nist-sp-800-150-p23-13', 0, 29, '03-nist-sp-800-150', 'retrieved', 'BDE4E24F80E43313D944D70D6ED7967669ADEAA7B5A49C653D58154EC37827B1', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p23-16', 'doc-03-nist-sp-800-150', '', 23, 'The Anti-Phishing Working Group (APWG) has also proposed a schema for expressing sharing designations [10]. The APWG schema describes an extensible, hierarchical tagging system that can be used to express distribution restrictions on shared information. The tags can be used to indicate with whom the information may or may not be shared (e.g., recipient only, with affected parties only, no restrictions) and to express other caveats (e.g., that no attribution is permitted).', 'kb-doc-03-nist-sp-800-150-p23-16', 0, 72, '03-nist-sp-800-150', 'retrieved', '7E398E6D38735E1F8A76FF03D3659C7EB2AAD17C6C254071D668E8A660E93B8C', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p23-17', 'doc-03-nist-sp-800-150', '', 23, 'For some threat information, collection methods may be considered confidential or proprietary, but the actual indicators observed may be shareable. In such cases, an organization may want to use tear line reporting, an approach where reports are organized such that information of differing sensitivity is not intermingled (e.g., the indicator information is presented in a separate part of the document than the', 'kb-doc-03-nist-sp-800-150-p23-17', 0, 62, '03-nist-sp-800-150', 'retrieved', 'DAA798A66F69DE60DAE2DC17EACB3999BF1F9145F6DD4EE31C33365A248949B9', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p24-2', 'doc-03-nist-sp-800-150', '', 24, 'collection methods). Organizing a report in this manner allows an organization to readily produce a report containing only information that designated recipients are authorized to receive.', 'kb-doc-03-nist-sp-800-150-p24-2', 0, 26, '03-nist-sp-800-150', 'retrieved', 'E3C0B7512D393DDE30162DAD25B9997525E528A21AD07F1F67F7C908593C2F21', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
