INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p24-3', 'doc-03-nist-sp-800-150', '', 24, 'An organization should carefully choose, or formulate, an approach for expressing sharing designations.', 'kb-doc-03-nist-sp-800-150-p24-3', 0, 13, '03-nist-sp-800-150', 'retrieved', '26013668D39E426EF6AF47AAFD949A8DCF3CA6317DD1648E6223D0B7D1DFEE47', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p24-4', 'doc-03-nist-sp-800-150', '', 24, 'Regardless of how an organization expresses sharing designations, the procedures for applying designations to threat information should be documented and approved, and the personnel responsible for assigning such designations properly trained.', 'kb-doc-03-nist-sp-800-150-p24-4', 0, 31, '03-nist-sp-800-150', 'retrieved', 'BA38DBD140F18861AF984150264622C147080D721569ED36635DB2B4D4B33756', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p24-5', 'doc-03-nist-sp-800-150', '', 24, '3.4.3 Cyber Threat Information Sharing and Tracking Procedures Over time, an organization’s cybersecurity activities can result in the accumulation of large quantities of threat information from various sources, both internal and external. Though challenging, tracking of data sources is important both for protecting information owners and for ensuring that consuming organizations can meet their legal or regulatory commitments for data protection. Organizations should also preserve the provenance of data by tracking who provided the information and how the information was collected, transformed, or processed, information that is important for drawing conclusions from shared information.', 'kb-doc-03-nist-sp-800-150-p24-5', 0, 94, '03-nist-sp-800-150', 'retrieved', 'A2F7B27B2758AABDEA8F8F27AA23233A50DA0C7AF5ED26D802AC13A732CBF2BA', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p24-6', 'doc-03-nist-sp-800-150', '', 24, 'An organization should formulate procedures that allow prompt sharing of threat information while at the same time satisfying its obligations for protecting potentially sensitive data. The procedures should, to the extent possible, balance the risks of possibly ineffective sharing against the risks of possibly flawed protection. An organization’s information sharing and tracking procedures should: • Identify threat information that can be readily shared with trusted parties.', 'kb-doc-03-nist-sp-800-150-p24-6', 0, 66, '03-nist-sp-800-150', 'retrieved', '4DCCA572546B5D4AAFA5A4D314FEECA297A894D38AB0B3BD4D79725AF3E0C70E', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p24-7', 'doc-03-nist-sp-800-150', '', 24, '• Establish processes for reviewing, sanitizing, and protecting threat information that is likely to contain sensitive information.', 'kb-doc-03-nist-sp-800-150-p24-7', 0, 17, '03-nist-sp-800-150', 'retrieved', '2884EF72E23079F1072B9DB048ED1E029399293D99C88C3E71CD3B90A4DA3F5A', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p24-10', 'doc-03-nist-sp-800-150', '', 24, '• Describe how information handling designations are applied, monitored, and enforced.', 'kb-doc-03-nist-sp-800-150-p24-10', 0, 11, '03-nist-sp-800-150', 'retrieved', 'E221849FFF6E734DFF2EB4B8C4249A6F40047C906ED252E2056A105D1A644576', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p24-13', 'doc-03-nist-sp-800-150', '', 24, 'The procedures should describe the roles, responsibilities, and authorities (both scope and duration) of all stakeholders. The procedures should allow for the effective transfer of authority and flow of shared information to key decision makers and should enable collaboration with approved external communities when needed.', 'kb-doc-03-nist-sp-800-150-p24-13', 0, 45, '03-nist-sp-800-150', 'retrieved', '5A3B910C34AF9BBD5F1845BE004282347CA62920940CFDB5E0D8ADA6840F84B5', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p24-14', 'doc-03-nist-sp-800-150', '', 24, '3.5 Join a Sharing Community When evaluating potential sharing partners, an organization should look to sources that complement its existing threat information resources or that offer actionable information that addresses known gaps in an organization’s situational awareness. Since sharing communities may focus on the exchange of a specific type of threat information, an organization may need to participate in multiple information sharing forums to meet its information sharing objectives.', 'kb-doc-03-nist-sp-800-150-p24-14', 0, 69, '03-nist-sp-800-150', 'retrieved', '7725A31BB275B53076B7235639E2F606492A9EAED32FB6BF0FE8B9A06A8E7BD4', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p24-15', 'doc-03-nist-sp-800-150', '', 24, 'Threat information can be acquired from public and private sharing communities, government repositories, across the organization, commercial threat information feeds, and open sources. Sharing communities often organize around a shared characteristic or interest. The composition of a community', 'kb-doc-03-nist-sp-800-150-p24-15', 0, 38, '03-nist-sp-800-150', 'retrieved', 'A4EE31D5397089607E118B225315439BB90E6E05E1E6C2BF1250EB800698FC44', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p25-2', 'doc-03-nist-sp-800-150', '', 25, 'may be based on geographic region, political boundary, industrial sector, business interest, or threat space (e.g., focused on phishing attacks). Many of these communities have multinational constituencies and global reach. Examples of potential sharing partners are ISACs, domestic and foreign Computer Emergency Readiness Teams (CERTs) or CSIRTs, Information Sharing and Analysis Organizations (ISAOs), DHS Automated Indicator Sharing (AIS) initiative, threat and vulnerability repositories, law enforcement agencies, product vendors, managed security service providers, internet service providers, supply chain partners, industry sector peers, business partners, and customers.', 'kb-doc-03-nist-sp-800-150-p25-2', 0, 85, '03-nist-sp-800-150', 'retrieved', 'E844FF493CFB4132AE9D21CAE0C84DA9F01B59BF41DD2914420863999982D48F', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p25-3', 'doc-03-nist-sp-800-150', '', 25, 'Some communities are informal, open, self-organizing groups that largely operate through voluntary cooperation. The membership of these communities is often mutable (i.e., no formal fixed membership), sometimes anonymous, and the members may maintain full autonomy with minimal central coordination.', 'kb-doc-03-nist-sp-800-150-p25-3', 0, 39, '03-nist-sp-800-150', 'retrieved', '009D825D928C1DAC371A12D2E2C1BE00DE30A40236B2B5B8A056A4E2D2A38C15', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p25-4', 'doc-03-nist-sp-800-150', '', 25, 'These communities generally operate under basic rules of conduct rather than formal agreements. In such communities, members publish threat information to the community on a voluntary, ad hoc basis and are individually responsible for ensuring that the content provided to the community is suitable for sharing.', 'kb-doc-03-nist-sp-800-150-p25-4', 0, 46, '03-nist-sp-800-150', 'retrieved', '0F30DBD9A095AB05DF2A21E6D2C59F78319640474B9626FCE441363C76649CDB', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p25-5', 'doc-03-nist-sp-800-150', '', 25, 'Organizations wishing to consume information can subscribe to or access various delivery mechanisms offered by a community such as web services, email or text alerts, and RSS feeds. Such sharing communities generally make no assertions regarding the quality and accuracy of data provided by their members, and the degree to which the information should be trusted depends on the reputation of submitters (if known).', 'kb-doc-03-nist-sp-800-150-p25-5', 0, 64, '03-nist-sp-800-150', 'retrieved', '0DAAC5E1BE7E17DD905ECFD685A9EE6B7B052694A5375D9EB05779F47D36C9F6', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p25-6', 'doc-03-nist-sp-800-150', '', 25, 'In contrast, formal sharing communities may define specific membership rules such as: • Membership fee structures; • Eligibility requirements for institutions (e.g., must operate within a specific industry sector); • Eligibility requirements for individuals (e.g., must have enterprise-wide security responsibilities); • Nomination or sponsorship requirements (i.e., brokered trust); • Probationary membership period requirements; • Types of threat information the community provides/accepts; • Standard delivery mechanisms, formats, and protocols supported by the community; and • Required organizational cybersecurity capabilities.', 'kb-doc-03-nist-sp-800-150-p25-6', 0, 78, '03-nist-sp-800-150', 'retrieved', '239742E51FA5D68F2860A9A12940200DD99F678C6A5113226A9E85091F41DD3C', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p25-7', 'doc-03-nist-sp-800-150', '', 25, 'Formal communities may recruit members by invitation or through sponsorship, and, as such, members are vetted. Membership rosters in formal communities are generally more stable than those of informal communities. The exchange of information in a formal community is often governed through service level agreements (SLAs), NDAs, and other agreements that describe the responsibilities of its members and participating organizations. Some communities collect an annual membership fee to cover the services and administrative costs of the community. These fees vary by community and the fee structure is sometimes tiered, providing for different levels of membership and service.', 'kb-doc-03-nist-sp-800-150-p25-7', 0, 97, '03-nist-sp-800-150', 'retrieved', '19E6D0C59FB7F596A6F48A93E8D6C7090141B7773561127A445068192179140B', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p25-8', 'doc-03-nist-sp-800-150', '', 25, 'Before entering into information sharing agreements, an organization should obtain approval from the: • Leadership team that has oversight for information sharing activities and for controlling the resources necessary to support the organization’s information sharing goals;', 'kb-doc-03-nist-sp-800-150-p25-8', 0, 36, '03-nist-sp-800-150', 'retrieved', '59838349BE7429061712B58EEB5B2E4935537233EE1AF4EE3F9BC65C116147B1', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p26-2', 'doc-03-nist-sp-800-150', '', 26, '• Legal team or those with the authority to enter into commitments; and • Privacy officers and other key stakeholders that have a role in the collection, ingest, storage, analysis, publication, or protection of threat information.', 'kb-doc-03-nist-sp-800-150-p26-2', 0, 36, '03-nist-sp-800-150', 'retrieved', '4E08CBE429E2FD367D46C76364672D278BE181B3D5CE45910582A1C0527DAE00', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p26-3', 'doc-03-nist-sp-800-150', '', 26, 'When choosing a sharing community, consideration should be given to the types of information that are shared within the community, the structure and dynamics of the community, and the cost of entry and sustainment of membership. When evaluating how information is shared within a community, an organization should consider the following questions: • Is the threat information shared within the community relevant and does it complement existing threat information by providing meaningful insights in the context of an organization’s threat environment? • Is the threat information exchanged within the community actionable? • Does the community have mechanisms in place to accept non-attributed threat information submissions and the ability to protect a submitter’s identity? • Is the threat information timely, reliable, and of known good quality? • Are the information exchange formats used by the community compatible with the infrastructure and tools used in an organization? • Given the frequency and volume of data sent by a community, does an organization have the capacity to ingest/analyze/store the information? In addition to the information shared within a community, consideration should also be given to the dynamics of the community and its participants, including: • What is the size and composition of the community? (e.g., number of participants, information producers, and information consumers) • How active is the community? (e.g., number of submissions or requests per day) • Are community members recruited and vetted? If so, how? • What are the technical skills and proficiencies of the community members? • What is the community’s governance model? • What are the initial and sustained costs of membership? • What type of sharing agreement does the community use? • Is the sharing agreement well-aligned with an organization’s goals, objectives, and business rules? • What are the community’s data retention and disposal policies? When researching sharing communities, organizations are encouraged to have conversations with current or former members regarding their experiences as a participant in a community. Such conversation can provide additional insight and help an organization assess the trustworthiness of a prospective community.', 'kb-doc-03-nist-sp-800-150-p26-3', 0, 338, '03-nist-sp-800-150', 'retrieved', '6E71517617F08BB235D32E6C1F665FB8C0BEF520FE226C1C20E34780DBD41FC7', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p26-4', 'doc-03-nist-sp-800-150', '', 26, '3.6 Plan to Provide Ongoing Support for Information Sharing Activities Organizations should develop a support plan that addresses information sharing infrastructure maintenance and user support. The plan should identify the personnel, funding, infrastructure, and processes needed to:', 'kb-doc-03-nist-sp-800-150-p26-4', 0, 37, '03-nist-sp-800-150', 'retrieved', 'C959A6A7D0A273A0DA89A850E39A3699A3130647FFE69EF428A6AF020AC723A2', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p27-2', 'doc-03-nist-sp-800-150', '', 27, '• Collect and analyze the information from both internal and external sources, • Acquire and deploy protective measures, and • Acquire and deploy a monitoring and threat detection infrastructure.', 'kb-doc-03-nist-sp-800-150-p27-2', 0, 29, '03-nist-sp-800-150', 'retrieved', '455C4FF7B668EFB6391E199F22ED21648A3DC7D2B53FE5D1EB5BC8E0EF0B05BA', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p27-3', 'doc-03-nist-sp-800-150', '', 27, 'Organizations should provide funding for the personnel, infrastructure, and training required for ongoing operational support for data collection, storage, analysis, and dissemination; for technology refreshment; and for membership or service fees required for community participation. Although participation in information sharing activities will require ongoing funding, effective use of threat information may avoid the potentially much larger costs of successful attacks.', 'kb-doc-03-nist-sp-800-150-p27-3', 0, 60, '03-nist-sp-800-150', 'retrieved', '13EDC54F526CD341A95AE217F9F0F4768B362199F749A00B4C5E0FCB820A9746', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p28-1', 'doc-03-nist-sp-800-150', '', 28, 'NIST SP 800-150 GUIDE TO CYBER THREAT INFORMATION SHARING 20 This publication is available free of charge from: http://dx.doi.org/10.6028/NIST.SP.800-150 4. Participating in Sharing Relationships An organization’s participation in an information sharing community will typically include some or all of the following activities: • Engage in ongoing communication (section 4.1), • Consume and respond to security alerts (section 4.2), • Consume and use indicators (section 4.3), • Organize and store indicators (section 4.4), and • Produce and publish indicators (section 4.5). The following sections describe these activities in greater detail. Organizations just starting their threat information sharing efforts should initially choose one or two activities to focus on and should consider adding activities as their information sharing capability matures. Organizations should understand that threat information sharing augments—not replaces—an organization’s fundamental cybersecurity capabilities, regardless of the maturity of their information sharing practices.', 'kb-doc-03-nist-sp-800-150-p28-1', 0, 140, '03-nist-sp-800-150', 'retrieved', 'A800677A9199FF43E9153A11D11B04C6C3DF75249D9C60233E724E56FADE0E0B', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p28-2', 'doc-03-nist-sp-800-150', '', 28, '4.1 Engage in Ongoing Communication Information sharing communities use a variety of communications methods to share threat information with their members. Most organizations can receive threat information via email lists, text alerts, and web portals without infrastructure investments specific to information sharing, although the content received through these delivery channels may need to be manually processed (e.g., “cut and paste” into tools).', 'kb-doc-03-nist-sp-800-150-p28-2', 0, 62, '03-nist-sp-800-150', 'retrieved', 'FE40D9FEA4062DB656123367768B7415E283A776C6CCCABE94DFA8309B8ABE01', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p28-3', 'doc-03-nist-sp-800-150', '', 28, 'Organizations with security tools that support standard data formats can use standards-based data feeds that enable semi-automated ingest, processing, and use of threat information. Other information sharing methods, such as conferences and workshops, require dedicated staff and travel. Organizations that actively produce and share threat information are likely to incur higher communication costs.', 'kb-doc-03-nist-sp-800-150-p28-3', 0, 53, '03-nist-sp-800-150', 'retrieved', '966147F9CF626E87D2B7DA08CC757EC96989601C89B2C20068021DE7EC627A28', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p28-4', 'doc-03-nist-sp-800-150', '', 28, 'Communications may be event-driven (i.e., in response to the actions or behavior of an actor) or periodic, such as bi-weekly reviews, teleconferences, and annual conferences.', 'kb-doc-03-nist-sp-800-150-p28-4', 0, 25, '03-nist-sp-800-150', 'retrieved', '9F3EE22B83DE177BD8CAF4F6B81E581CE98C4FD4E50B693773BBA5C43B3D1575', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p28-5', 'doc-03-nist-sp-800-150', '', 28, 'The level of detail, volume, and frequency of messages delivered in human-readable formats varies widely across information sharing communities. Some communities seek to deliver the most current threat information with minimal latency. In contrast, some recipients using threat information for trending and analysis may prefer summary data and may have no need for near real-time delivery of detailed information. To reduce the number of messages generated, sharing communities sometimes provide the option of subscribing to digests (i.e., compilations of messages over time intervals) rather than receiving individual messages.', 'kb-doc-03-nist-sp-800-150-p28-5', 0, 88, '03-nist-sp-800-150', 'retrieved', 'B09D2E462CCD07272756AB9234522C5F208F596CA7DFAE05FC01B6093270FE03', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p28-6', 'doc-03-nist-sp-800-150', '', 28, 'An organization that has recently joined an information sharing community may require time to integrate new threat information sources into its existing cybersecurity practices, configure security tools, and train decision makers on how to interpret and act upon the threat information. During this ramp-up period, an organization should consult any best practices guidance offered by a community, observe and learn from the interactions of more experienced members, and query community support resources (e.g., community knowledgebase, FAQs, blogs). Community-sponsored training events also provide opportunities for less mature organizations and inexperienced employees to gain practical insights from skilled practitioners.', 'kb-doc-03-nist-sp-800-150-p28-6', 0, 97, '03-nist-sp-800-150', 'retrieved', 'AF9506492D2B72CE9C9C53493F3D7EE5465D0145033CA44D8F271ACA69797AB1', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p28-7', 'doc-03-nist-sp-800-150', '', 28, 'Organizations should also establish recruitment and retention processes that reduce personnel turnover and foster the formation of trusted professional relationships between sharing communities and organizations. Retention of skilled staff mitigates the loss of institutional knowledge, and preserves investments in training.', 'kb-doc-03-nist-sp-800-150-p28-7', 0, 40, '03-nist-sp-800-150', 'retrieved', 'C9D56FE616D375FC6D5B6EC15471474BC86EF355A4F805D924DD1E2DA3639E51', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p29-2', 'doc-03-nist-sp-800-150', '', 29, 'Ongoing participation in a sharing community is essential for fostering trust, establishing stronger ties to other members, and continuously improving practices. Organizations that actively participate in community-sponsored conference calls and face-to-face meetings are better able to establish trust with other members and consequently to effectively collaborate over time.', 'kb-doc-03-nist-sp-800-150-p29-2', 0, 48, '03-nist-sp-800-150', 'retrieved', 'A028EDCCF2D9350FCE181F77EE8FB078B79E29649CF485A648AEF02EC6E820FF', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p29-3', 'doc-03-nist-sp-800-150', '', 29, '4.2 Consume and Respond to Security Alerts An information sharing community may publish security alerts notifying community members of emerging vulnerabilities, exploits, and other security issues. Fields that commonly appear in security alerts such as US-CERT alerts, NVD vulnerability advisories, and vendor security bulletins include10: • Brief overview/executive summary and detailed description, which would include indicators; • Platforms affected (e.g., operating system, application, hardware); • Estimated impact (e.g., system crash, data exfiltration, application hijacking)11; • Severity rating (e.g., Common Vulnerability Scoring System (CVSS) [11]); • Mitigation options, including permanent fixes and/or temporary workarounds; • References for more information; and • Alert metadata (e.g., alert creation and modification dates, acknowledgments).', 'kb-doc-03-nist-sp-800-150-p29-3', 0, 109, '03-nist-sp-800-150', 'retrieved', '4FF80CCD734CE05DCAEB3C3557087DACE9EFAD0335388C946EC54A7913042688', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p29-4', 'doc-03-nist-sp-800-150', '', 29, 'Upon receipt of a security alert, an organization should determine if the alert came from a trusted, reliable source. When alerts originate from unknown or untrusted sources, organizations may need to apply greater scrutiny and/or seek independent confirmation before taking action. If an alert is deemed credible and it applies to systems, applications, or hardware that the organization owns or operates; the organization should determine a suitable course of action.', 'kb-doc-03-nist-sp-800-150-p29-4', 0, 70, '03-nist-sp-800-150', 'retrieved', 'B622132D99837935FE2DA2B1C6BCF31D1A6D4759AA6FA37D21C09A34489661B8', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p29-5', 'doc-03-nist-sp-800-150', '', 29, 'When determining a proper response, an organization should characterize the overall impact of an alert by assessing factors such as the severity of the alert, the number of affected systems within the organization, the effects an attack might have on the organization’s mission-critical functions, and any operational impacts related to the deployment of mitigating security controls. This assessment should inform the prioritization and approach for response actions. Response actions include activities such as identifying and extracting indicators from an alert, using indicators to develop and deploy detection signatures, making configuration changes, applying patches, notifying personnel of threats, and implementing or enhancing security controls. Extracting indicators is largely a manual process today but there are clear incentives for automating indicator handling workflows. Manual processing of indicators can be time- consuming, tedious, error-prone, and slow; automation of the activities allows analysts to focus on the interpretation of information, rather than routine data manipulations.', 'kb-doc-03-nist-sp-800-150-p29-5', 0, 151, '03-nist-sp-800-150', 'retrieved', 'EC87BBCFEDE68C6BF4616F10A61ADAA4F4F7829354DF256EA1E7A463EB8F447F', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p29-6', 'doc-03-nist-sp-800-150', '', 29, '4.3 Consume and Use Indicators The consumption and use of indicators from external feeds is often a multi-step process that includes some, if not all, of the following activities:', 'kb-doc-03-nist-sp-800-150-p29-6', 0, 29, '03-nist-sp-800-150', 'retrieved', 'D85F7EBC47B9D35B5C96076CEF75EF59DA79F9BA1AC00B4AE0CF3890873B065F', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p29-8', 'doc-03-nist-sp-800-150', '', 29, '11 A more extensive list of potential effects is given in the MITRE Common Weakness Enumeration (http://cwe.mitre.org/) and Common Vulnerabilities and Exposures (http://cve.mitre.org/) listings.', 'kb-doc-03-nist-sp-800-150-p29-8', 0, 24, '03-nist-sp-800-150', 'retrieved', '7F214114B79CE6E62FFB72E39C13FCAA8EF320C2FB574FC4906836A57367B993', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p30-1', 'doc-03-nist-sp-800-150', '', 30, 'NIST SP 800-150 GUIDE TO CYBER THREAT INFORMATION SHARING 22 This publication is available free of charge from: http://dx.doi.org/10.6028/NIST.SP.800-150 • Validation: verifying the integrity of indicator content and provenance through digital signatures, c ryptographic hashes, or other means. • Decryption: transforming encrypted indicator files or data streams back to their original format. • Decompression: unpacking compressed indicator files, archive files (e.g., zip, tar), or data streams. • Content extraction: parsing indicator files and extracting indicators of interest to an organization.12 • P rioritization: processing indicators based on relative importance, the perceived value of a data source, the overall confidence in the data, any operational requirements that specify that data sources be processed in a particular order, the amount of effort required to transform the data into actionable information, or other factors. • Categorization: reviewing indicator metadata to determine its security designation and handling requirements. Sensitive information may require encrypted storage, more stringent access control, or limitations on distribution. These activities are typically performed in the order described above, but the order may vary based on specific operational or security requirements. Where feasible, organizations are encouraged to use automated techniques to make the indicators available more quickly and reduce manual effort. In cases where indicators are being informally shared, such as through email, indicator prioritization and categorization are still important and should be performed by the recipient.', 'kb-doc-03-nist-sp-800-150-p30-1', 0, 226, '03-nist-sp-800-150', 'retrieved', '0690A80D5B4413ADAFC60FCEAC3DEF2E8911D63DC2E7BD7F76C60341D8906547', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p30-2', 'doc-03-nist-sp-800-150', '', 30, 'Ideally, indicators are: • Timely. Indicators should be delivered with minimal latency thereby allowing additional time for r ecipients to prepare suitable responses. The time criticality of indicators depends on the characteristics of the threats, including their severity, speed, and ease of propagation, the i nfrastructure being targeted, the TTPs being used, and the capabilities of the actor(s). • Relevant. Indicators should be applicable to a recipient’s operating environment and address threats t he organization is likely to face. The unnecessary processing of extraneous indicators creates a dditional work for analysts and slows down prioritization and categorization actions. • Accurate. Indicators should be correct, complete, and unambiguous. Inaccurate or incomplete information introduces uncertainty and may prevent critical action, stimulate unnecessary action, result in ineffective responses, or instill a false sense of security. Recipients should be made aware of any uncertainty or caveats regarding the accuracy of an indicator. • Specific. Indicators should provide clear descriptions of observable events that recipients can use to d etect threats while minimizing false positives/negatives. • Actionable. Indicators should provide enough information and context to allow recipients to develop a suitable response. In practice, an indicator may exhibit some, but not all, of these characteristics. For example, a lone indicator may be ambiguous, but when aggregated and analyzed with threat information from other 12 The extraction and handling of content like malware samples should be limited to organizations and individuals who have the knowledge, ability, and infrastructure needed to safely analyze malware. Special handling precautions should be stated and followed to prevent inadvertent introduction of malicious code onto production networks.', 'kb-doc-03-nist-sp-800-150-p30-2', 0, 265, '03-nist-sp-800-150', 'retrieved', 'A62532F8E2B9DDEFD011A3B6ABDDB27C874F9881ECDA1C61CB65BCBE9DD0DF5B', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p31-2', 'doc-03-nist-sp-800-150', '', 31, 'sources the indicator is enriched and demonstrates additional value. Also threat information from multiple sources may vary in precision and accuracy and it is important for users to be able to evaluate the information and assign tags that describe the quality or confidence level of the information. The tags are especially important when an organization needs to resolve discrepancies between threat information sources. As organizations enrich indicators, any new insights should be shared so that the entire community may benefit. Organizations may, for example, use externally and internally-generated indicators to: • Add or modify rules or signatures used by firewalls, intrusion detection systems, data loss prevention systems, and/or other security controls to block or alert on activity matching the indicators (for example, connections involving IP addresses on a blacklist); • Configure security information and event management solutions or other log management-related systems to help with analysis of security log data; • Scan security logs, systems, or other sources of information, using indicators as search keys, to identify systems that may have already been compromised; • Find matching records when investigating an incident or potential incident to learn more about a threat, and to help hasten incident response and recovery actions; • Provide additional information to security operations center analysts; • Educate staff on threat characteristics; and • Identify threat trends that may suggest changes to security controls are needed.', 'kb-doc-03-nist-sp-800-150-p31-2', 0, 229, '03-nist-sp-800-150', 'retrieved', 'F5923379A9AA27814689AA4B7A2DA4AE0AB12C9F175661A6E394721B30B58353', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p31-3', 'doc-03-nist-sp-800-150', '', 31, 'Typically, an organization’s willingness to use indicators from external sources is strongly affected by the level of trust the organization has in the source. Indicators received from a trusted source might be put to immediate use to detect and respond to a threat. In contrast, indicators originating from an untrusted source may require independent validation, additional research, or testing before use. Indicator use might also be affected by other factors, such as an organization’s tolerance for service disruptions. For some organizations, security is paramount and occasionally blocking benign activity is considered acceptable.', 'kb-doc-03-nist-sp-800-150-p31-3', 0, 92, '03-nist-sp-800-150', 'retrieved', 'D09274C941558D325FA1F1B1EEF64934DB9F43636DDD31509A68F28B65FE3F5C', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p31-4', 'doc-03-nist-sp-800-150', '', 31, 'For other organizations, service availability may be so important that possible malicious activity might only trigger monitoring.', 'kb-doc-03-nist-sp-800-150-p31-4', 0, 17, '03-nist-sp-800-150', 'retrieved', '07817222441CC69025DF4ECBD9D88F64E96CE61849C8C23223C216B0A3A50FE8', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p31-5', 'doc-03-nist-sp-800-150', '', 31, 'An organization should carefully consider the characteristics of indicators that it receives and should take a risk-based approach to determining how indicators can be most effectively used. An organization may find that a specific indicator is useful in some situations but not in others. Ultimately each organization must decide how to best use indicators.', 'kb-doc-03-nist-sp-800-150-p31-5', 0, 54, '03-nist-sp-800-150', 'retrieved', '9882A7560B47374C23F055805F1BB89849D6E10936370AD5C532F9B831FC76BA', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p31-6', 'doc-03-nist-sp-800-150', '', 31, '4.4 Organize and Store Cyber Threat Information Organizations may collect indicators from a variety of sources, including open source repositories, commercial threat feeds, and external partners. Depending on how indicators are being used, there may be a need to organize them in a knowledgebase. Free-form methods such as wikis can be quite flexible and suitable for developing working notes and indicator metadata. Structured databases are also useful for storing, organizing, tracking, querying, and analyzing collections of indicators.', 'kb-doc-03-nist-sp-800-150-p31-6', 0, 77, '03-nist-sp-800-150', 'retrieved', '1AEFD0CE52810F213F5B228F41FACD92E629F69DBF4D47EBC50E85115D641822', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p32-2', 'doc-03-nist-sp-800-150', '', 32, 'Information commonly recorded in a knowledgebase includes the following, when known: • Source of an indicator; • Rules governing the use or sharing of an indicator; • Date or time an indicator was collected; • Length of time that an indicator is still considered valid; • Whether or not attacks associated with an indicator have targeted specific organizations or sectors; • Any Common Vulnerability Enumeration (CVE), Common Platform Enumeration (CPE), Common Weakness Enumeration (CWE), Common Configuration Enumeration (CCE) records associated with an indicator; • Groups or actors associated with an indicator; • Aliases of any associated actors; • TTPs commonly used by an actor; • Motives or intent of an associated actor; • Individuals or types of individuals targeted in associated attacks; and • Systems targeted in attacks.', 'kb-doc-03-nist-sp-800-150-p32-2', 0, 128, '03-nist-sp-800-150', 'retrieved', 'E19CF60B931274C92BB2A2CA82987D4AAADC149935541378E1DE441ACB7A8844', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p32-3', 'doc-03-nist-sp-800-150', '', 32, 'An indicator knowledgebase is an attractive target of attack; therefore effective security practices should be followed, including implementing access controls, performing regular backups, maintaining operating system and application software by installing current patches, verifying secure configurations, and following software development best practices for the production of any in-house software used for the knowledgebase.13 Organizations should establish policies and procedures that address the disposition of indicators (and threat information in general). Policies and procedures should define data retention requirements for short (online) and long (offline) term availability of indicator information. Information handling and retention requirements may change once threat information is entered into evidence. Evidence acquired during any incident investigations, for instance, should be collected and preserved using best practices for data preservation following chain of custody requirements and other laws pertaining to the submission of evidence. A more detailed treatment of forensic techniques related to chain of custody and preserving information integrity is available in NIST Special Publication 800-86 [12] and Section 3.3.2 of NIST Special Publication 800-61 [1].', 'kb-doc-03-nist-sp-800-150-p32-3', 0, 169, '03-nist-sp-800-150', 'retrieved', '3A61AC8A92669C45EC311BF87AB6222EC68D4598EF48EB818C0CD22B2C3E579F', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p32-4', 'doc-03-nist-sp-800-150', '', 32, 'For indicators that are not needed as evidence, organizations should determine proper retention policies.14 Although retaining threat information has costs, detailed information may provide historical value as well as help new sharing community members and partners understand the persistence and evolution of different actors and attack types. Other considerations, such as financial, legal, contractual, or regulatory issues, may limit data retention to a fixed period of months or years. Once a retention schedule is identified, organizations should either archive or destroy the indicators per applicable policies.15', 'kb-doc-03-nist-sp-800-150-p32-4', 0, 86, '03-nist-sp-800-150', 'retrieved', '859B236C433C26F0F4D95802721688714B49AECDFC087235913D94B1412324DF', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p32-5', 'doc-03-nist-sp-800-150', '', 32, '13 The NIST Software Assurance Metrics and Tool Evaluation (SAMATE) project seeks to develop standard evaluation measures and methods for software assurance. See http://samate.nist.gov/index.php/SAMATE_Publications.html.', 'kb-doc-03-nist-sp-800-150-p32-5', 0, 24, '03-nist-sp-800-150', 'retrieved', 'B07289FD16D69663D10B474862F2CCF43B6E5B527204DA32CDB373A5076221EF', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
