INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p32-6', 'doc-03-nist-sp-800-150', '', 32, '14 Federal agencies are subject to the National Archives and Records Administration (NARA) General Records Schedule as well as agency-specific retention policies.', 'kb-doc-03-nist-sp-800-150-p32-6', 0, 22, '03-nist-sp-800-150', 'retrieved', '498FADA98DD5E0C87C9926382BC0F00D3990D5E32FBBCE65675E6FE8E20D671E', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
