INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p32-7', 'doc-03-nist-sp-800-150', '', 32, '15 NIST SP 800-88 [14] provides guidance to assist organizations in making risk-based decisions regarding the sanitization and disposition of media and information.', 'kb-doc-03-nist-sp-800-150-p32-7', 0, 23, '03-nist-sp-800-150', 'retrieved', '476B585416F59377E300C3361AB5AC882C894344C321DDAA123E6DD1A6363ACB', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p33-1', 'doc-03-nist-sp-800-150', '', 33, 'NIST SP 800-150 GUIDE TO CYBER THREAT INFORMATION SHARING 25 This publication is available free of charge from: http://dx.doi.org/10.6028/NIST.SP.800-150 4.5 Produce and Publish Indicators Many organizations only consume indicators. However, some organizations, often those with more advanced security capabilities, choose to produce and publish their own indicators. An organization may benefit substantially by producing threat information. For example, an organization may gain greater expertise, help other organizations more effectively respond to threats in their environments, and foster trust with other community members. These effects are important for building and sustaining the flow of threat information that ultimately benefits a producing organization. A producer of shared threat information must decide what, if any, metadata should accompany shared information, what data formats should be used, how sensitive data should be handled, and how information sharing rules should be updated over time. The following subsections address these issues.', 'kb-doc-03-nist-sp-800-150-p33-1', 0, 145, '03-nist-sp-800-150', 'retrieved', '58AD4B1FDC92354DCCB3D2C5AE2588CB96E5BACF3491060ACEC2C8A29DCF5DAA', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p33-2', 'doc-03-nist-sp-800-150', '', 33, '4.5.1 Indicator Enrichment Indicators that are produced and published should include metadata that provides context for each indicator, describes how the indicator is to be used and interpreted and how the indicator relates to other indicators. Metadata may also include sensitivity designations and provenance information (e.g., what tool was used to acquire the data, how the data was processed, who collected the data). As indicators are created, aggregated, or enriched, their sensitivity and classification should be reevaluated. An aggregation, association, or enrichment process may enable re-identification (e.g., using data mining techniques) or elevate the sensitivity of the information, thus necessitating additional data handling restrictions.', 'kb-doc-03-nist-sp-800-150-p33-2', 0, 104, '03-nist-sp-800-150', 'retrieved', '65CEA0C8F9A7E0A935D655BE0BB6FD4597FB4D854155A8ABCE07610293050C03', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p33-3', 'doc-03-nist-sp-800-150', '', 33, 'The indicator production process should provide a mechanism for publishing indicators, updating indicators and associated metadata, and retracting submissions that are incorrect or perhaps inadvertently shared. Any automated mechanisms should be hardened and tested to ensure that they do not become viable attack vectors for threat actors. Organizations that share indicators should provide a feedback mechanism that allows sharing partners to submit error reports, suggest improvements, or request additional information about the indicators. Such feedback plays an important role in the enrichment, maturation, and quality of the indicators shared within a community.', 'kb-doc-03-nist-sp-800-150-p33-3', 0, 92, '03-nist-sp-800-150', 'retrieved', 'FAE65CCAAD36F81FB3F20D76F55FBB6AEB3B82EA93266B5086362BF33B3930C6', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p33-4', 'doc-03-nist-sp-800-150', '', 33, 'Some information shared within a community may be marked as “currently under investigation” and may require that members avoid sharing beyond the collective; such markings may also prohibit members from performing active information collection (such as retrieving malware samples from a suspect website, or performing DNS lookups on suspect hostnames) that might tip off a potential actor or otherwise compromise investigative activities. At some point, such information will probably have its distribution and investigation restrictions downgraded, so a mechanism to change the marking or to add a revised marking such as “downgraded to GREEN as of 12/20/2015” is useful.', 'kb-doc-03-nist-sp-800-150-p33-4', 0, 99, '03-nist-sp-800-150', 'retrieved', 'E7070D2BC37F6995EECD5959B01BA57FBFB07B9C7A75ACD437A9957D30C140A0', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p33-5', 'doc-03-nist-sp-800-150', '', 33, '4.5.2 Standard Data Formats The use of standard data formats for the exchange of indicators enhances interoperability and allows information to be exchanged with greater speed. Unstructured formats (e.g., text documents, email) are suitable for high-level threat reports and ad hoc exchanges of indicator information and other materials intended to be read by security personnel rather than machines. For time-critical exchanges of indicators, however, such as automatically configuring a firewall to block specified communications, the use of standard data formats is encouraged because such formats reduce the need for human assistance.', 'kb-doc-03-nist-sp-800-150-p33-5', 0, 91, '03-nist-sp-800-150', 'retrieved', 'A9AE68F8E87D02AD151D18E217E11624B0F753762BDBB21F2F1ED089F2DA2BA7', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p33-6', 'doc-03-nist-sp-800-150', '', 33, 'Organizations are encouraged to participate in threat information sharing standards development activities by sharing use cases, identifying desired features, and providing feedback to standards development', 'kb-doc-03-nist-sp-800-150-p33-6', 0, 25, '03-nist-sp-800-150', 'retrieved', '4101EF91E09BED8A5682695C1CF4AF994B9C7E5A3D431A8D7A1C868D75D90E8F', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p34-2', 'doc-03-nist-sp-800-150', '', 34, 'organizations.16 Organizations should seek out data formats and exchange protocols that can effectively support their key threat information sharing use cases, demonstrate a high degree of maturity, broad adoption, and enable interoperability between a wide range of products and/or organizations.', 'kb-doc-03-nist-sp-800-150-p34-2', 0, 40, '03-nist-sp-800-150', 'retrieved', 'A75EA7FC4D357767625B9B481AFDA073DE0B258C2F47305EBCA1E9A7FFC0202D', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p34-3', 'doc-03-nist-sp-800-150', '', 34, '4.5.3 Protection of Sensitive Data The indicators that an organization publishes may be sensitive, so proper safeguards should be used to prevent unauthorized disclosure or modification. Indicator data can be protected using a variety of methods, including encrypted network communications, authentication and authorization mechanisms, and storage in a hardened repository. If a repository is used, an organization should have a written SLA for the repository that specifies expected availability, security posture requirements, and acceptable use policies. When producing indicators that may contain sensitive information, proper sharing rules (see section 3.4) should be followed, and information should be shared only with community members that are trusted to follow sharing rules and that have agreed to do so.', 'kb-doc-03-nist-sp-800-150-p34-3', 0, 116, '03-nist-sp-800-150', 'retrieved', '2EBB644AF6D7607152A045AAC2273CD7A3CCE334C471DF1C4F9FB7B73702DFCC', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p35-2', 'doc-03-nist-sp-800-150', '', 35, 'Appendix A—Cyber Threat Information Sharing Scenarios This appendix presents some scenarios that describe threat information sharing in real-world applications.', 'kb-doc-03-nist-sp-800-150-p35-2', 0, 19, '03-nist-sp-800-150', 'retrieved', '0C65085F46F81987060E39354DE80D0C2DFF26705D66C4582BA8FEF75B657DA1', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p35-3', 'doc-03-nist-sp-800-150', '', 35, 'These scenarios seek to show how sharing and coordination can increase the efficiency and effectiveness of an organization’s cybersecurity capabilities. These scenarios represent only a small number of the possible applications of information sharing and collaboration.', 'kb-doc-03-nist-sp-800-150-p35-3', 0, 36, '03-nist-sp-800-150', 'retrieved', '72D41B25D839085A05275CA9DCCE6E6618B886B92317E2504227D092ABB781F2', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p35-5', 'doc-03-nist-sp-800-150', '', 35, 'A nation-state regularly targets companies in a certain industry sector over several months. The attacks come in the form of targeted emails that carry malicious attachments containing a software exploit that, upon opening, launches malware on a victim’s system. Systems that are successfully compromised by the malware are then reconfigured by the malware to contact command and control servers and other infrastructure operated by the actor to receive additional instructions, download other malware, and perform data exfiltration.', 'kb-doc-03-nist-sp-800-150-p35-5', 0, 77, '03-nist-sp-800-150', 'retrieved', '7FA4066F26335A905F137AC5070E619FE5C347D506AF7DD0AC13E9D360DCE17D', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p35-6', 'doc-03-nist-sp-800-150', '', 35, 'Many companies within this industry sector are members of a formal threat information sharing organization in which a central forum is used to post information about observed threats. The posts describe details relevant to detecting and defending against the threat, such as the sender addresses of phishing emails, samples of malware collected from the attacks, analysis of exploit code used by actors, the IPs and URLs associated with the actor’s command and control servers, and other infrastructure involved with attacks.', 'kb-doc-03-nist-sp-800-150-p35-6', 0, 80, '03-nist-sp-800-150', 'retrieved', 'DAB262017C81B4EC77A3C373958A64AC759141E2BB77E12AF29232CF5BCEEDC8', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p35-7', 'doc-03-nist-sp-800-150', '', 35, 'As soon as one company’s security team identifies a new attack, the information is shared with its peers within the forum. One of the companies (A) that participates in the forum has advanced malware analysis capabilities and is able to further characterize the actor and its command and control infrastructure using a malware sample shared via the forum by another company (B). Company A then shares back the information gained through its analysis of the malware. Through B’s sharing of the malware sample, the community benefits from the malware analysis capabilities of company A, and is able to quickly and efficiently detect and protect against similar attacks. In this scenario, an attack faced by one company contributes to another’s defense.', 'kb-doc-03-nist-sp-800-150-p35-7', 0, 120, '03-nist-sp-800-150', 'retrieved', 'FEED76F50013F87920A1FDF06A02EFED7F674C9CC9538D691526D3296A074578', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p35-9', 'doc-03-nist-sp-800-150', '', 35, 'Cybersecurity analysts from companies in a business sector have been sharing indicators and malware samples in an online forum over the past few years. Each company performs independent analysis of the attacks and observes consistent patterns over time, with groups of events often having some commonalities, such as the type of malware used, the DNS domains of command and control channels, and other technical indicators. These observations lead the analysts to suspect that the attacks are not fully random, but part of a larger coordinated set of actions.', 'kb-doc-03-nist-sp-800-150-p35-9', 0, 88, '03-nist-sp-800-150', 'retrieved', 'AC5E45460AE6D844AF04197BD2625F1DFF8B8660A8441ECBF850C7E375F4EAC4', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p35-10', 'doc-03-nist-sp-800-150', '', 35, 'The forum members participate in technical exchange meetings to share data, insights, and analyses of the different attacks. Through data aggregation and joint analyses, the members can identify activities that are likely attributable to a common actor or to coordination among actors. This scenario demonstrates how data fusion and analysis may help reveal collective action and campaigns by a threat actor and identify the TTPs that are used by specific actors as part of a campaign.', 'kb-doc-03-nist-sp-800-150-p35-10', 0, 76, '03-nist-sp-800-150', 'retrieved', 'BF31938ACB85FB1BCDACC095CE701B09DC844F90CD2D67A1955BC9700E1FAC43', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p36-2', 'doc-03-nist-sp-800-150', '', 36, 'group. By analyzing traffic generated by the botnet, one of the companies targeted in the attack is able to determine that the actors are using a variant of a popular DDoS tool.', 'kb-doc-03-nist-sp-800-150-p36-2', 0, 32, '03-nist-sp-800-150', 'retrieved', '7D6E503D72BDBCEF626BB09CB776060EEF1E7D3789E50FEC92C96B5BAAFE248A', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p36-3', 'doc-03-nist-sp-800-150', '', 36, 'The targeted companies are members of an ISAC and use the ISAC’s discussion portal to establish a working group to coordinate incident response activities. The working group contacts the ISAC’s law enforcement liaison, who coordinates with federal and international authorities to aid in the investigation and to gain court orders to shut down the actor’s systems.', 'kb-doc-03-nist-sp-800-150-p36-3', 0, 56, '03-nist-sp-800-150', 'retrieved', '0019B1D5EE88A0A05B658CD0390DDA17645B788B027836F02C4B84275F4AA5B4', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p36-4', 'doc-03-nist-sp-800-150', '', 36, 'The working group contacts various internet service providers (ISPs), and provides information to aid in identifying abnormal traffic to their network addresses. The ISPs assist both the affected companies and law enforcement personnel by helping to identify the upstream and downstream traffic sources, implementing routing changes, and enforcing data rate limits on these sources. Using network traffic collected by the ISPs, law enforcement agencies can identify the command and control servers, seize these assets, and identify some members of the hacktivist group.', 'kb-doc-03-nist-sp-800-150-p36-4', 0, 82, '03-nist-sp-800-150', 'retrieved', '1BA3D129F46AC7260C1CB560FF6B13241F520D26749E1A55AB4F59B071592099', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p36-5', 'doc-03-nist-sp-800-150', '', 36, 'After a technical exchange meeting among the targeted companies, several companies decide to enlist the services of content distribution providers to deploy DDoS-resistant web architectures.', 'kb-doc-03-nist-sp-800-150-p36-5', 0, 25, '03-nist-sp-800-150', 'retrieved', 'AD1EC63D53C8467D1BF92DEB72E56D61377F8F40134E0BD6A60ECF295E42B659', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p36-7', 'doc-03-nist-sp-800-150', '', 36, 'A cyber crime group makes use of a publicly available conference attendee list to target specific individuals with a wave of phishing emails. The group is able to identify attendees who are members of the target organization’s corporate accounting team (i.e., individuals who may have the authority to authorize payments or funds transfers). Using targeted malware, distributed through phishing attacks, the group tries to compromise machines and accounts to complete unauthorized electronic payments and funds transfers to overseas businesses.', 'kb-doc-03-nist-sp-800-150-p36-7', 0, 79, '03-nist-sp-800-150', 'retrieved', 'C51280EF39D443B875DD822217395F88CFA941055F39FB8F65C12A4914ABCC31', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p36-8', 'doc-03-nist-sp-800-150', '', 36, 'One company is able to identify the phishing attack against personnel within its corporate accounting team and learns, during their investigation, that all the recipients targeted during the attack had attended the same conference six months earlier. The company’s CSIRT contacts the conference organizers, as well as representatives from other organizations that attended the conference. The affected organizations arrange a conference call to share specific information (e.g., email header content, attachments, embedded URLs) regarding the attacks. Using the shared indicators, other conference attendees review their mail and network traffic logs to identify potentially compromised hosts. These companies agree to ongoing collaboration and information sharing about future attacks via an informal email list.', 'kb-doc-03-nist-sp-800-150-p36-8', 0, 112, '03-nist-sp-800-150', 'retrieved', '5CB25CA34A488FFD75C2C653305F66078EAF51635C2A30DF5A0E3E917C86A5AB', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p37-2', 'doc-03-nist-sp-800-150', '', 37, 'fixes the vulnerability, and the security operations team deploys logging and intrusion detection signatures to identify any similar future attacks.', 'kb-doc-03-nist-sp-800-150-p37-2', 0, 20, '03-nist-sp-800-150', 'retrieved', '6618BF4618BEF868C6A73EF53B2D2D4C01179CCB1DCCF9BF178328705D0AE05E', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p37-3', 'doc-03-nist-sp-800-150', '', 37, 'Because the security teams of the two companies had agreements and processes in place for a joint response, had pre-established contacts and existing trust relationships, and had already understood each other’s networks and operations, the companies were able to quickly respond and recover from the incident.', 'kb-doc-03-nist-sp-800-150-p37-3', 0, 46, '03-nist-sp-800-150', 'retrieved', 'E1343A76099701E409B7F25FE03A765654C2B0435DEFB78ACA5C3136B51E33E4', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p37-5', 'doc-03-nist-sp-800-150', '', 37, 'The US-CERT receives information, from a variety of independent sources, that servers located in the U.S. are being used to carry out cyber attacks against other U.S. companies. A specific foreign actor is known to control the compromised servers. The US-CERT identifies the targeted companies and notes that most operate within the aviation industry. The US-CERT contacts the security teams of these companies and shares initial threat information, including URLs, malware, and vulnerabilities being exploited by the actor.', 'kb-doc-03-nist-sp-800-150-p37-5', 0, 78, '03-nist-sp-800-150', 'retrieved', 'C6189028782535F26D0692DF59BFC411304D1998FF161B541FBF97AFBEDE049C', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p37-6', 'doc-03-nist-sp-800-150', '', 37, 'Using the indicators, some of the affected companies are able to detect attacks against their infrastructures and to take the actions necessary to prevent the attacks from being successful. While investigating incidents, the affected companies are also able to identify new indicators or provide context regarding the attack to the US-CERT. The US-CERT is able to share these new indicators with other firms after anonymizing the sources, which leads to a more comprehensive response to the threat.', 'kb-doc-03-nist-sp-800-150-p37-6', 0, 77, '03-nist-sp-800-150', 'retrieved', '2CD9427DE160C753690F1DD0FCA892E636C471C6EE9621DEE7AC3E79078F99F2', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p37-7', 'doc-03-nist-sp-800-150', '', 37, 'Scenario 7: A Retailer Fails to Share A large retailer is subject to a cyber attack by a criminal organization. Millions of credit card numbers and account information are stolen during a breach that goes undiscovered for several weeks. The retailer does not share threat information and relies on its own security and detection capabilities. The retailer’s internal capabilities prove inadequate in the face of a sophisticated, targeted threat that uses custom malware.', 'kb-doc-03-nist-sp-800-150-p37-7', 0, 73, '03-nist-sp-800-150', 'retrieved', '1E96A37CB073885BFE8A77F1841B4184B87887321467F3BACD668524A3B2A38A', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p37-8', 'doc-03-nist-sp-800-150', '', 37, 'The breach is discovered by credit card companies investigating a rash of credit card fraud. The credit card companies determine that the commonality in the credit card fraud was purchases made from this one retailer. The credit card companies notify both law enforcement and the retailer, and an investigation is initiated.', 'kb-doc-03-nist-sp-800-150-p37-8', 0, 51, '03-nist-sp-800-150', 'retrieved', '43BCAB16F8FAC4ABE5B5232BB8A5CBF35B359014976AC83A8B75A7C643C257FA', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p37-9', 'doc-03-nist-sp-800-150', '', 37, 'The damages are extensive. The retailer notifies its customers of the theft of personal information, but does not release details of how the attack was carried out. Consequently, several other retailers are successfully attacked using the same methods in the weeks following the initial breach. The financial losses realized by the retailers, customers, and credit card issuers and the reputation loss to the retailers could have been avoided, at least in part, had the retailers engaged in active sharing of threat information with one another. The attacker is emboldened by the successful attack and benefits from the delayed response and lack of a coordination. The attacker benefits financially from the fraudulent activity and can use these additional resources to expand the scope and sophistication of their operations.', 'kb-doc-03-nist-sp-800-150-p37-9', 0, 127, '03-nist-sp-800-150', 'retrieved', '466991CD5B2F3C0350108CAAD96F16BCA79544A573B3EFBA7D29CA6CA314B922', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p38-4', 'doc-03-nist-sp-800-150', '', 38, 'Alert A brief, usually human-readable, technical notification regarding current vulnerabilities, exploits, and other security issues. Also known as an advisory, bulletin, or vulnerability note.', 'kb-doc-03-nist-sp-800-150-p38-4', 0, 24, '03-nist-sp-800-150', 'retrieved', '3AB5B87122315CDB63403C58A2C42BFD7E57E9D63AEDE89EB238EAA75298C0A0', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
