INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p38-5', 'doc-03-nist-sp-800-150', '', 38, 'Continuous Monitoring Maintaining ongoing awareness of information security, vulnerabilities, and threats to support organizational risk management decisions.', 'kb-doc-03-nist-sp-800-150-p38-5', 0, 17, '03-nist-sp-800-150', 'retrieved', '01ECE05A8DF3722B1C09DD1BB9109B89245A15F1370E9CDE9354DABBD7B40694', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
