INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p38-7', 'doc-03-nist-sp-800-150', '', 38, 'Information that law, regulation, or government-wide policy requires to have safeguarding or disseminating controls, excluding information that is classified under Executive Order 13526, Classified National Security Information, December 29, 2009, or any predecessor or successor order, or the Atomic Energy Act of 1954, as amended.', 'kb-doc-03-nist-sp-800-150-p38-7', 0, 45, '03-nist-sp-800-150', 'retrieved', 'CE4C4E7B19F9CBAEC949BDFA80DC507036B16A21FAA4FCFE88228FF25BFF4A40', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
