INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p38-9', 'doc-03-nist-sp-800-150', '', 38, 'Indicator A technical artifact or observable that suggests an attack is imminent or is currently underway, or that a compromise may have already occurred.', 'kb-doc-03-nist-sp-800-150-p38-9', 0, 24, '03-nist-sp-800-150', 'retrieved', '17FA48C7D6610C44EA2B9941893B1109BFEDEE75D2023D0AA016DE38E5216B56', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
