INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p38-10', 'doc-03-nist-sp-800-150', '', 38, 'Information Sharing and Analysis Organization An ISAO is any entity or collaboration created or employed by public- or private sector organizations, for purposes of gathering and analyzing critical cyber and related information in order to better understand security problems and interdependencies related to cyber systems, so as to ensure their availability, integrity, and reliability.', 'kb-doc-03-nist-sp-800-150-p38-10', 0, 54, '03-nist-sp-800-150', 'retrieved', '8C31B60710EC1DDF90A64FF0FEE24B2E80C27A6A929D06120BBCE88478214701', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
