INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p38-11', 'doc-03-nist-sp-800-150', '', 38, '[17] Metadata Information describing the characteristics of data including, for example, structural metadata describing data structures (e.g., data format, syntax, and semantics) and descriptive metadata describing data contents (e.g., information security labels). [8] Observable An event (benign or malicious) on a network or system.', 'kb-doc-03-nist-sp-800-150-p38-11', 0, 44, '03-nist-sp-800-150', 'retrieved', '203B935689FD7F3E9105B298EED9885FB1769A99AA28EC2DA70B0DA53FEBE646', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
