INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p38-12', 'doc-03-nist-sp-800-150', '', 38, 'Phishing Tricking individuals into disclosing sensitive personal information through deceptive computer-based means. [19] Rootkit A set of tools used by an attacker after gaining root-level access to a host to conceal the attacker’s activities on the host and permit the attacker to maintain root-level access to the host through covert means. [18] Sensitive Information Information, the loss, misuse, or unauthorized access to or modification of, that could adversely affect the national interest or the conduct of federal programs, or the privacy to which individuals are entitled under 5 U.S.C. Section 552a (the Privacy Act), but that has not been specifically authorized under criteria established by an Executive Order or an Act of Congress to be kept classified in the interest of national defense or foreign policy. [18]', 'kb-doc-03-nist-sp-800-150-p38-12', 0, 127, '03-nist-sp-800-150', 'retrieved', 'A36A28AF91E958A51A04DF08EDB515415F43BABD425748C214E1DC94ABD52539', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p39-1', 'doc-03-nist-sp-800-150', '', 39, 'NIST SP 800-150 GUIDE TO CYBER THREAT INFORMATION SHARING 31 This publication is available free of charge from: http://dx.doi.org/10.6028/NIST.SP.800-150 Sensor An intrusion detection and prevention system component that monitors and analyzes network activity and may also perform prevention actions. [14] Tactics, Techniques, and Procedures (TTPs) The behavior of an actor. A tactic is the highest-level description of this behavior, while techniques give a more detailed description of behavior in the context of a tactic, and procedures an even lower- level, highly detailed description in the context of a technique.', 'kb-doc-03-nist-sp-800-150-p39-1', 0, 89, '03-nist-sp-800-150', 'retrieved', '05F6633EDF3AC67A1B1C638CD345242318804C1B339E3D6470FEF953A1DDCE66', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p39-2', 'doc-03-nist-sp-800-150', '', 39, 'Threat Any circumstance or event with the potential to adversely impact organizational operations (including mission, functions, image, or reputation), organizational assets, individuals, other organizations, or the Nation through an information system via unauthorized access, destruction, disclosure, or modification of information, and/or denial of service.', 'kb-doc-03-nist-sp-800-150-p39-2', 0, 44, '03-nist-sp-800-150', 'retrieved', '8FE20ACBF920C527E1CB65D93DD54F6379D17423C3071164230CCD40B03CFA4B', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
