INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p39-4', 'doc-03-nist-sp-800-150', '', 39, 'Threat Information Any information related to a threat that might help an organization protect itself against a threat or detect the activities of an actor. Major types of threat information include indicators, TTPs, security alerts, threat intelligence reports, and tool configurations.', 'kb-doc-03-nist-sp-800-150-p39-4', 0, 41, '03-nist-sp-800-150', 'retrieved', '86E6D8B7C1EA8C3D8A17AAEBDC35D0031B86B68C178B0B3D06FFB83B97CC625A', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
