INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p39-5', 'doc-03-nist-sp-800-150', '', 39, 'Threat Intelligence Threat information that has been aggregated, transformed, analyzed, interpreted, or enriched to provide the necessary context for decision- making processes.', 'kb-doc-03-nist-sp-800-150-p39-5', 0, 22, '03-nist-sp-800-150', 'retrieved', '94DA5B479D17A42A95CBE0392520551B43911B594F948C89785A2602F6EDEF90', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
