VALUES ('doc-03-nist-sp-800-150-p39-6', 'doc-03-nist-sp-800-150', '', 39, 'Threat Intelligence Report A prose document that describes TTPs, actors, types of systems and information being targeted, and other threat-related information.', 'kb-doc-03-nist-sp-800-150-p39-6', 0, 21, '03-nist-sp-800-150', 'retrieved', '537404EEFB618379443E54E56E1A27E1116F8EF9B9D60095FBCE918CC9F69B37', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
