INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-03-nist-sp-800-150-p39-7', 'doc-03-nist-sp-800-150', '', 39, 'Threat Shifting The response of actors to perceived safeguards and/or countermeasures (i.e., security controls), in which actors change some characteristic of their intent/targeting in order to avoid and/or overcome those safeguards/countermeasures.', 'kb-doc-03-nist-sp-800-150-p39-7', 0, 31, '03-nist-sp-800-150', 'retrieved', 'BBAAA24F895A97E2777AA9BEA6668D5A781E6E92868A62A7F11E047AAA00553B', 'v1', '{"source_id": "03-nist-sp-800-150", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
