VALUES ('doc-04-nist-sp-800-86-p9-2', 'doc-04-nist-sp-800-86', '', 9, 'Digital forensics, also known as computer and network forensics, has many definitions.', 'kb-doc-04-nist-sp-800-86-p9-2', 0, 12, '04-nist-sp-800-86', 'retrieved', 'BB4E4906F325C2138E88DF203618D5659115F42A871E148DB77F0A9220FBD1CE', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
