INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p9-3', 'doc-04-nist-sp-800-86', '', 9, 'Generally, it is considered the application of science to the identification, collection, examination, and analysis of data while preserving the integrity of the information and maintaining a strict chain of custody for the data.', 'kb-doc-04-nist-sp-800-86-p9-3', 0, 34, '04-nist-sp-800-86', 'retrieved', '264DB4D177FCAE7F1D97F21C7EF0AFF7D97E3F1083AB7473FA2A42AC4890400B', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
