VALUES ('doc-04-nist-sp-800-86-p9-7', 'doc-04-nist-sp-800-86', '', 9, 'Because of the variety of data sources, digital forensic techniques can be used for many purposes, such as investigating crimes and internal policy violations, reconstructing computer security incidents, troubleshooting operational problems, and recovering from accidental system damage.', 'kb-doc-04-nist-sp-800-86-p9-7', 0, 37, '04-nist-sp-800-86', 'retrieved', '30136B369FBB42F89B86DBFCC02299F2D9068DD4DC8074290F24CA93BDA4F319', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p9-8', 'doc-04-nist-sp-800-86', '', 9, 'Practically every organization needs to have the capability to perform digital forensics (referred to as forensics throughout the rest of the guide).', 'kb-doc-04-nist-sp-800-86-p9-8', 0, 22, '04-nist-sp-800-86', 'retrieved', '4A8D57D289A4F0DBC5C80830F6558C41C492AF4CCBD236D7BD37A56A9189AD14', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p9-9', 'doc-04-nist-sp-800-86', '', 9, 'Without such a capability, an organization will have difficulty determining what events have occurred within its systems and networks, such as exposures of protected, sensitive data.', 'kb-doc-04-nist-sp-800-86-p9-9', 0, 26, '04-nist-sp-800-86', 'retrieved', '182314D980895CFC3E89E264EF23DF41E984117B92500C34E55C37D7371B30E2', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p9-10', 'doc-04-nist-sp-800-86', '', 9, 'This guide provides detailed information on establishing a forensic capability, including the development of policies and procedures.', 'kb-doc-04-nist-sp-800-86-p9-10', 0, 17, '04-nist-sp-800-86', 'retrieved', 'A6500ACD53DA96F6207262ABC61EA08CA05ADD3C6257D5396BB261110F96BF52', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p9-11', 'doc-04-nist-sp-800-86', '', 9, 'Its focus is primarily on using forensic techniques to assist with computer security incident response, but much of the material is also applicable to other situations.', 'kb-doc-04-nist-sp-800-86-p9-11', 0, 26, '04-nist-sp-800-86', 'retrieved', 'A40B79173111F4AA0FAB3E8B257822355F16BA925FB80FE25F8A0B5A96EA3972', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p9-12', 'doc-04-nist-sp-800-86', '', 9, 'Because different organizations are subject to different laws and regulations, this publication should not be used as a guide to executing a digital forensic investigation, construed as legal advice, or used as the basis for investigations of criminal activity.1 Instead, organizations should use this guide as a starting point for developing a forensic capability in conjunction with extensive guidance provided by legal advisors, law enforcement officials, and management.', 'kb-doc-04-nist-sp-800-86-p9-12', 0, 68, '04-nist-sp-800-86', 'retrieved', 'BD1D5FA01A18B56F19E8A900793884FB4409F16F9FB87A55D9504A34FD9E5CB4', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p9-13', 'doc-04-nist-sp-800-86', '', 9, 'The process for performing digital forensics comprises the following basic phases: ! Collection: identifying, labeling, recording, and acquiring data from the possible sources of relevant data, while following procedures that preserve the integrity of the data.', 'kb-doc-04-nist-sp-800-86-p9-13', 0, 36, '04-nist-sp-800-86', 'retrieved', '4C7F3600FEE726760D38E902EA066938D9B19726F611FA88A62AE1B8CD2AF5E8', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p9-14', 'doc-04-nist-sp-800-86', '', 9, '! Examination: forensically processing collected data using a combination of automated and manual methods, and assessing and extracting data of particular interest, while preserving the integrity of the data.', 'kb-doc-04-nist-sp-800-86-p9-14', 0, 29, '04-nist-sp-800-86', 'retrieved', '8516C67B4D1C9558F292C698C7097999847A61CA4383D49CB9C43070BEE26111', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p9-15', 'doc-04-nist-sp-800-86', '', 9, '! Analysis: analyzing the results of the examination, using legally justifiable methods and techniques, to derive useful information that addresses the questions that were the impetus for performing the collection and examination.', 'kb-doc-04-nist-sp-800-86-p9-15', 0, 32, '04-nist-sp-800-86', 'retrieved', '5D9AB2187568180B55D9D410984E0C938629B9CA080A776A5413BA36E2AA0123', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p9-16', 'doc-04-nist-sp-800-86', '', 9, '! Reporting: reporting the results of the analysis, which may include describing the actions used, explaining how tools and procedures were selected, determining what other actions need to be performed (e.g., forensic examination of additional data sources, securing identified vulnerabilities, improving existing security controls), and providing recommendations for improvement to policies, procedures, tools, and other aspects of the forensic process.', 'kb-doc-04-nist-sp-800-86-p9-16', 0, 60, '04-nist-sp-800-86', 'retrieved', '1BCAE16ADEF41D986154760926CF1071278B75613726C633012C1A2A9C06BD3E', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p9-17', 'doc-04-nist-sp-800-86', '', 9, 'This guide provides general recommendations for performing the forensic process.', 'kb-doc-04-nist-sp-800-86-p9-17', 0, 10, '04-nist-sp-800-86', 'retrieved', 'C6AF168FAB60EF7FE18F917FB819CEF5D78D624CCDACFA3DC773C1D6A30B7076', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
