INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p9-18', 'doc-04-nist-sp-800-86', '', 9, 'It also provides detailed information about using the analysis process with four major categories of data sources: files,', 'kb-doc-04-nist-sp-800-86-p9-18', 0, 18, '04-nist-sp-800-86', 'retrieved', '1DD72A548BBF0B8021F00EB0EE3D223DBD386C834CB64116732788D31BA21774', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
