VALUES ('doc-04-nist-sp-800-86-p10-1', 'doc-04-nist-sp-800-86', '', 10, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE operating systems, network traffic, and applications.', 'kb-doc-04-nist-sp-800-86-p10-1', 0, 14, '04-nist-sp-800-86', 'retrieved', 'CA3F12CD959B61D854558073F8959C8CEEA4BF9191014B53892E53F37E027E63', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
