INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p10-2', 'doc-04-nist-sp-800-86', '', 10, 'The guide focuses on explaining the basic components and characteristics of data sources within each category, as well as techniques for the collection, examination, and analysis of data from each category.', 'kb-doc-04-nist-sp-800-86-p10-2', 0, 31, '04-nist-sp-800-86', 'retrieved', '71763B9E5FC64FBFA30372C2063371A17A7CDF4D3C8ED97868A38532AECAD27F', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p10-3', 'doc-04-nist-sp-800-86', '', 10, 'The guide also provides recommendations for how multiple data sources can be used together to gain a better understanding of an event.', 'kb-doc-04-nist-sp-800-86-p10-3', 0, 22, '04-nist-sp-800-86', 'retrieved', '4379546F74AF9128FB5FF33605A5E4CDAC11D7A2701B97E3D7D08A6EE43E0B5D', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p10-4', 'doc-04-nist-sp-800-86', '', 10, 'Implementing the following recommendations should facilitate efficient and effective digital forensic activities for Federal departments and agencies.', 'kb-doc-04-nist-sp-800-86-p10-4', 0, 17, '04-nist-sp-800-86', 'retrieved', '6577E6508D6D028C7001EABB58AB8B6DE08A0C0EA4C06D31493776AAE90016B4', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p10-5', 'doc-04-nist-sp-800-86', '', 10, 'Organizations should ensure that their policies contain clear statements addressing all major forensic considerations, such as contacting law enforcement, performing monitoring, and conducting regular reviews of forensic policies and procedures.', 'kb-doc-04-nist-sp-800-86-p10-5', 0, 30, '04-nist-sp-800-86', 'retrieved', '753DBBEF83B4B05CE64FAF2B61FABFA69F2ADF0846CE19EC90A6F3DCDEDC89FA', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p10-6', 'doc-04-nist-sp-800-86', '', 10, 'At a high level, policies should allow authorized personnel to monitor systems and networks and perform investigations for legitimate reasons under appropriate circumstances.', 'kb-doc-04-nist-sp-800-86-p10-6', 0, 23, '04-nist-sp-800-86', 'retrieved', '944A45B7E48843EDD1FF9046C2FCB548DD670BC51D5ED080644ECFB5E7C3BBE4', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p10-7', 'doc-04-nist-sp-800-86', '', 10, 'Organizations may also have a separate forensic policy for incident handlers and others with forensic roles; this policy would provide more detailed rules concerning appropriate behavior.', 'kb-doc-04-nist-sp-800-86-p10-7', 0, 26, '04-nist-sp-800-86', 'retrieved', '3CF808630E08AF4DB22F1BB9C26128B1ADE103ACD0809F89C62FF3C34FF28FD2', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p10-8', 'doc-04-nist-sp-800-86', '', 10, 'Forensic policy should clearly define the roles and responsibilities of all people and external organizations performing or assisting with the organizations forensic activities.', 'kb-doc-04-nist-sp-800-86-p10-8', 0, 23, '04-nist-sp-800-86', 'retrieved', '075957F2802A1309F1AF67063A8B73FA229426FB1234C313BE3816122594AD4B', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p10-9', 'doc-04-nist-sp-800-86', '', 10, 'The policy should clearly indicate who should contact which internal teams and external organizations under different circumstances.', 'kb-doc-04-nist-sp-800-86-p10-9', 0, 17, '04-nist-sp-800-86', 'retrieved', 'C45C5D935E6B510E7D54B53F28D6D9D9EE314A9DD2273350ACEC7C79A29D12E3', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p10-10', 'doc-04-nist-sp-800-86', '', 10, 'Organizations should create and maintain procedures and guidelines for performing forensic tasks, based on the organizations policies and all applicable laws and regulations.', 'kb-doc-04-nist-sp-800-86-p10-10', 0, 23, '04-nist-sp-800-86', 'retrieved', '34CDDACB80002C8C2C5DC2AD48777E8A6E028D514FA85D813E48DCBC2CB6B441', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p10-11', 'doc-04-nist-sp-800-86', '', 10, 'Guidelines should focus on general methodologies for investigating incidents using forensic techniques, since it is not feasible to develop comprehensive procedures tailored to every possible situation.', 'kb-doc-04-nist-sp-800-86-p10-11', 0, 26, '04-nist-sp-800-86', 'retrieved', 'EF7D6E8A83731E7FE5F1B837D4C600FF5934575763B847396DDDE8F9698C1B05', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p10-12', 'doc-04-nist-sp-800-86', '', 10, 'However, organizations should consider developing step-by-step procedures for performing routine tasks.', 'kb-doc-04-nist-sp-800-86-p10-12', 0, 11, '04-nist-sp-800-86', 'retrieved', '196923A85E6FFB43845505A93C374770F4AC13B1B76DE2E598FE890003BEBD28', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
