INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p10-13', 'doc-04-nist-sp-800-86', '', 10, 'The guidelines and procedures should facilitate consistent, effective, and accurate actions, which is particularly important for incidents that may lead to prosecution or internal disciplinary actions; handling evidence in a forensically sound manner puts decision makers in a position where they can confidently take the necessary actions.', 'kb-doc-04-nist-sp-800-86-p10-13', 0, 47, '04-nist-sp-800-86', 'retrieved', '7B3284B055604B116F7D5DA5C8006361F481B4930277E354531FAF4CE51D25A7', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p10-14', 'doc-04-nist-sp-800-86', '', 10, 'The guidelines and procedures should support the admissibility of evidence into legal proceedings, including information on gathering and handling evidence properly, preserving the integrity of tools and equipment, maintaining the chain of custody, and storing evidence appropriately.', 'kb-doc-04-nist-sp-800-86-p10-14', 0, 37, '04-nist-sp-800-86', 'retrieved', '4CC08F5A2B45F4A6B6187EA1522A176D1D3E1E1132D71C82B090EFB7CF17954D', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p10-15', 'doc-04-nist-sp-800-86', '', 10, 'Because electronic logs and other records can be altered or otherwise manipulated, organizations should be prepared, through their policies, guidelines, and procedures, to demonstrate the integrity of such records.', 'kb-doc-04-nist-sp-800-86-p10-15', 0, 29, '04-nist-sp-800-86', 'retrieved', 'A89B7C9AA40885A1774D3DA3281ED1C9024F8B421A652F4F539C7513604331C7', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p10-16', 'doc-04-nist-sp-800-86', '', 10, 'The guidelines and procedures should be reviewed periodically, as well as when significant changes are made to the teams policies and procedures.', 'kb-doc-04-nist-sp-800-86-p10-16', 0, 22, '04-nist-sp-800-86', 'retrieved', '0919D48EF24664D4FD8E3CFE0085BAC89C908227AE76A1A2315FAD527C213B2E', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p10-17', 'doc-04-nist-sp-800-86', '', 10, 'Organizations should ensure that their policies and procedures support the reasonable and appropriate use of forensic tools.', 'kb-doc-04-nist-sp-800-86-p10-17', 0, 17, '04-nist-sp-800-86', 'retrieved', 'C822E570737E11C2B3D8168DE5980F485EBD01F79D1E3D18155AC2F04E3C0D52', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p10-18', 'doc-04-nist-sp-800-86', '', 10, 'Organizations policies and procedures should clearly explain what forensic actions should and should not be performed under various circumstances, as well as describing the necessary safeguards for sensitive information that might be recorded by forensic tools, such as passwords, personal data (e.g., Social Security numbers), and the contents of e-mails.', 'kb-doc-04-nist-sp-800-86-p10-18', 0, 50, '04-nist-sp-800-86', 'retrieved', 'A28DBBF839D3D1DFEB0EFB04A22CBEF3027C114FC14ADFC0329D61A412877509', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p10-19', 'doc-04-nist-sp-800-86', '', 10, 'Legal advisors should carefully review all forensic policy and high-level procedures.', 'kb-doc-04-nist-sp-800-86-p10-19', 0, 11, '04-nist-sp-800-86', 'retrieved', '1DE87C58FAF737B506E33ADADD1D2D2F87E569B85D21BA456723D4784BC42082', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p10-20', 'doc-04-nist-sp-800-86', '', 10, 'Organizations should ensure that their IT professionals are prepared to participate in forensic activities.', 'kb-doc-04-nist-sp-800-86-p10-20', 0, 14, '04-nist-sp-800-86', 'retrieved', '3B60B9BDAB82EA57FDE2E9FA487E2D5777D159A4E80FF787884543E261118E4B', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p11-1', 'doc-04-nist-sp-800-86', '', 11, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE IT professionals throughout an organization, especially incident handlers and other first responders to incidents, should understand their roles and responsibilities for forensics, receive training and education on forensicrelated policies and procedures, and be prepared to cooperate with and assist others when the technologies that they are responsible for are part of an incident or other event.', 'kb-doc-04-nist-sp-800-86-p11-1', 0, 64, '04-nist-sp-800-86', 'retrieved', '284959528E8B31F155A94416686B2B74B570BC352C3466774495836509878104', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p11-2', 'doc-04-nist-sp-800-86', '', 11, 'IT professionals should also consult closely with legal counsel both in general preparation for forensics activities, such as determining which actions IT professionals should and should not perform, and also on an as-needed basis to discuss specific forensics situations.', 'kb-doc-04-nist-sp-800-86-p11-2', 0, 39, '04-nist-sp-800-86', 'retrieved', '40DB9B20C2F598CB00982864684A315782F4A8D7365EC65402728CEAED64A45A', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p11-3', 'doc-04-nist-sp-800-86', '', 11, 'In addition, management should be responsible for supporting forensic capabilities, reviewing and approving forensic policy, and approving certain forensic actions, such as taking mission-critical systems off-line.', 'kb-doc-04-nist-sp-800-86-p11-3', 0, 26, '04-nist-sp-800-86', 'retrieved', 'A6AF420D0171A373C16549C7DBC3F892D9F2AA4FE7CF18C437EACA0A23B60451', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p13-1', 'doc-04-nist-sp-800-86', '', 13, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE 1. Introduction 1.1 A uthority The National Institute of Standards and Technology (NIST) developed this document in furtherance of its statutory responsibilities under the Federal Information Security Management Act (FISMA) of 2002, Public Law 107-347.', 'kb-doc-04-nist-sp-800-86-p13-1', 0, 43, '04-nist-sp-800-86', 'retrieved', 'EF443BBCA4B885793B4F06D18221B984354C970F6054D2AD24FC29C0FD05FC4C', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p13-2', 'doc-04-nist-sp-800-86', '', 13, 'NIST is responsible for developing standards and guidelines, including minimum requirements, for providing adequate information security for all agency operations and assets; but such standards and guidelines shall not apply to national security systems.', 'kb-doc-04-nist-sp-800-86-p13-2', 0, 34, '04-nist-sp-800-86', 'retrieved', '6B1BC6AD4F73C97D3E5441B2AB16A00C8AA342B456FDB8D266FFE8D359B9B2CD', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p13-3', 'doc-04-nist-sp-800-86', '', 13, 'This guideline is consistent with the requirements of the Office of Management and Budget (OMB) Circular A-130, Section 8b(3), Securing Agency Information Systems, as analyzed in A-130, Appendix IV: Analysis of Key Sections.', 'kb-doc-04-nist-sp-800-86-p13-3', 0, 33, '04-nist-sp-800-86', 'retrieved', 'E9E957AF5EA0396DED2203E4D2C1D3E4DD61D502C0996EC683260091DA73943F', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p13-6', 'doc-04-nist-sp-800-86', '', 13, 'It may be used by nongovernmental organizations on a voluntary basis and is not subject to copyright, though attribution is desired.', 'kb-doc-04-nist-sp-800-86-p13-6', 0, 21, '04-nist-sp-800-86', 'retrieved', '2A5649720C2DE340A52788B2FA2C2A65022504580BCA5232C5DE59A7F66B20CA', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
