INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p13-7', 'doc-04-nist-sp-800-86', '', 13, 'Nothing in this document should be taken to contradict standards and guidelines made mandatory and binding on Federal agencies by the Secretary of Commerce under statutory authority, nor should these guidelines be interpreted as altering or superseding the existing authorities of the Secretary of Commerce, Director of the OMB, or any other Federal official.', 'kb-doc-04-nist-sp-800-86-p13-7', 0, 54, '04-nist-sp-800-86', 'retrieved', '8F192A9ED4044B5D675F2889F68C0286572ABA3D92D7BC565CEEC5AA46259FA4', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
