INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p13-8', 'doc-04-nist-sp-800-86', '', 13, 'This guideline should not be held as binding to law enforcement personnel relative to the investigation of criminal activity.', 'kb-doc-04-nist-sp-800-86-p13-8', 0, 19, '04-nist-sp-800-86', 'retrieved', 'BEC8649D0DF1D5F83EB316C7A5338641A7ADEE6BE5D8998E715AA70275CDB7E3', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
