INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p13-9', 'doc-04-nist-sp-800-86', '', 13, '1.2 Purpose and Scope This publication is intended to help organizations in investigating computer security incidents and troubleshooting some information technology (IT) operational problems by providing practical guidance on performing computer and network forensics.', 'kb-doc-04-nist-sp-800-86-p13-9', 0, 34, '04-nist-sp-800-86', 'retrieved', '08B4F4EB266F7B07E0554C5235BC5538280B8BB6373043CAC40AF0684556B63B', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p13-10', 'doc-04-nist-sp-800-86', '', 13, 'The guide presents forensics from an IT view, not a law enforcement view.2 Specifically, the publication describes the processes for performing effective forensics activities and provides advice regarding different data sources, including files, operating systems (OS), network traffic, and applications.', 'kb-doc-04-nist-sp-800-86-p13-10', 0, 40, '04-nist-sp-800-86', 'retrieved', '3841BA1769387037EC1D3BFD2444D2C14CA4A6944B11A61B372AD5B1795C71C1', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p13-11', 'doc-04-nist-sp-800-86', '', 13, 'The publication is not to be used as an all-inclusive step-by-step guide for executing a digital forensic investigation or construed as legal advice.', 'kb-doc-04-nist-sp-800-86-p13-11', 0, 23, '04-nist-sp-800-86', 'retrieved', '1DCCC8A5DD78333C8E7B51E0A8610D07D75F808A82FB75C8AB7ACCC649D14766', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p13-12', 'doc-04-nist-sp-800-86', '', 13, 'Its purpose is to inform readers of various technologies and potential ways of using them in performing incident response or troubleshooting activities.', 'kb-doc-04-nist-sp-800-86-p13-12', 0, 22, '04-nist-sp-800-86', 'retrieved', 'CF3CADB9CB3931B23BBC16DA49937373011CF05E3AF41872C1514B013D940E55', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p13-13', 'doc-04-nist-sp-800-86', '', 13, 'Readers are advised to apply the recommended practices only after consulting with management and legal counsel for compliance concerning laws and regulations (i.e., local, state, Federal, and international) that pertain to their situation.', 'kb-doc-04-nist-sp-800-86-p13-13', 0, 33, '04-nist-sp-800-86', 'retrieved', '0AB24799E6499A93BCD7ABB99F3F419EE8C72F6E7A46D1D1C20A34F3C289343F', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
