INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p13-14', 'doc-04-nist-sp-800-86', '', 13, '1.3 A udience This publication has been created for incident response teams; forensic analysts; system, network, and security administrators; and computer security program managers who are responsible for performing forensics for investigative, incident response, or troubleshooting purposes.', 'kb-doc-04-nist-sp-800-86-p13-14', 0, 37, '04-nist-sp-800-86', 'retrieved', '8AB4DFD4C035A399A7D4301E9BED39841C8E7A43A8C72401FF9086C2CE8C03B2', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
