INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p13-16', 'doc-04-nist-sp-800-86', '', 13, '2 For further information regarding computer and network forensic requirements for law enforcement, see Electronic Crime Scene Investigation: A Guide for First Responders and Forensic Examination of Digital Evidence: A Guide for Law Enforcement, which are both available at http://www.ncjrs.gov/ by searching on each documents title.', 'kb-doc-04-nist-sp-800-86-p13-16', 0, 46, '04-nist-sp-800-86', 'retrieved', '6E19AD8021B95D551DB9514E612D7D94EE0F3B63945CE42143101FCF88DA6DF6', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
