INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p14-2', 'doc-04-nist-sp-800-86', '', 14, 'Because of the constantly changing nature of electronic devices and software, and forensic procedures and tools, readers are expected to refer to other resources, including those listed in this guide, for more current and detailed information than that presented in this guide.', 'kb-doc-04-nist-sp-800-86-p14-2', 0, 42, '04-nist-sp-800-86', 'retrieved', 'FF83DC85AC32E307DC326B0440FA6C45FFCDDF84BC04B4776D54B3349D1B7A33', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
