VALUES ('doc-04-nist-sp-800-86-p14-3', 'doc-04-nist-sp-800-86', '', 14, '1.4 Pu blication Structure The remainder of this publication is divided into seven major sections: ! Section 2 discusses the need for computer and network forensics and provides guidance on establishing and organizing a forensics capability for an organization.', 'kb-doc-04-nist-sp-800-86-p14-3', 0, 39, '04-nist-sp-800-86', 'retrieved', '4BC49F4319FA0B0DB9B1586074804355FCB7F2BB3ACBD2A595E16839691FD547', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
