INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p14-4', 'doc-04-nist-sp-800-86', '', 14, '! Section 3 explains the basic steps involved in performing computer and network forensics: data collection, examination, analysis, and reporting.', 'kb-doc-04-nist-sp-800-86-p14-4', 0, 20, '04-nist-sp-800-86', 'retrieved', '6D27D3B02E5D3B6FE4B8A7A19C706816846A5709D67E03BE77F8A2A74365EADA', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
