INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p14-5', 'doc-04-nist-sp-800-86', '', 14, '! Sections 4 through 7 provide details on collecting, examining, and analyzing data from various data sources, based on the framework described in Section 3.', 'kb-doc-04-nist-sp-800-86-p14-5', 0, 25, '04-nist-sp-800-86', 'retrieved', '785899710FF44B9C2E38ECA7B695E23FB63740383A8C44190B5701D6C91846B9', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
