INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p14-6', 'doc-04-nist-sp-800-86', '', 14, 'The data source categories discussed in Sections 4 through 7 are data files, OSs, network traffic, and applications, respectively.', 'kb-doc-04-nist-sp-800-86-p14-6', 0, 19, '04-nist-sp-800-86', 'retrieved', '68D617985B04B6C1DA33DB17B05197F6FCDA0541B69E19B97CA23C283F7242CE', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
