VALUES ('doc-04-nist-sp-800-86-p14-7', 'doc-04-nist-sp-800-86', '', 14, '! Section 8 presents case studies that illustrate how analysis can correlate events among several data sources.', 'kb-doc-04-nist-sp-800-86-p14-7', 0, 17, '04-nist-sp-800-86', 'retrieved', 'CF9F249D23430B6C1FC810F16E171CB430048A90EA8593957B6E72D8950B6E41', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
