VALUES ('doc-04-nist-sp-800-86-p14-9', 'doc-04-nist-sp-800-86', '', 14, '! Appendix B presents scenarios in which forensics techniques might be useful and asks the reader a series of questions regarding each scenario.', 'kb-doc-04-nist-sp-800-86-p14-9', 0, 23, '04-nist-sp-800-86', 'retrieved', '37CF2EA06AD83314D6CBBEB5EE1FC89BBA248BD2EFB11C986990CD7291DEF051', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
