VALUES ('doc-04-nist-sp-800-86-p14-11', 'doc-04-nist-sp-800-86', '', 14, '! Appendix E lists print resources, and Appendix F identifies online tools and resources, that may be useful for establishing a forensics capability or understanding forensics tools and techniques.', 'kb-doc-04-nist-sp-800-86-p14-11', 0, 29, '04-nist-sp-800-86', 'retrieved', '3E69A50F68FD9645F4E01A336E4906D5A9D9EC1B77C1CDC4D7114CD223A0BB43', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
