INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p15-1', 'doc-04-nist-sp-800-86', '', 15, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE 2. Establishing and Organizing a Forensics Capability The term data refers to distinct pieces of digital information that have been formatted in a specific way.', 'kb-doc-04-nist-sp-800-86-p15-1', 0, 33, '04-nist-sp-800-86', 'retrieved', '8B2126009F8D303A49D1C3D4DF5A4D7DCABD735A9D5D40E6974D1DF7EBD449C6', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p15-2', 'doc-04-nist-sp-800-86', '', 15, 'The expansion of computers3 for professional and personal use and the pervasiveness of networking have fueled the need for tools that can record and analyze an ever-increasing amount of data from many sources.', 'kb-doc-04-nist-sp-800-86-p15-2', 0, 33, '04-nist-sp-800-86', 'retrieved', '15B2F15306882739F65D4C3EE794156CBA52353FAC6C44A0192F67C2B1BB3CF0', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p15-3', 'doc-04-nist-sp-800-86', '', 15, 'For example, data can be stored or transferred by standard computer systems (e.g., desktops, laptops, servers), networking equipment (e.g., firewalls, routers), computing peripherals (i.e., printers), personal digital assistants (PDA), CDs, DVDs, removable hard drives, backup tapes, flash memory, thumb drives, and jump drives.', 'kb-doc-04-nist-sp-800-86-p15-3', 0, 43, '04-nist-sp-800-86', 'retrieved', '773C02E594DC1D48DB0BB30E3C5B5F65472A47D5BCA64A05DC7E189A2389CA4B', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p15-4', 'doc-04-nist-sp-800-86', '', 15, 'Many consumer electronic devices (e.g., cell phones, video game consoles, digital audio players, digital video recorders) can also be used to store data.', 'kb-doc-04-nist-sp-800-86-p15-4', 0, 23, '04-nist-sp-800-86', 'retrieved', 'B67193FCFEF5748F7993B8944D04CB73B681285EFE96E5C50CDFA2AA2CE83193', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p15-5', 'doc-04-nist-sp-800-86', '', 15, 'This increasing variety of data sources has helped spur the development and refinement of forensics tools and techniques.', 'kb-doc-04-nist-sp-800-86-p15-5', 0, 18, '04-nist-sp-800-86', 'retrieved', 'D0E43252348ECD40D1A739C77815E3872D25294D767BEC3B7CEFFE2DB5355984', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p15-6', 'doc-04-nist-sp-800-86', '', 15, 'This has also been caused by the realization that such tools and techniques can be used for many purposes, such as investigating crimes, reconstructing computer security incidents, troubleshooting operational problems, and recovering from accidental system damage.', 'kb-doc-04-nist-sp-800-86-p15-6', 0, 36, '04-nist-sp-800-86', 'retrieved', '309F6689BC5DCEEB19C2EFD3AD4383B408B74447C0B30F5A36C3389D2FB2207F', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
