VALUES ('doc-04-nist-sp-800-86-p15-7', 'doc-04-nist-sp-800-86', '', 15, 'This section discusses several aspects of organizing a forensics capability for an organization.', 'kb-doc-04-nist-sp-800-86-p15-7', 0, 13, '04-nist-sp-800-86', 'retrieved', '602A568A85E6EACDFFD7285254E0EDA6D672440DAFABEF03F901B5016C489234', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
