INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p15-8', 'doc-04-nist-sp-800-86', '', 15, 'It begins by showing the wide variety of potential uses for forensics, and then presents a high-level overview of the forensics process.', 'kb-doc-04-nist-sp-800-86-p15-8', 0, 22, '04-nist-sp-800-86', 'retrieved', 'A7DD60E2A5DF09B748FA9E55FD3E37A75E99DAB77BC0D1D04C5A352A8A70603D', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p15-9', 'doc-04-nist-sp-800-86', '', 15, 'The next part of the section discusses how forensics services are typically provided and provides guidance on building and maintaining the necessary skills to perform forensics tasks.', 'kb-doc-04-nist-sp-800-86-p15-9', 0, 27, '04-nist-sp-800-86', 'retrieved', '17A2F11D8228BBE7E2903296EA2294C72F532D87D31223BF32A7642CED065BD2', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p15-10', 'doc-04-nist-sp-800-86', '', 15, 'The section also explains the need to include various teams from throughout the organization, such as legal advisors and physical security staff, in some forensic activities.', 'kb-doc-04-nist-sp-800-86-p15-10', 0, 26, '04-nist-sp-800-86', 'retrieved', '95178E30BF2E30EDC343DD03D91596C7B8CCD63E4C6EFDBD081EE04F74DAED42', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p15-11', 'doc-04-nist-sp-800-86', '', 15, 'The section ends by discussing how policies, guidelines, and procedures should address forensics (e.g., defining roles and responsibilities, providing guidance on the proper usage of tools and techniques, incorporating forensics into the information system life cycle).', 'kb-doc-04-nist-sp-800-86-p15-11', 0, 36, '04-nist-sp-800-86', 'retrieved', '638ADED3E2F16F5BDF885431AEFDAFD6E760475C4392AACB4157ACB2B5B0B863', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p15-12', 'doc-04-nist-sp-800-86', '', 15, 'The techniques and processes presented in this guide are based on principles of digital forensics.', 'kb-doc-04-nist-sp-800-86-p15-12', 0, 15, '04-nist-sp-800-86', 'retrieved', '0C9399B4D303B667AE41400C89879C44EBA9C4B96390C07C7A68C0A5BC12336C', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p15-16', 'doc-04-nist-sp-800-86', '', 15, 'Because different organizations are subject to different laws and regulations, this publication should not be used as a guide for executing a digital forensic investigation, construed as legal advice, or used as the basis for investigations of criminal activity.', 'kb-doc-04-nist-sp-800-86-p15-16', 0, 39, '04-nist-sp-800-86', 'retrieved', '29D849145D2216329A9A96E0D39594CFE1A0265322984C41DC3D9C3297DACADA', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p15-17', 'doc-04-nist-sp-800-86', '', 15, 'Instead, organizations should use this guide as a starting point for developing a forensic capability in conjunction with extensive guidance provided by legal advisors, law enforcement officials, and management.', 'kb-doc-04-nist-sp-800-86-p15-17', 0, 29, '04-nist-sp-800-86', 'retrieved', '0F4BDF2B314274D02A5E96B15D31DF7B1375FD165F2719624FF8A3258589D4BC', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p15-18', 'doc-04-nist-sp-800-86', '', 15, '2.1 The Need for Forensics Over the last decade, the number of crimes that involve computers has grown, spurring an increase in companies and products that aim to assist law enforcement in using computer-based evidence to determine the who, what, where, when, and how for crimes.', 'kb-doc-04-nist-sp-800-86-p15-18', 0, 46, '04-nist-sp-800-86', 'retrieved', '6BC4D764F3CAC722ACA21320FAB0304EC1219423364C35FF3294A82530D07ABA', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
