VALUES ('doc-04-nist-sp-800-86-p15-20', 'doc-04-nist-sp-800-86', '', 15, 'Forensic tools and techniques are most often thought of in the context of criminal investigations and computer security incident handlingused to respond to an event by investigating suspect systems, gathering and preserving evidence, reconstructing events, and assessing the current state of an event.', 'kb-doc-04-nist-sp-800-86-p15-20', 0, 43, '04-nist-sp-800-86', 'retrieved', 'B21A9AF219E4FD2C8DB2A2E820EB81369B41594E52F1D0A01F558CEDAF015FF0', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
