VALUES ('doc-04-nist-sp-800-86-p15-21', 'doc-04-nist-sp-800-86', '', 15, 'However, forensic tools and techniques are also useful for many other types of tasks, such as the following: ! Operational Troubleshooting.', 'kb-doc-04-nist-sp-800-86-p15-21', 0, 21, '04-nist-sp-800-86', 'retrieved', 'F49D091350721C3196E2CCFD1E7837AFB9639C7B3529866BEE0B6236C3CF08D5', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
