VALUES ('doc-04-nist-sp-800-86-p15-22', 'doc-04-nist-sp-800-86', '', 15, 'Many forensic tools and techniques can be applied to troubleshooting operational issues, such as finding the virtual and physical location of a host with', 'kb-doc-04-nist-sp-800-86-p15-22', 0, 24, '04-nist-sp-800-86', 'retrieved', '501B3E5A0656499794D055DEE82261E3336A64AE09FB37BF44588930536987BB', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
