VALUES ('doc-04-nist-sp-800-86-p16-1', 'doc-04-nist-sp-800-86', '', 16, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE an incorrect network configuration, resolving a functional problem with an application, and recording and reviewing the current OS and application configuration settings for a host.', 'kb-doc-04-nist-sp-800-86-p16-1', 0, 33, '04-nist-sp-800-86', 'retrieved', '788DC3E795CEAA98B4F2201E95799F7F160C2E55A2CCF2872C832C5AABD2E4A4', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
