VALUES ('doc-04-nist-sp-800-86-p16-3', 'doc-04-nist-sp-800-86', '', 16, 'Various tools and techniques can assist in log monitoring, such as analyzing log entries and correlating log entries across multiple systems.', 'kb-doc-04-nist-sp-800-86-p16-3', 0, 21, '04-nist-sp-800-86', 'retrieved', '1E0D2EF7CCEBE183886D7DEFD42CB2B9F9D17BE205FB5A57701EC9DEE826EA78', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
