VALUES ('doc-04-nist-sp-800-86-p16-4', 'doc-04-nist-sp-800-86', '', 16, 'This can assist in incident handling, identifying policy violations, auditing, and other efforts.', 'kb-doc-04-nist-sp-800-86-p16-4', 0, 13, '04-nist-sp-800-86', 'retrieved', 'D96C6678ABCF8724A943347F033FFC8F3AC2507BEAABC8CA3FEE3BA400CA6708', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
