VALUES ('doc-04-nist-sp-800-86-p16-6', 'doc-04-nist-sp-800-86', '', 16, 'There are dozens of tools that can recover lost data from systems, including data that has been accidentally or purposely deleted or otherwise modified.', 'kb-doc-04-nist-sp-800-86-p16-6', 0, 24, '04-nist-sp-800-86', 'retrieved', '7ABDD364DD9331AC2FEF21E06AFE6FF09FE9BE07DD359375D07B281977EC7524', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
