VALUES ('doc-04-nist-sp-800-86-p16-9', 'doc-04-nist-sp-800-86', '', 16, 'Some organizations use forensics tools to acquire data from hosts that are being redeployed or retired.', 'kb-doc-04-nist-sp-800-86-p16-9', 0, 16, '04-nist-sp-800-86', 'retrieved', 'AB4891E1918269F17F9867FC29B95723A1B8C2405C818845012294929DEAEECE', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
