INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p16-10', 'doc-04-nist-sp-800-86', '', 16, 'For example, when a user leaves an organization, the data from the users workstation can be acquired and stored in case it is needed in the future.', 'kb-doc-04-nist-sp-800-86-p16-10', 0, 27, '04-nist-sp-800-86', 'retrieved', '0112035A4FA72CCD50D468168C0FAF77AB6AF4ACF4EF85C056E4A8798B7D9528', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
