INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p16-11', 'doc-04-nist-sp-800-86', '', 16, 'The workstations media can then be sanitized to remove all of the original users data.', 'kb-doc-04-nist-sp-800-86-p16-11', 0, 15, '04-nist-sp-800-86', 'retrieved', '006A94F4048791704BB0B442A6A4E93C286DB6FF1FA15D5E9E848367A50B682F', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
