INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p16-13', 'doc-04-nist-sp-800-86', '', 16, 'Existing and emerging regulations require many organizations to protect sensitive information and maintain certain records for audit purposes.', 'kb-doc-04-nist-sp-800-86-p16-13', 0, 18, '04-nist-sp-800-86', 'retrieved', 'FBF72368C43496D47D70DEE43575777AB89ABD9D45FEF0F64525E4B656AD04A2', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p16-14', 'doc-04-nist-sp-800-86', '', 16, 'Also, when protected information is exposed to other parties, organizations may be required to notify other agencies or impacted individuals.', 'kb-doc-04-nist-sp-800-86-p16-14', 0, 20, '04-nist-sp-800-86', 'retrieved', '10D04C21D61A4AEF4681E52638A9C9B8C575AB472DEF8FF2600D5ACCB24898F9', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
