INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p16-15', 'doc-04-nist-sp-800-86', '', 16, 'Forensics can help organizations exercise due diligence and comply with such requirements.', 'kb-doc-04-nist-sp-800-86-p16-15', 0, 12, '04-nist-sp-800-86', 'retrieved', '04386989E8538A878E040F979B11307ABD95D0C37E8A68F2AD41FC86569085B0', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
