INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p16-16', 'doc-04-nist-sp-800-86', '', 16, 'Regardless of the situation, the forensic process comprises the following basic phases:4 ! Collection.', 'kb-doc-04-nist-sp-800-86-p16-16', 0, 14, '04-nist-sp-800-86', 'retrieved', 'F68AB1038A79A1C3640E10BFA72D92F6E92D74DA10021490F9F472E6B90F9642', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p16-17', 'doc-04-nist-sp-800-86', '', 16, 'The first phase in the process is to identify, label, record, and acquire data from the possible sources of relevant data, while following guidelines and procedures that preserve the integrity of the data.', 'kb-doc-04-nist-sp-800-86-p16-17', 0, 33, '04-nist-sp-800-86', 'retrieved', 'EFD1A8FD82B896FD3A6451C34A33CF9D954F9B45FBA791B1572519FA97264AF7', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p16-18', 'doc-04-nist-sp-800-86', '', 16, 'Collection is typically performed in a timely manner because of the likelihood of losing dynamic data such as current network connections, as well as losing data from battery-powered devices (e.g., cell phones, PDAs).', 'kb-doc-04-nist-sp-800-86-p16-18', 0, 33, '04-nist-sp-800-86', 'retrieved', 'A9F56BCF2737F261E85345E52A23B1FDF7E922E910C084E63BE73FEAC5068F3F', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p16-20', 'doc-04-nist-sp-800-86', '', 16, 'Examinations involve forensically processing large amounts of collected data using a combination of automated and manual methods to assess and extract data of particular interest, while preserving the integrity of the data.', 'kb-doc-04-nist-sp-800-86-p16-20', 0, 32, '04-nist-sp-800-86', 'retrieved', 'ABEC934D67D217860363B6567D34CEA0386A340BF1BE720EF49D806702E004F4', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p16-22', 'doc-04-nist-sp-800-86', '', 16, 'The next phase of the process is to analyze the results of the examination, using legally justifiable methods and techniques, to derive useful information that addresses the questions that were the impetus for performing the collection and examination.', 'kb-doc-04-nist-sp-800-86-p16-22', 0, 38, '04-nist-sp-800-86', 'retrieved', '79FBD2C57AD4E736F03B3456E92FD9467F679604350AA43F7596F9F0BA66520C', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p16-24', 'doc-04-nist-sp-800-86', '', 16, 'The final phase is reporting the results of the analysis, which may include describing the actions used, explaining how tools and procedures were selected, determining what other actions need to be performed (e.g., forensic examination of additional data sources, securing identified vulnerabilities, improving existing security controls), and providing recommendations for improvement to policies, guidelines, procedures, tools, and other aspects of the forensic process.', 'kb-doc-04-nist-sp-800-86-p16-24', 0, 63, '04-nist-sp-800-86', 'retrieved', '8D7C386B35AB8E1EC92885258E92142310E2F5C4069C48E8C4DEFAB5F6F80852', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p16-27', 'doc-04-nist-sp-800-86', '', 16, 'Sections 4 through 7 provide additional information on collecting, examining, and analyzing different types of forensic data.', 'kb-doc-04-nist-sp-800-86-p16-27', 0, 17, '04-nist-sp-800-86', 'retrieved', '049EB73409B1F46078C9A3C3790133490AB7E56E0B59C0EC47E58BCF138A45E9', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p16-29', 'doc-04-nist-sp-800-86', '', 16, 'Although the exact phases of the models vary somewhat, the models reflect the same basic principles and the same overall methodology.', 'kb-doc-04-nist-sp-800-86-p16-29', 0, 21, '04-nist-sp-800-86', 'retrieved', '6BBB1036EFB0FDE051B68C2D38DB6FF2CE5EBEA4B507DB255C63FB15A32594DE', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
