VALUES ('doc-04-nist-sp-800-86-p16-30', 'doc-04-nist-sp-800-86', '', 16, 'Models differ primarily in how granular each phase of the process is and in the terms used for specific phases.', 'kb-doc-04-nist-sp-800-86-p16-30', 0, 20, '04-nist-sp-800-86', 'retrieved', 'F1021090457439646A2B33A792ECC23F4B1E862C209F9CE03D7930CEB2F2D8A4', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
