VALUES ('doc-04-nist-sp-800-86-p16-32', 'doc-04-nist-sp-800-86', '', 16, 'Organizations should choose the specific forensic model that is most appropriate for their needs.', 'kb-doc-04-nist-sp-800-86-p16-32', 0, 14, '04-nist-sp-800-86', 'retrieved', '1C871FCB8798F86FADD60788FA4A2D6E9D60FD064709AEF7B23E91BA9D043B8E', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
