VALUES ('doc-04-nist-sp-800-86-p17-1', 'doc-04-nist-sp-800-86', '', 17, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE 2.2 F orensic Staffing Practically every organization needs to have some capability to perform computer and network forensics.', 'kb-doc-04-nist-sp-800-86-p17-1', 0, 26, '04-nist-sp-800-86', 'retrieved', 'D830F283458480A7EB036F7F2BAD605174500F3F098F0D8DBFE90B5399646D09', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
