INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p17-3', 'doc-04-nist-sp-800-86', '', 17, 'Although the extent of this need varies, the primary users of forensic tools and techniques within an organization usually can be divided into the following three groups:5 ! Investigators.', 'kb-doc-04-nist-sp-800-86-p17-3', 0, 29, '04-nist-sp-800-86', 'retrieved', '4D43D59129DA15D6618ACDA7E377311BF976DD5D69280AC1EA2528B0EB413F3C', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p17-4', 'doc-04-nist-sp-800-86', '', 17, 'Investigators within an organization are most often from the Office of Inspector General (OIG), and they are responsible for investigating allegations of misconduct.', 'kb-doc-04-nist-sp-800-86-p17-4', 0, 23, '04-nist-sp-800-86', 'retrieved', '61B5DECEABEB32EE56C4887E00CBE3E2373434AB3E5332A5B9355126FF01D7B9', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p17-5', 'doc-04-nist-sp-800-86', '', 17, 'For some organizations, the OIG immediately takes over the investigation of any event that is suspected to involve criminal activity.', 'kb-doc-04-nist-sp-800-86-p17-5', 0, 20, '04-nist-sp-800-86', 'retrieved', '9EB77BDF97A107DC78CE86760E9536E219D5540104AD3141DB95EE5F23065F8F', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p17-7', 'doc-04-nist-sp-800-86', '', 17, 'Other investigators within an organization might include legal advisors and members of the human resources department.', 'kb-doc-04-nist-sp-800-86-p17-7', 0, 16, '04-nist-sp-800-86', 'retrieved', '0296F848CFBCCA84FD5775344DEEE926958C7854C985DF6060E98FC578BC68A9', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p17-8', 'doc-04-nist-sp-800-86', '', 17, 'Law enforcement officials and others outside the organization that might perform criminal investigations are not considered part of an organizations internal group of investigators.', 'kb-doc-04-nist-sp-800-86-p17-8', 0, 24, '04-nist-sp-800-86', 'retrieved', '15584DA9D91F00BDEFE0A48E8357F776AF88E943FBDABE6163968C1F5A1F4863', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p17-10', 'doc-04-nist-sp-800-86', '', 17, 'This group includes technical support staff and system, network, and security administrators.', 'kb-doc-04-nist-sp-800-86-p17-10', 0, 12, '04-nist-sp-800-86', 'retrieved', '250054C39D43F96CDF6C5846FF9BB7B981954A5CB832AD6999E0E773A9D361F7', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p17-11', 'doc-04-nist-sp-800-86', '', 17, 'They use a small number of forensic techniques and tools specific to their area of expertise during their routine work (e.g., monitoring, troubleshooting, data recovery).', 'kb-doc-04-nist-sp-800-86-p17-11', 0, 25, '04-nist-sp-800-86', 'retrieved', 'E971D21D34BCC12B432491E87541569A3192ED7C9B653CD425EB8D1374BC363C', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p17-13', 'doc-04-nist-sp-800-86', '', 17, 'This group responds to a variety of computer security incidents, such as unauthorized data access, inappropriate system usage, malicious code infections, and denial of service attacks.', 'kb-doc-04-nist-sp-800-86-p17-13', 0, 26, '04-nist-sp-800-86', 'retrieved', '4E5FC22472DB87B536B740359C08615BEA779E72C306D0AE1B678EF6373761D3', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p17-14', 'doc-04-nist-sp-800-86', '', 17, 'Incident handlers typically use a wide variety of forensic techniques and tools during their investigations.', 'kb-doc-04-nist-sp-800-86-p17-14', 0, 15, '04-nist-sp-800-86', 'retrieved', '449BAF643F0C9186CD626E635D8696E5DE879E637E09394F3EB90D9522CB4B1C', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p17-15', 'doc-04-nist-sp-800-86', '', 17, 'Many organizations rely on a combination of their own staff and external parties to perform forensic tasks.', 'kb-doc-04-nist-sp-800-86-p17-15', 0, 17, '04-nist-sp-800-86', 'retrieved', '3748F4D64A530E69174619F7315CCAAACE5F68166F1EE8374790C3305DEDB94A', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p17-16', 'doc-04-nist-sp-800-86', '', 17, 'For example, some organizations perform standard tasks themselves and use outside parties only when specialized assistance is needed.', 'kb-doc-04-nist-sp-800-86-p17-16', 0, 18, '04-nist-sp-800-86', 'retrieved', '6AD917FE6697A569CC3FDA4EB0F675333669202A1CAE9DA963826246F8D62546', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p17-17', 'doc-04-nist-sp-800-86', '', 17, 'Even organizations that want to perform all forensic tasks themselves usually outsource the most demanding ones, such as sending physically damaged media to a data recovery firm for reconstruction, or having specially trained law enforcement personnel or consultants collect data from an unusual source (e.g., cell phone).', 'kb-doc-04-nist-sp-800-86-p17-17', 0, 47, '04-nist-sp-800-86', 'retrieved', '0534E5493935AE76B9ADD3A5C625C4BE5D1BF6F1493FD96EE7149818770720B1', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p17-18', 'doc-04-nist-sp-800-86', '', 17, 'Such tasks typically require the use of specialized software, equipment, facilities, and technical expertise that most organizations cannot justify the high expense of acquiring and maintaining.', 'kb-doc-04-nist-sp-800-86-p17-18', 0, 26, '04-nist-sp-800-86', 'retrieved', 'CFB9EDFFEE729ACA18409244AC82D094CC455ADBA5789FC7E8B249FA078D7E53', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p17-19', 'doc-04-nist-sp-800-86', '', 17, 'As described in Section 3.1.2, organizations should determine in advance which actions should be performed by law enforcement officials.', 'kb-doc-04-nist-sp-800-86-p17-19', 0, 19, '04-nist-sp-800-86', 'retrieved', '340F06AF9FC69B2B215BD19756372202542C142AC5B318AAD0DB54921F1099CD', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p17-20', 'doc-04-nist-sp-800-86', '', 17, 'Also, when expert testimony is needed for legal proceedings, organizations might seek external assistance.', 'kb-doc-04-nist-sp-800-86-p17-20', 0, 14, '04-nist-sp-800-86', 'retrieved', '4CCE835E05A5EC7F4CCEA61824DABDFA4B98D3B67B25B2FC468E83A28F678DEA', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p17-21', 'doc-04-nist-sp-800-86', '', 17, 'When deciding which internal or external parties should handle each aspect of forensics, organizations should keep the following factors in mind: ! Cost.', 'kb-doc-04-nist-sp-800-86-p17-21', 0, 23, '04-nist-sp-800-86', 'retrieved', '54F9EF0438F2CEDC2E32D7ABAEB6E6714DCCB75DA1B4C0AE220F7255761166E7', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p17-23', 'doc-04-nist-sp-800-86', '', 17, 'Software, hardware, and equipment used to collect and examine data may carry significant costs (e.g., purchase price, software updates and upgrades, maintenance), and may also require additional physical security measures to safeguard them from tampering.', 'kb-doc-04-nist-sp-800-86-p17-23', 0, 35, '04-nist-sp-800-86', 'retrieved', '804D896EF50FF106F52337FF7EC4D494556840A35B85AA3CAFD3341C00CFD577', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p17-24', 'doc-04-nist-sp-800-86', '', 17, 'Other significant expenses involve staff training and labor costs, which are particularly significant for dedicated forensic specialists.', 'kb-doc-04-nist-sp-800-86-p17-24', 0, 17, '04-nist-sp-800-86', 'retrieved', '31BC046D3B7349256A5A9A7A9FF7F28F129F95E6939EB29C08EA7F13F9B149F1', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p17-25', 'doc-04-nist-sp-800-86', '', 17, 'In general, forensic actions that are needed rarely might be more cost-effectively performed by an external party, whereas actions that are needed frequently might be more cost-effectively performed internally.', 'kb-doc-04-nist-sp-800-86-p17-25', 0, 29, '04-nist-sp-800-86', 'retrieved', 'F91A45486D912A05F4FF58CD7DDE56628385115436808C1EA71B58B14FCBEA6D', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p17-26', 'doc-04-nist-sp-800-86', '', 17, '5 An individual performing forensic activities needs to understand forensic principles and practices, and follow the correct procedures for each activity, regardless of which group he or she is a member.', 'kb-doc-04-nist-sp-800-86-p17-26', 0, 31, '04-nist-sp-800-86', 'retrieved', 'E7AFCFF4EFC0BD78AF382EFDBD3D92B7AD56C8C745F34C377A570931BE71F85C', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
