VALUES ('doc-04-nist-sp-800-86-p18-1', 'doc-04-nist-sp-800-86', '', 18, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE ! Response Time.', 'kb-doc-04-nist-sp-800-86-p18-1', 0, 11, '04-nist-sp-800-86', 'retrieved', 'EEC2286826530E303CAA0130E4EC52580B4E524C4F2CEFB8E06B339A11BA5F83', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
