INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p18-2', 'doc-04-nist-sp-800-86', '', 18, 'Personnel located on-site might be able to initiate computer forensic activity more quickly than could off-site personnel.', 'kb-doc-04-nist-sp-800-86-p18-2', 0, 17, '04-nist-sp-800-86', 'retrieved', '1B6F5D9E9E460344F76DD4CCEA63D8B12E2DA677CE7671E0234A72E94C79C45D', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p18-3', 'doc-04-nist-sp-800-86', '', 18, 'For organizations with geographically dispersed physical locations, off-site outsourcers located near distant facilities might be able to respond more quickly than personnel located at the organizations headquarters.', 'kb-doc-04-nist-sp-800-86-p18-3', 0, 27, '04-nist-sp-800-86', 'retrieved', 'C6CD67EEE6B32DD71C36D5FB22F752C7E2E331EF2B4805D1A191FF58A23F9F11', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p18-5', 'doc-04-nist-sp-800-86', '', 18, 'Because of data sensitivity and privacy concerns, some organizations might be reluctant to allow external parties to image hard drives and perform other actions that provide access to data.', 'kb-doc-04-nist-sp-800-86-p18-5', 0, 29, '04-nist-sp-800-86', 'retrieved', 'DC83EBF021E87E79BBB5429DAA461F3B8ED10DFBCCE54D3150D7E21297F9C4DC', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
