INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p18-6', 'doc-04-nist-sp-800-86', '', 18, 'For example, a system that contains traces of an incident might also contain health care information, financial records, or other sensitive data; an organization might prefer to keep that system under its own control to safeguard the privacy of the data.', 'kb-doc-04-nist-sp-800-86-p18-6', 0, 41, '04-nist-sp-800-86', 'retrieved', '3DADC30D16F28E38426693A3432FBF34D6925196FE33C6302DFFD333019D6DEC', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p18-7', 'doc-04-nist-sp-800-86', '', 18, 'On the other hand, if there is a privacy concern within the teamfor example, if an incident is suspected to involve a member of the incident handling teamuse of an independent third party to perform forensic actions would be preferable.', 'kb-doc-04-nist-sp-800-86-p18-7', 0, 40, '04-nist-sp-800-86', 'retrieved', '002E8723402F4577C418D5F8CEF5A4398D05609D3F2118ED2F4E003BE46912FC', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p18-8', 'doc-04-nist-sp-800-86', '', 18, 'Incident handlers performing forensic tasks need to have a reasonably comprehensive knowledge of forensic principles, guidelines, procedures, tools, and techniques, as well as anti-forensic tools and techniques that could conceal or destroy data.', 'kb-doc-04-nist-sp-800-86-p18-8', 0, 33, '04-nist-sp-800-86', 'retrieved', '8871980E6A8170B8217D124264DD5EDE5C124FD02E323CDBE56427558D96B293', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p18-9', 'doc-04-nist-sp-800-86', '', 18, 'It is also beneficial for incident handlers to have expertise in information security and specific technical subjects, such as the most commonly used OSs, filesystems, applications, and network protocols within the organization.', 'kb-doc-04-nist-sp-800-86-p18-9', 0, 32, '04-nist-sp-800-86', 'retrieved', '430185C5BF66BC45770BBAD3B2381D854E895519814F3F56FE017A0A608D11D5', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p18-10', 'doc-04-nist-sp-800-86', '', 18, 'Having this type of knowledge facilitates faster and more effective responses to incidents.', 'kb-doc-04-nist-sp-800-86-p18-10', 0, 13, '04-nist-sp-800-86', 'retrieved', 'DFCB5B37584DDDFF1D0CF872E760BFA0B527913C1679FE117EBE491D1CC67A70', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p18-11', 'doc-04-nist-sp-800-86', '', 18, 'Incident handlers also need a general, broad understanding of systems and networks so that they can determine quickly which teams and individuals are well-suited to providing technical expertise for particular forensic efforts, such as examining and analyzing data for an uncommon application.', 'kb-doc-04-nist-sp-800-86-p18-11', 0, 42, '04-nist-sp-800-86', 'retrieved', '59CB26BE6C35AEC0BE0713A7CBDCAF4589B0C07162466B8194B99AA465CB17FC', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p18-12', 'doc-04-nist-sp-800-86', '', 18, 'Individuals performing forensics might need to perform other types of tasks as well.', 'kb-doc-04-nist-sp-800-86-p18-12', 0, 13, '04-nist-sp-800-86', 'retrieved', '2DF79F838CDA9938D585BF3D26216D9B7958681D63C2CA446192FAF6D5FDFB33', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p18-13', 'doc-04-nist-sp-800-86', '', 18, 'For example, if the results of an investigation are used in a court of law, incident handlers may be called upon to provide testimony and corroborate their findings.', 'kb-doc-04-nist-sp-800-86-p18-13', 0, 28, '04-nist-sp-800-86', 'retrieved', '7BC9CD6AC4505BDDF6D947B89F65E1E7AC0D178CE6F08C0773C1D33B04382A81', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p18-14', 'doc-04-nist-sp-800-86', '', 18, 'Incident handlers might provide training courses in forensics to technical support staff, system and network administrators, and other IT professionals.', 'kb-doc-04-nist-sp-800-86-p18-14', 0, 20, '04-nist-sp-800-86', 'retrieved', '24A42C16D1DA8819334963CB941283E0F32603A3382DC286879A4448FD8AD70E', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p18-15', 'doc-04-nist-sp-800-86', '', 18, 'Possible training topics include an overview of forensics tools and techniques, advice on using a particular tool, and the signs of a new type of attack.', 'kb-doc-04-nist-sp-800-86-p18-15', 0, 26, '04-nist-sp-800-86', 'retrieved', 'A5C0E101F1DA15D182EDA2198C9BB5A020B8854AD0D18150F6AFBBE2EED9332D', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p18-16', 'doc-04-nist-sp-800-86', '', 18, 'Incident handlers might also want to have interactive sessions with groups of IT professionals to hear their thoughts on forensics tools and identify potential shortcomings in existing forensics capabilities.', 'kb-doc-04-nist-sp-800-86-p18-16', 0, 29, '04-nist-sp-800-86', 'retrieved', '80B54C5129D16C019A63CA4D8A04FD26C7F372A9FF5A76D7A47A4070C7A53088', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p18-17', 'doc-04-nist-sp-800-86', '', 18, 'On an incident handling team, more than one team member should be able to perform each typical forensic activity so that the absence of any single team member will not severely impact the teams abilities.', 'kb-doc-04-nist-sp-800-86-p18-17', 0, 35, '04-nist-sp-800-86', 'retrieved', '06FDFE14374BFBD393850C4E39812893D82B9A6D6192D4A300DC178129816566', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p18-18', 'doc-04-nist-sp-800-86', '', 18, 'Incident handlers can train each other in the use of forensic tools and other technical and procedural topics.', 'kb-doc-04-nist-sp-800-86-p18-18', 0, 18, '04-nist-sp-800-86', 'retrieved', 'E320532285DE42AE5AD06696E7AC048C6E57D123B2DD4E03725814C9AA43049E', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p18-19', 'doc-04-nist-sp-800-86', '', 18, 'Hands-on exercises and external IT and forensic training courses can also be helpful in building and maintaining skills.', 'kb-doc-04-nist-sp-800-86-p18-19', 0, 18, '04-nist-sp-800-86', 'retrieved', 'BA1414FD324D0BD7B5764EF1CAACB4F9A60AD7CF69E3AB1BD104833E87E47011', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p18-20', 'doc-04-nist-sp-800-86', '', 18, 'In addition, it might be beneficial to have team members see demonstrations of new tools and technologies or try out forensic and anti-forensic tools in a lab.', 'kb-doc-04-nist-sp-800-86-p18-20', 0, 27, '04-nist-sp-800-86', 'retrieved', '36098C6AA31832A3BB1B6F24929F1B135952AEA0D0E6E7DA33B24043B035BAAB', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p18-21', 'doc-04-nist-sp-800-86', '', 18, 'This can be particularly useful in familiarizing incident handlers with the collection, examination, and analysis of data from devices such as cell phones and PDAs.', 'kb-doc-04-nist-sp-800-86-p18-21', 0, 25, '04-nist-sp-800-86', 'retrieved', '043B6E4DE225024039AED46C478B426DA097AA0524BDC2C83E049387FF6E52A7', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p18-22', 'doc-04-nist-sp-800-86', '', 18, 'Incident handlers need to stay current with new forensic technologies, techniques, and procedures.', 'kb-doc-04-nist-sp-800-86-p18-22', 0, 13, '04-nist-sp-800-86', 'retrieved', '9E34F5FC1745AFDB7FE715156821C87587F6DAB0E911C977BFF0028BEDD25681', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p18-23', 'doc-04-nist-sp-800-86', '', 18, '2.3 Interactions with Other Teams It is not feasible for any one person to be well-versed in every technology (including all software) used within an organization; therefore, individuals performing forensic actions should be able to reach out to other teams and individuals within their organization as needed for additional assistance.', 'kb-doc-04-nist-sp-800-86-p18-23', 0, 50, '04-nist-sp-800-86', 'retrieved', '1423F46DCABB56EC8AF993630E1D78019F2AD93D0910B193AF06E1A36F58D308', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p18-24', 'doc-04-nist-sp-800-86', '', 18, 'For example, an incident involving a particular database server might be handled more efficiently if the database administrator were available to provide background information, answer technical questions, and provide database documentation and other reference material.', 'kb-doc-04-nist-sp-800-86-p18-24', 0, 35, '04-nist-sp-800-86', 'retrieved', 'A436917E5A7B880C6B55AB3B8EEAB4B953DDD6194A5FA535D3F525905D75C226', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p18-25', 'doc-04-nist-sp-800-86', '', 18, 'Organizations should ensure that IT professionals throughout the organization, especially incident handlers and other first responders to incidents, 2-4', 'kb-doc-04-nist-sp-800-86-p18-25', 0, 19, '04-nist-sp-800-86', 'retrieved', '309C10004B2B92F3050D090AF701AB5900B9F7B74EEDDC52468404796CE98EAF', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p19-1', 'doc-04-nist-sp-800-86', '', 19, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE understand their roles and responsibilities for forensics, receive ongoing training and education on forensicrelated policies, guidelines, and procedures, and are prepared to cooperate with and assist others when the technologies that they are responsible for are part of an incident or other event.', 'kb-doc-04-nist-sp-800-86-p19-1', 0, 51, '04-nist-sp-800-86', 'retrieved', '39037732A1AEE29AF6C7AE29F2250D57FD6E071919A13A7D887D126226082C29', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p19-2', 'doc-04-nist-sp-800-86', '', 19, 'In addition to IT professionals and incident handlers, others within an organization may also need to participate in forensic activities in a less technical capacity.', 'kb-doc-04-nist-sp-800-86-p19-2', 0, 25, '04-nist-sp-800-86', 'retrieved', '259C8A168B86974B413CC4B89EB48B92FD62AC259E76F6742A6350997178DA6C', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p19-3', 'doc-04-nist-sp-800-86', '', 19, 'Examples include management, legal advisors, human resources personnel, auditors, and physical security staff.', 'kb-doc-04-nist-sp-800-86-p19-3', 0, 13, '04-nist-sp-800-86', 'retrieved', '3177668180D10B7CC315EDB156515CC7524A581CD56E66CB9AF4833D0B315789', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p19-4', 'doc-04-nist-sp-800-86', '', 19, 'Management is responsible for supporting forensic capabilities, reviewing and approving forensic policy, and approving certain forensic actions (e.g., taking a mission-critical system off-line for 6 hours to collect data from its hard drives).', 'kb-doc-04-nist-sp-800-86-p19-4', 0, 33, '04-nist-sp-800-86', 'retrieved', '0F31BF8FEB6D868D006F8BE323668E8E2EC31C7EB5D6D7C7C3DAF3646A9B3798', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p19-5', 'doc-04-nist-sp-800-86', '', 19, 'Legal advisors should carefully review all forensic policy and high-level guidelines and procedures, and they can provide additional guidance when needed to ensure that forensic actions are performed lawfully.', 'kb-doc-04-nist-sp-800-86-p19-5', 0, 29, '04-nist-sp-800-86', 'retrieved', 'C9939F5AA7357A940D8DC4211FC87A359634D3CAE795DC24419DBEE0EBBE4E97', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
