INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p19-6', 'doc-04-nist-sp-800-86', '', 19, 'The human resources department can provide assistance in dealing with employee relations and the handling of internal incidents.', 'kb-doc-04-nist-sp-800-86-p19-6', 0, 18, '04-nist-sp-800-86', 'retrieved', '22BD243F88EA4DA74F811E80B2955C1C10054D100E95D5AE41C0EAA0D2BAB452', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
