INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p19-7', 'doc-04-nist-sp-800-86', '', 19, 'Auditors can help determine the economic impact of an incident, including the cost of forensic activity.', 'kb-doc-04-nist-sp-800-86-p19-7', 0, 16, '04-nist-sp-800-86', 'retrieved', 'BDC92FEA1A315AE41A66C193EBAC1037D99F6A68B64E30CC1743E1DEB185EBF2', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
