INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p19-8', 'doc-04-nist-sp-800-86', '', 19, 'Physical security staff can assist in gaining access to and physically securing evidence.', 'kb-doc-04-nist-sp-800-86-p19-8', 0, 13, '04-nist-sp-800-86', 'retrieved', '58B1793EB0B02662BD35C62CE8192AA2F85C428BA0368778A43F19B909208A5F', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
