INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p19-9', 'doc-04-nist-sp-800-86', '', 19, 'Although these teams often do not play a prominent role in the forensic process, the services that these teams provide can be beneficial.', 'kb-doc-04-nist-sp-800-86-p19-9', 0, 23, '04-nist-sp-800-86', 'retrieved', '79E0A95606F77333FCDF08FF5750569B86591D237C7C23E2DE1B430AB877656B', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p19-10', 'doc-04-nist-sp-800-86', '', 19, 'To facilitate inter-team communications, each team should designate one or more points of contact.', 'kb-doc-04-nist-sp-800-86-p19-10', 0, 14, '04-nist-sp-800-86', 'retrieved', 'E880FFAACD4F82A7FFB0B7A42AA253C0441F00661647567BCB566164400A5185', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p19-11', 'doc-04-nist-sp-800-86', '', 19, 'These individuals are responsible for knowing the expertise of each team member and directing inquiries for assistance to the appropriate person.', 'kb-doc-04-nist-sp-800-86-p19-11', 0, 21, '04-nist-sp-800-86', 'retrieved', '25E1A5F4B5D6E66C5DFC175D89847B3F7BD266A732A4CA305B17777E5A66EDD5', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p19-12', 'doc-04-nist-sp-800-86', '', 19, 'Organizations should maintain a list of contacts that the appropriate teams can reference as needed.', 'kb-doc-04-nist-sp-800-86-p19-12', 0, 15, '04-nist-sp-800-86', 'retrieved', 'E6CFCD2B9FF30EC6D5626231C63476755A0ACBCD233B048668304BE561F2D8B5', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p19-13', 'doc-04-nist-sp-800-86', '', 19, 'The list should include both standard (e.g., office phone) and emergency (e.g., cell phone) contact methods.', 'kb-doc-04-nist-sp-800-86-p19-13', 0, 16, '04-nist-sp-800-86', 'retrieved', '0AD47E5DD42954DEAD23B05EC247C107FE229F1E72C462E699997EB5AD7B0007', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p19-14', 'doc-04-nist-sp-800-86', '', 19, '2.4 P olicies Organizations should ensure that their policies contain clear statements that address all major forensic considerations, such as contacting law enforcement, performing monitoring, and conducting regular reviews of forensic policies, guidelines, and procedures.', 'kb-doc-04-nist-sp-800-86-p19-14', 0, 35, '04-nist-sp-800-86', 'retrieved', 'B0B913D7B2CA57C97DBEFE3EC7E7E1104CE0243CFCF3D8A7F9F730A5DA00C169', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p19-16', 'doc-04-nist-sp-800-86', '', 19, 'Organizations may also have a separate policy for incident handlers and others with forensic roles; this policy would provide more detailed rules for appropriate behavior.', 'kb-doc-04-nist-sp-800-86-p19-16', 0, 25, '04-nist-sp-800-86', 'retrieved', '3977AB7065F2B6F6B591E6F575C772F4B39F1732D5253D018C939BD5FEDB7B9D', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p19-18', 'doc-04-nist-sp-800-86', '', 19, 'Policies may need to be updated frequently, particularly for organizations that span many jurisdictions, because of changes to laws and regulations, as well as new court rulings.', 'kb-doc-04-nist-sp-800-86-p19-18', 0, 27, '04-nist-sp-800-86', 'retrieved', '15116C5D34C74EF2A43F262D53A2B95BB3736E7BE198EE3117C9B18F75B2D106', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p19-19', 'doc-04-nist-sp-800-86', '', 19, 'In addition, the organizations forensic policy should be consistent with the organizations other policies, including policies related to reasonable expectations of privacy.', 'kb-doc-04-nist-sp-800-86-p19-19', 0, 22, '04-nist-sp-800-86', 'retrieved', 'A956456FE3EFDBCC7A23C402C66B13A5EB7B2078DEC54C7B2FD03818697D6A4F', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p19-21', 'doc-04-nist-sp-800-86', '', 19, '2.4.1 Defining Roles and Responsibilities Forensic policy should clearly define the roles and responsibilities of all people performing or assisting with the organizations forensic activities.', 'kb-doc-04-nist-sp-800-86-p19-21', 0, 25, '04-nist-sp-800-86', 'retrieved', 'F9C81AC46B86A2F528ACFD7BBEE783D88B4C3FA093E6F581404C346A07B17997', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p19-22', 'doc-04-nist-sp-800-86', '', 19, 'This should include actions performed during both incident handling and routine work activities (e.g., system administration, network troubleshooting).', 'kb-doc-04-nist-sp-800-86-p19-22', 0, 18, '04-nist-sp-800-86', 'retrieved', '2D29696A9A9D8E30C8432DB82D52D554ADA9FD40564174605F1C7AB731CA2139', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p19-23', 'doc-04-nist-sp-800-86', '', 19, 'The policy should include all internal teams that may participate in forensic efforts, such as those listed in Section 2.3, and external organizations such as law enforcement agencies, outsourcers, and incident response organizations.', 'kb-doc-04-nist-sp-800-86-p19-23', 0, 33, '04-nist-sp-800-86', 'retrieved', 'F5A20A0EEBAC224A4465673F88CD565E410E25E4EEB7FF7CEE8C3F0438EB46E4', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p19-25', 'doc-04-nist-sp-800-86', '', 19, 'The policy should also discuss jurisdictional conflictsa crime that involves multiple jurisdictions, which could be investigated by multiple law enforcement agenciesand explain how to resolve them.', 'kb-doc-04-nist-sp-800-86-p19-25', 0, 26, '04-nist-sp-800-86', 'retrieved', '3D0D4C3CDFFD561A9435A3076B3BCCB9BD2D26400CE991A950BD2E84201D433E', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p19-26', 'doc-04-nist-sp-800-86', '', 19, 'As mentioned in Section 2.2, some organizations have an Office of Inspector General (OIG) that is responsible for investigating allegations of misconduct; the OIG may also be well-suited to resolving jurisdictional conflicts.', 'kb-doc-04-nist-sp-800-86-p19-26', 0, 32, '04-nist-sp-800-86', 'retrieved', '4D002A4EFE5F0706567621AD0673E6B3CA6DDAD615258F6C5D858361355AFC8E', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p19-27', 'doc-04-nist-sp-800-86', '', 19, 'In some organizations, if a crime may have been committed, the OIG immediately takes over the investigation.', 'kb-doc-04-nist-sp-800-86-p19-27', 0, 17, '04-nist-sp-800-86', 'retrieved', '7E2DBF0B1E92436AB9DF71EB3C1E6CDF7D034738CAF1019182200992FBB8C4CE', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p20-1', 'doc-04-nist-sp-800-86', '', 20, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE 2.4.2 2.4.3 Providing Guidance for Forensic Tool Use Incident handlers; IT professionals, such as system and network administrators; and others within an organization use forensic tools and techniques for a variety of reasons.', 'kb-doc-04-nist-sp-800-86-p20-1', 0, 41, '04-nist-sp-800-86', 'retrieved', '3C2EC94F2AAE6ED23E8E298C5171743B849E1817A77E9478153DFECBCA3F3628', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p20-2', 'doc-04-nist-sp-800-86', '', 20, 'Although the technologies have many benefits, they can also be misused accidentally or intentionally to provide unauthorized access to information, or to alter or destroy information, including evidence of an incident.', 'kb-doc-04-nist-sp-800-86-p20-2', 0, 31, '04-nist-sp-800-86', 'retrieved', '4682723AD631FFCA696172637EBEBCF6263BD60629B6EF13B9509149B0724155', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p20-3', 'doc-04-nist-sp-800-86', '', 20, 'In addition, the use of certain forensic tools may not be warranted in some situations (for example, a minor incident probably does not merit hundreds of hours of data collection and examination efforts).', 'kb-doc-04-nist-sp-800-86-p20-3', 0, 33, '04-nist-sp-800-86', 'retrieved', '87217B3F5E6F9F0740FC54CA79EF97334F0CBB15D2C5825CDE6963099C390226', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p20-4', 'doc-04-nist-sp-800-86', '', 20, 'To ensure that tools are used reasonably and appropriately, the organizations policies, guidelines, and procedures should clearly explain what forensic actions should and should not be performed under various circumstances.', 'kb-doc-04-nist-sp-800-86-p20-4', 0, 30, '04-nist-sp-800-86', 'retrieved', '1B1A3CDE35A26D37299D20BFEBD5C9C112E7330CB846417DB3B95DB4224AB836', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p20-5', 'doc-04-nist-sp-800-86', '', 20, 'For example, a network administrator should be able to monitor network communications on a regular basis to solve operational problems, but should not read users e-mail unless specifically authorized to do so.', 'kb-doc-04-nist-sp-800-86-p20-5', 0, 32, '04-nist-sp-800-86', 'retrieved', '45B1BC128DB4C7F797DDA57A1704FD22D27F284B5325111072B4471561F76D0B', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p20-6', 'doc-04-nist-sp-800-86', '', 20, 'A help desk agent might be permitted to monitor network communications for a particular users workstation to troubleshoot an application problem but not be permitted to perform any other network monitoring.', 'kb-doc-04-nist-sp-800-86-p20-6', 0, 31, '04-nist-sp-800-86', 'retrieved', '7D20A5C90143FD27ADC72277E9180B76D10BEF8A8708CB27C78072123A85FE56', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p20-7', 'doc-04-nist-sp-800-86', '', 20, 'Individual users might be forbidden from performing any network monitoring under any circumstances.', 'kb-doc-04-nist-sp-800-86-p20-7', 0, 13, '04-nist-sp-800-86', 'retrieved', '3A32A013FF99E3D12FAF38AEA2E9104FDD810B487616211346E0E833409F08B1', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
