INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p20-8', 'doc-04-nist-sp-800-86', '', 20, 'Policies, guidelines, and procedures should clearly define the specific actions that are permitted and forbidden for each applicable role under normal circumstances (e.g., typical duties) and special circumstances (e.g., incident handling).', 'kb-doc-04-nist-sp-800-86-p20-8', 0, 31, '04-nist-sp-800-86', 'retrieved', '1FB774A11A8A92EF37119543C08909795A49FDA993130F955E5EF8273316A23E', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p20-9', 'doc-04-nist-sp-800-86', '', 20, 'Policies, guidelines, and procedures should also address the use of anti-forensic tools and techniques.', 'kb-doc-04-nist-sp-800-86-p20-9', 0, 14, '04-nist-sp-800-86', 'retrieved', '2D4DA747EF6086465B7E198464307D536B1A43FE3C568BF84F315D8D12773B65', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p20-10', 'doc-04-nist-sp-800-86', '', 20, 'Described in Sections 4 through 7, anti-forensic software is designed to conceal or destroy data so that others cannot access it.', 'kb-doc-04-nist-sp-800-86-p20-10', 0, 21, '04-nist-sp-800-86', 'retrieved', 'E1F415303F76BD88858AF50705E98930D009A7E1D5F9F20E177B473AA9BE9095', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p20-11', 'doc-04-nist-sp-800-86', '', 20, 'There are many positive uses for anti-forensic software, such as removing data from computers that are to be donated to charity and removing data cached by Web browsers to preserve a users privacy.', 'kb-doc-04-nist-sp-800-86-p20-11', 0, 33, '04-nist-sp-800-86', 'retrieved', 'F1A6855BC5DC57CC6D9181E0A59F44077E8190EE02AA7CFA15C224D6D1FA75B6', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p20-12', 'doc-04-nist-sp-800-86', '', 20, 'However, like forensic tools, anti-forensic tools can also be used for malicious reasons.', 'kb-doc-04-nist-sp-800-86-p20-12', 0, 13, '04-nist-sp-800-86', 'retrieved', 'EB525680CDF668634064650BF58D9BFCD938DDDDC5CC19F11F437CFDA5C99AD7', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p20-13', 'doc-04-nist-sp-800-86', '', 20, 'Therefore, organizations should specify who is permitted to use such tools and under what circumstances.', 'kb-doc-04-nist-sp-800-86-p20-13', 0, 15, '04-nist-sp-800-86', 'retrieved', '4408EAEE96EB11DE23B2738057F2408A49058C2C8C72DE73F7D8086B70E901DD', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p20-14', 'doc-04-nist-sp-800-86', '', 20, 'Because forensic tools may record sensitive information, policies, guidelines, and procedures should also describe the necessary safeguards for the information.', 'kb-doc-04-nist-sp-800-86-p20-14', 0, 20, '04-nist-sp-800-86', 'retrieved', '41B581084181E64DB362A1DAF40F7EE7C439A39AF58D1BCDB1BE879DDF96E04C', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p20-15', 'doc-04-nist-sp-800-86', '', 20, 'There should also be requirements for handling inadvertent exposures of sensitive information, such as an incident handler seeing passwords or patient medical information.', 'kb-doc-04-nist-sp-800-86-p20-15', 0, 23, '04-nist-sp-800-86', 'retrieved', '3EA3282E0890FF582B210B942FBC55E7156D2770BFF11C4C050CE50713279E9B', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p20-16', 'doc-04-nist-sp-800-86', '', 20, 'Supporting Forensics in the Information System Life Cycle Many incidents can be handled more efficiently and effectively if forensic considerations have been incorporated into the information system life cycle.', 'kb-doc-04-nist-sp-800-86-p20-16', 0, 29, '04-nist-sp-800-86', 'retrieved', 'F3AD80DDE08FC611005C2CDF32D31880AFB6E77BB9E75252619DCD76C35D44A2', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p20-17', 'doc-04-nist-sp-800-86', '', 20, 'Examples of such considerations are as follows: ! Performing regular backups of systems and maintaining previous backups for a specific period of time ! Enabling auditing on workstations, servers, and network devices ! Forwarding audit records to secure centralized log servers ! Configuring mission-critical applications to perform auditing, including recording all authentication attempts ! Maintaining a database of file hashes for the files of common OS and application deployments, and using file integrity checking software on particularly important assets ! Maintaining records (e.g., baselines) of network and system configurations 2-6', 'kb-doc-04-nist-sp-800-86-p20-17', 0, 90, '04-nist-sp-800-86', 'retrieved', '4BBD24ACED0F909DED2CF902E1B637C859E8E52BDD63F13C198E1D82F5DE2599', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p21-1', 'doc-04-nist-sp-800-86', '', 21, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE ! Establishing data retention policies that support performing historical reviews of system and network activity, complying with requests or requirements to preserve data relating to ongoing litigation and investigations, and destroying data that is no longer needed.', 'kb-doc-04-nist-sp-800-86-p21-1', 0, 45, '04-nist-sp-800-86', 'retrieved', '43A5053E771189F47563CA24F411F0D8CB8D57ECCAD1FCC2327483A3FB5325FD', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p21-2', 'doc-04-nist-sp-800-86', '', 21, 'Most of these considerations are extensions of existing provisions in the organizations policies and procedures, so they are typically specified within the relevant individual documents instead of a centralized forensics policy.', 'kb-doc-04-nist-sp-800-86-p21-2', 0, 31, '04-nist-sp-800-86', 'retrieved', 'DC0EC9F83B9D4AC63E9912C5C65B8FAACDA246FC042476595CD1E9D86E2C086B', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p21-3', 'doc-04-nist-sp-800-86', '', 21, '2.5 Guidelines and Procedures As mentioned in Section 2.4, an organization should create and maintain guidelines and procedures for performing forensic tasks, based on the organizations policies, incident response staffing models, and other teams identified as participants in forensic activities.', 'kb-doc-04-nist-sp-800-86-p21-3', 0, 40, '04-nist-sp-800-86', 'retrieved', '6FBAD8233C945DE01DE93C379A1BF245C0E7B88D2C970C7FA6C1C08394B80242', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p21-4', 'doc-04-nist-sp-800-86', '', 21, 'Even if the activities are performed by external parties, the organizations internal staff will still interact with them and participate to some extent in the activities, such as notifying the external party of a need for assistance, granting physical or logical access to systems, and securing an incident scene until an investigator arrives.', 'kb-doc-04-nist-sp-800-86-p21-4', 0, 53, '04-nist-sp-800-86', 'retrieved', 'A3EED4819220563C0C1580535D8482DDF9F680CD18DCF142D54EFF0F6E6E4B72', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p21-5', 'doc-04-nist-sp-800-86', '', 21, 'The internal staff should work closely with the external parties to ensure that the organizations policies, guidelines, and procedures are understood and followed.', 'kb-doc-04-nist-sp-800-86-p21-5', 0, 23, '04-nist-sp-800-86', 'retrieved', '8473DE2AC0160EC8A093DEF5C932CF93C85DADF4BEE37EC03A7ACE4391C4C6FC', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p21-6', 'doc-04-nist-sp-800-86', '', 21, 'An organizations forensic guidelines should include general methodologies for investigating an incident using forensic techniques, since it is not feasible to develop comprehensive procedures tailored to every possible situation.', 'kb-doc-04-nist-sp-800-86-p21-6', 0, 29, '04-nist-sp-800-86', 'retrieved', 'E3955E0544E80D94AFDCBD2186707109243B595F159128C14054E8B7B0DDBB08', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p21-7', 'doc-04-nist-sp-800-86', '', 21, 'However, organizations also should consider developing step-by-step procedures for performing routine tasks, such as imaging a hard disk, capturing and recording volatile information from systems, or securing physical evidence (e.g., removable media).', 'kb-doc-04-nist-sp-800-86-p21-7', 0, 32, '04-nist-sp-800-86', 'retrieved', '77BDAE52033323C91EEF41644D8072089608E66BF302901257512F106B509E19', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p21-8', 'doc-04-nist-sp-800-86', '', 21, 'The goal for the guidelines and procedures is to facilitate consistent, effective, and accurate forensic actions, which is particularly important for incidents that may lead to prosecution or internal disciplinary actions.', 'kb-doc-04-nist-sp-800-86-p21-8', 0, 31, '04-nist-sp-800-86', 'retrieved', 'D40B5348357AC43CA7F1E3A4500D717A6FB012FBD912A2C0AD50F0EAC8E1673C', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p21-9', 'doc-04-nist-sp-800-86', '', 21, 'Because electronic logs and other records can be altered or otherwise manipulated, organizations should be prepared, through their policies, guidelines, and procedures, to demonstrate the integrity of such records.6 Information is rapidly migrating to a form in which all the information assets exist in electronic form.', 'kb-doc-04-nist-sp-800-86-p21-9', 0, 46, '04-nist-sp-800-86', 'retrieved', 'E635E6301803C2347D2F03B8DFD9743365D1A2327145D2E99C3FAD5816C8A829', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p21-10', 'doc-04-nist-sp-800-86', '', 21, 'In both the public and private sectors, it is increasingly important to demonstrate conclusively the authenticity, credibility, and reliability of electronic records, such as the performance of a specific action or decision, or the existence of a certain item of information.', 'kb-doc-04-nist-sp-800-86-p21-10', 0, 41, '04-nist-sp-800-86', 'retrieved', 'D29F48CF5D829511FBEAFAB429BFF3CC403866AA36D73076EFC09FCC88934C27', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p21-12', 'doc-04-nist-sp-800-86', '', 21, 'Increasingly, some in the legal and forensic communities are concerned with the ease with which electronic records can be created, altered, or otherwise manipulated.', 'kb-doc-04-nist-sp-800-86-p21-12', 0, 24, '04-nist-sp-800-86', 'retrieved', 'B29184545E54AF00F684312E98397F06ED4E996214CFD22D02012AF070A52FA9', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p21-13', 'doc-04-nist-sp-800-86', '', 21, 'In addition, various compliance initiatives in the public and private sectors are making it increasingly important to demonstrate the integrity of electronic records.', 'kb-doc-04-nist-sp-800-86-p21-13', 0, 23, '04-nist-sp-800-86', 'retrieved', '72076037EDFD5531D3FA70557FB2206C7254C96B0E4935FEA32E015BE3473E94', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p21-14', 'doc-04-nist-sp-800-86', '', 21, 'With the explicit caveat that such issues are matters for discussion with legal counsel and senior IT officials and well beyond the scope of this publication, the use of sound, documented, and reasonably explicable forensic techniques coupled with other methods (such as log retention and analysis) is an important resource for decision makers as well as for incident handlers.', 'kb-doc-04-nist-sp-800-86-p21-14', 0, 59, '04-nist-sp-800-86', 'retrieved', 'E16A42B9CC5ABC297B02499D138676AEAFF9C251C159C66713DC35DF95F62D74', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p21-15', 'doc-04-nist-sp-800-86', '', 21, 'Forensic guidelines and procedures should be consistent with the organizations policies and all applicable laws.', 'kb-doc-04-nist-sp-800-86-p21-15', 0, 15, '04-nist-sp-800-86', 'retrieved', 'F44CFCED819904B14392886EE60A71326A5337F906DA6D20BAF1553E1AC5F00B', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p21-16', 'doc-04-nist-sp-800-86', '', 21, 'Organizations should include technical experts and legal advisors in the development of guidelines and procedures as a quality assurance measure.', 'kb-doc-04-nist-sp-800-86-p21-16', 0, 20, '04-nist-sp-800-86', 'retrieved', 'B68E2FB31789A247C1CBB1D8E3F349EE2FF9B702C993803E18179E0EBE28357B', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
