INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p21-17', 'doc-04-nist-sp-800-86', '', 21, 'Management should also be involved in guideline and procedure development, particularly in ensuring that all major decision-making points are documented and that the proper course of action is defined so that decisions are made consistently.', 'kb-doc-04-nist-sp-800-86-p21-17', 0, 35, '04-nist-sp-800-86', 'retrieved', '3991A27CCA020F861D21A81836B904CF764BAAF42854E154D8366249D58DC5E1', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
