INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p21-18', 'doc-04-nist-sp-800-86', '', 21, '6 For more information on preserving the integrity of computer security logs, see NIST SP 800-92 (DRAFT), Guide to Computer Security Log Management, which is available at http://csrc.nist.gov/publications/nistpubs/.', 'kb-doc-04-nist-sp-800-86-p21-18', 0, 28, '04-nist-sp-800-86', 'retrieved', '21EC8662CCFD66F344DC6B280154558ADE73A27F0AED0B97BFC4FE920EFF7D09', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
