INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p22-1', 'doc-04-nist-sp-800-86', '', 22, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE The guidelines and procedures should support the admissibility of evidence into legal proceedings, including information on gathering and handling evidence properly, preserving the integrity of tools and equipment, maintaining the chain of custody, and storing evidence securely.7 Although it may not be feasible to record every event or action taken in response to an incident, having a record of the major events and actions taken helps ensure that nothing has been overlooked, and helps explain to others how the incident was handled.', 'kb-doc-04-nist-sp-800-86-p22-1', 0, 90, '04-nist-sp-800-86', 'retrieved', '8A04A9E737DAEB4C8F434F12DE467B55AFBAE5531CD662A47679A903FEC76A06', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p22-2', 'doc-04-nist-sp-800-86', '', 22, 'This documentation can be useful for case management, report writing, and testifying.', 'kb-doc-04-nist-sp-800-86-p22-2', 0, 12, '04-nist-sp-800-86', 'retrieved', 'DBA5ED4BE0D0212360C195AB7490AF851847643712658D9B09AE3D23C8EC6852', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
