VALUES ('doc-04-nist-sp-800-86-p22-3', 'doc-04-nist-sp-800-86', '', 22, 'Keeping a record of the dates and times that people worked on an incident, including the time needed to recover systems, can also help calculate the costs of damages.', 'kb-doc-04-nist-sp-800-86-p22-3', 0, 29, '04-nist-sp-800-86', 'retrieved', '6E2A7E01553B0A2EA4923B392AA6239F53F6151BA26872DD400C67F8D2210E18', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
