VALUES ('doc-04-nist-sp-800-86-p22-4', 'doc-04-nist-sp-800-86', '', 22, 'Also, handling evidence in a forensically sound manner puts decision makers in a position where they can confidently take the necessary actions.', 'kb-doc-04-nist-sp-800-86-p22-4', 0, 22, '04-nist-sp-800-86', 'retrieved', '7498FDB882D2BF98B2E2BB479039A011695EBCA2CE7D19A46903AD767A1DF395', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
