VALUES ('doc-04-nist-sp-800-86-p22-5', 'doc-04-nist-sp-800-86', '', 22, 'It is also important to maintain the guidelines and procedures once they are created so that they remain accurate.', 'kb-doc-04-nist-sp-800-86-p22-5', 0, 19, '04-nist-sp-800-86', 'retrieved', 'EFAFB7C768EFF411E871698F90AC9A3E1A37893A14A647C9E7D4C1BB5DF22726', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
