VALUES ('doc-04-nist-sp-800-86-p22-6', 'doc-04-nist-sp-800-86', '', 22, 'Management should determine how frequently the guidelines and procedures should be reviewed (generally, at least annually).', 'kb-doc-04-nist-sp-800-86-p22-6', 0, 16, '04-nist-sp-800-86', 'retrieved', '98689064475B8E37F9631512149457B7682374E9EAE0926248B4DF239090E6AE', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
