VALUES ('doc-04-nist-sp-800-86-p22-7', 'doc-04-nist-sp-800-86', '', 22, 'Reviews should also be conducted whenever the teams policies, guidelines, and procedures undergo significant changes.', 'kb-doc-04-nist-sp-800-86-p22-7', 0, 15, '04-nist-sp-800-86', 'retrieved', '215E8F781E80B28525DDC29D8D71958A0D28143DF56CE2E46AFC432E0C77FD00', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
