VALUES ('doc-04-nist-sp-800-86-p22-8', 'doc-04-nist-sp-800-86', '', 22, 'When a guideline or procedure is updated, the previous version should be archived for possible future use in legal proceedings.', 'kb-doc-04-nist-sp-800-86-p22-8', 0, 20, '04-nist-sp-800-86', 'retrieved', '94F2364E931D1EDE7090A744C3C77333255C82BEE2193CF013E58C232ABC18F6', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
