VALUES ('doc-04-nist-sp-800-86-p22-9', 'doc-04-nist-sp-800-86', '', 22, 'Guideline and procedure reviews should include the same teams that participate in their creation.', 'kb-doc-04-nist-sp-800-86-p22-9', 0, 14, '04-nist-sp-800-86', 'retrieved', '27DCC8A9145D4B86100016010A49F1C15C06FA381874312A29D4737B26D32659', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
