VALUES ('doc-04-nist-sp-800-86-p22-10', 'doc-04-nist-sp-800-86', '', 22, 'In addition to performing reviews, organizations might choose to conduct exercises that help to validate the accuracy of certain guidelines and procedures.', 'kb-doc-04-nist-sp-800-86-p22-10', 0, 22, '04-nist-sp-800-86', 'retrieved', '151DD82B0AFEDD60035D20414EA537E9955DA4115D28E2C66DD27063992BA6DA', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
