INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p22-11', 'doc-04-nist-sp-800-86', '', 22, '2.6 Re commendations The key recommendations on establishing and organizing a forensic capability are as follows: ! Organizations should have a capability to perform computer and network forensics.', 'kb-doc-04-nist-sp-800-86-p22-11', 0, 28, '04-nist-sp-800-86', 'retrieved', 'EF2253206DE5DED048134312EB351D43A4B2E28FE6C7F9C2BB559DB18ADDCF0D', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p22-12', 'doc-04-nist-sp-800-86', '', 22, 'Forensics is needed for various tasks within an organization, including investigating crimes and inappropriate behavior, reconstructing computer security incidents, troubleshooting operational problems, supporting due diligence for audit record maintenance, and recovering from accidental system damage.', 'kb-doc-04-nist-sp-800-86-p22-12', 0, 35, '04-nist-sp-800-86', 'retrieved', '17DC02155EEF1C38889BA00A463CFD09105531DFFBDAFF2D13486F349140BE6C', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p22-15', 'doc-04-nist-sp-800-86', '', 22, '! Organizations should determine which parties should handle each aspect of forensics.', 'kb-doc-04-nist-sp-800-86-p22-15', 0, 12, '04-nist-sp-800-86', 'retrieved', '9F2C82056EF938BD5B6B4E6AC7B3A3265972EBD0490AAB383B2D4E9B41C0E4D1', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p22-16', 'doc-04-nist-sp-800-86', '', 22, 'Most organizations rely on a combination of their own staff and external parties to perform forensic tasks.', 'kb-doc-04-nist-sp-800-86-p22-16', 0, 17, '04-nist-sp-800-86', 'retrieved', '8A9DE89B637E53A6822A37AC378180668A884529FFCD1B913D7AFDDE48F5C7B8', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p22-17', 'doc-04-nist-sp-800-86', '', 22, 'Organizations should decide which parties should take care of which tasks based on skills and abilities, cost, response time, and data sensitivity.', 'kb-doc-04-nist-sp-800-86-p22-17', 0, 22, '04-nist-sp-800-86', 'retrieved', '6997C6034B148D5FBDDBB46CEFAF169E7F243D04885346A895B0D99E6BEAF278', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
