INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p22-19', 'doc-04-nist-sp-800-86', '', 22, 'More than one team member should be able to perform each typical forensic activity.', 'kb-doc-04-nist-sp-800-86-p22-19', 0, 14, '04-nist-sp-800-86', 'retrieved', '1F64A8F72B07CEB1163E471E9E5E46978D44EAFE1EFA72E7DD71445038EFBC17', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
