INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p22-20', 'doc-04-nist-sp-800-86', '', 22, 'Hands-on exercises and IT and forensic training courses can be helpful in building and maintaining skills, as can demonstrations of new tools and technologies.', 'kb-doc-04-nist-sp-800-86-p22-20', 0, 24, '04-nist-sp-800-86', 'retrieved', '2A0B167BEC73AF586D6F3B081FBF7F1916A0A8FF820757016826AA3F106C34D9', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
