INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p22-22', 'doc-04-nist-sp-800-86', '', 22, 'Individuals performing forensic actions should be able to reach out to other teams and individuals within an organization, as needed, for additional assistance.', 'kb-doc-04-nist-sp-800-86-p22-22', 0, 23, '04-nist-sp-800-86', 'retrieved', 'F1098BDD0DFE684737302B09F138BB4E20D01EE19738E75239F1B52937A7ECD1', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
