VALUES ('doc-04-nist-sp-800-86-p22-23', 'doc-04-nist-sp-800-86', '', 22, 'Examples of teams that may provide assistance in these efforts include IT professionals, management, legal advisors, human resources personnel, auditors, and physical security staff.', 'kb-doc-04-nist-sp-800-86-p22-23', 0, 24, '04-nist-sp-800-86', 'retrieved', 'A79C918E868248C5ABFEFC5BE793E036B616DC21303711C04D98F5378C0C7959', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
