VALUES ('doc-04-nist-sp-800-86-p22-25', 'doc-04-nist-sp-800-86', '', 22, '7 This document does not describe the computer and network forensic requirements placed on law enforcement.', 'kb-doc-04-nist-sp-800-86-p22-25', 0, 16, '04-nist-sp-800-86', 'retrieved', '03D6BD069B88E7848E26D4DE237C90CC467BD195E56D40ABD2B72AC6AF8CABCF', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
