INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p22-26', 'doc-04-nist-sp-800-86', '', 22, 'For further information regarding computer and network forensic requirements for law enforcement, see Electronic Crime Scene Investigation: A Guide for First Responders and Forensic Examination of Digital Evidence: A Guide for Law Enforcement, which are both available at http://www.ncjrs.gov/app/topics/topic.aspx?topicid=158.', 'kb-doc-04-nist-sp-800-86-p22-26', 0, 39, '04-nist-sp-800-86', 'retrieved', '76193845640BB39BE447736D5297C3ECF840BF89473880AAFC81B64483BA8E83', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
