VALUES ('doc-04-nist-sp-800-86-p23-4', 'doc-04-nist-sp-800-86', '', 23, 'Organizations may also have a separate forensic policy for incident handlers and others with forensic roles that provides more detailed rules for appropriate behavior.', 'kb-doc-04-nist-sp-800-86-p23-4', 0, 24, '04-nist-sp-800-86', 'retrieved', '9EE9D223A238C3622775227271C5CCD9B8EE9F49BBA500CFB6B05E5E4A5AC99B', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
