INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p23-5', 'doc-04-nist-sp-800-86', '', 23, 'Everyone who may be called upon to assist with any forensic efforts should be familiar with and understand the forensic policy.', 'kb-doc-04-nist-sp-800-86-p23-5', 0, 21, '04-nist-sp-800-86', 'retrieved', '7F9E4ED282DCE015D43324686EF6149ECCCFFA963F0F5FD9794220762FE0EF7A', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p23-6', 'doc-04-nist-sp-800-86', '', 23, 'Additional policy considerations are as follows:  Forensic policy should clearly define the roles and responsibilities of all people performing or assisting with the organizations forensic activities.', 'kb-doc-04-nist-sp-800-86-p23-6', 0, 27, '04-nist-sp-800-86', 'retrieved', '087D19ECEDD9112199653221F0BA7C23461E810C9BBEF927553B81084E8B6F31', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p23-7', 'doc-04-nist-sp-800-86', '', 23, 'The policy should include all internal and external parties that may be involved and should clearly indicate who should contact which parties under different circumstances.', 'kb-doc-04-nist-sp-800-86-p23-7', 0, 25, '04-nist-sp-800-86', 'retrieved', '08BD5188005FC2F4792EA31D013EE839F40793FAD7C8A72A4F08A027079FC788', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
