INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p23-8', 'doc-04-nist-sp-800-86', '', 23, ' The organizations policies, guidelines, and procedures should clearly explain what forensic actions should and should not be performed under normal and special circumstances and should address the use of anti-forensic tools and techniques.', 'kb-doc-04-nist-sp-800-86-p23-8', 0, 34, '04-nist-sp-800-86', 'retrieved', '96383ECF977C109FA1E6F9B181C9728D329EB24AFEF8B77D72B6EFA25707A67F', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
