INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p23-9', 'doc-04-nist-sp-800-86', '', 23, 'Policies, guidelines, and procedures should also address the handling of inadvertent exposures of sensitive information.', 'kb-doc-04-nist-sp-800-86-p23-9', 0, 15, '04-nist-sp-800-86', 'retrieved', '18191EEC8914F4B9B4C82236102DC8C6E9EE835CD488DB51BC46B5EA67EA5A9A', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
