INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p23-10', 'doc-04-nist-sp-800-86', '', 23, ' Incorporating forensic considerations into the information system life cycle can lead to more efficient and effective handling of many incidents.', 'kb-doc-04-nist-sp-800-86-p23-10', 0, 21, '04-nist-sp-800-86', 'retrieved', 'FAA470D82E55A5899062743C30B73EF8A046670DC3DEC54866BB57629D19F5D5', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
