INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p23-11', 'doc-04-nist-sp-800-86', '', 23, 'Examples include performing auditing on hosts and establishing data retention policies that support performing historical reviews of system and network activity.', 'kb-doc-04-nist-sp-800-86-p23-11', 0, 21, '04-nist-sp-800-86', 'retrieved', '8141E71C67F0AD925DAF96ADD6F8F8D8EB85097AB94B4604BFA67797CD029B57', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
