INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p23-12', 'doc-04-nist-sp-800-86', '', 23, '! Organizations should create and maintain guidelines and procedures for performing forensic tasks.', 'kb-doc-04-nist-sp-800-86-p23-12', 0, 13, '04-nist-sp-800-86', 'retrieved', '0A1A978809BAFA3F018E09358920796B495DB02E9102FF3C98A4D56D79EB7844', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
