INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p23-13', 'doc-04-nist-sp-800-86', '', 23, 'The guidelines should include general methodologies for investigating an incident using forensic techniques, and step-by-step procedures should explain how to perform routine tasks.', 'kb-doc-04-nist-sp-800-86-p23-13', 0, 23, '04-nist-sp-800-86', 'retrieved', 'E5EFBB11E055628EBD5E9C9824E3931A07C0184EE382FE96E3E658ABB5E245E5', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
