INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p23-14', 'doc-04-nist-sp-800-86', '', 23, 'The guidelines and procedures should support the admissibility of evidence into legal proceedings.', 'kb-doc-04-nist-sp-800-86-p23-14', 0, 13, '04-nist-sp-800-86', 'retrieved', '18020C87BB45B1A5B50B5C93D0E3D1CB531A58487CD90174DBC14B284565CFE5', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p23-15', 'doc-04-nist-sp-800-86', '', 23, 'Because electronic logs and other records can be altered or otherwise manipulated, organizations should be prepared, through their policies, guidelines, and procedures, to demonstrate the reliability and integrity of such records.', 'kb-doc-04-nist-sp-800-86-p23-15', 0, 31, '04-nist-sp-800-86', 'retrieved', 'BC942EED738FBAB80C00D5FA1E42318EE83D1D2323B89B102EB36230D6369846', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p23-16', 'doc-04-nist-sp-800-86', '', 23, 'The guidelines and procedures should also be reviewed regularly and maintained so that they are accurate.', 'kb-doc-04-nist-sp-800-86-p23-16', 0, 16, '04-nist-sp-800-86', 'retrieved', '8943B736033A419FD614380D08C37E55C99AB8A1F0A3E3F50A3CC148DCDD9A85', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p25-1', 'doc-04-nist-sp-800-86', '', 25, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE 3. Performing the Forensic Process The most common goal of performing forensics is to gain a better understanding of an event of interest by finding and analyzing the facts related to that event.', 'kb-doc-04-nist-sp-800-86-p25-1', 0, 41, '04-nist-sp-800-86', 'retrieved', '7138F5412C7E8F509B2EFC1D1AB9F5F3D4A64ADC14DA85334518AAD36C0832DB', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p25-2', 'doc-04-nist-sp-800-86', '', 25, 'As described in Section 2.1, forensics may be needed in many different situations, such as evidence collection for legal proceedings and internal disciplinary actions, and handling of malware incidents and unusual operational problems.', 'kb-doc-04-nist-sp-800-86-p25-2', 0, 33, '04-nist-sp-800-86', 'retrieved', '6E3FC9D19F8E0283A53E6B70F59D97CB0AFAD2ACBC85E3569A3FE83B5E47C72B', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p25-3', 'doc-04-nist-sp-800-86', '', 25, 'Regardless of the need, forensics should be performed using the four-phase process shown in Figure 3-1.', 'kb-doc-04-nist-sp-800-86-p25-3', 0, 16, '04-nist-sp-800-86', 'retrieved', '36C6735F39E9D078B22398F79C19D976F98355C3ECD62B3E0510E63F6512890C', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p25-4', 'doc-04-nist-sp-800-86', '', 25, 'The exact details of these steps may vary based on the specific need for forensics; the organizations policies, guidelines, and procedures should indicate any variations from the standard procedure.', 'kb-doc-04-nist-sp-800-86-p25-4', 0, 29, '04-nist-sp-800-86', 'retrieved', '52CB5F7753A61BBA417B1D7F0494764E54B6764FDFC3761291A04337EB6A9D30', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p25-5', 'doc-04-nist-sp-800-86', '', 25, 'This section describes the basic phases of the forensic process: collection, examination, analysis, and reporting.8 During collection, data related to a specific event is identified, labeled, recorded, and collected, and its integrity is preserved.', 'kb-doc-04-nist-sp-800-86-p25-5', 0, 34, '04-nist-sp-800-86', 'retrieved', '689AE3EF4F38F11B0D799ADE75E5D8D8F48A20FAEDC47566A1D9E7509F19B1E5', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p25-6', 'doc-04-nist-sp-800-86', '', 25, 'In the second phase, examination, forensic tools and techniques appropriate to the types of data that were collected are executed to identify and extract the relevant information from the collected data while protecting its integrity.', 'kb-doc-04-nist-sp-800-86-p25-6', 0, 35, '04-nist-sp-800-86', 'retrieved', 'F4623BB82C4D649B24C2F1BFF3DC343604AE17313BF8C789BB0B100F638308A0', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p25-8', 'doc-04-nist-sp-800-86', '', 25, 'The next phase, analysis, involves analyzing the results of the examination to derive useful information that addresses the questions that were the impetus for performing the collection and examination.', 'kb-doc-04-nist-sp-800-86-p25-8', 0, 29, '04-nist-sp-800-86', 'retrieved', 'DD43F5575C7E743AED8ADCA436987FF0C53B7F5832BBF8328FFA7DAA2625B5C9', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p25-9', 'doc-04-nist-sp-800-86', '', 25, 'The final phase involves reporting the results of the analysis, which may include describing the actions performed, determining what other actions need to be performed, and recommending improvements to policies, guidelines, procedures, tools, and other aspects of the forensic process.', 'kb-doc-04-nist-sp-800-86-p25-9', 0, 40, '04-nist-sp-800-86', 'retrieved', 'B723C50E2C2FEA56DD4F39B4E6FB585035D83385BBC416ADD138514DE72C6EE5', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p25-11', 'doc-04-nist-sp-800-86', '', 25, 'Forensic Process As shown at the bottom of Figure 3-1, the forensic process transforms media into evidence, whether evidence is needed for law enforcement or for an organizations internal usage.9 Specifically, the first transformation occurs when collected data is examined, which extracts data from media and transforms it into a format that can be processed by forensic tools.10 Second, data is transformed into information', 'kb-doc-04-nist-sp-800-86-p25-11', 0, 64, '04-nist-sp-800-86', 'retrieved', '7107F3733123419DFEF16E1A35BD92F21BC38B9B08CD8090DE641D0013DF3971', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p25-12', 'doc-04-nist-sp-800-86', '', 25, '8 As explained in Section 2.1, the forensic process model presented in this document offers a simple way of looking at the phases of the forensic process.', 'kb-doc-04-nist-sp-800-86-p25-12', 0, 27, '04-nist-sp-800-86', 'retrieved', '1A008DE34ED50DC8836EA0A06139C57BF4E320E8AB9AA69FAEAFBEAB5A1E8D85', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p25-13', 'doc-04-nist-sp-800-86', '', 25, 'There are many other forensic process models that reflect the same basic principles and overall methodology.', 'kb-doc-04-nist-sp-800-86-p25-13', 0, 16, '04-nist-sp-800-86', 'retrieved', 'F009286376CA0C29B17AF7B74799E9ABF36FB9F0CC6FD04E54F31957DEA3BD19', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p25-14', 'doc-04-nist-sp-800-86', '', 25, 'Forensic models differ primarily in how granular each phase of the process is and in the terms used for specific phases.', 'kb-doc-04-nist-sp-800-86-p25-14', 0, 21, '04-nist-sp-800-86', 'retrieved', '2C20CF75BD2CB451F2C12B32CD3F5FDCC24861D9352236726F1D1AEAEBF68E42', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
