INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p25-16', 'doc-04-nist-sp-800-86', '', 25, '9 From a legal perspective, the term evidence technically refers only to those items that are admitted into a court case by a judge.', 'kb-doc-04-nist-sp-800-86-p25-16', 0, 24, '04-nist-sp-800-86', 'retrieved', '66C6B40A2727B6C3769F1A256A8F0EF1499E7734B5FE0EAB915012B9602A430A', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p25-17', 'doc-04-nist-sp-800-86', '', 25, 'However, the term evidence is widely used in a much broader sense, and this publication uses the less restrictive definition of evidence.', 'kb-doc-04-nist-sp-800-86-p25-17', 0, 22, '04-nist-sp-800-86', 'retrieved', '8504A9AD93A5470E7BF5C04A26691609F29CAA672C7DD73070B40D69F0695664', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
