VALUES ('doc-04-nist-sp-800-86-p26-1', 'doc-04-nist-sp-800-86', '', 26, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE through analysis.', 'kb-doc-04-nist-sp-800-86-p26-1', 0, 10, '04-nist-sp-800-86', 'retrieved', 'DA552E85EEE1359236238F1CE71F9BE06C10A85A941C0055726C5D1A2F8FF7BC', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
