INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p26-2', 'doc-04-nist-sp-800-86', '', 26, 'Finally, the information transformation into evidence is analogous to transferring knowledge into actionusing the information produced by the analysis in one or more ways during the reporting phase.', 'kb-doc-04-nist-sp-800-86-p26-2', 0, 28, '04-nist-sp-800-86', 'retrieved', '83F08AECC32291EDC16B594B67C8757DE34B6C905D2712A706797451D5E98C76', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p26-3', 'doc-04-nist-sp-800-86', '', 26, 'For example, it could be used as evidence to help prosecute a specific individual, actionable information to help stop or mitigate some activity, or knowledge in the generation of new leads for a case.', 'kb-doc-04-nist-sp-800-86-p26-3', 0, 34, '04-nist-sp-800-86', 'retrieved', 'DF8AE78B5D997933247FF7B2FFCD1DBAA6A1F44A6208132CBA215CF26733B36F', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
