INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p26-4', 'doc-04-nist-sp-800-86', '', 26, '3.1 D ata Collection The first step in the forensic process is to identify potential sources of data and acquire data from them.', 'kb-doc-04-nist-sp-800-86-p26-4', 0, 23, '04-nist-sp-800-86', 'retrieved', 'B2997752B27476892017983D336C521A01BEF1EC9B079F488620DD1D79B20E05', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
