INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p26-5', 'doc-04-nist-sp-800-86', '', 26, 'Section 3.1.1 describes the variety of data sources available and discusses actions that organizations can take to support the ongoing collection of data for forensic purposes.', 'kb-doc-04-nist-sp-800-86-p26-5', 0, 26, '04-nist-sp-800-86', 'retrieved', '79E01F7865BE93535CA315B75C043B3BE08A5FFEF5B75F6897C4B20CC22AFF55', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p26-6', 'doc-04-nist-sp-800-86', '', 26, 'Section 3.1.2 describes the recommended steps for collecting data, including additional actions necessary to support legal or internal disciplinary proceedings.', 'kb-doc-04-nist-sp-800-86-p26-6', 0, 20, '04-nist-sp-800-86', 'retrieved', '70E10610E31F09222C34DAB98E35FDEEC279F07E07373D727A246D7B8D79ACEB', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p26-7', 'doc-04-nist-sp-800-86', '', 26, 'Section 3.1.3 discusses incident response considerations, emphasizing the need to weigh the value of collected data against the costs and impact to the organization of the collection process.', 'kb-doc-04-nist-sp-800-86-p26-7', 0, 28, '04-nist-sp-800-86', 'retrieved', '3498978BF4B278352D9278427CACF5CD0611C465A996E9DE09C2CE681AA61BBB', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p26-9', 'doc-04-nist-sp-800-86', '', 26, 'Identifying Possible Sources of Data The increasingly widespread use of digital technology for both professional and personal purposes has led to an abundance of data sources.', 'kb-doc-04-nist-sp-800-86-p26-9', 0, 26, '04-nist-sp-800-86', 'retrieved', 'A78CC3D7ABD1DAA4410ECA0170C2A0432EED61120F7191EA351D0402AFE7826E', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p26-10', 'doc-04-nist-sp-800-86', '', 26, 'The most obvious and common sources of data are desktop computers, servers, network storage devices, and laptops.', 'kb-doc-04-nist-sp-800-86-p26-10', 0, 17, '04-nist-sp-800-86', 'retrieved', 'D8E67B2E2BB6F0A92ADF12E1582C8364CBD6AD59367C846CF332474433936BBC', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p26-11', 'doc-04-nist-sp-800-86', '', 26, 'These systems typically have internal drives that accept media, such as CDs and DVDs, and also have several types of ports (e.g., Universal Serial Bus [USB], Firewire, Personal Computer Memory Card International Association [PCMCIA]) to which external data storage media and devices can be attached.', 'kb-doc-04-nist-sp-800-86-p26-11', 0, 45, '04-nist-sp-800-86', 'retrieved', '7A670E7101180588D359047D418FD4C5245298DFD220EE2B540EC1257E0C856F', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p26-12', 'doc-04-nist-sp-800-86', '', 26, 'Examples of external storage forms that might be sources of data are thumb drives, memory and flash cards, optical discs, and magnetic disks.', 'kb-doc-04-nist-sp-800-86-p26-12', 0, 23, '04-nist-sp-800-86', 'retrieved', '1A8C2D654DFA554AA215A7E56DDACA6126CFE92C65A3621DD6E2695B1EC99624', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p26-13', 'doc-04-nist-sp-800-86', '', 26, 'Standard computer systems also contain volatile data that is available temporarily (i.e., until the system is shut down or rebooted).', 'kb-doc-04-nist-sp-800-86-p26-13', 0, 20, '04-nist-sp-800-86', 'retrieved', 'AF621EB9AB2B27C96D225B07A9B91FC4042FD9E1ED8EEBDCA12AD132B95C140D', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p26-14', 'doc-04-nist-sp-800-86', '', 26, 'In addition to computer-related devices, many types of portable digital devices (e.g., PDAs, cell phones, digital cameras, digital recorders, audio players) may also contain data.', 'kb-doc-04-nist-sp-800-86-p26-14', 0, 25, '04-nist-sp-800-86', 'retrieved', '251255364AEF59DFF0CF2385729D59DBF93592901BBD0E141C13B532607B5352', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p26-15', 'doc-04-nist-sp-800-86', '', 26, 'Analysts should be able to survey a physical area, such as an office, and recognize the possible sources of data.11 Analysts should also think of possible data sources located in other places.', 'kb-doc-04-nist-sp-800-86-p26-15', 0, 32, '04-nist-sp-800-86', 'retrieved', '042AD52CC0C7C5A2E831DB0BA1DDA6C172C6E21AC46BE6E1BABE3DAD82AED3C3', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p26-16', 'doc-04-nist-sp-800-86', '', 26, 'For example, as described in Sections 6 and 7, there are usually many sources of information within an organization regarding network activity and application usage.', 'kb-doc-04-nist-sp-800-86-p26-16', 0, 25, '04-nist-sp-800-86', 'retrieved', '0A563757EDF82B0063CC0A2D0AD5AD946802D3EA290450B4083AD067B45D8C2E', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p26-17', 'doc-04-nist-sp-800-86', '', 26, 'Information may also be recorded by other organizations, such as logs of network activity for an Internet service provider (ISP).', 'kb-doc-04-nist-sp-800-86-p26-17', 0, 20, '04-nist-sp-800-86', 'retrieved', '2406E5E3D6A700B105ACED70B77992D26768E67CEEE49D19F7C0E5222410DCA9', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p26-18', 'doc-04-nist-sp-800-86', '', 26, 'Analysts should be mindful of the owner of each data source and the effect that this might have on collecting data.', 'kb-doc-04-nist-sp-800-86-p26-18', 0, 21, '04-nist-sp-800-86', 'retrieved', '0CAD24FB0EDF4D5EBFCB9C10CBC5278734B2248FF29AE4BF8F9A6717D7D43492', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p26-20', 'doc-04-nist-sp-800-86', '', 26, 'Analysts should also be aware of the organizations policies, as well as legal considerations, regarding externally owned property at the organizations facilities (for example, an employees personal laptop or a contractors laptop).', 'kb-doc-04-nist-sp-800-86-p26-20', 0, 32, '04-nist-sp-800-86', 'retrieved', '98B69D35BEF0D5F9849D84DDC131BF02B13608757276E8E373154836B862179C', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p26-21', 'doc-04-nist-sp-800-86', '', 26, 'The situation can become even more complicated if locations outside the organizations control are involved, such as an incident involving a computer at a telecommuters home office.', 'kb-doc-04-nist-sp-800-86-p26-21', 0, 27, '04-nist-sp-800-86', 'retrieved', '1B032B1709AECC6FF98826C22005A645D4532C807FB35417E3FC658254C825FA', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p26-22', 'doc-04-nist-sp-800-86', '', 26, 'Sometimes it is simply not feasible to collect data from a primary data source; therefore, analysts should be aware of alternate data sources that might contain some or all of the same data, and should use those sources instead of the unattainable source.', 'kb-doc-04-nist-sp-800-86-p26-22', 0, 43, '04-nist-sp-800-86', 'retrieved', '133DD786EB9CFE2FC53F98B9AE63305B55645415F7F5182BD0E5009FE5394868', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p26-23', 'doc-04-nist-sp-800-86', '', 26, 'Organizations can take ongoing proactive measures to collect data that may be useful for forensic purposes.', 'kb-doc-04-nist-sp-800-86-p26-23', 0, 16, '04-nist-sp-800-86', 'retrieved', '64C405355A1F374A124ED81E6BBB6AC8F61405037CD171ECCB7F1EAEC4102757', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p26-24', 'doc-04-nist-sp-800-86', '', 26, 'For example, as described in Section 5.1.1, most OSs can be configured to audit and record certain types of events, such as authentication attempts and security policy changes, as part of normal operations.', 'kb-doc-04-nist-sp-800-86-p26-24', 0, 33, '04-nist-sp-800-86', 'retrieved', '61A6057D7AF1DDD1079D05346B9FAFADED9FE84E3EFD085ACFA697CF083D099F', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p26-25', 'doc-04-nist-sp-800-86', '', 26, 'Audit records can provide valuable information, including the time that an event occurred and', 'kb-doc-04-nist-sp-800-86-p26-25', 0, 14, '04-nist-sp-800-86', 'retrieved', '39BF04D9B33DDD86790D7456B7B3D328BC8387DBFF37BD273B07653A45E4AD8F', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
