INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p28-1', 'doc-04-nist-sp-800-86', '', 28, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE By considering these three factors for each potential data source, analysts can make informed decisions regarding the prioritization of data source acquisition, as well as determining which data sources to acquire.', 'kb-doc-04-nist-sp-800-86-p28-1', 0, 39, '04-nist-sp-800-86', 'retrieved', '81101DCE5991CFE736E008D1ADC6208E1EC7BEDD4ED9A1404F1F8A5F8856DDDE', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p28-2', 'doc-04-nist-sp-800-86', '', 28, 'In some cases, there are so many possible data sources that it is not practical to acquire them all.', 'kb-doc-04-nist-sp-800-86-p28-2', 0, 19, '04-nist-sp-800-86', 'retrieved', '8C51D8291EF18787C85D6B6EC50C9B071E1A0B51A146D4FC8AAF6D336118D5E0', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p28-3', 'doc-04-nist-sp-800-86', '', 28, 'Organizations should carefully consider the complexities of prioritizing data source acquisition and develop written plans, guidelines, and procedures that can help analysts perform prioritization effectively.', 'kb-doc-04-nist-sp-800-86-p28-3', 0, 25, '04-nist-sp-800-86', 'retrieved', '298CF7D7A4F66477EFFD98D6B8ADE6679F309196B66EDF7064293CDE2B2DED7F', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p28-5', 'doc-04-nist-sp-800-86', '', 28, 'If the data has not already been acquired by security tools, analysis tools, or other means, the general process for acquiring data involves using forensic tools to collect volatile data, duplicating non-volatile data sources to collect their data, and securing the original non-volatile data sources.', 'kb-doc-04-nist-sp-800-86-p28-5', 0, 45, '04-nist-sp-800-86', 'retrieved', '5179783A4C171EAA4FEA15D0C91A42315250F26DFB7752070D72E89934AC8362', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p28-7', 'doc-04-nist-sp-800-86', '', 28, 'Although it is generally preferable to acquire data locally because there is greater control over the system and data, local data collection is not always feasible (e.g., system in locked room, system in another location).', 'kb-doc-04-nist-sp-800-86-p28-7', 0, 35, '04-nist-sp-800-86', 'retrieved', '1945DAE0F743A7E07F1CF6B70792F6971B1B2DAFB48E25C44B54BC23FF465D6C', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p28-8', 'doc-04-nist-sp-800-86', '', 28, 'When acquiring data over a network, decisions should be made regarding the type of data to be collected and the amount of effort to use.', 'kb-doc-04-nist-sp-800-86-p28-8', 0, 25, '04-nist-sp-800-86', 'retrieved', '7C20F6666D8A7D1B23856480EB4D072B06218F1FFD883EFFF570D4A90AE06E99', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p28-9', 'doc-04-nist-sp-800-86', '', 28, 'For instance, it might be necessary to acquire data from several systems through different network connections, or it might be sufficient to copy a logical volume from just one system.', 'kb-doc-04-nist-sp-800-86-p28-9', 0, 30, '04-nist-sp-800-86', 'retrieved', '41BD6F6AE2A6711DD405E9D3782E908EEB7676983B7108E781EBED7CC5F505C3', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p28-12', 'doc-04-nist-sp-800-86', '', 28, 'It is particularly important for an analyst to prove that the data has not been tampered with if it might be needed for legal reasons.', 'kb-doc-04-nist-sp-800-86-p28-12', 0, 25, '04-nist-sp-800-86', 'retrieved', '7B4D6D4001ACBBF627C74C6034C56C56FC81CD75F81C8F330AE0B6626F2AB5D6', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p28-13', 'doc-04-nist-sp-800-86', '', 28, 'Data integrity verification typically consists of using tools to compute the message digest of the original and copied data, then comparing the digests to make sure that they are the same.', 'kb-doc-04-nist-sp-800-86-p28-13', 0, 31, '04-nist-sp-800-86', 'retrieved', '7E5C295EB2BA9629D885F2D2B29959006CF9F15ADC3441AEC89E10B9B7A6C239', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p28-14', 'doc-04-nist-sp-800-86', '', 28, 'Before the analyst begins to collect any data, a decision should be made by the analyst or management (in accordance with the organizations policies and legal advisors) on the need to collect and preserve evidence in a way that supports its use in future legal or internal disciplinary proceedings.', 'kb-doc-04-nist-sp-800-86-p28-14', 0, 49, '04-nist-sp-800-86', 'retrieved', '0B8B85ABB7CD5043EB38AA49B7322614F09525DF101C5467E3C3F786AFB4AA86', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p28-15', 'doc-04-nist-sp-800-86', '', 28, 'In such situations, a clearly defined chain of custody should be followed to avoid allegations of mishandling or tampering of evidence.', 'kb-doc-04-nist-sp-800-86-p28-15', 0, 21, '04-nist-sp-800-86', 'retrieved', '1820F6351059B97135A64683FC9374D01CB27D54BA99E71B906772EE4C125BF5', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p28-16', 'doc-04-nist-sp-800-86', '', 28, 'This involves keeping a log of every person who had physical custody of the evidence, documenting the actions that they performed on the evidence and at what time, storing the evidence in a secure location when it is not being used, making a copy of the evidence and performing examination and analysis using only the copied evidence, and verifying the integrity of the original and copied evidence.', 'kb-doc-04-nist-sp-800-86-p28-16', 0, 67, '04-nist-sp-800-86', 'retrieved', '47A8AB2211BA16B2638841D0330F40B88895BFA3939F202CC3FDE9FD0E2AF3EB', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p28-17', 'doc-04-nist-sp-800-86', '', 28, 'If it is unclear whether or not evidence needs to be preserved, by default it generally should be preserved.', 'kb-doc-04-nist-sp-800-86-p28-17', 0, 19, '04-nist-sp-800-86', 'retrieved', 'EEEB56829E23ADAF9C96AE5FC75FD5C51DBE5DDA7D608D163FA3895D4C1A87D7', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p28-19', 'doc-04-nist-sp-800-86', '', 28, 'Throughout the process, a detailed log should be kept of every step that was taken to collect the data, including information about each tool used in the process.', 'kb-doc-04-nist-sp-800-86-p28-19', 0, 28, '04-nist-sp-800-86', 'retrieved', '4C8F9720AD366CA4101CFA02D18D3CCD26199AB4F74046AE9883D21E660C90D7', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p28-21', 'doc-04-nist-sp-800-86', '', 28, 'Additionally, evidence should be photographed to provide visual reminders of the computer setup and peripheral devices.', 'kb-doc-04-nist-sp-800-86-p28-21', 0, 16, '04-nist-sp-800-86', 'retrieved', 'C4B516EBF77E22819389D26D67C30C53E58D69331CA187BF8ADC72C6E94A2384', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p28-22', 'doc-04-nist-sp-800-86', '', 28, 'In addition, before actually touching a system, the analyst should make a note or photograph of any pictures, documents, running programs, and other relevant information displayed on the monitor.', 'kb-doc-04-nist-sp-800-86-p28-22', 0, 29, '04-nist-sp-800-86', 'retrieved', '5B21C9BC4AAECF14DDFB59B278E37FEA6879075391A0622893126FE83521C2E9', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p28-23', 'doc-04-nist-sp-800-86', '', 28, 'If a screen saver is active, that should be documented as well since it may be password-protected.', 'kb-doc-04-nist-sp-800-86-p28-23', 0, 17, '04-nist-sp-800-86', 'retrieved', '8FADEC5237F962F62B69F95507A4865D06F007BA5D4CFC3A579BF83877689CF6', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p28-24', 'doc-04-nist-sp-800-86', '', 28, 'If possible, one person on the scene should be designated the evidence custodian, and given the sole responsibility to photograph, document, and label every item that is collected, and record every action that was taken along with who performed the action, where it was performed, and at what time.', 'kb-doc-04-nist-sp-800-86-p28-24', 0, 49, '04-nist-sp-800-86', 'retrieved', 'A5F28A4BC5EA25F0CF90090F277CD7D72E7BC11099C363FE3C394CC71FB4C493', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p28-25', 'doc-04-nist-sp-800-86', '', 28, 'Since the evidence may not be needed for legal proceedings for an extended time, proper documentation enables an analyst to remember exactly what was done to collect data and can be used to refute claims of mishandling.', 'kb-doc-04-nist-sp-800-86-p28-25', 0, 37, '04-nist-sp-800-86', 'retrieved', '64FED450858D7269DA74CC694FB9C8C84DEA15015B047A08AC6AE8176FF2AA87', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p28-26', 'doc-04-nist-sp-800-86', '', 28, 'To assist the analyst with evidence collection, the necessary resources, such as forensic workstations, backup devices, blank media, and evidence handling supplies (e.g., hard-bound notebooks, chain of custody forms, evidence storage bags and tags, evidence tape, digital cameras) should be prepared 3-4', 'kb-doc-04-nist-sp-800-86-p28-26', 0, 42, '04-nist-sp-800-86', 'retrieved', '21BE1D0FABB779B37A1C5CB4F38C67C4D654BFBF1235BC2ACE95BE9958D48C96', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p29-2', 'doc-04-nist-sp-800-86', '', 29, 'In some cases, it may be necessary to ensure that the scene is physically secured to prevent unauthorized access and alteration of the evidence.', 'kb-doc-04-nist-sp-800-86-p29-2', 0, 24, '04-nist-sp-800-86', 'retrieved', 'D744F23B6FC9352F778898F62803F262CFCEF2E87146202D2776F23141B4D443', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p29-4', 'doc-04-nist-sp-800-86', '', 29, 'There also may be situations where a law enforcement representative should handle the data collection for legal reasons.', 'kb-doc-04-nist-sp-800-86-p29-4', 0, 18, '04-nist-sp-800-86', 'retrieved', '8F9F1BD250C7E547C57BF96762B89A992A2ABB62ED01098CEB3F105C2E918F55', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p29-5', 'doc-04-nist-sp-800-86', '', 29, 'This includes, but is not limited to, obtaining ISP records and collecting data from external computer systems and unusual devices and media.', 'kb-doc-04-nist-sp-800-86-p29-5', 0, 22, '04-nist-sp-800-86', 'retrieved', '3F851A8B2394A879BB90DEB12760382094CBB0BA7814E4444DC28C5FFFA0ADE5', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p29-6', 'doc-04-nist-sp-800-86', '', 29, 'Based on guidance from legal advisors, organizations should determine in advance what types of data are best collected by law enforcement officials.', 'kb-doc-04-nist-sp-800-86-p29-6', 0, 22, '04-nist-sp-800-86', 'retrieved', '324CC1C183982696080E8C8810157F8D7A98B414DD039BD4BF95383881DBDE7F', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p29-7', 'doc-04-nist-sp-800-86', '', 29, 'Analysts should take into account what will be done with the collected data and plan for the potential ramifications.', 'kb-doc-04-nist-sp-800-86-p29-7', 0, 19, '04-nist-sp-800-86', 'retrieved', '0FE0A7E5CCABE5CA9617C59B22CD9C7C602B6BDEB0A49E2277E89BD49EE9EDFB', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
