INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p29-8', 'doc-04-nist-sp-800-86', '', 29, 'In some cases, the data may be turned over to a law enforcement agency or another external party for examination and analysis.', 'kb-doc-04-nist-sp-800-86-p29-8', 0, 22, '04-nist-sp-800-86', 'retrieved', 'B623ABB94B03C35AE7ABC802F31E2D5DF672259967BBF6CCC29EEB9202739221', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p29-9', 'doc-04-nist-sp-800-86', '', 29, 'This could result in the collected hardware being unavailable for an extended period of time.', 'kb-doc-04-nist-sp-800-86-p29-9', 0, 15, '04-nist-sp-800-86', 'retrieved', 'E696D4B36A5758AF2F6803FBC8CF43A31C90DDF1F98C79779FC1F0624678D01E', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p29-10', 'doc-04-nist-sp-800-86', '', 29, 'If the original media needs to be kept secured for legal proceedings, it could be unavailable for years.', 'kb-doc-04-nist-sp-800-86-p29-10', 0, 18, '04-nist-sp-800-86', 'retrieved', '15C5D406BB0E7E49636CBA2661CB59F3D16901617122285EFF76E06BE22956DE', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p29-11', 'doc-04-nist-sp-800-86', '', 29, 'Another concern is that sensitive information unrelated to the investigation (e.g., medical records, financial information) might be inadvertently captured along with the desired data.', 'kb-doc-04-nist-sp-800-86-p29-11', 0, 24, '04-nist-sp-800-86', 'retrieved', 'C14265770A276DFE1F26E9F987F06B07909177465D1827239815AF8B56A146CE', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p29-12', 'doc-04-nist-sp-800-86', '', 29, '3.1.3 Incident Response Considerations When performing forensics during incident response, an important consideration is how and when the incident should be contained.', 'kb-doc-04-nist-sp-800-86-p29-12', 0, 22, '04-nist-sp-800-86', 'retrieved', 'FCCA42F983BDD39BCA9C56E4ECF2DB2E44608A8B5AF85D65950A2E43350F93EF', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p29-13', 'doc-04-nist-sp-800-86', '', 29, 'Isolating the pertinent systems from external influences may be necessary to prevent further damage to the system and its data or to preserve evidence.', 'kb-doc-04-nist-sp-800-86-p29-13', 0, 24, '04-nist-sp-800-86', 'retrieved', '7B4558063C786661DB2B52A78E02F42B9B3A8EECFAEB9573B9DB4E65740C4F45', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p29-14', 'doc-04-nist-sp-800-86', '', 29, 'In many cases, the analyst should work with the incident response team to make a containment decision (e.g., disconnecting network cables, unplugging power, increasing physical security measures, gracefully shutting down a host).', 'kb-doc-04-nist-sp-800-86-p29-14', 0, 32, '04-nist-sp-800-86', 'retrieved', 'B2E79E8BAB20FB61950D23966422ED9FF08F25B68864928A2CA725AE17A2113A', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p29-15', 'doc-04-nist-sp-800-86', '', 29, 'This decision should be based on existing policies and procedures regarding incident containment, as well as the teams assessment of the risk posed by the incident, so that the chosen containment strategy or combination of strategies sufficiently mitigates risk while maintaining the integrity of potential evidence whenever possible.', 'kb-doc-04-nist-sp-800-86-p29-15', 0, 48, '04-nist-sp-800-86', 'retrieved', '6F4E6F4BF6D85FED6DA489A25D9767AB57541BF2934D3936046DAE01688840FF', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p29-16', 'doc-04-nist-sp-800-86', '', 29, 'The organization should also consider in advance the impact that various containment strategies may have on the ability of the organization to operate effectively.', 'kb-doc-04-nist-sp-800-86-p29-16', 0, 24, '04-nist-sp-800-86', 'retrieved', 'E27A478BD7BB8EEEB299A6FB1A707AC22A7D6301B695A70823DF2C6EE0999B39', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p29-17', 'doc-04-nist-sp-800-86', '', 29, 'For example, taking a critical system offline for several hours to acquire disk images and other data might adversely affect the ability of the organization to perform its necessary operations.', 'kb-doc-04-nist-sp-800-86-p29-17', 0, 30, '04-nist-sp-800-86', 'retrieved', '113982F9B884BAF490CD222049D487CDB03F19C0322FB01EF985CEA7F9114E2E', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p29-18', 'doc-04-nist-sp-800-86', '', 29, 'Significant downtime could result in substantial monetary losses to the organization.', 'kb-doc-04-nist-sp-800-86-p29-18', 0, 11, '04-nist-sp-800-86', 'retrieved', '2015464A8B1D9585CF9299C806E0513AA29841E92964C2911DBB6FDF54270649', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p29-19', 'doc-04-nist-sp-800-86', '', 29, 'Therefore, care should be taken to minimize disruptions to an organizations operations.', 'kb-doc-04-nist-sp-800-86-p29-19', 0, 12, '04-nist-sp-800-86', 'retrieved', 'B6F8BA4F149498C542F689F72914F06C85EAC1BAAFBA9E67B6F9C6A6882C7CEC', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p29-20', 'doc-04-nist-sp-800-86', '', 29, 'One step often taken to contain an incident is to secure the perimeter around a computer and limit access to authorized personnel during the collection process to ensure that the evidence is not altered.', 'kb-doc-04-nist-sp-800-86-p29-20', 0, 34, '04-nist-sp-800-86', 'retrieved', 'D36B81CE56E55372F890B4B288B9B30FD1B6BBB7386014877EA66FF54CAC8555', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p29-21', 'doc-04-nist-sp-800-86', '', 29, 'Also, a list of all users who have access to the computer should be documented, because these persons may be able to provide passwords or information on where specific data is located.', 'kb-doc-04-nist-sp-800-86-p29-21', 0, 32, '04-nist-sp-800-86', 'retrieved', '19CFADEA411A2EF222FEB24C5225EA6A6511A30CAA59ECBE5E11CA6BF86FA659', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p29-22', 'doc-04-nist-sp-800-86', '', 29, 'If the computer is connected to a network, disconnecting network cables attached to the computer can prevent remote users from modifying the computers data.', 'kb-doc-04-nist-sp-800-86-p29-22', 0, 24, '04-nist-sp-800-86', 'retrieved', 'C3CE53905B13AD903DB5AB86756E96341A87DD270758C252707A13AE0FCDA794', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p29-23', 'doc-04-nist-sp-800-86', '', 29, 'If the computer uses a wireless network connection, the external network adapter may be unplugged from the computer or the internal network adapter may be disabled to sever the network connection.', 'kb-doc-04-nist-sp-800-86-p29-23', 0, 31, '04-nist-sp-800-86', 'retrieved', 'E6491DD842EE4D84FDC846E0B293FDD0C0995F9CC1932B95B4A54117B69A84F4', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p29-24', 'doc-04-nist-sp-800-86', '', 29, 'If neither option is possible, then powering off the wireless network access point that the computer is using should achieve the same result; however, doing so may prevent users outside the scope of the investigation from performing their daily routines.', 'kb-doc-04-nist-sp-800-86-p29-24', 0, 40, '04-nist-sp-800-86', 'retrieved', 'C9E70081D8CA623389519D9D12926704F1ACE129C3513BDE4A251255C311E6AC', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p29-25', 'doc-04-nist-sp-800-86', '', 29, 'In addition, there could be more than one access point within range of the computer.', 'kb-doc-04-nist-sp-800-86-p29-25', 0, 15, '04-nist-sp-800-86', 'retrieved', 'EA8AFDEAC4810CBE6E95EAA066707F9994956ED71380CABAD790CDE8569E61E0', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p29-26', 'doc-04-nist-sp-800-86', '', 29, 'Some wireless network adapters automatically attempt to connect to other access points when the primary access point is unavailable, so that containing the incident in this way could involve disconnecting several access points.', 'kb-doc-04-nist-sp-800-86-p29-26', 0, 33, '04-nist-sp-800-86', 'retrieved', '02847DC6DE015985CFF0BEF5997B0F4AAA2717559FE368C8316B2DF1FA06D9C6', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p30-1', 'doc-04-nist-sp-800-86', '', 30, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE 3.2 Exam ination After data has been collected, the next phase is to examine the data, which involves assessing and extracting the relevant pieces of information from the collected data.', 'kb-doc-04-nist-sp-800-86-p30-1', 0, 38, '04-nist-sp-800-86', 'retrieved', '8757D13BD8FA98AA17C2AF6E58D9184787A49863BEB5D1A01787735761B99AEC', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p30-2', 'doc-04-nist-sp-800-86', '', 30, 'This phase may also involve bypassing or mitigating OS or application features that obscure data and code, such as data compression, encryption, and access control mechanisms.', 'kb-doc-04-nist-sp-800-86-p30-2', 0, 26, '04-nist-sp-800-86', 'retrieved', 'FAFB0CA00BF1F5666D1715D3FED92BCEEBD0A3B0383C25BB89B6622E3723B7A1', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p30-3', 'doc-04-nist-sp-800-86', '', 30, 'An acquired hard drive may contain hundreds of thousands of data files; identifying the data files that contain information of interest, including information concealed through file compression and access control, can be a daunting task.', 'kb-doc-04-nist-sp-800-86-p30-3', 0, 35, '04-nist-sp-800-86', 'retrieved', '8A79CBF7375D95F6CD672D02758523AFA2B59692A748FB9EB929BDFA06FB3CA0', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p30-4', 'doc-04-nist-sp-800-86', '', 30, 'In addition, data files of interest may contain extraneous information that should be filtered.', 'kb-doc-04-nist-sp-800-86-p30-4', 0, 14, '04-nist-sp-800-86', 'retrieved', 'F9AE50AC0BDF29938B56EF46B73BFC06F57010CBD6E7987ECC030CD13F5996AE', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p30-5', 'doc-04-nist-sp-800-86', '', 30, 'For example, yesterdays firewall log might hold millions of records, but only five of the records might be related to the event of interest.', 'kb-doc-04-nist-sp-800-86-p30-5', 0, 24, '04-nist-sp-800-86', 'retrieved', '69FA1965CE9DBB74FDFFDFC48BA3314BAFDB589DC52307FA8222468FC25A56BD', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p30-6', 'doc-04-nist-sp-800-86', '', 30, 'Fortunately, various tools and techniques can be used to reduce the amount of data that has to be sifted through.', 'kb-doc-04-nist-sp-800-86-p30-6', 0, 20, '04-nist-sp-800-86', 'retrieved', 'D79EED3D0CC2C9551CF66EA76CA014CAE3C0E565BBBFC2FA1C3E78DD617BB0DE', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
