INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p30-7', 'doc-04-nist-sp-800-86', '', 30, 'Text and pattern searches can be used to identify pertinent data, such as finding documents that mention a particular subject or person, or identifying e-mail log entries for a particular e-mail address.', 'kb-doc-04-nist-sp-800-86-p30-7', 0, 32, '04-nist-sp-800-86', 'retrieved', '224E522F73F2C5F35613C7DB03FA03015062E8A3B0CAD1E787317C5BC8D7C03C', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
