INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p30-8', 'doc-04-nist-sp-800-86', '', 30, 'Another helpful technique is to use a tool that can determine the type of contents of each data file, such as text, graphics, music, or a compressed file archive.', 'kb-doc-04-nist-sp-800-86-p30-8', 0, 29, '04-nist-sp-800-86', 'retrieved', '50207963DDDA01E7ABF7B3BA8D1D196E3C161B1D77442ACB2830428847021BB7', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
