INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p30-9', 'doc-04-nist-sp-800-86', '', 30, 'Knowledge of data file types can be used to identify files that merit further study, as well as to exclude files that are of no interest to the examination.', 'kb-doc-04-nist-sp-800-86-p30-9', 0, 29, '04-nist-sp-800-86', 'retrieved', 'BD0CA78EDF8182BE6B7B76551D6A30BFADA5319F64FE695D3D4A8B242D5B9494', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
