VALUES ('doc-04-nist-sp-800-86-p30-10', 'doc-04-nist-sp-800-86', '', 30, 'There are also databases containing information about known files, which can also be used to include or exclude files from further consideration.', 'kb-doc-04-nist-sp-800-86-p30-10', 0, 22, '04-nist-sp-800-86', 'retrieved', '56DAFE95208F09524ACE5B200A41979CC8F11F3133F4DC0473ABBCDF3B51C5D9', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
