VALUES ('doc-04-nist-sp-800-86-p30-11', 'doc-04-nist-sp-800-86', '', 30, 'Specific information about examination tools and techniques is presented in Sections 4.3, 5.3, 6.4, and 7.4.', 'kb-doc-04-nist-sp-800-86-p30-11', 0, 16, '04-nist-sp-800-86', 'retrieved', '62C6D409AA9476FBF23E7B6D1A8D978D6A8EEFA9E671F6308AA280D522D87C68', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
