INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p30-12', 'doc-04-nist-sp-800-86', '', 30, '3.3 A nalysis Once the relevant information has been extracted, the analyst should study and analyze the data to draw conclusions from it.14 The foundation of forensics is using a methodical approach to reach appropriate conclusions based on the available data or determine that no conclusion can yet be drawn.', 'kb-doc-04-nist-sp-800-86-p30-12', 0, 50, '04-nist-sp-800-86', 'retrieved', '962CC581B8AF7C13D56655ABF112A893F74957BF63244E777F538613C64239A4', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
