INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p30-13', 'doc-04-nist-sp-800-86', '', 30, 'The analysis should include identifying people, places, items, and events, and determining how these elements are related so that a conclusion can be reached.', 'kb-doc-04-nist-sp-800-86-p30-13', 0, 24, '04-nist-sp-800-86', 'retrieved', 'C563C1DE54A7C521A568DF7526D3F0C02A4421041FC6CF2916D91A836ECB382C', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
