INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p30-15', 'doc-04-nist-sp-800-86', '', 30, 'For instance, a network intrusion detection system (IDS) log may link an event to a host, the host audit logs may link the event to a specific user account, and the host IDS log may indicate what actions that user performed.', 'kb-doc-04-nist-sp-800-86-p30-15', 0, 41, '04-nist-sp-800-86', 'retrieved', '9968F35221FEFB9A443B8497EFE29B1BA95F0610C53D83CB71D72D490CBAB77F', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
