INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p30-16', 'doc-04-nist-sp-800-86', '', 30, 'Tools such as centralized logging and security event management software can facilitate this process by automatically gathering and correlating the data.', 'kb-doc-04-nist-sp-800-86-p30-16', 0, 21, '04-nist-sp-800-86', 'retrieved', '1C6A4EE7CFDF5009EC4BA7EF81562C5B5458078527B89BD71B596CD786666589', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
