VALUES ('doc-04-nist-sp-800-86-p30-17', 'doc-04-nist-sp-800-86', '', 30, 'Comparing system characteristics to known baselines can identify various types of changes made to the system.', 'kb-doc-04-nist-sp-800-86-p30-17', 0, 16, '04-nist-sp-800-86', 'retrieved', '3C4F1BC7C2AC21A6BB3B0C29788619D429A10A6DDFFFB3AB7053563E54AA034A', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
