VALUES ('doc-04-nist-sp-800-86-p30-19', 'doc-04-nist-sp-800-86', '', 30, 'As described in Section 3.1.2, if evidence may be needed for legal or internal disciplinary actions, analysts should carefully document the findings and all steps taken.', 'kb-doc-04-nist-sp-800-86-p30-19', 0, 26, '04-nist-sp-800-86', 'retrieved', 'D3ADAC55415582C9CA9AADE14478651DBEF2BB39056C6B1F34953FB0A37E06F1', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
