INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p30-20', 'doc-04-nist-sp-800-86', '', 30, '3.4 Re porting The final phase is reporting, which is the process of preparing and presenting the information resulting from the analysis phase.', 'kb-doc-04-nist-sp-800-86-p30-20', 0, 23, '04-nist-sp-800-86', 'retrieved', '3A2A87F15CDBFD5C567A4AA09F5199E0F4BD5A48D43FBDA806056A431361E864', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
