VALUES ('doc-04-nist-sp-800-86-p30-21', 'doc-04-nist-sp-800-86', '', 30, 'Many factors affect reporting, including the following: ! Alternative Explanations.', 'kb-doc-04-nist-sp-800-86-p30-21', 0, 10, '04-nist-sp-800-86', 'retrieved', 'EDCADE684DFA68228298773FE7B81CAF60A42B7AA29C3AB2948239CD3F979A46', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
