INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p30-22', 'doc-04-nist-sp-800-86', '', 30, 'When the information regarding an event is incomplete, it may not be possible to arrive at a definitive explanation of what happened.', 'kb-doc-04-nist-sp-800-86-p30-22', 0, 22, '04-nist-sp-800-86', 'retrieved', '4048E7E5BA29722CDFEC68083E7C3C6A221E34B747E2F92342CDEBD327424824', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
