INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p30-23', 'doc-04-nist-sp-800-86', '', 30, 'When an event has two or more plausible explanations, each should be given due consideration in the reporting process.', 'kb-doc-04-nist-sp-800-86-p30-23', 0, 19, '04-nist-sp-800-86', 'retrieved', '262D7B8618F03B5A4073EBF9EDC9E8F6EBB3A4B64C39837456EA7671866A085A', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
