VALUES ('doc-04-nist-sp-800-86-p30-24', 'doc-04-nist-sp-800-86', '', 30, 'Analysts should use a methodical approach to attempt to prove or disprove each possible explanation that is proposed.', 'kb-doc-04-nist-sp-800-86-p30-24', 0, 18, '04-nist-sp-800-86', 'retrieved', 'DD672E1916E35DECFB8EE9D2F859CB7E7A24113084D50E5C1A04EB0CA44D31E4', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
