VALUES ('doc-04-nist-sp-800-86-p30-25', 'doc-04-nist-sp-800-86', '', 30, '14 Some forensic process methodologies have a separate analysis phase after the examination phase.', 'kb-doc-04-nist-sp-800-86-p30-25', 0, 14, '04-nist-sp-800-86', 'retrieved', '05BBF470F5F11DC8414C8D7E55E8C256969F2E034A838C135B916CEC0FD1DBEC', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
