VALUES ('doc-04-nist-sp-800-86-p30-26', 'doc-04-nist-sp-800-86', '', 30, 'For the sake of simplicity, this publication presents analysis as part of the examination phase.', 'kb-doc-04-nist-sp-800-86-p30-26', 0, 15, '04-nist-sp-800-86', 'retrieved', 'CBDF1442E4584EEF236EFE31A024AE11DC78C620196151E48A116E77E574DB90', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
