INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p30-27', 'doc-04-nist-sp-800-86', '', 30, 'Typically, an analyst examines data and performs analysis of that data, then conducts additional examination and analysis based on the results of the initial analysis.', 'kb-doc-04-nist-sp-800-86-p30-27', 0, 25, '04-nist-sp-800-86', 'retrieved', 'B75CAB48E0F32A661291AD2AD76035686581C183F2B6E8FECADC04630A75B85C', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
