INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p31-2', 'doc-04-nist-sp-800-86', '', 31, 'Knowing the audience to which the data or information will be shown is important.', 'kb-doc-04-nist-sp-800-86-p31-2', 0, 14, '04-nist-sp-800-86', 'retrieved', 'A3F6380F2B46EA4ACE2A0FDEA907FA2FB5A9EF2084EBF35D7B31C0EB9927E514', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
