INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p31-3', 'doc-04-nist-sp-800-86', '', 31, 'An incident requiring law enforcement involvement requires highly detailed reports of all information gathered, and may also require copies of all evidentiary data obtained.', 'kb-doc-04-nist-sp-800-86-p31-3', 0, 24, '04-nist-sp-800-86', 'retrieved', '46B535EFE82A71D1A8BEDD1CB743322DC8EFF8B73951A972D1CD760CAC0867D0', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p31-4', 'doc-04-nist-sp-800-86', '', 31, 'A system administrator might want to see network traffic and related statistics in great detail.', 'kb-doc-04-nist-sp-800-86-p31-4', 0, 15, '04-nist-sp-800-86', 'retrieved', '0F0BC16B9770F3BADDCCE96918A6075396138FCECC782878CDF8A02980EA53D8', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p31-5', 'doc-04-nist-sp-800-86', '', 31, 'Senior management might simply want a high-level overview of what happened, such as a simplified visual representation of how the attack occurred, and what should be done to prevent similar incidents.', 'kb-doc-04-nist-sp-800-86-p31-5', 0, 31, '04-nist-sp-800-86', 'retrieved', 'FC23278DA64D478C4F165850939EA10A436842624C157838E9E9F35C4763705F', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p31-7', 'doc-04-nist-sp-800-86', '', 31, 'Reporting also includes identifying actionable information gained from data that may allow an analyst to collect new sources of information.', 'kb-doc-04-nist-sp-800-86-p31-7', 0, 20, '04-nist-sp-800-86', 'retrieved', 'EFC211C1D4C89051FB02B63A69F799F2AD5936FC1C13322C509312749267AA67', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p31-8', 'doc-04-nist-sp-800-86', '', 31, 'For example, a list of contacts may be developed from the data that might lead to additional information about an incident or crime.', 'kb-doc-04-nist-sp-800-86-p31-8', 0, 23, '04-nist-sp-800-86', 'retrieved', 'B341A57BC39380B57A7F1C5F4B1ED0D4DD68BAAB5F40F6CCE8C969814E751DBE', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p31-9', 'doc-04-nist-sp-800-86', '', 31, 'Also, information might be obtained that could prevent future events, such as a backdoor on a system that could be used for future attacks, a crime that is being planned, a worm scheduled to start spreading at a certain time, or a vulnerability that could be exploited.', 'kb-doc-04-nist-sp-800-86-p31-9', 0, 47, '04-nist-sp-800-86', 'retrieved', '841782021CC62516D5F0FDCFD433909331B488E6BFC3FBE8B711DC3ECB8E5C51', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p31-10', 'doc-04-nist-sp-800-86', '', 31, 'As part of the reporting process, analysts should identify any problems that may need to be remedied, such as policy shortcomings or procedural errors.', 'kb-doc-04-nist-sp-800-86-p31-10', 0, 24, '04-nist-sp-800-86', 'retrieved', 'BD52206637BC18170C5036DF8187919579678384ACE1A561AEDF35948BA614DA', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p31-11', 'doc-04-nist-sp-800-86', '', 31, 'Many forensic and incident response teams hold formal reviews after each major event.', 'kb-doc-04-nist-sp-800-86-p31-11', 0, 13, '04-nist-sp-800-86', 'retrieved', '4A5B11AEABDE3C723D62B9E7B432371E31F363B05E5D03FBFBD08DD2FF4FA6B2', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p31-12', 'doc-04-nist-sp-800-86', '', 31, 'Such reviews tend to include serious consideration of possible improvements to guidelines and procedures, and typically at least some minor changes are approved and implemented after each review.', 'kb-doc-04-nist-sp-800-86-p31-12', 0, 28, '04-nist-sp-800-86', 'retrieved', 'CADD4F319189A411F649412D34A702D63D2CB3F9E131B38FDB273E8D5E6EE75F', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p31-13', 'doc-04-nist-sp-800-86', '', 31, 'For example, one common problem is that many organizations find it resource-intensive to maintain current lists of personnel to contact regarding each different type of incident that may occur.', 'kb-doc-04-nist-sp-800-86-p31-13', 0, 29, '04-nist-sp-800-86', 'retrieved', 'EE68A8C9D8B66840082CC36C2D383EC2DB1DA669C8C6D846D89BBE5D33D279EB', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p31-14', 'doc-04-nist-sp-800-86', '', 31, 'Other common issues are what to do with the gigabytes or terabytes of data collected during an investigation, and how security controls (e.g., auditing, logging, intrusion detection) can be altered to record additional data that would be helpful for future investigations.', 'kb-doc-04-nist-sp-800-86-p31-14', 0, 41, '04-nist-sp-800-86', 'retrieved', 'C61E8DF2EA2E59B1D09273EE45B7599F8749F95B16AB26671D501CC41ADD4342', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p31-16', 'doc-04-nist-sp-800-86', '', 31, 'Once changes to guidelines and procedures are implemented, all team members should be informed of the changes and frequently reminded of the proper procedures to follow.', 'kb-doc-04-nist-sp-800-86-p31-16', 0, 26, '04-nist-sp-800-86', 'retrieved', '15866D126005B13270F58571B06C82ECF7E55E109D3904B42A9BBFDBE4F3FCDD', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p31-17', 'doc-04-nist-sp-800-86', '', 31, 'Teams typically have formal mechanisms for tracking changes and identifying the current versions of each process and procedure document.', 'kb-doc-04-nist-sp-800-86-p31-17', 0, 19, '04-nist-sp-800-86', 'retrieved', '4F3D3A67F2736C8CD3540C032D3640B692C39F0EFEF01ACBDAA711A11A2C5AD1', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p31-18', 'doc-04-nist-sp-800-86', '', 31, 'In addition, many teams have posters or other highly visible documents mounted on walls or doors that remind teams of the key steps to take, so that everyone is constantly reminded of how things are supposed to be done.', 'kb-doc-04-nist-sp-800-86-p31-18', 0, 39, '04-nist-sp-800-86', 'retrieved', '1FFAF6935395988A748D9CD3AF228BDADCABFA07CD6F1B5EFB8244FED27DA17B', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p31-19', 'doc-04-nist-sp-800-86', '', 31, 'In addition to addressing identified problems, analysts should take other steps to maintain and grow their skills.', 'kb-doc-04-nist-sp-800-86-p31-19', 0, 17, '04-nist-sp-800-86', 'retrieved', '07C1BF8DF238472FD3CF32F5AED4BE190D9A031B92D80697A058BA508723ED85', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p31-20', 'doc-04-nist-sp-800-86', '', 31, 'As a matter of maintaining their certification or accreditation, some forensic examiners must routinely refresh themselves with the latest tools and techniques that address the latest technologies pertaining to computer storage media, data types and formats, and other relevant issues.', 'kb-doc-04-nist-sp-800-86-p31-20', 0, 40, '04-nist-sp-800-86', 'retrieved', '454E7259EAF2687B5DB40B2D9E419D9F587B312717FF024298AE70ECE7FD6BD5', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p31-21', 'doc-04-nist-sp-800-86', '', 31, 'Whether required or not, periodic refreshing of skills through coursework, on-the-job experience, and academic sources helps ensure that people performing forensic actions keep pace with rapidly changing technologies and job responsibilities.', 'kb-doc-04-nist-sp-800-86-p31-21', 0, 31, '04-nist-sp-800-86', 'retrieved', '9D6CD22103251254247C03F952C82716DF1DFF75017952E35E1F178AB004CE72', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p31-22', 'doc-04-nist-sp-800-86', '', 31, 'Some organizations require all members of their forensic teams to pass annual proficiency examinations.', 'kb-doc-04-nist-sp-800-86-p31-22', 0, 14, '04-nist-sp-800-86', 'retrieved', '7096145F81034F6411AC237B5B4E9754C8A9267B63B696B1F5FD84E220CA1BD6', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p31-23', 'doc-04-nist-sp-800-86', '', 31, 'Periodic review of policies, guidelines, and procedures also helps ensure that the organization stays current with trends in technology and changes in law.', 'kb-doc-04-nist-sp-800-86-p31-23', 0, 23, '04-nist-sp-800-86', 'retrieved', '0DB4B92115ECDB4C3B711CB961105170A2BB0B4AB13141D434D00D6D400C5E19', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p31-24', 'doc-04-nist-sp-800-86', '', 31, '3.5 Re commendations The key recommendations presented in this section for the forensic process are as follows: ! Organizations should perform forensics using a consistent process.', 'kb-doc-04-nist-sp-800-86-p31-24', 0, 26, '04-nist-sp-800-86', 'retrieved', '25C2CEA9FC576CF47C6ACE4C5D93F475F909DE4F628CEA41456C822CD3930951', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p31-25', 'doc-04-nist-sp-800-86', '', 31, 'This guide presents a four-phase forensic process, with collection, examination, analysis, and reporting phases.', 'kb-doc-04-nist-sp-800-86-p31-25', 0, 14, '04-nist-sp-800-86', 'retrieved', '93425D0347AA1A4D2A5C091D1A07D260486172281F55E0345833ADE85E3B5047', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p31-28', 'doc-04-nist-sp-800-86', '', 31, 'Analysts should be able to survey a physical area and recognize possible sources of data.', 'kb-doc-04-nist-sp-800-86-p31-28', 0, 15, '04-nist-sp-800-86', 'retrieved', '4DC943FC8288FE2B59DFD3A23CAC579435243A7944D2F127F807B3D3C9AC414B', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p31-29', 'doc-04-nist-sp-800-86', '', 31, 'Analysts should also think of possible data sources located elsewhere within an organization and outside the organization.', 'kb-doc-04-nist-sp-800-86-p31-29', 0, 17, '04-nist-sp-800-86', 'retrieved', 'FE1C7A4026CF755B49932AFEE34DB759FAEA60FBE4A97536D76A074A83EC569E', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p32-1', 'doc-04-nist-sp-800-86', '', 32, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE Analysts should be prepared to use alternate data sources if it is not feasible to collect data from a primary source.', 'kb-doc-04-nist-sp-800-86-p32-1', 0, 29, '04-nist-sp-800-86', 'retrieved', '1A82741C0859DC9624210A268C67C688EA4A4F73198A77FB4B29DD691C9CDD49', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p32-3', 'doc-04-nist-sp-800-86', '', 32, 'Configuring auditing on OSs, implementing centralized logging, performing regular system backups, and using security monitoring controls can all generate sources of data for future forensic efforts.', 'kb-doc-04-nist-sp-800-86-p32-3', 0, 26, '04-nist-sp-800-86', 'retrieved', 'AD6DF082DC5150154943720FA47FC05188F4E5165C8F1CDD5B3D599BFB30C512', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p32-5', 'doc-04-nist-sp-800-86', '', 32, 'The recommended steps in this process are identifying sources of data, developing a plan to acquire the data, acquiring the data, and verifying the integrity of the data.', 'kb-doc-04-nist-sp-800-86-p32-5', 0, 28, '04-nist-sp-800-86', 'retrieved', 'A4486A9D6427C63557AA51F39270874798A72FED639F04F25155715E7D9F0F35', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p32-6', 'doc-04-nist-sp-800-86', '', 32, 'The plan should prioritize the data sources, establishing the order in which the data should be acquired based on the likely value of the data, the volatility of the data, and the amount of effort required.', 'kb-doc-04-nist-sp-800-86-p32-6', 0, 36, '04-nist-sp-800-86', 'retrieved', '52B41E786571264C9260EC0A3636EA0F1C29C7215E90B32F0579472865B83886', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p32-7', 'doc-04-nist-sp-800-86', '', 32, 'Before data collection begins, a decision should be made by the analyst or management regarding the need to collect and preserve evidence in a manner that supports its use in future legal or internal disciplinary proceedings.', 'kb-doc-04-nist-sp-800-86-p32-7', 0, 36, '04-nist-sp-800-86', 'retrieved', '299686F3CFA132519FFE6EC112A8B4D51A3511F74FFE8DDC0851AF6ACCD7C391', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p32-11', 'doc-04-nist-sp-800-86', '', 32, 'The foundation of forensics is using a methodical approach in analyzing the available data so that analysts can either draw appropriate conclusions based on the available data or determine that no conclusion can yet be drawn.', 'kb-doc-04-nist-sp-800-86-p32-11', 0, 36, '04-nist-sp-800-86', 'retrieved', 'B5AD4CD608F34B69D6FA24DF669F4E729DDEBDCD977E6FCA7BF3620B5EE75340', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
