INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p32-12', 'doc-04-nist-sp-800-86', '', 32, 'If evidence might be needed for legal or internal disciplinary actions, analysts should carefully document the findings and all steps taken.', 'kb-doc-04-nist-sp-800-86-p32-12', 0, 21, '04-nist-sp-800-86', 'retrieved', '67BEAD53B876B8D3824598EE3E79C560ECA46FF4F981429C83669930C2FD66BA', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
