INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p32-14', 'doc-04-nist-sp-800-86', '', 32, 'Reviews of current and recent forensic actions can help identify policy shortcomings, procedural errors, and other issues that might need to be remedied, as well as ensuring that the organization stays current with trends in technology and changes in law.', 'kb-doc-04-nist-sp-800-86-p32-14', 0, 40, '04-nist-sp-800-86', 'retrieved', '900D9425FE212C05D8C47153794C26F83415EF5E217E0E2667531174978E5F01', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
