INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p33-1', 'doc-04-nist-sp-800-86', '', 33, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE 4. Using Data from Data Files A data file (also called a file) is a collection of information logically grouped into a single entity and referenced by a unique name, such as a filename.', 'kb-doc-04-nist-sp-800-86-p33-1', 0, 42, '04-nist-sp-800-86', 'retrieved', '171210F9A1C00C25848154CFFE79D1486EBD9F83811474D31F384BE5A5942BBB', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
