INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p33-2', 'doc-04-nist-sp-800-86', '', 33, 'A file can be of many data types, including a document, an image, a video, or an application.', 'kb-doc-04-nist-sp-800-86-p33-2', 0, 18, '04-nist-sp-800-86', 'retrieved', '07FEBFCFE04E98D8A3722D313D9E1B17942B7FD45D8A187A1C4232657E84FF88', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
