INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p33-3', 'doc-04-nist-sp-800-86', '', 33, 'Successful forensic processing of computer media depends on the ability to collect, examine, and analyze the files that reside on the media.', 'kb-doc-04-nist-sp-800-86-p33-3', 0, 22, '04-nist-sp-800-86', 'retrieved', '2EF6DE73ED02343FD5A5C985F38A32E3144F5020A2A163CECADF3501C6652431', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p33-4', 'doc-04-nist-sp-800-86', '', 33, 'This section provides an overview of the most common media types and filesystemsmethods for naming, storing, organizing, and accessing files.', 'kb-doc-04-nist-sp-800-86-p33-4', 0, 20, '04-nist-sp-800-86', 'retrieved', '6AEB8077619395BD87BA912B7B19CDFBEA02FECDBD89EBDB3D7C9F63490E1AA4', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
