VALUES ('doc-04-nist-sp-800-86-p33-5', 'doc-04-nist-sp-800-86', '', 33, 'It then discusses how files should be collected and how the integrity of the files should be preserved.', 'kb-doc-04-nist-sp-800-86-p33-5', 0, 18, '04-nist-sp-800-86', 'retrieved', 'B0689EACF71D292B8783613325EB7201D46FA4D800ACFA92D8FE2E6542B87898', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
