VALUES ('doc-04-nist-sp-800-86-p33-6', 'doc-04-nist-sp-800-86', '', 33, 'The section also discusses various technical issues related to file recovery, such as recovering data from deleted files.', 'kb-doc-04-nist-sp-800-86-p33-6', 0, 18, '04-nist-sp-800-86', 'retrieved', '88E00725AFAC15EFDEF0107355D76AF0372D3E1334294F2368A82F12B6CC032F', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
