INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p33-7', 'doc-04-nist-sp-800-86', '', 33, 'The last portion of the section describes the examination and analysis of files, providing guidance on tools and techniques that can assist analysts.15 4.1 F ile Basics Before attempting to collect or examine files, analysts should have a reasonably comprehensive understanding of files and filesystems.', 'kb-doc-04-nist-sp-800-86-p33-7', 0, 45, '04-nist-sp-800-86', 'retrieved', '441B79D51A2A91BACF85651234DE75EE843A806782961770015713C4868F59C9', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
