INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p33-8', 'doc-04-nist-sp-800-86', '', 33, 'First, analysts should be aware of the variety of media that may contain files; Section 4.1.1 provides several examples of the media used in personal computers and other types of digital devices. Section 4.1.2 then explains how filesystems are used to organize files and provides an overview of several common filesystems.', 'kb-doc-04-nist-sp-800-86-p33-8', 0, 51, '04-nist-sp-800-86', 'retrieved', '48E5580B7C8177554439454F11ED4EE89655F505E0DB971B2E356D560B3865FC', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p33-9', 'doc-04-nist-sp-800-86', '', 33, 'Section 4.1.3 discusses how data from deleted files can still exist within filesystems.', 'kb-doc-04-nist-sp-800-86-p33-9', 0, 13, '04-nist-sp-800-86', 'retrieved', 'CF0EEDC33A5071791670EBBB9572628B96CC9C9C0B21FFA669DEDEF11FF7D085', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
