INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p33-11', 'doc-04-nist-sp-800-86', '', 33, 'File Storage Media The widespread use of computers and other digital devices has resulted in a significant increase in the number of different media types that are used to store files.', 'kb-doc-04-nist-sp-800-86-p33-11', 0, 31, '04-nist-sp-800-86', 'retrieved', '7FD4AA217256AF68AB1AE840181B9D2D79AD3607C19FC2D72CE61B9A5B312D98', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
