INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p33-12', 'doc-04-nist-sp-800-86', '', 33, 'In addition to traditional media types such as hard drives and floppy disks, files are often stored on consumer devices such as PDAs and cell phones, as well as on newer media types, such as flash memory cards, which were made popular by digital cameras.', 'kb-doc-04-nist-sp-800-86-p33-12', 0, 45, '04-nist-sp-800-86', 'retrieved', 'B28F74BE7FF1DFAA6FC6360D9462D53D1BE95CC31A778C181E78777007E4E4E5', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
