VALUES ('doc-04-nist-sp-800-86-p33-13', 'doc-04-nist-sp-800-86', '', 33, 'Table 4-1 lists media types that are commonly used on computers and digital devices.', 'kb-doc-04-nist-sp-800-86-p33-13', 0, 14, '04-nist-sp-800-86', 'retrieved', '8E65BDAD6797C896CACEAAECB8010D662A709AAA5B873C38D762446C7EECD624', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
