VALUES ('doc-04-nist-sp-800-86-p33-14', 'doc-04-nist-sp-800-86', '', 33, 'This list does not include every media type available; rather, it is intended to show the variety of media types that an analyst might come across.', 'kb-doc-04-nist-sp-800-86-p33-14', 0, 26, '04-nist-sp-800-86', 'retrieved', 'AB8F074AE3B4259DE76B42F3FC9B54A1DA8E33DCE9FBBCA0224C76E45DA526D7', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
