VALUES ('doc-04-nist-sp-800-86-p33-15', 'doc-04-nist-sp-800-86', '', 33, '15 For additional information regarding examination and analysis, see Examination of Digital Evidence: A Guide for Law Enforcement, which can be found at http://www.ncjrs.gov/pdffiles1/nij/199408.pdf.', 'kb-doc-04-nist-sp-800-86-p33-15', 0, 24, '04-nist-sp-800-86', 'retrieved', 'FB8C14C041331C3D364FE5224FD6956A3B5CA9D08FD5C69D990BBEE2C30972DF', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
