INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p34-2', 'doc-04-nist-sp-800-86', '', 34, 'Commonly Used Media Types Media Type Reader Typical Capacity16 Comments Primarily Used in Personal Computers Floppy disk Floppy disk drive 1.44 megabytes (MB) 3.5-inch disks; decreasing in popularity CD-ROM CD-ROM drive 650 MB800 MB Includes write-once (CD-R) and rewritable (CD- RW) disks; most commonly used media DVD-ROM DVD-ROM drive 1.67 gigabytes (GB)15.9 GB Includes write-once (DVD±R) and rewritable (DVD±RW) single and dual layer disks Hard drive N/A 20 GB400 GB Higher capacity drives used in many file servers Zip disk Zip drive 100 MB750 MB Larger than a floppy disk Jaz disk Jaz drive 1 GB2 GB Similar to Zip disks; no longer manufactured Backup tape Compatible tape drive 80 MB320 GB Many resemble audio cassette tapes; fairly susceptible to corruption from environmental conditions Magneto optical (MO) disk Compatible MO drive 600 MB9.1 GB 5.25-inch disks; less susceptible to environmental conditions than backup tapes Advanced Technology Attachment (ATA) flash card PCMCIA slot 8 MB2 GB PCMCIA flash memory card; measures 85.6 x 54 x 5 mm Used by Many Types of Digital Devices Flash/Jump drive USB interface 16 MB2 GB Also known as thumb drives because of their size CompactFlash card PCMCIA adapter or memory card reader 16 MB6 GB Type I cards measure 43 x 36 x 3.3 mm; Type II cards measure 43 x 36 x 5 mm Microdrive PCMCIA adapter or memory card reader 340 MB4 GB Same interface and form factor as CompactFlash Type II cards MultiMediaCard (MMC) PCMCIA adapter or memory card reader 16 MB512 MB Measures 24 x 32 x 1.4 mm Secure Digital (SD) Card PCMCIA adapter or memory card reader 32 MB1 GB Compliant with Secure Digital Music Initiative (SDMI) requirements; provides built-in data encryption of file contents; similar in form factor to MMCs Memory Stick PCMCIA adapter or memory card reader 16 MB2 GB Includes Memory Stick (50 x 21.5 x 2.8 mm), Memory Stick Duo (31 x 20 x 1.6 mm), Memory Stick PRO, Memory Stick PRO Duo; some are compliant with SDMI requirements and provide built-in encryption of file contents SmartMedia Card PCMCIA adapter or memory card reader 8 MB128 MB Measures 37 x 45 x 0.76 mm xD-Picture Card PCMCIA adapter or xD-Picture card reader 16 MB512 MB Currently used only in Fujifilm and Olympus digital cameras; measures 20 x 25 x 1.7 mm', 'kb-doc-04-nist-sp-800-86-p34-2', 0, 386, '04-nist-sp-800-86', 'retrieved', '1C40651FA3B139423EC177D2AA9AD03600B45ED4C6F1639A8F74916A26D499F7', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
