VALUES ('doc-04-nist-sp-800-86-p34-3', 'doc-04-nist-sp-800-86', '', 34, '16 The maximum capacity of many media types increases over time because of advances in technology and reductions in cost.', 'kb-doc-04-nist-sp-800-86-p34-3', 0, 20, '04-nist-sp-800-86', 'retrieved', 'E91872C9CA89BD66D26C5F97927FFBF6C8BDA29D44CC18F8C40C1BD28CBF85DE', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
