VALUES ('doc-04-nist-sp-800-86-p35-2', 'doc-04-nist-sp-800-86', '', 35, 'Filesystems Before media can be used to store files, the media must usually be partitioned and formatted into logical volumes.', 'kb-doc-04-nist-sp-800-86-p35-2', 0, 20, '04-nist-sp-800-86', 'retrieved', '3C6772762988E1E2E2686D155B4838C1EA508C50E0813B8109F10D18572157DF', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
