INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p35-3', 'doc-04-nist-sp-800-86', '', 35, 'Partitioning is the act of logically dividing a media into portions that function as physically separate units.', 'kb-doc-04-nist-sp-800-86-p35-3', 0, 17, '04-nist-sp-800-86', 'retrieved', 'D4BB3E857448A71C48C8E879D456CB701779CE29E2E5B6B20226323F5C642334', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
