INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p35-4', 'doc-04-nist-sp-800-86', '', 35, 'A logical volume is a partition or a collection of partitions acting as a single entity that has been formatted with a filesystem.', 'kb-doc-04-nist-sp-800-86-p35-4', 0, 23, '04-nist-sp-800-86', 'retrieved', '8AC258C5035DF00304FBE1A6FCBABB923BAE4FB85428FB1FE9307F71862D7391', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p35-5', 'doc-04-nist-sp-800-86', '', 35, 'Some media types, such as floppy disks, can contain at most one partition (and consequently, one logical volume).', 'kb-doc-04-nist-sp-800-86-p35-5', 0, 18, '04-nist-sp-800-86', 'retrieved', 'D1DA217442EB01FCC3F42B8975D29C596613D016F98CD310E1947FE38F8DD2A9', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
