INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p35-7', 'doc-04-nist-sp-800-86', '', 35, 'A filesystem defines the way that files are named, stored, organized, and accessed on logical volumes.', 'kb-doc-04-nist-sp-800-86-p35-7', 0, 16, '04-nist-sp-800-86', 'retrieved', '749B45F6F879F66163D7EF979FE125B37CA44CDFB532AF559510418070DE8C5A', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
