VALUES ('doc-04-nist-sp-800-86-p35-8', 'doc-04-nist-sp-800-86', '', 35, 'Many different filesystems exist, each providing unique features and data structures.', 'kb-doc-04-nist-sp-800-86-p35-8', 0, 11, '04-nist-sp-800-86', 'retrieved', 'C1C1BA09EB394616F89E6486649F859C0D834C197E2EF8C4763E5981CB3B6AFA', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
