VALUES ('doc-04-nist-sp-800-86-p35-10', 'doc-04-nist-sp-800-86', '', 35, 'First, they use the concepts of directories and files to organize and store data.', 'kb-doc-04-nist-sp-800-86-p35-10', 0, 14, '04-nist-sp-800-86', 'retrieved', 'CC4F89FD9745B55FAE1D6114DA472DB57AB461D394750E96CED3589516E7D5E7', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
