VALUES ('doc-04-nist-sp-800-86-p35-11', 'doc-04-nist-sp-800-86', '', 35, 'Directories are organizational structures that are used to group files together.', 'kb-doc-04-nist-sp-800-86-p35-11', 0, 11, '04-nist-sp-800-86', 'retrieved', 'AF7FADD8D9D26A090C4BAC49BA85D21FAD52FFF26FC09CA1CD7A66EDBF7365A4', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
