VALUES ('doc-04-nist-sp-800-86-p35-12', 'doc-04-nist-sp-800-86', '', 35, 'In addition to files, directories may contain other directories called subdirectories.', 'kb-doc-04-nist-sp-800-86-p35-12', 0, 11, '04-nist-sp-800-86', 'retrieved', 'C1F454446F4FF04DBDA6082F69AA9F9C0EAC58CDCB72193558D5DAEE1C496686', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
