VALUES ('doc-04-nist-sp-800-86-p35-13', 'doc-04-nist-sp-800-86', '', 35, 'Second, filesystems use some data structure to point to the location of files on media.', 'kb-doc-04-nist-sp-800-86-p35-13', 0, 15, '04-nist-sp-800-86', 'retrieved', '10A6B7A608EFE28A0E567AAF72A4BF67E8744F526CB314EFC4E9BDAACBFC0B90', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
