VALUES ('doc-04-nist-sp-800-86-p35-16', 'doc-04-nist-sp-800-86', '', 35, 'A file allocation unit is simply a group of sectors, which are the smallest units that can be accessed on media.', 'kb-doc-04-nist-sp-800-86-p35-16', 0, 21, '04-nist-sp-800-86', 'retrieved', '8F94E516E6043ACC57B52A88B4A647601988A83D7955D561CD88EA5910E34469', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
