VALUES ('doc-04-nist-sp-800-86-p35-17', 'doc-04-nist-sp-800-86', '', 35, 'Some commonly used filesystems are as follows: ! FAT12.17 FAT12 is used only on floppy disks and FAT volumes smaller than 16 MB.', 'kb-doc-04-nist-sp-800-86-p35-17', 0, 23, '04-nist-sp-800-86', 'retrieved', 'B0AC5553B7AEFE53DD95043BF7F9F9E4E71AE6A32BBC44B5B435D5BED8F73078', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
