VALUES ('doc-04-nist-sp-800-86-p35-30', 'doc-04-nist-sp-800-86', '', 35, 'NTFS is a recoverable filesystem, which means that it can automatically restore the consistency of the filesystem when errors occur.', 'kb-doc-04-nist-sp-800-86-p35-30', 0, 20, '04-nist-sp-800-86', 'retrieved', 'BDB98654F0AB895DCBF8DBDA6BF52C4B4E6B109AE4868B1F68AA41F994722294', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
