VALUES ('doc-04-nist-sp-800-86-p35-31', 'doc-04-nist-sp-800-86', '', 35, 'In addition, NTFS supports data compression and encryption, and allows user and group-level access permissions to be defined for data files and directories.19 The maximum NTFS volume size is 2 TB.', 'kb-doc-04-nist-sp-800-86-p35-31', 0, 31, '04-nist-sp-800-86', 'retrieved', 'A7D3DB0DD833480373C2B4BF45E415912243433B3678098E707697217EFF9C4E', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
