VALUES ('doc-04-nist-sp-800-86-p35-34', 'doc-04-nist-sp-800-86', '', 35, 'HPFS builds on the directory organization of FAT by providing automatic sorting of directories.', 'kb-doc-04-nist-sp-800-86-p35-34', 0, 14, '04-nist-sp-800-86', 'retrieved', '3253673632F3F871FF1BEFF1BF5E743604FABCC4030092D5A4DBA040D6CEBFCB', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
