INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p36-6', 'doc-04-nist-sp-800-86', '', 36, 'It is based on the ext2fs filesystem and provides journaling capabilities that allow consistency checks of the filesystem to be performed quickly on large amounts of data.', 'kb-doc-04-nist-sp-800-86-p36-6', 0, 27, '04-nist-sp-800-86', 'retrieved', '1EADDE1B85D4007C146067E265FE330445CD04774C9B790F698D6C4995BA8AF1', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
