VALUES ('doc-04-nist-sp-800-86-p36-8', 'doc-04-nist-sp-800-86', '', 36, '! ReiserFS.21 ReiserFS is supported by Linux and is the default filesystem for several common versions of Linux.', 'kb-doc-04-nist-sp-800-86-p36-8', 0, 18, '04-nist-sp-800-86', 'retrieved', 'E450576648A372D89357CB83E8E62798F3D78210A23FCBC1774D8BA77CC91A84', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
