VALUES ('doc-04-nist-sp-800-86-p36-9', 'doc-04-nist-sp-800-86', '', 36, 'It offers journaling capabilities and is significantly faster than the ext2fs and ext3fs filesystems.', 'kb-doc-04-nist-sp-800-86-p36-9', 0, 14, '04-nist-sp-800-86', 'retrieved', 'F31133F95F3436F2F2206F31C03FB69B47A3AB6BC99358DDAB95D595D4ADD121', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
