VALUES ('doc-04-nist-sp-800-86-p36-12', 'doc-04-nist-sp-800-86', '', 36, 'HFS is mainly used in older versions of Mac OS but is still supported in newer versions.', 'kb-doc-04-nist-sp-800-86-p36-12', 0, 17, '04-nist-sp-800-86', 'retrieved', '668BAE591949553A023567163D10C420F3FEEB1F13EF3D2EB8A3B8F412DD3624', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
