VALUES ('doc-04-nist-sp-800-86-p36-17', 'doc-04-nist-sp-800-86', '', 36, 'It is the successor to HFS and provides numerous enhancements, such as long filename support and Unicode filename support for international filenames.', 'kb-doc-04-nist-sp-800-86-p36-17', 0, 22, '04-nist-sp-800-86', 'retrieved', '1BEDF65BADE5F8CBF4435B040265166E1EE5CFB7159F79D45FCE12BE0221B3D5', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
