VALUES ('doc-04-nist-sp-800-86-p36-19', 'doc-04-nist-sp-800-86', '', 36, '! UNIX File System (UFS).24 UFS is supported natively by several types of UNIX OSs, including Solaris, FreeBSD, OpenBSD, and Mac OS X.', 'kb-doc-04-nist-sp-800-86-p36-19', 0, 23, '04-nist-sp-800-86', 'retrieved', 'C25E5A01721FF4895654D2047FEFD87F93029A049F1B852015065E7FCAA71EFD', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
