VALUES ('doc-04-nist-sp-800-86-p36-20', 'doc-04-nist-sp-800-86', '', 36, 'However, most OSs have added proprietary features, so the details of UFS differ among implementations.', 'kb-doc-04-nist-sp-800-86-p36-20', 0, 15, '04-nist-sp-800-86', 'retrieved', '97FB706938FF51BEA745FB1ECA9B4032010B507DBAF56C64D1C45F23BCE208CC', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
