VALUES ('doc-04-nist-sp-800-86-p36-26', 'doc-04-nist-sp-800-86', '', 36, 'ISO 9660 supports filename lengths of up to 32 characters, whereas Joliet supports up to 64 characters.', 'kb-doc-04-nist-sp-800-86-p36-26', 0, 17, '04-nist-sp-800-86', 'retrieved', '0E6AA4A0B24185875AECE93D9FE83B1048DE3479DEE2DE4268B03355D8A2AD75', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
