VALUES ('doc-04-nist-sp-800-86-p36-31', 'doc-04-nist-sp-800-86', '', 36, 'Other Data on Media As described in Section 4.1.2, filesystems are designed to store files on media.', 'kb-doc-04-nist-sp-800-86-p36-31', 0, 17, '04-nist-sp-800-86', 'retrieved', '3208CCD626BD3A507D7B28C08AD3BB0A12846B4C9D7A822144E7A826EB5EC558', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
