VALUES ('doc-04-nist-sp-800-86-p36-32', 'doc-04-nist-sp-800-86', '', 36, 'However, filesystems may also hold data from deleted files or earlier versions of existing files.', 'kb-doc-04-nist-sp-800-86-p36-32', 0, 15, '04-nist-sp-800-86', 'retrieved', 'FC5AB6D1B09F8CE1F9A58D9743B761D204AC9B2EE4FCC78633548AFE712B982D', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
