VALUES ('doc-04-nist-sp-800-86-p36-34', 'doc-04-nist-sp-800-86', '', 36, '(Section 4.2 discusses techniques for collecting this type of data.) The following items describe how this data can still exist on various media: ! Deleted Files.', 'kb-doc-04-nist-sp-800-86-p36-34', 0, 26, '04-nist-sp-800-86', 'retrieved', '4E6FACEB771147C7B45CBF0ABE1D35903D2690F0E02F0F94BFC55D7FEC8C110F', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
