INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p36-35', 'doc-04-nist-sp-800-86', '', 36, 'When a file is deleted, it is typically not erased from the media; instead, the information in the directorys data structure that points to the location of the file is marked as deleted.', 'kb-doc-04-nist-sp-800-86-p36-35', 0, 33, '04-nist-sp-800-86', 'retrieved', '426A55CCBFBDF6321B40F89F74B5BAF8996BBA1C3EA6F6403543693DE06CE82F', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p36-36', 'doc-04-nist-sp-800-86', '', 36, 'This means that the file is still stored on the media but is no longer enumerated by the', 'kb-doc-04-nist-sp-800-86-p36-36', 0, 18, '04-nist-sp-800-86', 'retrieved', '44621A5EF3D3450D8E222E24DFEACB7CB308F17C46F64EC896841B78DE9AAFBF', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
