VALUES ('doc-04-nist-sp-800-86-p36-41', 'doc-04-nist-sp-800-86', '', 36, '24 An overview of UFS is available at http://en.wikipedia.org/wiki/Unix_File_System.', 'kb-doc-04-nist-sp-800-86-p36-41', 0, 9, '04-nist-sp-800-86', 'retrieved', '1EC020CF1F3662D655035A48EC35BC166145E5AD6B3764D7981EA4F523B66701', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
