INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p37-2', 'doc-04-nist-sp-800-86', '', 37, 'The operating system considers this to be free space and can overwrite any portion of or the entire deleted file at any time.', 'kb-doc-04-nist-sp-800-86-p37-2', 0, 23, '04-nist-sp-800-86', 'retrieved', '353F1C3CDAA048A5BD6B6CEA210891A82487468A696992F65C33EA9AA3D83E6F', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p37-5', 'doc-04-nist-sp-800-86', '', 37, 'Even if a file requires less space than the file allocation unit size, an entire file allocation unit is still reserved for the file.', 'kb-doc-04-nist-sp-800-86-p37-5', 0, 24, '04-nist-sp-800-86', 'retrieved', '2ED3A4C0FCA3B0077E12142DAE7FF0FB75A9AFB42EF1C5AF1F6DA66EAFC6EE66', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p37-6', 'doc-04-nist-sp-800-86', '', 37, 'For example, if the file allocation unit size is 32 kilobytes (KB) and a file is only 7 KB, the entire 32 KB is still allocated to the file, but only 7 KB is used, resulting in 25 KB of unused space.', 'kb-doc-04-nist-sp-800-86-p37-6', 0, 42, '04-nist-sp-800-86', 'retrieved', 'DADC7B3560A15BEE8A3AD952D56AF765DE4C1FA32FEE94D5C870172A0268B82D', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p37-7', 'doc-04-nist-sp-800-86', '', 37, 'This unused space is referred to as file slack space, and it may hold residual data such as portions of deleted files.', 'kb-doc-04-nist-sp-800-86-p37-7', 0, 22, '04-nist-sp-800-86', 'retrieved', '79E99F87206E4D425DCE083AF059EA748C6C7A47FBD02CFEAE6C9224C21320F5', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p37-9', 'doc-04-nist-sp-800-86', '', 37, 'Free space is the area on media that is not allocated to any partition; it includes unallocated clusters or blocks.', 'kb-doc-04-nist-sp-800-86-p37-9', 0, 20, '04-nist-sp-800-86', 'retrieved', 'BD6841C0027B80B95C8D916DBC50387BBD03D41172E5CE8C57311B13EAF27DD2', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p37-10', 'doc-04-nist-sp-800-86', '', 37, 'This often includes space on the media where files (and even entire volumes) may have resided at one point but have since been deleted.', 'kb-doc-04-nist-sp-800-86-p37-10', 0, 24, '04-nist-sp-800-86', 'retrieved', '88931E42DBA968902796B4A1F923BCFE77EC872EF3EDDC8012F538E8A6654184', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
