INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p37-12', 'doc-04-nist-sp-800-86', '', 37, 'Another way in which data might be hidden is through Alternate Data Streams (ADS) within NTFS volumes.', 'kb-doc-04-nist-sp-800-86-p37-12', 0, 17, '04-nist-sp-800-86', 'retrieved', '6C154A11D66D674B6AEF6D8E9BBD688A65AEDC0C4B56C7B7C53B3B898A02F365', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p37-14', 'doc-04-nist-sp-800-86', '', 37, 'Each file in an NTFS volume consists of an unnamed stream that is used to store the file''s primary data, and optionally one or more named streams (i.e., file.txt:Stream1, file.txt:Stream2) that can be used to store auxiliary information, such as file properties and picture thumbnail data.25 For instance, if a user right-clicks on a file in Windows Explorer, views the files properties, and then modifies the information displayed in the summary tab, the OS stores the summary information for the file in a named stream.', 'kb-doc-04-nist-sp-800-86-p37-14', 0, 85, '04-nist-sp-800-86', 'retrieved', 'A4F42934FD3B75C3DC96E92B51EED9BAC1169BCD857E4C5689DA025D45EA4F25', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p37-15', 'doc-04-nist-sp-800-86', '', 37, 'All data streams within a file share the files attributes (e.g., timestamps, security attributes).', 'kb-doc-04-nist-sp-800-86-p37-15', 0, 14, '04-nist-sp-800-86', 'retrieved', '55A473B0E10E722AA20E022511DC86B33ADFCC8914F5651FE041CE47F9CE21B4', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p37-16', 'doc-04-nist-sp-800-86', '', 37, 'Although named streams do affect the storage quota of a file, they are largely concealed from users because standard Windows file utilities, such as Explorer, only report the size of a file''s unnamed stream.', 'kb-doc-04-nist-sp-800-86-p37-16', 0, 34, '04-nist-sp-800-86', 'retrieved', 'CD39C5FCF087D24896BA42C87C1AEF9D584658C85F001B47C87E4D51510EB6E3', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p37-17', 'doc-04-nist-sp-800-86', '', 37, 'As a result, a user cannot readily determine whether a file contains ADS using the standard Windows file utilities.', 'kb-doc-04-nist-sp-800-86-p37-17', 0, 19, '04-nist-sp-800-86', 'retrieved', '147098C771407605573E2C5DB5FC8FCE11AE432170255161E9E3B84C5D5440BD', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p37-19', 'doc-04-nist-sp-800-86', '', 37, 'Moving files with ADS to non-NTFS filesystems effectively strips ADS from the file, so the ADS can be lost if analysts are not aware of their presence.', 'kb-doc-04-nist-sp-800-86-p37-19', 0, 27, '04-nist-sp-800-86', 'retrieved', 'AFF375A9C665507187090E50C1A02FF3763CDAB166FB38EDD11186A9DD0AD81D', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p37-20', 'doc-04-nist-sp-800-86', '', 37, 'Software and processes are available to identify ADS.26 4.2 C ollecting Files During data collection, the analyst should make multiple copies of the relevant files or filesystems typically a master copy and a working copy.27 The analyst can then use the working copy without affecting the original files or the master copy.', 'kb-doc-04-nist-sp-800-86-p37-20', 0, 52, '04-nist-sp-800-86', 'retrieved', '9DA5C361E2ACBC5E0B8181AC3883E7110EF4DF0AAA955896FEDCCC69E502B3A3', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p37-21', 'doc-04-nist-sp-800-86', '', 37, 'Section 4.2.1 describes the primary techniques and tools for copying files and residual file data from media.', 'kb-doc-04-nist-sp-800-86-p37-21', 0, 17, '04-nist-sp-800-86', 'retrieved', 'E470267D8070B40DADEC3E12D84F04E160294CBF2020461442ABF3FEB8C0721C', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
