INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p37-22', 'doc-04-nist-sp-800-86', '', 37, 'Section 4.2.2 discusses the importance of maintaining the integrity of the files and provides guidance on hardware and software that can assist in preserving and verifying file integrity.', 'kb-doc-04-nist-sp-800-86-p37-22', 0, 28, '04-nist-sp-800-86', 'retrieved', '05B7F33AE402651933ADD04C334A36A367DF745E6FBB91D03D6AF2D9A33D2450', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
