INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p37-23', 'doc-04-nist-sp-800-86', '', 37, 'It is often important to collect not only the files, but also significant timestamps for the files, such as when the files were last modified or accessed.', 'kb-doc-04-nist-sp-800-86-p37-23', 0, 27, '04-nist-sp-800-86', 'retrieved', 'CF33D54490757C6BC455A4E9BCC042342801A8A65848C283E4798FBD7729F74D', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
