VALUES ('doc-04-nist-sp-800-86-p37-25', 'doc-04-nist-sp-800-86', '', 37, 'Other technical issues related to file collection, such as finding hidden files and copying files from redundant array of inexpensive disks (RAID) implementations, are addressed in Section 4.2.4.', 'kb-doc-04-nist-sp-800-86-p37-25', 0, 28, '04-nist-sp-800-86', 'retrieved', '50EE5E486502F0D6D2D2208D19CBD7135EBFEBC2739E62F19EB25DFC9F7A672D', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
