VALUES ('doc-04-nist-sp-800-86-p37-27', 'doc-04-nist-sp-800-86', '', 37, '26 Additional information on ADS is available at http://www.microsoft.com/technet/prodtechnol/winxppro/reskit/c13621675.mspx, http://www.infosecwriters.com/texts.php?op=display&id=53, and within http://www.heysoft.de/Frames/f_faq_ads_en.htm.', 'kb-doc-04-nist-sp-800-86-p37-27', 0, 13, '04-nist-sp-800-86', 'retrieved', '9523B650B88572D44E0E52C5E678FBA3682B2D34AB6B7BC946E78FF48CA79800', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
