INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p37-28', 'doc-04-nist-sp-800-86', '', 37, '27 The purpose of the master copy is to generate additional working copies if the first working copy can no longer be used because of alteration or other reasons.', 'kb-doc-04-nist-sp-800-86-p37-28', 0, 29, '04-nist-sp-800-86', 'retrieved', '614A892A15ADD47AA7F6592F70D09CF86A9F875B752A5FAF51D615DDF231275A', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
