VALUES ('doc-04-nist-sp-800-86-p38-2', 'doc-04-nist-sp-800-86', '', 38, 'Copying Files from Media Files can be copied from media using two different techniques: ! Logical Backup.', 'kb-doc-04-nist-sp-800-86-p38-2', 0, 17, '04-nist-sp-800-86', 'retrieved', '454455DA27A92C7259C95D3130E49C2892F483842DA846DDCD08F41806D415AB', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
