INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p38-4', 'doc-04-nist-sp-800-86', '', 38, 'It does not capture other data that may be present on the media, such as deleted files or residual data stored in slack space.', 'kb-doc-04-nist-sp-800-86-p38-4', 0, 24, '04-nist-sp-800-86', 'retrieved', '397FAFE0B5EBAA4E7D6430D857704D724F1E5A5C2E875245ADC733F6038A5672', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
