INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p38-6', 'doc-04-nist-sp-800-86', '', 38, 'Also known as disk imaging, bit stream imaging generates a bit-for-bit copy of the original media, including free space and slack space.', 'kb-doc-04-nist-sp-800-86-p38-6', 0, 22, '04-nist-sp-800-86', 'retrieved', '9452301B4F9D230C51DB9F55FCB6C21F04C07793A9FA1A5616EFBE5C4AA31D1B', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p38-7', 'doc-04-nist-sp-800-86', '', 38, 'Bit stream images require more storage space and take longer to perform than logical backups.', 'kb-doc-04-nist-sp-800-86-p38-7', 0, 15, '04-nist-sp-800-86', 'retrieved', '07981C3174F8F7B0BE13033F8D531A1629B1B0D6848629C0E36B25D922925CCE', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p38-8', 'doc-04-nist-sp-800-86', '', 38, 'If evidence may be needed for prosecution or disciplinary actions, the analyst should get a bit stream image of the original media, label the original media, and store it securely as evidence.', 'kb-doc-04-nist-sp-800-86-p38-8', 0, 32, '04-nist-sp-800-86', 'retrieved', 'A36DDFB7B18EB4C74B25A786C3BFAB79D959CF29B0579A688FA1A080DE108F2D', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p38-9', 'doc-04-nist-sp-800-86', '', 38, 'All subsequent analysis should be performed using the copied media to ensure that the original media is not modified and that a copy of the original media can always be recreated if necessary.', 'kb-doc-04-nist-sp-800-86-p38-9', 0, 33, '04-nist-sp-800-86', 'retrieved', 'FA6C53AD48B65363E2269C58ECC2EA5B415509C8F5ECA8C765A9B4E70C58DE0C', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p38-11', 'doc-04-nist-sp-800-86', '', 38, 'Doing so should allow any analyst to produce an exact duplicate of the original media using the same procedures.', 'kb-doc-04-nist-sp-800-86-p38-11', 0, 19, '04-nist-sp-800-86', 'retrieved', '3DDB407DE8E8C8154E8D13824796BA0CBEFFFC5CA58517E3B9A725C036BCAF16', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
