INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p38-12', 'doc-04-nist-sp-800-86', '', 38, 'In addition, proper documentation can be used to demonstrate that evidence was not mishandled during the collection process.', 'kb-doc-04-nist-sp-800-86-p38-12', 0, 18, '04-nist-sp-800-86', 'retrieved', '46972BDDE15C5CC2696ADE843EC6884D4CECF5B0C9B26988427A0F7BDE107C47', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
