INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p38-15', 'doc-04-nist-sp-800-86', '', 38, 'When a bit stream image is executed, either a disk-to-disk or a disk-to-file copy can be performed.', 'kb-doc-04-nist-sp-800-86-p38-15', 0, 17, '04-nist-sp-800-86', 'retrieved', '5CD0F70BE3C2459B1BBB119499D27054E6BE61B3618334C94528101C1364E4A6', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
