INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p38-16', 'doc-04-nist-sp-800-86', '', 38, 'A disk-to-disk copy, as its name suggests, copies the contents of the media directly to another media.', 'kb-doc-04-nist-sp-800-86-p38-16', 0, 17, '04-nist-sp-800-86', 'retrieved', 'EF7B6B5F72D6EFFF6EA994C22155664001C0E39967C3F2A70F6A54DC20D7220F', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p38-17', 'doc-04-nist-sp-800-86', '', 38, 'A disk-to-file copy copies the contents of the media to a single logical data file.', 'kb-doc-04-nist-sp-800-86-p38-17', 0, 15, '04-nist-sp-800-86', 'retrieved', 'F2CCB11DE7D92AA8750B346E86A56D1F031259E2C4B96C03B0823651D7EBC0F3', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p38-18', 'doc-04-nist-sp-800-86', '', 38, 'A disk-to-disk copy is useful since the copied media can be connected directly to a computer and its contents readily viewed.', 'kb-doc-04-nist-sp-800-86-p38-18', 0, 21, '04-nist-sp-800-86', 'retrieved', '74F9EBF9FDFBEC5812B080D36117201BA8DBFE719F8F8C689DA1454DCD42EBB6', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p38-19', 'doc-04-nist-sp-800-86', '', 38, 'However, a disk-to-disk copy requires a second media similar to the original media.28 A disk-to-file copy allows the data file image to be moved and backed up easily.', 'kb-doc-04-nist-sp-800-86-p38-19', 0, 28, '04-nist-sp-800-86', 'retrieved', '600BB6FB51CF4FBED7869432C88755A1E21EB7D8F3A9424657FAA1CDA9576601', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p38-20', 'doc-04-nist-sp-800-86', '', 38, 'However, to view the logical contents of an image file, the analyst has to restore the image to media or open or read it from an application capable of displaying the logical contents of bit stream images.', 'kb-doc-04-nist-sp-800-86-p38-20', 0, 37, '04-nist-sp-800-86', 'retrieved', 'DA13DEF908DAAE1332B64E069B899ADF532C6293133ABC20F876C09F02C87720', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p38-23', 'doc-04-nist-sp-800-86', '', 38, 'Numerous hardware and software tools can perform bit stream imaging and logical backups.', 'kb-doc-04-nist-sp-800-86-p38-23', 0, 13, '04-nist-sp-800-86', 'retrieved', '976D2C7B9E05E686972F06D378B2559D3E43D99809B38B723D29C341B17999EE', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p38-24', 'doc-04-nist-sp-800-86', '', 38, 'Hardware tools are generally portable, provide bit-by-bit images, connect directly to the drive or computer to be imaged, and have built-in hash functions.29 Hardware tools can acquire data from drives that use common types of controllers, such as Integrated Drive Electronics (IDE) and Small Computer System Interface (SCSI).', 'kb-doc-04-nist-sp-800-86-p38-24', 0, 48, '04-nist-sp-800-86', 'retrieved', 'A740B4462DA397CE4FF0D2C90EBC178B6705389DFDC376744A12EBB55DC5C6C3', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p38-25', 'doc-04-nist-sp-800-86', '', 38, 'Software solutions generally consist of a startup diskette, CD, or installed programs that run on a workstation to which the media to be imaged is attached.30 Some software solutions create logical copies', 'kb-doc-04-nist-sp-800-86-p38-25', 0, 32, '04-nist-sp-800-86', 'retrieved', '8E686D7EED573E4D826A2A94EBBEF52AF12176D098DFABD4084AA8B6030E2418', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p38-26', 'doc-04-nist-sp-800-86', '', 38, '28 The destination medium should be forensically clean before the copy occurs, so that any existing data on the medium is eliminated.', 'kb-doc-04-nist-sp-800-86-p38-26', 0, 22, '04-nist-sp-800-86', 'retrieved', 'E3574A298163B5B4E93461B190C1DA4C041DBDB423CEA534B2D66DD64CAD526A', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p38-27', 'doc-04-nist-sp-800-86', '', 38, 'The destination medium should have a larger storage capacity than the data to be copied.', 'kb-doc-04-nist-sp-800-86-p38-27', 0, 15, '04-nist-sp-800-86', 'retrieved', '0A4B660243DA2637164D197AE7DF70063036CFBD56FBF0B0982F1A04BFC84065', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p38-28', 'doc-04-nist-sp-800-86', '', 38, '29 Examples of hardware-based disk imaging tools are Image MASSters SOLO Forensics (http://www.ics-iq.com/) and Logicubes Solitaire (http://www.logicube.com/).', 'kb-doc-04-nist-sp-800-86-p38-28', 0, 17, '04-nist-sp-800-86', 'retrieved', 'C1E1D4353AAC2EB84495D105B9AA47A16EABB008C656BA84FC230B73B7D26D1D', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p38-29', 'doc-04-nist-sp-800-86', '', 38, 'Additional products are referenced in Web sites listed in Appendix F, including The Ultimate Collection of Forensics Software (TUCOFS) (http://www.tucofs.com/tucofs/tucofs.asp?mode=filelist&catid=10&oskey=12).', 'kb-doc-04-nist-sp-800-86-p38-29', 0, 20, '04-nist-sp-800-86', 'retrieved', '18FCC1A09B9848014E735B8E47ECC064F9F1FB3C388892FEB4014708A7A51359', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p38-30', 'doc-04-nist-sp-800-86', '', 38, 'The applications referenced throughout this publication are by no means a complete list of applications to use for forensic purposes, nor does this publication imply any endorsement of certain products.', 'kb-doc-04-nist-sp-800-86-p38-30', 0, 30, '04-nist-sp-800-86', 'retrieved', 'D5AFA810001BCB90429D0B7C060F7BB40430F76898A5044513B905E7CFEEE8C3', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p38-31', 'doc-04-nist-sp-800-86', '', 38, '30 Examples of software-based disk imaging tools are Linux dd, SafeBack (http://www.forensics-intl.com/safeback.html), EnCase (http://www.encase.com/), Norton Ghost (http://www.symantec.com/home_homeoffice/products/overview.jsp?pcid=br&pvid=ghost10), and ILook (http://www.ilook-forensics.org/).', 'kb-doc-04-nist-sp-800-86-p38-31', 0, 20, '04-nist-sp-800-86', 'retrieved', 'BF39DBC55FE19A9AE1D1539410EB26A5E2ADDBA9EE67CE51EBF4CDE2C3E7CF34', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p39-1', 'doc-04-nist-sp-800-86', '', 39, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE of files or partitions and may ignore free or unallocated drive space, whereas others create a bit-by-bit image copy of the media.', 'kb-doc-04-nist-sp-800-86-p39-1', 0, 30, '04-nist-sp-800-86', 'retrieved', '7D70A0B99042CA9068065C91184D4CBBC768B510E5BABF5C2A59BDB7299F8191', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p39-2', 'doc-04-nist-sp-800-86', '', 39, 'In addition to their primary function, some disk imaging tools can also perform forensic recordkeeping, such as automated audit trails and chain of custody.', 'kb-doc-04-nist-sp-800-86-p39-2', 0, 24, '04-nist-sp-800-86', 'retrieved', '722B7EE7B086B6F734AFE4AC03572EFBB054E534913948873E43A064D7B45464', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p39-3', 'doc-04-nist-sp-800-86', '', 39, 'The use of such tools can support consistency in the examination process and the accuracy and reproducibility of results.', 'kb-doc-04-nist-sp-800-86-p39-3', 0, 19, '04-nist-sp-800-86', 'retrieved', '2094CEDD189B48FFDFF2BFB98BD5FF5EE2FCDD31E1E281CAE9D24C9B12F4566D', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p39-5', 'doc-04-nist-sp-800-86', '', 39, 'In response to this proliferation and the lack of a standard for testing them, NISTs Computer Forensics Tool Testing (CFTT) project has developed rigorous testing procedures for validating the tools results.', 'kb-doc-04-nist-sp-800-86-p39-5', 0, 31, '04-nist-sp-800-86', 'retrieved', 'B9A207E0ED8F3A1689ED8B36FDB4929662C2E30806916CCE5113284C0BDCF1A6', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p39-6', 'doc-04-nist-sp-800-86', '', 39, 'Currently, only a few disk imaging tools have undergone CFTT testing.31 Generally, tools that perform bit stream imaging should not be used to acquire bit-by-bit copies of an entire physical device from a live systema system currently in usebecause the files and memory on such a system are changing constantly and therefore cannot be validated.32 However, a bit-by-bit copy of the logical areas of a live system can be completed and validated.', 'kb-doc-04-nist-sp-800-86-p39-6', 0, 72, '04-nist-sp-800-86', 'retrieved', '0BE916C160E841FA21D9B631F9B63EBB8DD65480CD6E8B6F555C20986BA1E55F', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p39-7', 'doc-04-nist-sp-800-86', '', 39, 'When logical backups are being performed, it is still preferable not to copy files from a live system; changes might be made to files during the backup, and files that are held open by a process might not be easy to copy.', 'kb-doc-04-nist-sp-800-86-p39-7', 0, 42, '04-nist-sp-800-86', 'retrieved', '80E1895F8A75BBEE52A75E7E9199BB564100D6A59F30698B88656741D1A0287A', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p39-8', 'doc-04-nist-sp-800-86', '', 39, 'Accordingly, analysts should decide whether copying files from a live system is feasible based on which files need to be obtained, how accurate and complete the copying needs to be, and how important the live system is.33 For example, it is not necessary to take down a critical server used by hundreds of people just to collect files from a single users home directory.', 'kb-doc-04-nist-sp-800-86-p39-8', 0, 64, '04-nist-sp-800-86', 'retrieved', '1ECFE08847D94234EA98F5D4486C770B16256B041355368BEEE200E330FB6E72', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p39-9', 'doc-04-nist-sp-800-86', '', 39, 'For logical backups of live systems, analysts can use standard system backup software.', 'kb-doc-04-nist-sp-800-86-p39-9', 0, 13, '04-nist-sp-800-86', 'retrieved', '1F69469185096E7EC19A5C73409A2981528C87DCE5763E9A92CA35322A74FE72', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p39-10', 'doc-04-nist-sp-800-86', '', 39, 'However, performing a backup could affect the performance of the system and consume significant amounts of network bandwidth, depending on whether the backup is performed locally or remotely.', 'kb-doc-04-nist-sp-800-86-p39-10', 0, 28, '04-nist-sp-800-86', 'retrieved', 'FBB977660F1F22CBEF8742A561D2F3603834E29FB0B939F7150DAE4C36488627', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p39-11', 'doc-04-nist-sp-800-86', '', 39, 'Organizations should have policy, guidelines, and procedures that indicate the circumstances under which bit stream images and logical backups (including those from live systems) may be performed for forensic purposes and which personnel may perform them.34 It is typically most effective to establish policy, guidelines, and procedures based on categories of systems (i.e., low, moderate, or high impact) and the nature of the event of interest; some organizations also choose to create separate policy statements, guidelines, and procedures for particularly important systems.', 'kb-doc-04-nist-sp-800-86-p39-11', 0, 82, '04-nist-sp-800-86', 'retrieved', 'F207640792CCC21F5C439672B6131806159278D8B1DF05D71A46E10FAA69B072', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p39-12', 'doc-04-nist-sp-800-86', '', 39, 'The policy, guidelines, or procedures should identify the individuals or groups with authority to make decisions regarding backups and images; these people should be capable of weighing the risks and making sound decisions.', 'kb-doc-04-nist-sp-800-86-p39-12', 0, 33, '04-nist-sp-800-86', 'retrieved', '28AE99F7821CA3E4EE06CEA39FF998BF36DCF0FFB174C1A99EAEC7DE4F427444', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p39-13', 'doc-04-nist-sp-800-86', '', 39, 'The policy, guidelines, or procedures should also identify which individuals or groups have the authority to perform the backup or imaging for each type of system.', 'kb-doc-04-nist-sp-800-86-p39-13', 0, 26, '04-nist-sp-800-86', 'retrieved', '9C95726CCB47864AA79B7EEC790646CBCDAB4B11AF8C72EF480A80054E303B45', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
