VALUES ('doc-04-nist-sp-800-86-p39-14', 'doc-04-nist-sp-800-86', '', 39, 'Access to some systems might be restricted because of the sensitivity of the operations or data in the system.', 'kb-doc-04-nist-sp-800-86-p39-14', 0, 19, '04-nist-sp-800-86', 'retrieved', '36F029CA550B4A7589285266215E7B81905369A895D71088EE50C6D308A6AB58', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
