VALUES ('doc-04-nist-sp-800-86-p39-16', 'doc-04-nist-sp-800-86', '', 39, 'Data File Integrity During backups and imaging, the integrity of the original media should be maintained.', 'kb-doc-04-nist-sp-800-86-p39-16', 0, 16, '04-nist-sp-800-86', 'retrieved', '2E8DE56658A72DF5DA9D89A43EA8AC7382734074043EF58F47A5BB442F850B2F', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p39-17', 'doc-04-nist-sp-800-86', '', 39, 'To ensure that the backup or imaging process does not alter data on the original media, analysts can use a write-blocker while backing up or imaging the media.', 'kb-doc-04-nist-sp-800-86-p39-17', 0, 28, '04-nist-sp-800-86', 'retrieved', 'BC32A049FBB35BE31F572D70A9EE89B9642C6CE1B94399183DF5F64C5E9BE539', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p39-18', 'doc-04-nist-sp-800-86', '', 39, 'A write-blocker is a hardware or software-based tool that prevents a computer from writing to computer storage media connected to it.', 'kb-doc-04-nist-sp-800-86-p39-18', 0, 21, '04-nist-sp-800-86', 'retrieved', 'D8C7640A96CCF1A499C6D823C4BA5EA416DFD87186B8386337C635C06374AD86', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p39-19', 'doc-04-nist-sp-800-86', '', 39, 'Hardware write-blockers are physically connected to the computer and the storage media being processed to prevent any writes to', 'kb-doc-04-nist-sp-800-86-p39-19', 0, 19, '04-nist-sp-800-86', 'retrieved', '7C1FA38E30EFAAF9FD0ABDE3D5DA1D5E1F2E8F11DF1B559AA43B1F8C4CCE0C72', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p39-21', 'doc-04-nist-sp-800-86', '', 39, '32 For example, services or processes running on the system might be writing to a systems hard drive, even if no person is currently using the computer.', 'kb-doc-04-nist-sp-800-86-p39-21', 0, 27, '04-nist-sp-800-86', 'retrieved', '02C4C1FBA16C61551F18D730CC4937B38759A1A64CF6EA12BCB25876FF1EC5EB', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p39-22', 'doc-04-nist-sp-800-86', '', 39, '33 Analysts should also consider the possible need to collect volatile data from the system.', 'kb-doc-04-nist-sp-800-86-p39-22', 0, 15, '04-nist-sp-800-86', 'retrieved', '58822CBB82F5376A70F6B6EA7EFDB1547AA3FEEF6FEBD356BD1E2F60A0F0E2F2', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p39-23', 'doc-04-nist-sp-800-86', '', 39, 'If the system is live, its volatile data is likely to change more quickly and to be more challenging to preserve.', 'kb-doc-04-nist-sp-800-86-p39-23', 0, 21, '04-nist-sp-800-86', 'retrieved', '8B346320CCB2C52109677DA08AB3C771370A9E52DD9837F3621E5D917169E04F', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p39-24', 'doc-04-nist-sp-800-86', '', 39, '34 This recommendation is not intended to restrict users from performing backups of their own data and local workstations, but to prevent people from collecting backups of others systems and data without appropriate cause for doing so.', 'kb-doc-04-nist-sp-800-86-p39-24', 0, 37, '04-nist-sp-800-86', 'retrieved', 'D436442A5D95CE3B45C0725E16C77185E5F469138071F44DBA278FFBA5B7947A', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p40-1', 'doc-04-nist-sp-800-86', '', 40, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE that media.35 Software write-blockers are installed on the analysts forensic system and currently are available only for MS-DOS and Windows systems.', 'kb-doc-04-nist-sp-800-86-p40-1', 0, 29, '04-nist-sp-800-86', 'retrieved', '1189E0A215F55A13EA5316FCEEF534A9DDA2847BC316AA66496C4A31D2E33BFC', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p40-2', 'doc-04-nist-sp-800-86', '', 40, '(Some OSs [e.g., Mac OS X, Linux] may not require software write-blockers because they can be set to boot with secondary devices not mounted.', 'kb-doc-04-nist-sp-800-86-p40-2', 0, 24, '04-nist-sp-800-86', 'retrieved', '25D4D7F11911E17412DF2544C30EC5D9A1E69624F58C4693EAF9FC17F38FE838', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p40-3', 'doc-04-nist-sp-800-86', '', 40, 'However, attaching a hardware write-blocking device will ensure that integrity is maintained.) MS-DOSbased software write-blockers work by trapping Interrupt 13 and extended Interrupt 13 disk writes.', 'kb-doc-04-nist-sp-800-86-p40-3', 0, 26, '04-nist-sp-800-86', 'retrieved', 'C50C6379F6C966B01CDED1F21242917D1C65ACEA7140E4A8CF9B4CB98B14BE80', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p40-4', 'doc-04-nist-sp-800-86', '', 40, 'Windows- based software write-blockers use filters to sort interrupts sent to devices to prevent any writes to storage media.36 In general, when using a hardware write-blocker, the media or device used to read the media should be connected directly to the write-blocker, and the write-blocker should be connected to the computer or device used to perform the backup or imaging.', 'kb-doc-04-nist-sp-800-86-p40-4', 0, 60, '04-nist-sp-800-86', 'retrieved', '8AAD3270BA152CC1CDC9B6BE6FB1AC66F1F88824C7CAD16F95A85391ED551A42', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p40-5', 'doc-04-nist-sp-800-86', '', 40, 'When using a software write-blocker, the software should be loaded onto a computer before the media or device used to read the media is connected to the computer.', 'kb-doc-04-nist-sp-800-86-p40-5', 0, 28, '04-nist-sp-800-86', 'retrieved', 'FB5DF3772F0E7ABB061DD7E053F130335AA56D3F226B3E30804A3035E9C18681', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p40-6', 'doc-04-nist-sp-800-86', '', 40, 'Write-blockers may also allow write-blocking to be toggled on or off for a particular device.', 'kb-doc-04-nist-sp-800-86-p40-6', 0, 15, '04-nist-sp-800-86', 'retrieved', 'C1031E0F693D817997BE4C0B2E1F3B784E15B48BD054387705DE1AEC0B7D66B4', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p40-7', 'doc-04-nist-sp-800-86', '', 40, 'It is important when write-blocking is used, that it be toggled on for all connected devices.37 Write- blockers also should be tested routinely to ensure that they support newer devices.', 'kb-doc-04-nist-sp-800-86-p40-7', 0, 30, '04-nist-sp-800-86', 'retrieved', '2D90A4E731C4982BC60EC4D3DD8EF4ACD44224AB6150916D99446969AB2F8491', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p40-8', 'doc-04-nist-sp-800-86', '', 40, 'For example, a new device might make use of reserved or previously unused functions or placeholders to implement device- specific functions that might ultimately write to the device and alter its contents.', 'kb-doc-04-nist-sp-800-86-p40-8', 0, 32, '04-nist-sp-800-86', 'retrieved', 'C8741FB88AA23BA0FAE57A9865189553495AB4AC0B14B2C6652A013B2E098E54', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p40-9', 'doc-04-nist-sp-800-86', '', 40, 'After a backup or imaging is performed, it is important to verify that the copied data is an exact duplicate of the original data.38 Computing the message digest of the copied data can be used to verify and ensure data integrity.39 A message digest is a hash that uniquely identifies data and has the property that changing a single bit in the data will cause a completely different message digest to be generated.', 'kb-doc-04-nist-sp-800-86-p40-9', 0, 73, '04-nist-sp-800-86', 'retrieved', '016FD067D4DC299FFBE61BBF424091682B19AA59366004C3DECB506D9B4EEF34', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p40-10', 'doc-04-nist-sp-800-86', '', 40, 'There are many algorithms for computing the message digest of data, but the two most commonly used are MD5 and Secure Hash Algorithm 1 (SHA-1).', 'kb-doc-04-nist-sp-800-86-p40-10', 0, 25, '04-nist-sp-800-86', 'retrieved', 'D6BF5B3CFD5FBF67C01B9FBB7365F874E1B33D2073CA51289B3EBA3C87BE9C09', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p40-11', 'doc-04-nist-sp-800-86', '', 40, 'These algorithms take as input data of arbitrary length and produce as output 128-bit message digests.', 'kb-doc-04-nist-sp-800-86-p40-11', 0, 16, '04-nist-sp-800-86', 'retrieved', 'A7C99B9B1CB4ED6961618B07D66271BE7B8C2C22F6F88057587125C9097DA8E9', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p40-12', 'doc-04-nist-sp-800-86', '', 40, 'Because SHA-1 is a Federal Information Processing Standards (FIPS)approved algorithm and MD5 is not, Federal agencies should use SHA-1 instead of MD5 for message digests.40 When a bit stream image is performed, the message digest of the original media should be computed and recorded before the image is performed.', 'kb-doc-04-nist-sp-800-86-p40-12', 0, 49, '04-nist-sp-800-86', 'retrieved', '9C83B75F1F99E02C055E475DA20F65058B4CFCE07B7FB61441BACC2E821E5FB5', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p40-13', 'doc-04-nist-sp-800-86', '', 40, 'After the imaging, the message digest of the copied media should be computed and compared with the original message digest to verify that data integrity has been preserved.', 'kb-doc-04-nist-sp-800-86-p40-13', 0, 28, '04-nist-sp-800-86', 'retrieved', '028BDF877D222CEAD10D943C512093905B0C6C203EF6C25A3F434BCD53B5B746', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p40-14', 'doc-04-nist-sp-800-86', '', 40, 'The message digest of the original media should then be computed again to verify that the imaging process did not alter the original media, and all results should be documented.', 'kb-doc-04-nist-sp-800-86-p40-14', 0, 30, '04-nist-sp-800-86', 'retrieved', 'B5D469718F3AC7385E4FAE5F5716138ACBC0F0741C95D8B2AACC5EAE3D424FDD', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p40-15', 'doc-04-nist-sp-800-86', '', 40, 'The process should be used for logical backups, except that message digests should be computed and compared for', 'kb-doc-04-nist-sp-800-86-p40-15', 0, 18, '04-nist-sp-800-86', 'retrieved', 'FBE32B10614A0BABC2731BB53333FC7A28E9DD8C9675AC51854EB54134149B13', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
