VALUES ('doc-04-nist-sp-800-86-p40-16', 'doc-04-nist-sp-800-86', '', 40, '35 Examples of hardware write-blockers are FastBloc (http://www.guidancesoftware.com/lawenforcement/ef_index.asp), NoWrite (http://www.mykeytech.com/nowrite.html), and SCSIBlock (http://www.digitalintelligence.com/products/scsiblock/).', 'kb-doc-04-nist-sp-800-86-p40-16', 0, 13, '04-nist-sp-800-86', 'retrieved', '22044A50F62F4D6CC0C4FF7393B64ADB847439262DF89F1C9923525B0CCA0A55', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
