VALUES ('doc-04-nist-sp-800-86-p40-18', 'doc-04-nist-sp-800-86', '', 40, '36 An example of a software write-blocker is PDBlock (http://www.digitalintelligence.com/software/disoftware/pdblock/).', 'kb-doc-04-nist-sp-800-86-p40-18', 0, 10, '04-nist-sp-800-86', 'retrieved', '55141630A0F5E0BFC8FFB35CC5DBA8E72144D651C881D5489BF97C72B932881E', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
