VALUES ('doc-04-nist-sp-800-86-p40-21', 'doc-04-nist-sp-800-86', '', 40, 'Analysts should refer to the operating procedures for a specific write-blocker product for instructions on proper usage.', 'kb-doc-04-nist-sp-800-86-p40-21', 0, 17, '04-nist-sp-800-86', 'retrieved', '62C3A3EF9F37414C89B8881A5F6DEE9139151C13FC7322F390E3D4063E92E1C9', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
