INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p40-22', 'doc-04-nist-sp-800-86', '', 40, '38 If a backup is performed on a live system, it is likely that some files will change between the time the backup was initiated and the time it is completed and verified.', 'kb-doc-04-nist-sp-800-86-p40-22', 0, 33, '04-nist-sp-800-86', 'retrieved', '4D29B6E12370F76F69241A237A781C0C9F297A2465A7B5D032122B6B3EA4F026', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
