INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p40-23', 'doc-04-nist-sp-800-86', '', 40, '39 Message digests should be used to ensure the integrity of all data that is acquired during forensic activity, including log files and logical backups.', 'kb-doc-04-nist-sp-800-86-p40-23', 0, 25, '04-nist-sp-800-86', 'retrieved', '309D03663077516CE8093F47E5B7FF91E320EE5E3E0732935C8C4F267FA28D5B', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
