INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p40-24', 'doc-04-nist-sp-800-86', '', 40, '40 Federal agencies must use FIPS-approved encryption algorithms contained in validated cryptographic modules.', 'kb-doc-04-nist-sp-800-86-p40-24', 0, 13, '04-nist-sp-800-86', 'retrieved', '3D3997B5003CA7785EA6D08F2031BA046D961B19DD2B2E86D2422BB01510F041', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
