INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p40-25', 'doc-04-nist-sp-800-86', '', 40, 'The Cryptographic Module Validation Program (CMVP) at NIST coordinates FIPS testing; the CMVP Web site is located at http://csrc.nist.gov/cryptval/.', 'kb-doc-04-nist-sp-800-86-p40-25', 0, 19, '04-nist-sp-800-86', 'retrieved', '6CE8F1B8633F05D7A78ACAB496B6736C8CB662F02CFDDC0459F106FBA1CEB5B2', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
