INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p40-26', 'doc-04-nist-sp-800-86', '', 40, 'FIPS 180-2, Secure Hash Standard, is available at http://csrc.nist.gov/publications/fips/fips180-2/fips180-2withchangenotice.pdf.', 'kb-doc-04-nist-sp-800-86-p40-26', 0, 9, '04-nist-sp-800-86', 'retrieved', '431E6C4E0215689AC70A5AD990004EC872F9D231DBD88397A25F5FF9F539B1CD', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
