INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p40-27', 'doc-04-nist-sp-800-86', '', 40, 'NIST has announced that Federal agencies should plan to transition from SHA-1 to stronger forms of SHA (e.g., SHA-224, SHA-256) by 2010.', 'kb-doc-04-nist-sp-800-86-p40-27', 0, 22, '04-nist-sp-800-86', 'retrieved', '0BAEFE5F64C3DC96D235CE480CA57CDF5064FAC638EC21C16F771B9DD6B61262', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
