INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p40-28', 'doc-04-nist-sp-800-86', '', 40, 'For more information, see NIST comments from August 2004 posted at http://csrc.nist.gov/hash_standards_comments.pdf, as well as http://www.nsrl.nist.gov/collision.html.', 'kb-doc-04-nist-sp-800-86-p40-28', 0, 16, '04-nist-sp-800-86', 'retrieved', 'DA8088F14844C9847351305F87BDEA355B8F06EE9C6D7D872ED65AF20F553327', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
