INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p41-2', 'doc-04-nist-sp-800-86', '', 41, 'For both bit stream images and logical backups, the message digests created to ensure data integrity should be stored on read-only or write-once media or printed, and then secured in a proper location.', 'kb-doc-04-nist-sp-800-86-p41-2', 0, 33, '04-nist-sp-800-86', 'retrieved', '444E2FD7A79D94ED5C8AD0574F5ADC48B2F1DAD6A0A106F9C1D13404318DBD35', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
