INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p41-4', 'doc-04-nist-sp-800-86', '', 41, 'File Modification, Access, and Creation Times It is often important to know when a file was created, used, or manipulated, and most OSs keep track of certain timestamps related to files.', 'kb-doc-04-nist-sp-800-86-p41-4', 0, 31, '04-nist-sp-800-86', 'retrieved', '176236A75AA94638188C0706B03DA258D3D19BF897FC9290FC3E73F7EF907A0F', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p41-5', 'doc-04-nist-sp-800-86', '', 41, 'The most commonly used timestamps are the modification, access, and creation (MAC) times, as follows: ! Modification Time.', 'kb-doc-04-nist-sp-800-86-p41-5', 0, 18, '04-nist-sp-800-86', 'retrieved', '24943B9AE560890EDE824D0C9CEA8D71E714F1EE4A100B3F04AD0E8FFEBA122F', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p41-6', 'doc-04-nist-sp-800-86', '', 41, 'This is the last time a file was changed in any way, including when a file is written to and when it is changed by another program.', 'kb-doc-04-nist-sp-800-86-p41-6', 0, 27, '04-nist-sp-800-86', 'retrieved', 'B91F515ACC130E41A5676CD4EE2275F92A86655251B375B18830EE640B3B3D7E', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p41-8', 'doc-04-nist-sp-800-86', '', 41, 'This is the last time any access was performed on a file (e.g., viewed, opened, printed).', 'kb-doc-04-nist-sp-800-86-p41-8', 0, 16, '04-nist-sp-800-86', 'retrieved', 'CD494162EE629A488FFBAFD45D811ADF88C8F52495EBF71004DD9E103C374DF4', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p41-10', 'doc-04-nist-sp-800-86', '', 41, 'This is generally the time and date the file was created; however, when a file is copied to a system, the creation time will become the time the file was copied to the new system.', 'kb-doc-04-nist-sp-800-86-p41-10', 0, 35, '04-nist-sp-800-86', 'retrieved', 'E5E41CD27E09891AD96F3860244A2023E4D4FB624B21971FC5F05EC253B23D23', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p41-13', 'doc-04-nist-sp-800-86', '', 41, 'For example, Windows systems retain the last modified time, the last access time, and the creation time of files.41 UNIX systems retain the last modification, last inode42 change, and last access times; however, some UNIX systems (including versions of BSD and SunOS) do not update the last access time of executable files when they are run.', 'kb-doc-04-nist-sp-800-86-p41-13', 0, 56, '04-nist-sp-800-86', 'retrieved', '143EB5017E36A39A677A0AEA0050D0B76D5805CED44B9FCE59FF85964F0D2B87', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p41-14', 'doc-04-nist-sp-800-86', '', 41, 'Some UNIX systems record the time when the metadata for a file was most recently altered.', 'kb-doc-04-nist-sp-800-86-p41-14', 0, 16, '04-nist-sp-800-86', 'retrieved', 'EB760DD607EDFEA4E82A8819E63FF1F378772FF8D1A796ABFFB7C749B8265330', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p41-15', 'doc-04-nist-sp-800-86', '', 41, 'Metadata is data about data; for filesystems, metadata is data that provides information about a files contents.', 'kb-doc-04-nist-sp-800-86-p41-15', 0, 17, '04-nist-sp-800-86', 'retrieved', '4C7A0A25565E43C50658FBDE1241FF983E29177E7F8B1E8EFC4D437BB60B8C36', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p41-16', 'doc-04-nist-sp-800-86', '', 41, 'If an analyst needs to establish an accurate timeline of events, then the file times should be preserved.', 'kb-doc-04-nist-sp-800-86-p41-16', 0, 18, '04-nist-sp-800-86', 'retrieved', '4E5C5EAF3065070DDB3393DC1F6B8C39ECF0CA5535E78547A3986B83E0A8A9CD', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p41-17', 'doc-04-nist-sp-800-86', '', 41, 'Accordingly, analysts should be aware that not all methods for collecting data files can preserve file times.', 'kb-doc-04-nist-sp-800-86-p41-17', 0, 17, '04-nist-sp-800-86', 'retrieved', '93A58C6531A164ECB118EAF49B6433A8742A9A74974ABEDF3969F764CBA04DD1', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p41-18', 'doc-04-nist-sp-800-86', '', 41, 'Bit stream images can preserve file times because a bit-for-bit copy is generated; performing a logical backup using some tools may cause file creation times to be altered when the data file is copied.', 'kb-doc-04-nist-sp-800-86-p41-18', 0, 34, '04-nist-sp-800-86', 'retrieved', '125C9A47FC749D34BAE4F51C61E40B11DD3A1BC550F8A88422285311A36A3517', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p41-19', 'doc-04-nist-sp-800-86', '', 41, 'For this reason, whenever file times are essential, bit stream imaging should be used to collect data.', 'kb-doc-04-nist-sp-800-86-p41-19', 0, 17, '04-nist-sp-800-86', 'retrieved', 'B75AA8B0CFFAFF9DEACE07645B82BA76C6A6B65E3CDA0FD01FE1E7A23BFE3DAD', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p41-21', 'doc-04-nist-sp-800-86', '', 41, 'Among the reasons for such inaccuracies are the following: ! The computers clock does not have the correct time.', 'kb-doc-04-nist-sp-800-86-p41-21', 0, 19, '04-nist-sp-800-86', 'retrieved', '4A0DE3FC3B842AB34C0CC7967E85ADA74096BE4381DFFBBEC2CD5098824F524E', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p41-22', 'doc-04-nist-sp-800-86', '', 41, 'For example, the clock may not have been synchronized regularly with an authoritative time source.', 'kb-doc-04-nist-sp-800-86-p41-22', 0, 15, '04-nist-sp-800-86', 'retrieved', '484F087D55C7AD7FED2A65C367B6CB81923BA648DFD4B02999AE80F54485E490', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
