VALUES ('doc-04-nist-sp-800-86-p41-23', 'doc-04-nist-sp-800-86', '', 41, '! The time may not be recorded with the expected level of detail, such omitting the seconds or minutes.', 'kb-doc-04-nist-sp-800-86-p41-23', 0, 19, '04-nist-sp-800-86', 'retrieved', '779EBF5B0831AE7083EB0C420D9CB783368EFBDD6514E0ADA5465008211CA1C9', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
