VALUES ('doc-04-nist-sp-800-86-p41-26', 'doc-04-nist-sp-800-86', '', 41, 'As noted in Section 4.2.1, the primary issue is the collection of deleted files and remnants of files existing in free and slack space on media.', 'kb-doc-04-nist-sp-800-86-p41-26', 0, 26, '04-nist-sp-800-86', 'retrieved', '8167F8D4BD2F62A1E6D9896C40A883042BAC0094F2D322BF4CAE1B3C66A93545', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p41-27', 'doc-04-nist-sp-800-86', '', 41, 'Individuals can use a variety of techniques to hinder the collection of such data.', 'kb-doc-04-nist-sp-800-86-p41-27', 0, 14, '04-nist-sp-800-86', 'retrieved', 'A22A3705E54C7B8098D6DC86F64B005A47435CEB748C8596847553FA588F7B21', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p41-28', 'doc-04-nist-sp-800-86', '', 41, 'For example, there are many utilities available that perform wipingthe overwriting of media (or portions of media, such as particular files) with random or constant values (e.g., all 0s).', 'kb-doc-04-nist-sp-800-86-p41-28', 0, 29, '04-nist-sp-800-86', 'retrieved', 'EBB9D0B983354058D8FCEDD0A77B8ECCF3B196ACE76D9E836A38C1EE96D0C244', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p41-30', 'doc-04-nist-sp-800-86', '', 41, '41 Windows systems using the NTFS filesystem also record the entry modified time.', 'kb-doc-04-nist-sp-800-86-p41-30', 0, 13, '04-nist-sp-800-86', 'retrieved', '1168E0E7F00779C71100CA6348FD95F8C86FCCA1323EDCF63F32C696ECE23F71', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p41-31', 'doc-04-nist-sp-800-86', '', 41, '42 An inode is a set of data regarding certain characteristics of a file, such as the privileges set for the file and the files owner.', 'kb-doc-04-nist-sp-800-86-p41-31', 0, 26, '04-nist-sp-800-86', 'retrieved', '0CC2EF616F17119C6B9068F2A7347D4C956FE2A785EA625D1D25F07A589567FE', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p42-1', 'doc-04-nist-sp-800-86', '', 42, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE effective in preventing easy collection of files, especially if several wipes are performed.', 'kb-doc-04-nist-sp-800-86-p42-1', 0, 21, '04-nist-sp-800-86', 'retrieved', '4836AD13CB9B9D386E5008FD82B24743FB807687457171EC11E13706E8B9584D', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p42-2', 'doc-04-nist-sp-800-86', '', 42, 'Individuals can also use physical means to prevent data collection, such as demagnetizing a hard drive (also known as degaussing) or physically damaging or destroying media.', 'kb-doc-04-nist-sp-800-86-p42-2', 0, 26, '04-nist-sp-800-86', 'retrieved', 'AEF4CA490F11210E532229988CBC6991737808A240ECB80A71BA98CBE9081E97', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p42-3', 'doc-04-nist-sp-800-86', '', 42, 'Both physical and software-based techniques can make it very difficult, or even impossible, to recover all of the data using software.', 'kb-doc-04-nist-sp-800-86-p42-3', 0, 21, '04-nist-sp-800-86', 'retrieved', '94C1BCB433DC3F53182F9781B4BCFC66B3C8BE62E0DA31EC594FCBFA44B51317', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p42-4', 'doc-04-nist-sp-800-86', '', 42, 'Recovery attempts in these cases necessitate the use of highly specialized forensic experts with advanced facilities, hardware, and techniques, but the cost and effort involved in making use of such means are prohibitive for general use.43 In some cases, the data is simply not recoverable.', 'kb-doc-04-nist-sp-800-86-p42-4', 0, 45, '04-nist-sp-800-86', 'retrieved', '0BDE06975E5D8C3E6BA480E913ED6E7E5546E244E8A8F3C4A34504C662A78293', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p42-6', 'doc-04-nist-sp-800-86', '', 42, 'Many OSs permit users to tag certain files, directories, or even partitions as hidden, which means that by default they are not displayed in directory listings.44 Some applications and OSs hide configuration files to reduce the chance that users will accidentally modify or delete them.', 'kb-doc-04-nist-sp-800-86-p42-6', 0, 45, '04-nist-sp-800-86', 'retrieved', 'CB658EA4736B77AED2C3ABF1A41FD4D81CCFE9DCFBC507D5AB61CE2A4C151AF7', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p42-8', 'doc-04-nist-sp-800-86', '', 42, 'Hidden data may contain a wealth of information; for example, a hidden partition could contain a separate OS and many data files.45 Users may create hidden partitions by altering the partition table to disrupt disk management and prevent applications from seeing that the data area exists.', 'kb-doc-04-nist-sp-800-86-p42-8', 0, 46, '04-nist-sp-800-86', 'retrieved', '29D8BAED74A318DC9029414C7CB716D99056D1DEFDA26EEC4C1F91CDF2F28CB6', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p42-9', 'doc-04-nist-sp-800-86', '', 42, 'Hidden data can also be found within ADSs on NTFS volumes, in the end-of-file slack space and free space on a medium, and in the Host Protected Area (HPA) on some hard drives, which is a region of a drive intended to be used by vendors only.', 'kb-doc-04-nist-sp-800-86-p42-9', 0, 47, '04-nist-sp-800-86', 'retrieved', 'EC71E482FCB604594ED3C8ACD8EBB286602A746CBB236FF2DDD378B1DBF64819', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p42-10', 'doc-04-nist-sp-800-86', '', 42, 'Many collection tools can recognize some or all of these methods of hiding data and recover the associated data.', 'kb-doc-04-nist-sp-800-86-p42-10', 0, 19, '04-nist-sp-800-86', 'retrieved', '58E33C37F2FFAE5307012EA8C68C0AF1752A8267FE87C4D7C25D6472BDA0D1C2', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p42-11', 'doc-04-nist-sp-800-86', '', 42, 'Yet another issue that may arise is collection of data from RAID arrays that use striping (e.g., RAID-0, RAID-5).46 In this configuration, a striped volume consists of equal-sized partitions that reside on separate disk drives.', 'kb-doc-04-nist-sp-800-86-p42-11', 0, 35, '04-nist-sp-800-86', 'retrieved', 'F5C284489904B5FC478489CD1CCC0F38B8E8F855999A0D43797A0778A5AE873D', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p42-12', 'doc-04-nist-sp-800-86', '', 42, 'When data is written to the volume, it is evenly distributed across the partitions to improve disk performance.', 'kb-doc-04-nist-sp-800-86-p42-12', 0, 18, '04-nist-sp-800-86', 'retrieved', 'C1A54EA86058078108C62AAB755EF3D6D9B0FD655650BFBA88E2DDCEF4EC7E67', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p42-13', 'doc-04-nist-sp-800-86', '', 42, 'This can cause problems because all partitions of a striped volume must be present for the examination of its contents, but in this case the partitions reside on separate physical disk drives.', 'kb-doc-04-nist-sp-800-86-p42-13', 0, 32, '04-nist-sp-800-86', 'retrieved', 'A397EA94AB9B376F63350E3502C1D34559C8047333C5F4F1C3A655D9F093E4AD', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p42-14', 'doc-04-nist-sp-800-86', '', 42, 'To examine a striped volume, each disk drive in the RAID array needs to be imaged and the RAID configuration has to be recreated on the examination system.47 The examination system needs to be booted using a forensic boot disk that can recognize and use the RAID array and that prevents writes to the array.', 'kb-doc-04-nist-sp-800-86-p42-14', 0, 55, '04-nist-sp-800-86', 'retrieved', '31F1D06045242773F205E345AB8E41B7FB60A82C704BA9BE59967F182B2654F8', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p42-15', 'doc-04-nist-sp-800-86', '', 42, 'Some imaging tools can acquire striped volumes and preserve unused data areas of the volume, such as free space and slack space.48 4.3 Examining Data Files After a logical backup or bit stream imaging has been performed, the backup or image may have to be restored to another media before the data can be examined.', 'kb-doc-04-nist-sp-800-86-p42-15', 0, 55, '04-nist-sp-800-86', 'retrieved', '2FC0A9C9215F9F72D12082F407056066EC5B2F7B5A9414C6C58C804BE10DFF08', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p42-16', 'doc-04-nist-sp-800-86', '', 42, 'This is dependent on the forensic tools that will be used to perform the analysis.', 'kb-doc-04-nist-sp-800-86-p42-16', 0, 15, '04-nist-sp-800-86', 'retrieved', '05006FC8EA084F670281EBD380C5A88FD1C956BE6A73CBAAD9A1667DE67E5060', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p42-17', 'doc-04-nist-sp-800-86', '', 42, 'Some tools can analyze data directly from an image file, whereas others require that the backup or image be restored to a medium first.49 Regardless of whether an image file or a restored image is used in the examination, the data should be accessed only as read-only to ensure', 'kb-doc-04-nist-sp-800-86-p42-17', 0, 49, '04-nist-sp-800-86', 'retrieved', '7598A54FF0210FB6A8C7C3760EF93BA0401ED228F24E519E66D03B1AD25893F1', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p42-18', 'doc-04-nist-sp-800-86', '', 42, '43 Companies that specialize in such recovery efforts include Data Recovery Services, DriveSavers, and Ontrack Data Recovery.', 'kb-doc-04-nist-sp-800-86-p42-18', 0, 17, '04-nist-sp-800-86', 'retrieved', 'CDFDA2D744300AA21C93BA12131C97575AF0C23970803ACB6A019CB24F34D36F', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p42-19', 'doc-04-nist-sp-800-86', '', 42, '44 On UNIX systems, files or folders beginning with a . are considered hidden and are not displayed when listing files unless the a flag is used.', 'kb-doc-04-nist-sp-800-86-p42-19', 0, 27, '04-nist-sp-800-86', 'retrieved', 'D9E45455413EF0090226CB9429819D34A426BEECB06A811D1246DEA13788D5D8', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p42-20', 'doc-04-nist-sp-800-86', '', 42, '45 An example of a freely available tool that can be used to locate hidden partitions is the FDISK utility built into DOS.', 'kb-doc-04-nist-sp-800-86-p42-20', 0, 23, '04-nist-sp-800-86', 'retrieved', 'EF870190E41352F029D7BCF739ED5893BA80AD00922BB939F5CEA16586744A87', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
