VALUES ('doc-04-nist-sp-800-86-p42-21', 'doc-04-nist-sp-800-86', '', 42, 'Information about additional tools is available from the Web sites listed in Appendix F.', 'kb-doc-04-nist-sp-800-86-p42-21', 0, 14, '04-nist-sp-800-86', 'retrieved', '1DE582052BE63BACA9F31898E132EB9D84F4BDECB392917E3ADD73A12277D798', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
