VALUES ('doc-04-nist-sp-800-86-p42-22', 'doc-04-nist-sp-800-86', '', 42, '46 An overview of RAID is available at http://www.adaptec.com/worldwide/product/markeditorial.html?prodkey=quick_explanation_of_raid.', 'kb-doc-04-nist-sp-800-86-p42-22', 0, 9, '04-nist-sp-800-86', 'retrieved', '2FFD4FD999D40086ECE222FD1B09E8308EF2890C78C8B8F0E629A10B3558B1AC', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
