INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p42-23', 'doc-04-nist-sp-800-86', '', 42, '47 Because RAID-5 stores parity information on one disk, it is possible to examine a RAID-5 volume by imaging all of the disks but one.', 'kb-doc-04-nist-sp-800-86-p42-23', 0, 25, '04-nist-sp-800-86', 'retrieved', 'C142682BDC156DF9D4FBA2C3C7967BF94A1F634E63B6D7966BB12037EE3C1E7D', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
