VALUES ('doc-04-nist-sp-800-86-p42-24', 'doc-04-nist-sp-800-86', '', 42, '48 For more information regarding RAIDs, visit http://www.anandtech.com/storage/showdoc.html?i=1491.', 'kb-doc-04-nist-sp-800-86-p42-24', 0, 8, '04-nist-sp-800-86', 'retrieved', 'A5B7366F2946F6B75A5965E81B3664C3F98F7913D4D4064CE592959E291F54C1', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
