INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p42-25', 'doc-04-nist-sp-800-86', '', 42, '49 At one time, when tools had more limited capabilities, it was often recommended that data files be restored to a system using the same OS or a related one.', 'kb-doc-04-nist-sp-800-86-p42-25', 0, 30, '04-nist-sp-800-86', 'retrieved', '4C04B30B771F52FC95278526D0B00B7D024A76F3A5CEBFB4E05A3BDB4DD35B14', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p42-26', 'doc-04-nist-sp-800-86', '', 42, 'Current tools are more advanced and are designed to be used with many types of data files, regardless of the underlying OS, so it is no longer necessary in most cases to restore data files to a particular OS.', 'kb-doc-04-nist-sp-800-86-p42-26', 0, 39, '04-nist-sp-800-86', 'retrieved', '897157B9B0F846611FF56DB3177DFE85173E56AC75C46D66DA393478C55B0335', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p43-1', 'doc-04-nist-sp-800-86', '', 43, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE that the data being examined is not modified and that it will provide consistent results on successive runs.', 'kb-doc-04-nist-sp-800-86-p43-1', 0, 26, '04-nist-sp-800-86', 'retrieved', '81C272BA2BAE378B761ABC21F80DCF81E0172D64E6AAF72DA441B801948BB8AA', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p43-2', 'doc-04-nist-sp-800-86', '', 43, 'As noted in Section 4.2.2, write-blockers can be used during this process to prevent writes from occurring to the restored image.', 'kb-doc-04-nist-sp-800-86-p43-2', 0, 21, '04-nist-sp-800-86', 'retrieved', 'C813FEC68E6139B2BD74552ECED6D78D196FE4CB1DECF2F776F20CD3997BAE2B', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p43-3', 'doc-04-nist-sp-800-86', '', 43, 'After restoring the backup (if needed), the analyst begins to examine the collected data and performs an assessment of the relevant files and data by locating all files, including deleted files, remnants of files in slack and free space, and hidden files.', 'kb-doc-04-nist-sp-800-86-p43-3', 0, 42, '04-nist-sp-800-86', 'retrieved', 'C7C167DE5960532AF2C62B119257F4E32DD3B743B0FA85BE35F43278F894E492', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p43-4', 'doc-04-nist-sp-800-86', '', 43, 'Next, the analyst may need to extract the data from some or all of the files, which may be complicated by such measures as encryption and password protection.', 'kb-doc-04-nist-sp-800-86-p43-4', 0, 28, '04-nist-sp-800-86', 'retrieved', '5E35B799462FA959D0F4FE2598A4FE69165BD10F60BD91AAB4C677FFAEDEDB9F', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p43-5', 'doc-04-nist-sp-800-86', '', 43, 'This section describes the processes involved in examining files and data, as well as techniques that can expedite examination.', 'kb-doc-04-nist-sp-800-86-p43-5', 0, 19, '04-nist-sp-800-86', 'retrieved', 'B50AF181939D1D18FDAB328148AF076D4705A6CB45F74B862FAF160AA99AB0CF', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p43-8', 'doc-04-nist-sp-800-86', '', 43, 'A disk image can capture many gigabytes of slack space and free space, which could contain thousands of files and file fragments.', 'kb-doc-04-nist-sp-800-86-p43-8', 0, 22, '04-nist-sp-800-86', 'retrieved', '0B426829930B3A7CBEFDE7D518DD53DE20F99F99613AF362F800B13655090F2C', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p43-9', 'doc-04-nist-sp-800-86', '', 43, 'Manually extracting data from unused space can be a time-consuming and difficult process, because it requires knowledge of the underlying filesystem format.', 'kb-doc-04-nist-sp-800-86-p43-9', 0, 22, '04-nist-sp-800-86', 'retrieved', '56282EDFAFC7EA61BED0FE411AD2E6ACCA77A542B00C457E6A921EFF5A217FB2', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p43-10', 'doc-04-nist-sp-800-86', '', 43, 'Fortunately, several tools are available that can automate the process of extracting data from unused space and saving it to data files, as well as recovering deleted files and files within a recycling bin.', 'kb-doc-04-nist-sp-800-86-p43-10', 0, 34, '04-nist-sp-800-86', 'retrieved', '79822B8B1029E4D8AD2BF9CB3291BA896ED547A15D500568AAACC7A8BF180C6D', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p43-11', 'doc-04-nist-sp-800-86', '', 43, 'Analysts can also display the contents of slack space with hex editors or special slack recovery tools.', 'kb-doc-04-nist-sp-800-86-p43-11', 0, 17, '04-nist-sp-800-86', 'retrieved', 'F9B29F210B85A2BF97AFFCF92016ABCB60D53576C0B4260BCCFC4D6FD6E27608', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p43-12', 'doc-04-nist-sp-800-86', '', 43, 'Extracting the Data The rest of the examination process involves extracting data from some or all of the files.', 'kb-doc-04-nist-sp-800-86-p43-12', 0, 19, '04-nist-sp-800-86', 'retrieved', '94E16104723DD633717ADA8592BAB880EBA9E177830BA2A1F862E0A7F9B3FE2D', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p43-13', 'doc-04-nist-sp-800-86', '', 43, 'To make sense of the contents of a file, an analyst needs to know what type of data the file contains.', 'kb-doc-04-nist-sp-800-86-p43-13', 0, 21, '04-nist-sp-800-86', 'retrieved', '569CD80D0B610F472874F68F674EA0334B9CB9AF95EC5D03C3B1ABE662F5D485', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p43-14', 'doc-04-nist-sp-800-86', '', 43, 'The intended purpose of file extensions is to denote the nature of the files contents; for example, a jpg extension indicates a graphic file, and an mp3 extension indicates a music file.', 'kb-doc-04-nist-sp-800-86-p43-14', 0, 32, '04-nist-sp-800-86', 'retrieved', '999629502186E0A345280909C902B6EAD895F18702419D812ABB597B49C3F9D2', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p43-15', 'doc-04-nist-sp-800-86', '', 43, 'However, users can assign any file extension to any type of file, such as naming a text file mysong.mp3 or omitting a file extension.', 'kb-doc-04-nist-sp-800-86-p43-15', 0, 24, '04-nist-sp-800-86', 'retrieved', '33A944DC5C44A11F2E370A1A09C91E1C9F01143A410B88D0052B21A58F14BD8B', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p43-18', 'doc-04-nist-sp-800-86', '', 43, 'Analysts can more accurately identify the type of data stored in many files by looking at their file headers.', 'kb-doc-04-nist-sp-800-86-p43-18', 0, 19, '04-nist-sp-800-86', 'retrieved', 'FD3F3FD073680D17500E1EAA1627C8436BE643508CEF66566E49EC3506E9BB12', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p43-19', 'doc-04-nist-sp-800-86', '', 43, 'A file header contains identifying information about a file and possibly metadata that provides information about the files contents.', 'kb-doc-04-nist-sp-800-86-p43-19', 0, 19, '04-nist-sp-800-86', 'retrieved', 'C8998FC0F3BF82EF6CDC5C235BD548B5F4A911CB4D2D3E24309D5F29758CA902', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p43-20', 'doc-04-nist-sp-800-86', '', 43, 'As shown in Figure 4-1, the file header contains a file signature that identifies the type of data that particular file contains.50 The example in Figure 4-1 has a file header of FF D8, which indicates that this is a JPEG file.', 'kb-doc-04-nist-sp-800-86-p43-20', 0, 42, '04-nist-sp-800-86', 'retrieved', '1CB77E5E25B22518DE426BAF96CAFFCAB6474811565B1A9A55AD2FDEBA03A25D', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p43-22', 'doc-04-nist-sp-800-86', '', 43, 'Another effective technique for identifying the type of data in a file is a simple histogram showing the distribution of ASCII values as a percentage of total characters in a file.', 'kb-doc-04-nist-sp-800-86-p43-22', 0, 31, '04-nist-sp-800-86', 'retrieved', 'B61B787A60BF34EB039E66E6DD2B2B9910DD3FB19F57154F603F264AC9B02364', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p43-23', 'doc-04-nist-sp-800-86', '', 43, 'For example, a spike in the space, a, and e lines generally indicates a text file, while consistency across the histogram indicates a compressed file.', 'kb-doc-04-nist-sp-800-86-p43-23', 0, 25, '04-nist-sp-800-86', 'retrieved', '09D638B272A394356126FDB896CB6BF5F2597FB322B1F6A3B016C3611FA4B871', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p43-24', 'doc-04-nist-sp-800-86', '', 43, 'Other patterns are indicative of files that are encrypted or that were modified through steganography.', 'kb-doc-04-nist-sp-800-86-p43-24', 0, 15, '04-nist-sp-800-86', 'retrieved', '43ECAB017B0F39C3786768D3C825EA810D4E16BE3350B05DA908048CF07E52BB', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p43-26', 'doc-04-nist-sp-800-86', '', 43, 'Attackers can alter file headers using a hex editor to conceal the actual file type, and then alter the file header back to use the file.', 'kb-doc-04-nist-sp-800-86-p43-26', 0, 26, '04-nist-sp-800-86', 'retrieved', '5FA2BE36C2ABE6467ECD1D16D345CF142D2856A4D6A0BAEE7B6A349337982AE1', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p44-4', 'doc-04-nist-sp-800-86', '', 44, 'Users might encrypt individual files, folders, volumes, or partitions so that others cannot access their contents without a decryption key or passphrase.51 The encryption might be performed by the OS or a third-party program.', 'kb-doc-04-nist-sp-800-86-p44-4', 0, 34, '04-nist-sp-800-86', 'retrieved', 'BB0F00EA30ACDD8B5E6B0FD7FC0C76DCFE54B314630A8121CCEABEBA9ACE07F8', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p44-5', 'doc-04-nist-sp-800-86', '', 44, 'Although it is relatively easy to identify an encrypted file, it is usually not so easy to decrypt it.', 'kb-doc-04-nist-sp-800-86-p44-5', 0, 19, '04-nist-sp-800-86', 'retrieved', 'DC2547A57DCD0B146AE4F81774F5F3EE75B9073E20969F3866139BDA88DF895C', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p44-6', 'doc-04-nist-sp-800-86', '', 44, 'The analyst might be able to identify the encryption method by examining the file header, identifying encryption programs installed on the system, or finding encryption keys (which are often stored on other media).', 'kb-doc-04-nist-sp-800-86-p44-6', 0, 33, '04-nist-sp-800-86', 'retrieved', '24D4B8D3C37BA680AA2D4A288A8801660500936CFFC0B4DA62A50A937EEBFB58', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p44-7', 'doc-04-nist-sp-800-86', '', 44, 'Once the encryption method is known, the analyst can better determine the feasibility of decrypting the file.', 'kb-doc-04-nist-sp-800-86-p44-7', 0, 17, '04-nist-sp-800-86', 'retrieved', '151346B8078637D5A2F6740C18DFB7BD26DB64B594B008ECD7B92B402746BC2A', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p44-8', 'doc-04-nist-sp-800-86', '', 44, 'In many cases, it is not possible to decrypt files because the encryption method is strong and the authentication (e.g., passphrase) used to perform decryption is unavailable.', 'kb-doc-04-nist-sp-800-86-p44-8', 0, 27, '04-nist-sp-800-86', 'retrieved', '776608C8C9890D6ADAC59223F45BFC4826522AA6EA42073A416108C5C38764BA', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p44-9', 'doc-04-nist-sp-800-86', '', 44, 'Although an analyst can detect the presence of encrypted data rather easily, the use of steganography is more difficult to detect.', 'kb-doc-04-nist-sp-800-86-p44-9', 0, 21, '04-nist-sp-800-86', 'retrieved', '4C0502580CD95727A2A9681F08A1BC9B560FF69FAED80C4E3A3B7441D938386C', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p44-11', 'doc-04-nist-sp-800-86', '', 44, 'Digital watermarks and the hiding of words and information within images are examples of steganography.', 'kb-doc-04-nist-sp-800-86-p44-11', 0, 15, '04-nist-sp-800-86', 'retrieved', '35FE32AF51192938972BB47BABA2BB33DF6BC7D1D56ECB83D2F79589CE380A25', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p44-12', 'doc-04-nist-sp-800-86', '', 44, 'Some techniques an analyst can use to locate stegged data include looking for multiple versions of the same image, identifying the presence of grayscale images, searching metadata and registries, using histograms, and using hash sets to search for known steganography software.', 'kb-doc-04-nist-sp-800-86-p44-12', 0, 41, '04-nist-sp-800-86', 'retrieved', '43B9C602AF3C78A502D146AB2B2B26C1EDBBCAB9BD4F95366AE727DDB194E3AC', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p44-13', 'doc-04-nist-sp-800-86', '', 44, 'Once certain that stegged data exists, analysts might be able to extract the embedded data by determining what software created the data and then finding the stego key, or by using brute force and cryptographic attacks to determine a password.52 However, such efforts are often unsuccessful and can be extremely time- consuming, particularly if the analyst does not find the presence of known steganography software on the media being reviewed.', 'kb-doc-04-nist-sp-800-86-p44-13', 0, 70, '04-nist-sp-800-86', 'retrieved', 'E095C525BF9985A04ED9B4DA1428FC191EE0356A1D5B3BAA9276FFD92B7A1725', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p44-14', 'doc-04-nist-sp-800-86', '', 44, 'In addition, some software programs can analyze files and estimate the probability that the files were altered with steganography.', 'kb-doc-04-nist-sp-800-86-p44-14', 0, 19, '04-nist-sp-800-86', 'retrieved', 'A6FF93C276F779BA610350D18BF44DDBDD5A9AE2884F24DB3C5BC1D487950986', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p44-15', 'doc-04-nist-sp-800-86', '', 44, 'Analysts may also need to access non-stegged files that are protected by passwords.', 'kb-doc-04-nist-sp-800-86-p44-15', 0, 13, '04-nist-sp-800-86', 'retrieved', '30DDE2F360D1F01B19F3FB5B63A07E67F8008D6186B9072BDB049F424F552AE1', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p44-16', 'doc-04-nist-sp-800-86', '', 44, 'Passwords are often stored on the same system as the files they protect, but in an encoded or encrypted format.', 'kb-doc-04-nist-sp-800-86-p44-16', 0, 20, '04-nist-sp-800-86', 'retrieved', '2294B2E7E848D1766F2495CEE350A184846C53A5BB1C97B95FE1EE78C601EAFB', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p44-17', 'doc-04-nist-sp-800-86', '', 44, 'Various utilities are available that can crack passwords placed on individual files, as well as OS passwords.53 Most cracking utilities can attempt to guess passwords, as well as performing brute force attempts that try every possible password.', 'kb-doc-04-nist-sp-800-86-p44-17', 0, 37, '04-nist-sp-800-86', 'retrieved', '8D86741A2027E8517352B18E869843F3AC8D146A3BC24D8F1EB2FB7ACC1FFCC4', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p44-18', 'doc-04-nist-sp-800-86', '', 44, 'The time needed for a brute force attack on an encoded or encrypted password can vary greatly, depending on the type of encryption used and the sophistication of the password itself.', 'kb-doc-04-nist-sp-800-86-p44-18', 0, 31, '04-nist-sp-800-86', 'retrieved', 'F96F0639CEFA1E471C1BBC8901EB846342930DE4E639ABAF4A08EE5CD3FE4526', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p44-20', 'doc-04-nist-sp-800-86', '', 44, 'For example, an analyst could boot a system and disable its screensaver password, or bypass a Basic Input/Output System (BIOS) password by pulling the BIOS', 'kb-doc-04-nist-sp-800-86-p44-20', 0, 25, '04-nist-sp-800-86', 'retrieved', '3BB933B082617EDE1F88B75ECBE9AFD2DF93086D671A01A97EF574A31DC6119E', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p44-21', 'doc-04-nist-sp-800-86', '', 44, '51 Although volumes and partitions can be encrypted on some operating systems, this is not common due to corruption and other functional problems that may result in a complete loss of data if only a sector of data is corrupted.', 'kb-doc-04-nist-sp-800-86-p44-21', 0, 40, '04-nist-sp-800-86', 'retrieved', 'F3CB300AB0115B170499E858E619AE9B955B13CB720B2B378CB98FE0699AE90B', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p44-22', 'doc-04-nist-sp-800-86', '', 44, 'Encryption of individual files and folders is far more common, and is supported by many newer operating systems.', 'kb-doc-04-nist-sp-800-86-p44-22', 0, 18, '04-nist-sp-800-86', 'retrieved', '4E49AE93CB0E528BF2026C204E7924A863AB2A2A181EE217D695C21CBA241406', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p44-23', 'doc-04-nist-sp-800-86', '', 44, '52 Further discussion regarding steganography is outside the scope of this document.', 'kb-doc-04-nist-sp-800-86-p44-23', 0, 12, '04-nist-sp-800-86', 'retrieved', 'E105FFB0D4F4ADF00087E4076000FA6C48DF33448DF52008B6C0F75DEECB68AC', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p44-24', 'doc-04-nist-sp-800-86', '', 44, 'For more information, see the article An Overview of Steganography for the Computer Forensics Examiner by Gary Kessler, available at http://www.fbi.gov/hq/lab/fsc/backissu/july2004/research/2004_03_research01.htm.', 'kb-doc-04-nist-sp-800-86-p44-24', 0, 21, '04-nist-sp-800-86', 'retrieved', 'D0F34DDE82DD1D16A7B138BB67EF1C3F54B124F969C2318A5A7DCCAC107A5EE8', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p44-25', 'doc-04-nist-sp-800-86', '', 44, '53 An example of an open source password cracking utility is John the Ripper, which supports multiple OSs and file types.', 'kb-doc-04-nist-sp-800-86-p44-25', 0, 21, '04-nist-sp-800-86', 'retrieved', '82DE1AA37F6B013F582BF6539BDE6A7014FD9C66739618B0F97D392551A1E9B9', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p44-26', 'doc-04-nist-sp-800-86', '', 44, 'Additional password cracking utilities are listed on several Web sites listed in Appendix F, including Computer Forensics Tools (http://www.forensix.org/tools/) and The Ultimate Collection of Forensic Software (TUCOFS) (http://www.tucofs.com/tucofs.htm).', 'kb-doc-04-nist-sp-800-86-p44-26', 0, 28, '04-nist-sp-800-86', 'retrieved', '0828BB78A820719EEF1A613F2155A7C749E430FFB13F2675424B87E15AE02046', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p45-1', 'doc-04-nist-sp-800-86', '', 45, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE jumper from the systems motherboard or using a manufacturers backdoor password.54 Of course, bypassing a password might mean rebooting the system, which might be undesirable.', 'kb-doc-04-nist-sp-800-86-p45-1', 0, 33, '04-nist-sp-800-86', 'retrieved', '040068AB59BCFEA85A2D72126FF4614838700FC76D3A8F3C12D1D83D833264AA', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p45-2', 'doc-04-nist-sp-800-86', '', 45, 'Another possibility is to attempt to capture the password through network or host-based controls (e.g., packet sniffer, keystroke logger), with proper management and legal approval.', 'kb-doc-04-nist-sp-800-86-p45-2', 0, 25, '04-nist-sp-800-86', 'retrieved', '1388C31E277487BBDDADDEEEB3965BE686C13365CA137269DB7E986DC2C25366', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p45-3', 'doc-04-nist-sp-800-86', '', 45, 'If a boot-up password has been set on a hard drive, it might be possible to guess it (i.e., a default password from a vendor) or to circumvent it with specialized hardware and software.', 'kb-doc-04-nist-sp-800-86-p45-3', 0, 34, '04-nist-sp-800-86', 'retrieved', '68B6D9DD38A30C8FEE9338FE9DB58279C743E50FFD22A55F56890532DBB8552E', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p45-5', 'doc-04-nist-sp-800-86', '', 45, 'Using a Forensic Toolkit Analysts should have access to various tools that enable them to perform examinations and analysis of data, as well as some collection activities.', 'kb-doc-04-nist-sp-800-86-p45-5', 0, 27, '04-nist-sp-800-86', 'retrieved', '7150F346DD6AD1A499CAF0322AF01DEB597C12AE537E409F8E4F2F1DB1889441', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
