INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p45-6', 'doc-04-nist-sp-800-86', '', 45, 'Many forensic products allow the analyst to perform a wide range of processes to analyze files and applications, as well as collecting files, reading disk images, and extracting data from files.', 'kb-doc-04-nist-sp-800-86-p45-6', 0, 31, '04-nist-sp-800-86', 'retrieved', 'B1A7C2CEC593A85F1B85BEF4D4F5FEB86DB4710171013558DCDA187E66C80009', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p45-7', 'doc-04-nist-sp-800-86', '', 45, 'Most analysis products also offer the ability to generate reports and to log all errors that occurred during the analysis.', 'kb-doc-04-nist-sp-800-86-p45-7', 0, 20, '04-nist-sp-800-86', 'retrieved', 'EAAC65EED78B34F1A375A177F5BFC5D24055BA8D6937792485F23B90B486958A', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
