INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p45-8', 'doc-04-nist-sp-800-86', '', 45, 'Although these products are invaluable in performing analysis, it is critical to understand which processes should be run to answer particular questions about the data.', 'kb-doc-04-nist-sp-800-86-p45-8', 0, 25, '04-nist-sp-800-86', 'retrieved', 'C0B54A2C8FB025F022AC988134622ECDCF60942BE6F34D20D5C80E074DDE9D77', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p45-9', 'doc-04-nist-sp-800-86', '', 45, 'An analyst may need to provide a quick response or just answer a simple question about the collected data.', 'kb-doc-04-nist-sp-800-86-p45-9', 0, 19, '04-nist-sp-800-86', 'retrieved', 'BA6D18361918D3050780FD4E701CEE5493DCD3798C21CB866CFB589C2C78583F', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p45-10', 'doc-04-nist-sp-800-86', '', 45, 'In these cases, a complete forensic evaluation may not be necessary or even feasible.', 'kb-doc-04-nist-sp-800-86-p45-10', 0, 14, '04-nist-sp-800-86', 'retrieved', '478E2610A23F1FB5F913A2C6D5A1F4053DC2A652FFD801687EF6E4D6B3A4F970', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
