INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p45-11', 'doc-04-nist-sp-800-86', '', 45, 'The forensic toolkit should contain applications that can accomplish data examination and analysis in many ways and can be run quickly and efficiently from floppy disks, CDs, or a forensic workstation.', 'kb-doc-04-nist-sp-800-86-p45-11', 0, 31, '04-nist-sp-800-86', 'retrieved', '5A45D00A5D9E0FBF4F8ED47034709B6F59797CC25CC2435BFF45E957021F5693', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p45-12', 'doc-04-nist-sp-800-86', '', 45, 'The following processes are among those that an analyst should be able to perform with a variety of tools: ! Using File Viewers.', 'kb-doc-04-nist-sp-800-86-p45-12', 0, 23, '04-nist-sp-800-86', 'retrieved', '676CFD063E071B94D65FD7AC1F542A54F16224E569AC12DD2D0F7F0CC23ECEFA', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p45-13', 'doc-04-nist-sp-800-86', '', 45, 'Using viewers instead of the original source applications to display the contents of certain types of files is an important technique for scanning or previewing data, and is more efficient because the analyst does not need native applications for viewing each type of file.', 'kb-doc-04-nist-sp-800-86-p45-13', 0, 44, '04-nist-sp-800-86', 'retrieved', '41AA719A8D38DB42C1D1A1A34CFDAFBDEBD05DD55CAB1957616A249EBF64F220', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p45-14', 'doc-04-nist-sp-800-86', '', 45, 'Various tools are available for viewing common types of files, and there are also specialized tools solely for viewing graphics.', 'kb-doc-04-nist-sp-800-86-p45-14', 0, 20, '04-nist-sp-800-86', 'retrieved', 'F69867F5586BEDB104CFB9B0A15399E4616C21C3C1D767CFD5BD895CB6982CB9', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p45-15', 'doc-04-nist-sp-800-86', '', 45, 'If available file viewers do not support a particular file format, the original source application should be used; if this is not available, then it may be necessary to research the files format and manually extract the data from the file.55 ! Uncompressing Files.', 'kb-doc-04-nist-sp-800-86-p45-15', 0, 44, '04-nist-sp-800-86', 'retrieved', 'DE91C46B393843E74E9AB43CC167CEA8D3EBBAA87FB251DD56306C13260F80EA', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p45-16', 'doc-04-nist-sp-800-86', '', 45, 'Compressed files may contain files with useful information, as well as other compressed files.', 'kb-doc-04-nist-sp-800-86-p45-16', 0, 14, '04-nist-sp-800-86', 'retrieved', 'ABA4AC7D190FE68BD390698DE296B6769ADAEABA3F81DC940B1A445A5341CDF5', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p45-17', 'doc-04-nist-sp-800-86', '', 45, 'Therefore, it is important that the analyst locate and extract compressed files.', 'kb-doc-04-nist-sp-800-86-p45-17', 0, 12, '04-nist-sp-800-86', 'retrieved', '48A1EDA1A472FAF1F40CBE838CD3B250911D947048D591A191BC1001FE17D673', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p45-18', 'doc-04-nist-sp-800-86', '', 45, 'Uncompressing files should be performed early in the forensic process to ensure that the contents of compressed files are included in searches and other actions.', 'kb-doc-04-nist-sp-800-86-p45-18', 0, 25, '04-nist-sp-800-86', 'retrieved', '724960CA631AC0EAB242B81E6DAE276B874A304102D7A86A67CBCB85E3F6522D', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p45-19', 'doc-04-nist-sp-800-86', '', 45, 'However, analysts should keep in mind that compressed files might contain malicious content, such as compression bombs, which are files that have been repeatedly compressed, typically dozens or hundreds of times.', 'kb-doc-04-nist-sp-800-86-p45-19', 0, 31, '04-nist-sp-800-86', 'retrieved', 'EEE23111D39230998B6FC605107487018FA6BC34191BBBB7CD615FA4BD722028', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p45-20', 'doc-04-nist-sp-800-86', '', 45, 'Compression bombs can cause examination tools to fail or consume considerable resources; they might also contain malware and other malicious payloads.', 'kb-doc-04-nist-sp-800-86-p45-20', 0, 21, '04-nist-sp-800-86', 'retrieved', '72CD1EEC9C066B46D6B611720E0B8165062EBD05D80AAB7CC51CACA689D2CEFF', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p45-21', 'doc-04-nist-sp-800-86', '', 45, 'Although there is no definite way to detect compression bombs before uncompressing a file, there are ways to minimize their impact.', 'kb-doc-04-nist-sp-800-86-p45-21', 0, 21, '04-nist-sp-800-86', 'retrieved', '0643B323CB7DDC58E3863284475B2E10981F727519E9A539379422B86E36BFCD', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p45-22', 'doc-04-nist-sp-800-86', '', 45, 'For instance, the examination system should use up-to-date antivirus software and should be standalone to limit the effects to just that system.', 'kb-doc-04-nist-sp-800-86-p45-22', 0, 22, '04-nist-sp-800-86', 'retrieved', 'FB8135F2978ADEC38C24D72F50AF7A1943D52CB2ABD0381A50186A2287575433', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p45-23', 'doc-04-nist-sp-800-86', '', 45, 'In addition, an image of the examination system should be created so that, if needed, the system can be restored.', 'kb-doc-04-nist-sp-800-86-p45-23', 0, 20, '04-nist-sp-800-86', 'retrieved', 'B60B5574C42E54884B094005EEB67498178AF31FC17025A8C9D8FB3A817B3A08', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p45-25', 'doc-04-nist-sp-800-86', '', 45, 'This practice makes it easier and faster for analysts to gather general information about the contents of media, such as the type of software installed and the likely technical aptitude of the user(s) who created the data.', 'kb-doc-04-nist-sp-800-86-p45-25', 0, 37, '04-nist-sp-800-86', 'retrieved', 'D9F95D2649024B3168CC90EA43DD0340C51F81FFA3F033E335B1A7AFA8193ECC', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p45-26', 'doc-04-nist-sp-800-86', '', 45, 'Most products can display Windows, Linux, and UNIX directory structures, whereas other products are specific to Macintosh directory structures.', 'kb-doc-04-nist-sp-800-86-p45-26', 0, 19, '04-nist-sp-800-86', 'retrieved', 'FB2A7A7D96AA46C9C515C492EC55340187A949E19A2BCC84288181C83AB9595E', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
