INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p45-27', 'doc-04-nist-sp-800-86', '', 45, '54 See the article How to Bypass BIOS Passwords (available at http://labmice.techtarget.com/articles/BIOS_hack.htm) for more information and examples of known BIOS backdoor passwords.', 'kb-doc-04-nist-sp-800-86-p45-27', 0, 22, '04-nist-sp-800-86', 'retrieved', 'F7D6BB8D09E138D50F9E8E380BA20E69928553C52A29E8DF59A131973481EB72', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
