VALUES ('doc-04-nist-sp-800-86-p45-28', 'doc-04-nist-sp-800-86', '', 45, '55 Web sites such as Wotsits Format (http://www.wotsit.org/) contain file format information for hundreds of file types.', 'kb-doc-04-nist-sp-800-86-p45-28', 0, 17, '04-nist-sp-800-86', 'retrieved', 'E44B6608873EDDCA25B1E71628DD14160594AFE7608D168D33290F460351975E', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
