VALUES ('doc-04-nist-sp-800-86-p46-1', 'doc-04-nist-sp-800-86', '', 46, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE ! Identifying Known Files.', 'kb-doc-04-nist-sp-800-86-p46-1', 0, 12, '04-nist-sp-800-86', 'retrieved', 'F85C9E0D37AC5496765B070BAF9D5589E16E0DDEBBD8466C94127B5D519CED67', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p46-2', 'doc-04-nist-sp-800-86', '', 46, 'The benefit of finding files of interest is obvious, but it is also often beneficial to eliminate unimportant files, such as known good OS and application files, from consideration.', 'kb-doc-04-nist-sp-800-86-p46-2', 0, 29, '04-nist-sp-800-86', 'retrieved', '21E3A208750C30DDAA4E908221E59C15C3A25987FDB888D329B5C70A50A51BE6', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p46-3', 'doc-04-nist-sp-800-86', '', 46, 'Analysts should use validated hash sets, such as those created by NISTs National Software Reference Library (NSRL) project56 or personally created hash sets57 that have been validated, as a basis for identifying known benign and malicious files.', 'kb-doc-04-nist-sp-800-86-p46-3', 0, 37, '04-nist-sp-800-86', 'retrieved', '26330399FB89EBF58E7CC714EFCD62EE0CB44FF06D2696FAFDA6DE78A7B6BB39', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
