VALUES ('doc-04-nist-sp-800-86-p46-6', 'doc-04-nist-sp-800-86', '', 46, 'String searches aid in perusing large amounts of data to find key words or strings.', 'kb-doc-04-nist-sp-800-86-p46-6', 0, 15, '04-nist-sp-800-86', 'retrieved', 'E94D8F3BD7AC76D50DEDE77937210CD13CD1EFCB1D03A15079325A707F4F2486', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
