VALUES ('doc-04-nist-sp-800-86-p46-7', 'doc-04-nist-sp-800-86', '', 46, 'Various searching tools are available that can use Boolean, fuzzy logic, synonyms and concepts, stemming, and other search methods.', 'kb-doc-04-nist-sp-800-86-p46-7', 0, 19, '04-nist-sp-800-86', 'retrieved', '0FEC6E1F8580BB26A4108C34820B77BD3B9439E277569C93D258A1F324E74232', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
