VALUES ('doc-04-nist-sp-800-86-p46-8', 'doc-04-nist-sp-800-86', '', 46, 'Examples of common searches include searching for multiple words in a single file and searching for misspelled versions of certain words.', 'kb-doc-04-nist-sp-800-86-p46-8', 0, 21, '04-nist-sp-800-86', 'retrieved', '452A04D6E13C7A5D6C9F39E2055845728370A078C0C3F41881DEFF19982754B2', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
