VALUES ('doc-04-nist-sp-800-86-p46-9', 'doc-04-nist-sp-800-86', '', 46, 'Developing concise sets of search terms for common situations can help the analyst reduce the volume of information to review.', 'kb-doc-04-nist-sp-800-86-p46-9', 0, 20, '04-nist-sp-800-86', 'retrieved', 'F227D84B99D121CE1C6A04E26FD769D0CF8A02A2CE48EED90064B38B2D1BD2F4', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
