VALUES ('doc-04-nist-sp-800-86-p46-10', 'doc-04-nist-sp-800-86', '', 46, 'Some considerations or possible difficulties in performing string searches are as follows:  Some proprietary file formats cannot be string searched without additional tools.', 'kb-doc-04-nist-sp-800-86-p46-10', 0, 24, '04-nist-sp-800-86', 'retrieved', '15D8D6A265F347CB4E884D282AA3325EC8A144F0C6F04A9145BAE13E9142B43B', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p46-11', 'doc-04-nist-sp-800-86', '', 46, 'In addition, compressed, encrypted, and password-protected files require additional pre-processing before a string search.', 'kb-doc-04-nist-sp-800-86-p46-11', 0, 14, '04-nist-sp-800-86', 'retrieved', '9644D5C072E8B6522D2B7601BA0C552500EEE13C9F267F379CC30B9972F467E5', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
