INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p46-12', 'doc-04-nist-sp-800-86', '', 46, ' The use of multi-character data sets that include foreign or Unicode characters can cause problems with string searches; some searching tools attempt to overcome this by providing language translation functions.', 'kb-doc-04-nist-sp-800-86-p46-12', 0, 31, '04-nist-sp-800-86', 'retrieved', '6ED651A248307010AB5272883F206CBC5DFF26C958DE1782DD89A058F00A55D1', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
