INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p46-13', 'doc-04-nist-sp-800-86', '', 46, ' Another possible issue is the inherent limitations of the search tool or algorithm.', 'kb-doc-04-nist-sp-800-86-p46-13', 0, 14, '04-nist-sp-800-86', 'retrieved', 'AE2B96278BD4CB8DD65640012B751883FE9D85BC67A21D487D841C4107AECEF3', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
