INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p46-14', 'doc-04-nist-sp-800-86', '', 46, 'For example, a match might not be found for a search string if part of the string resided in one cluster and the rest of the string resided in a nonadjacent cluster.', 'kb-doc-04-nist-sp-800-86-p46-14', 0, 32, '04-nist-sp-800-86', 'retrieved', 'DAAF231D79B9C2E23A8F3A9A09941E3BD71ED6580FB84B28801330F3D9946DAD', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p46-15', 'doc-04-nist-sp-800-86', '', 46, 'Similarly, some search tools might report a false match if part of a search string resided in one cluster and the remainder of the string resided in another cluster that was not part of the same file that contained the first cluster.', 'kb-doc-04-nist-sp-800-86-p46-15', 0, 42, '04-nist-sp-800-86', 'retrieved', '4CCA67A5F12BF5334A13CE9B2411BFA07E8EC00E6713AF3B4EEA30E8FDB44939', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p46-18', 'doc-04-nist-sp-800-86', '', 46, 'For example, collecting the metadata on a graphic file might provide the graphics creation date, copyright information, and description, and the creators identity.58 Metadata for graphics generated by a digital camera might include the make and model of the digital camera used to take the image, as well as F-stop, flash, and aperture settings.', 'kb-doc-04-nist-sp-800-86-p46-18', 0, 54, '04-nist-sp-800-86', 'retrieved', '7C1975D1627AD637D1FE547F9B7F52746FCC06AF9DABA3AB9432519C94087818', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p46-19', 'doc-04-nist-sp-800-86', '', 46, 'For word processing files, metadata could specify the author, the organization that licensed the software, when and by whom edits were last performed, and user-defined comments.', 'kb-doc-04-nist-sp-800-86-p46-19', 0, 26, '04-nist-sp-800-86', 'retrieved', 'BA6CAAB359986A079E3B9AE50482517A429C40B7D2061F785F45E3037C1C7202', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
