VALUES ('doc-04-nist-sp-800-86-p46-21', 'doc-04-nist-sp-800-86', '', 46, '4.4 A nalysis After the examination has been completed, the next step is to perform analysis of the extracted data.', 'kb-doc-04-nist-sp-800-86-p46-21', 0, 20, '04-nist-sp-800-86', 'retrieved', '85C2452722755C9BF5C5006D4A41555EDE35BEA2692C0AC76844C2A9803A0FE1', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
