VALUES ('doc-04-nist-sp-800-86-p46-22', 'doc-04-nist-sp-800-86', '', 46, 'As mentioned in Section 4.3.3, there are many tools available that can be helpful in analysis of different types of data.', 'kb-doc-04-nist-sp-800-86-p46-22', 0, 21, '04-nist-sp-800-86', 'retrieved', '1175030A2C9A323D5B68C957DD8707E52C3D1A81862A223972BAD5ADA721AEDE', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
