VALUES ('doc-04-nist-sp-800-86-p46-23', 'doc-04-nist-sp-800-86', '', 46, 'When using these tools or performing manual reviews of data, analysts should be aware of the value of using system times and file times.', 'kb-doc-04-nist-sp-800-86-p46-23', 0, 24, '04-nist-sp-800-86', 'retrieved', 'B586F60177F5622BBCB4089D3602233D90EBBA998BD5A64A940E89D91CE5D573', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
