VALUES ('doc-04-nist-sp-800-86-p46-24', 'doc-04-nist-sp-800-86', '', 46, 'Knowing when an incident occurred, a file was created or modified, or an e-mail was sent can be critical to forensic analysis.', 'kb-doc-04-nist-sp-800-86-p46-24', 0, 22, '04-nist-sp-800-86', 'retrieved', '201E9C6EDCB8762988B35112D3DC880E8249E045624E1F5F21CECF0F73CA95C5', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
