VALUES ('doc-04-nist-sp-800-86-p46-25', 'doc-04-nist-sp-800-86', '', 46, 'For example, such information can be used to reconstruct a timeline of activities.', 'kb-doc-04-nist-sp-800-86-p46-25', 0, 13, '04-nist-sp-800-86', 'retrieved', 'DC4598EDFCE422A7734F4108AE610FB4B0DFCC68FF20CC07B17E99EE30295C30', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
