INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p46-29', 'doc-04-nist-sp-800-86', '', 46, 'Analysts should rely on standard hash sets such as those from the NSRL project whenever possible, and create custom hash sets primarily for organization-specific files.', 'kb-doc-04-nist-sp-800-86-p46-29', 0, 25, '04-nist-sp-800-86', 'retrieved', 'EAEA9BFCA7E4348A330BD5E6314C5F9352764B382256DACD6555D76CC53D0C6D', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
