VALUES ('doc-04-nist-sp-800-86-p46-30', 'doc-04-nist-sp-800-86', '', 46, '58 Only certain types of graphics files include metadata; for example, JPEG-format graphics might have metadata, but bitmap- format graphics cannot.', 'kb-doc-04-nist-sp-800-86-p46-30', 0, 21, '04-nist-sp-800-86', 'retrieved', '04FCBE0A50FED3B9D06C771C851194AAB6DC655DF99E89D9F62BCDA60C929B05', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
