VALUES ('doc-04-nist-sp-800-86-p47-1', 'doc-04-nist-sp-800-86', '', 47, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE complicated by unintentional or intentional discrepancies in time settings among systems.', 'kb-doc-04-nist-sp-800-86-p47-1', 0, 19, '04-nist-sp-800-86', 'retrieved', '51C2B59609C935D2163DBB5015624661A6EAFFA21526B54035E1C0C8005ABB75', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
