VALUES ('doc-04-nist-sp-800-86-p47-2', 'doc-04-nist-sp-800-86', '', 47, 'Knowing the time, date, and time zone settings for a computer whose data will be analyzed can greatly assist an analyst; Section 5 describes this in more detail.', 'kb-doc-04-nist-sp-800-86-p47-2', 0, 28, '04-nist-sp-800-86', 'retrieved', 'EA0749F47F7E6087B336DF8E512B58890E115567789FA604B11806E355A76E95', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
