VALUES ('doc-04-nist-sp-800-86-p47-3', 'doc-04-nist-sp-800-86', '', 47, 'It is usually beneficial to analysts if an organization maintains its systems with accurate timestamping.', 'kb-doc-04-nist-sp-800-86-p47-3', 0, 15, '04-nist-sp-800-86', 'retrieved', 'DEDC22E9EF22CD607EFBFF2249C08CCA1501FD00C894FFA8F743FD4ECFDB0CEB', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
