INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p47-4', 'doc-04-nist-sp-800-86', '', 47, 'The Network Time Protocol (NTP) synchronizes the time on a computer with an atomic clock run by NIST or other organizations.', 'kb-doc-04-nist-sp-800-86-p47-4', 0, 21, '04-nist-sp-800-86', 'retrieved', '8E5642842D6DFBDED8EFBB6E662B33BE4AC2A116ED275C0198E5F551FEF618A2', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p47-5', 'doc-04-nist-sp-800-86', '', 47, 'Synchronization helps ensure that each system maintains a reasonably accurate measurement of time.', 'kb-doc-04-nist-sp-800-86-p47-5', 0, 13, '04-nist-sp-800-86', 'retrieved', '6890C356D727EC11077DB026A49E6623845ED9A0595F77970D36A091392FB6EB', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p47-6', 'doc-04-nist-sp-800-86', '', 47, 'If multiple tools are used to complete an examination and analysis, the analyst should understand how each tool extracts, modifies, and displays file modification, access, and creation (MAC) times.', 'kb-doc-04-nist-sp-800-86-p47-6', 0, 29, '04-nist-sp-800-86', 'retrieved', '25E5B7F17AB6E649EDD6B60632C7C4DF5D9BD1B0608013F243510A51383B0F30', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p47-7', 'doc-04-nist-sp-800-86', '', 47, 'For instance, some tools modify the last access time of a file or directory if the filesystem has been mounted with write permissions by the OS.', 'kb-doc-04-nist-sp-800-86-p47-7', 0, 26, '04-nist-sp-800-86', 'retrieved', '0AD7A8A716532BA1D7C6AD32C168E6EC54BCB1BF8D070AB76E43D9C9CDBEDFF0', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p47-8', 'doc-04-nist-sp-800-86', '', 47, 'Write-blockers can be used to prevent these tools from modifying the MAC times; however, although write-blockers can prevent these times from being modified on the media, they cannot prevent the OS from caching the changes in memory (i.e., storing the changes in random access memory [RAM]).', 'kb-doc-04-nist-sp-800-86-p47-8', 0, 46, '04-nist-sp-800-86', 'retrieved', '620B9F2F6F240A30E991B92DF82B568236EFAB365FDE276BA6E10AE32C5084F5', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p47-9', 'doc-04-nist-sp-800-86', '', 47, 'The OS might then report the cached MAC times rather than the actual times, thereby returning inaccurate results.', 'kb-doc-04-nist-sp-800-86-p47-9', 0, 18, '04-nist-sp-800-86', 'retrieved', '5786DBC4C6DF620D34EC2B4D2AC76B891A3EE2A0003020858DC26316E61ECF94', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p47-10', 'doc-04-nist-sp-800-86', '', 47, 'The analyst should be aware that the last access time for data files and directories might change between queries, depending on the tool used to perform the query.', 'kb-doc-04-nist-sp-800-86-p47-10', 0, 28, '04-nist-sp-800-86', 'retrieved', 'DBF3C9A647258824D034BCD7F00E24D8A47799FCAF016F7761F3830C6FD59125', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p47-11', 'doc-04-nist-sp-800-86', '', 47, 'Because of these issues, analysts should take care in choosing a MAC viewing method and record the details of that method.', 'kb-doc-04-nist-sp-800-86-p47-11', 0, 21, '04-nist-sp-800-86', 'retrieved', '63AAE5942D42DA8E4EF3309A225BBAAF6C39350792DC295ABE43B0543BDB38B4', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p47-12', 'doc-04-nist-sp-800-86', '', 47, 'Analysts can use special tools that can generate forensic timelines based on event data.', 'kb-doc-04-nist-sp-800-86-p47-12', 0, 14, '04-nist-sp-800-86', 'retrieved', '00F705882DC469EB5858618C5DFE8AA5DC8DCBD9D30EFE15E229BD4F4F627F22', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
