VALUES ('doc-04-nist-sp-800-86-p47-13', 'doc-04-nist-sp-800-86', '', 47, 'Such tools typically give analysts a graphical interface for viewing and analyzing sequences of events.', 'kb-doc-04-nist-sp-800-86-p47-13', 0, 15, '04-nist-sp-800-86', 'retrieved', '4238C7D2CA140D0EDE911567B1D5B877030E83749FAFEA5984DEFE16272B5D67', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
