INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p47-14', 'doc-04-nist-sp-800-86', '', 47, 'A common feature of these tools is to permit analysts to group related events into meta-events.', 'kb-doc-04-nist-sp-800-86-p47-14', 0, 16, '04-nist-sp-800-86', 'retrieved', '96ADF4107B1E485D9D959115F79C0114E09825F44A655C7433E24032A3CBD73E', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
