INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p47-16', 'doc-04-nist-sp-800-86', '', 47, 'In many cases, forensic analysis involves not only data from files, but also data from other sources, such as the OS state, network traffic, or applications.', 'kb-doc-04-nist-sp-800-86-p47-16', 0, 26, '04-nist-sp-800-86', 'retrieved', 'B0B3995B67ACC54E0BCC7FB4A66459521092B699F0D61C01332E5D35B2EFF2E0', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p47-17', 'doc-04-nist-sp-800-86', '', 47, 'Section 8 provides examples of how data from files and data from other sources can be correlated through analysis.', 'kb-doc-04-nist-sp-800-86-p47-17', 0, 19, '04-nist-sp-800-86', 'retrieved', '7D7F3B13CA006989253D31E12BF145F705878477FE7737BCFFD1A6E13FDC9732', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
