INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p47-18', 'doc-04-nist-sp-800-86', '', 47, '4.5 Re commendations The key recommendations presented in this section for using data from data files are as follows.', 'kb-doc-04-nist-sp-800-86-p47-18', 0, 19, '04-nist-sp-800-86', 'retrieved', '7424844B2680301DE566E0EF8E83A69E3240FF0673FF3048B31504B8B72F27DC', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
