INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p47-20', 'doc-04-nist-sp-800-86', '', 47, 'During the collection phase, the analyst should make multiple copies of the desired files or filesystems, typically a master copy and a working copy.', 'kb-doc-04-nist-sp-800-86-p47-20', 0, 24, '04-nist-sp-800-86', 'retrieved', 'FA2D051D532A4A065C88CDFEBB2444F5E6AADDF361202C03B3A6A172858381D6', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p47-21', 'doc-04-nist-sp-800-86', '', 47, 'The analyst can then work with the working copy of the files without affecting the original files or the master copy.', 'kb-doc-04-nist-sp-800-86-p47-21', 0, 21, '04-nist-sp-800-86', 'retrieved', '3069334F38828C718A6FDCCB6E723AB435FF7897CA86C143409CA04831F05D10', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
