INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p47-22', 'doc-04-nist-sp-800-86', '', 47, 'A bit stream image should be performed if evidence may be needed for prosecution or disciplinary actions, or if preserving file times is important.', 'kb-doc-04-nist-sp-800-86-p47-22', 0, 24, '04-nist-sp-800-86', 'retrieved', '9BFD94DB6D2483EAF2EC3037184138D19FF34E679DCAA886DDAA0CC225700030', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
