INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p47-24', 'doc-04-nist-sp-800-86', '', 47, 'Using a write-blocker during backups and imaging prevents a computer from writing to its storage media.', 'kb-doc-04-nist-sp-800-86-p47-24', 0, 16, '04-nist-sp-800-86', 'retrieved', '98D8E7E100A26A0902E7913732F3C161DFC808E68B2A72EBE8EBA580F343628F', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p47-25', 'doc-04-nist-sp-800-86', '', 47, 'The integrity of copied data should be verified by computing and comparing the message digests of files.', 'kb-doc-04-nist-sp-800-86-p47-25', 0, 17, '04-nist-sp-800-86', 'retrieved', '6E96709282027095777DF47FFDD88D18DFDABF61560A8CA013866BB5B8AABE4C', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
