INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p47-26', 'doc-04-nist-sp-800-86', '', 47, 'Backups and images should be accessed as read-only whenever possible; write-blockers can also be used to prevent writes to the backup or image file or restored backup or image.', 'kb-doc-04-nist-sp-800-86-p47-26', 0, 29, '04-nist-sp-800-86', 'retrieved', '223D28C4A5E7F7E69EEF191323D2D45B9220434EFAD9C88D288C428A68785442', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
