INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p47-27', 'doc-04-nist-sp-800-86', '', 47, '! Analysts should rely on file headers, not file extensions, to identify file content types.', 'kb-doc-04-nist-sp-800-86-p47-27', 0, 15, '04-nist-sp-800-86', 'retrieved', '60AF2D72F2B68D4CE68DC80A814FF7E57445EC4DE6AA67363D248FFA091BA8DD', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p47-28', 'doc-04-nist-sp-800-86', '', 47, 'Because users can assign any file extension to a file, analysts should not assume that file extensions are accurate.', 'kb-doc-04-nist-sp-800-86-p47-28', 0, 19, '04-nist-sp-800-86', 'retrieved', 'CDB6D7664A5945F44D69D63438871F6A05C5418948867C4DC6319924C4271B15', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p47-29', 'doc-04-nist-sp-800-86', '', 47, 'Analysts can identify the type of data stored in many files by looking at their file headers.', 'kb-doc-04-nist-sp-800-86-p47-29', 0, 17, '04-nist-sp-800-86', 'retrieved', 'E46B248D5B93560F45D3392DDEF8BAED5E7D35777799A5EF3022B6743FF82F98', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p47-30', 'doc-04-nist-sp-800-86', '', 47, 'Although people can alter file headers to conceal actual file types, this is much less common than altering file extensions.', 'kb-doc-04-nist-sp-800-86-p47-30', 0, 20, '04-nist-sp-800-86', 'retrieved', '421D74EBC8F21BF3341A2E32530EB6E4F0DA800095F791586A52C39300AD6A58', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
