INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p48-2', 'doc-04-nist-sp-800-86', '', 48, 'The toolkit should contain various tools that provide the ability to perform quick reviews of data as well as in-depth analysis.', 'kb-doc-04-nist-sp-800-86-p48-2', 0, 21, '04-nist-sp-800-86', 'retrieved', '5E1D341BAE2254E7B0E91BB741BF8FD9CF2491DADFBE4153B229DF28A09420B3', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
