VALUES ('doc-04-nist-sp-800-86-p48-3', 'doc-04-nist-sp-800-86', '', 48, 'The toolkit should allow its applications to be run quickly and efficiently from removable media (e.g., floppy disk, CD) or a forensic workstation.', 'kb-doc-04-nist-sp-800-86-p48-3', 0, 23, '04-nist-sp-800-86', 'retrieved', '8BF88B12970A85B89B2F1A7D4FB9DE45972BE84A4406389DC29FC2929FC397F9', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
