INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p49-1', 'doc-04-nist-sp-800-86', '', 49, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE 5. Using Data from Operating Systems An operating system (OS) is a program that runs on a computer and provides a software platform on which other programs can run.', 'kb-doc-04-nist-sp-800-86-p49-1', 0, 37, '04-nist-sp-800-86', 'retrieved', '2003EAC2E82B1C3471931EEBC653E54D4320D7F01DBABA626B228C6E01CE905A', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p49-2', 'doc-04-nist-sp-800-86', '', 49, 'In addition, an OS is responsible for processing input commands from a user, sending output to a display, interacting with storage devices to store and retrieve data, and controlling peripheral devices such as printers and modems.', 'kb-doc-04-nist-sp-800-86-p49-2', 0, 36, '04-nist-sp-800-86', 'retrieved', 'CF1976EFE1DB91B2DC902E2967B61B24623C74BC6E14716724B629AEFB7220D5', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p49-3', 'doc-04-nist-sp-800-86', '', 49, 'Some common OSs for workstations or servers include various versions of Windows, Linux, UNIX, and Mac OS.', 'kb-doc-04-nist-sp-800-86-p49-3', 0, 17, '04-nist-sp-800-86', 'retrieved', '3F0BA8914530B24039D836E3C2488359214F732FA531E08F1174495B21CBD7A6', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p49-4', 'doc-04-nist-sp-800-86', '', 49, 'Some network devices, such as routers, have their own proprietary OSs (e.g., Cisco Internetwork Operating System [IOS]).', 'kb-doc-04-nist-sp-800-86-p49-4', 0, 17, '04-nist-sp-800-86', 'retrieved', '7E43EC00CDA61BCE990B6FEBFF9692A14177632D045CF5E9C9AAC3B61080D1C9', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p49-5', 'doc-04-nist-sp-800-86', '', 49, 'PDAs often run specialized OSs, including PalmOS and Windows CE.59 Many embedded systems, such as cellular phones, digital cameras, and audio players, also use OSs.60 This section discusses the components of an OS that might be relevant to forensics and provides guidance on collecting, examining, and analyzing data from common workstation and server OSs.61 5.1 O S Basics OS data exists in both non-volatile and volatile states.', 'kb-doc-04-nist-sp-800-86-p49-5', 0, 67, '04-nist-sp-800-86', 'retrieved', '7EB73E850819E66B1336B50E3427F3A58F5228854D9AD19EB492961D7E492EC1', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p49-6', 'doc-04-nist-sp-800-86', '', 49, 'Non-volatile data refers to data that persists even after a computer is powered down, such as a filesystem stored on a hard drive.', 'kb-doc-04-nist-sp-800-86-p49-6', 0, 23, '04-nist-sp-800-86', 'retrieved', 'A545DCBCE00A34C64776057A2E33DB8601970B057315B148D049D482051CD32B', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p49-7', 'doc-04-nist-sp-800-86', '', 49, 'Volatile data refers to data on a live system that is lost after a computer is powered down, such as the current network connections to and from the system.', 'kb-doc-04-nist-sp-800-86-p49-7', 0, 29, '04-nist-sp-800-86', 'retrieved', '64C1979026B562150A5F03B2AA48FA7E2C3FF0364F1C84D0A72929EC288917F5', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p49-8', 'doc-04-nist-sp-800-86', '', 49, 'Many types of non-volatile and volatile data may be of interest from a forensics perspective.', 'kb-doc-04-nist-sp-800-86-p49-8', 0, 15, '04-nist-sp-800-86', 'retrieved', 'E85C1BC0E509C4BAEA4415FBAB20B1EE3CB7DCD00A3410BF0AA34AB211991205', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p49-11', 'doc-04-nist-sp-800-86', '', 49, 'Non-Volatile Data The primary source of non-volatile data within an OS is the filesystem.62 The filesystem is also usually the largest and richest source of data within the OS, containing most of the information recovered during a typical forensic event.', 'kb-doc-04-nist-sp-800-86-p49-11', 0, 40, '04-nist-sp-800-86', 'retrieved', 'C67D3B285041CCAEABD12E391F56BCD185E71E099BAD88273C0230C1B6439925', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p49-12', 'doc-04-nist-sp-800-86', '', 49, 'The filesystem provides storage for the OS on one or more media.63 A filesystem typically contains many types of files, each of which may be of value to analysts in different situations.', 'kb-doc-04-nist-sp-800-86-p49-12', 0, 32, '04-nist-sp-800-86', 'retrieved', '70F99B5AFD808069ACBA09E5FFD3D0313EA7FDBB439B1C4D6A2F15413D53699B', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p49-13', 'doc-04-nist-sp-800-86', '', 49, 'In addition, as noted in Section 4.1.2, important residual data can be recovered from unused filesystem space.', 'kb-doc-04-nist-sp-800-86-p49-13', 0, 17, '04-nist-sp-800-86', 'retrieved', 'AA31016B10DAB470D619EF1F027E89E2EBBAB1DD92B1396AF9432C67BAEBA8DE', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p49-14', 'doc-04-nist-sp-800-86', '', 49, 'Several types of data that are commonly found within OS filesystems are as follows: ! Configuration Files.', 'kb-doc-04-nist-sp-800-86-p49-14', 0, 17, '04-nist-sp-800-86', 'retrieved', '1B08A57957ECFF4DE20C1E0BED0D49CA82B1F65DBE7577CECA6E7FBA0CAFF661', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p49-15', 'doc-04-nist-sp-800-86', '', 49, 'The OS may use configuration files to store OS and application settings.64 For example, configuration files could list the services to be started automatically after system boot, and specify the location of log files and temporary files.', 'kb-doc-04-nist-sp-800-86-p49-15', 0, 37, '04-nist-sp-800-86', 'retrieved', '073C86D8C2EE91382FB3DE1F6FA43DDD15937FFA58A1E7EA0DDCBEA073B75A48', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p49-16', 'doc-04-nist-sp-800-86', '', 49, 'Users might also have individual OS and application configuration files that contain user-specific information and preferences, such as hardware-related settings (e.g., screen resolution, printer settings) and file associations.', 'kb-doc-04-nist-sp-800-86-p49-16', 0, 28, '04-nist-sp-800-86', 'retrieved', 'DA2D09A6AD76BAA57D1AFCBD4752847795C67170B9F35A73B4B5E0EF8D2DD2E8', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p49-18', 'doc-04-nist-sp-800-86', '', 49, '59 For more information on PDA forensics, see NIST SP 800-72, Guidelines on PDA Forensics, available at http://csrc.nist.gov/publications/nistpubs/index.html.', 'kb-doc-04-nist-sp-800-86-p49-18', 0, 18, '04-nist-sp-800-86', 'retrieved', 'BECEBCE09AD67055ED6CF7260AD5C7A8644A55D1072E92016A88502A5AFBB22C', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p49-19', 'doc-04-nist-sp-800-86', '', 49, '60 A discussion of the types of information that can be found on these types of devices and the methods for collecting, examining, and analyzing the information is beyond the scope of this document.', 'kb-doc-04-nist-sp-800-86-p49-19', 0, 34, '04-nist-sp-800-86', 'retrieved', 'C704237D44C639618CB32AF498D12676BF5C5F06BE8944D2CA1A25EFEA0A832A', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p49-20', 'doc-04-nist-sp-800-86', '', 49, 'Because of the wide variety of devices and the knowledge and equipment needed in many cases to forensically process the data they contain, most organizations will find it best to secure such a device and transfer it to an appropriate party that is experienced in collecting, examining, and analyzing data from such devices (e.g., a law enforcement agency).', 'kb-doc-04-nist-sp-800-86-p49-20', 0, 58, '04-nist-sp-800-86', 'retrieved', '1D9FC24D9C1A0F5D7979111CCA247FF4235F5B930E83185513BB22EEA3602086', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p49-21', 'doc-04-nist-sp-800-86', '', 49, '61 Guidance specific to data from proprietary and specialized operating systems is beyond the scope of this document; however, many of the concepts described in this section should also apply to them.', 'kb-doc-04-nist-sp-800-86-p49-21', 0, 32, '04-nist-sp-800-86', 'retrieved', '7AFFD436AF1F5444592378899ADF787E405DA39E84856BE3DC2A5EA2D868F885', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p49-22', 'doc-04-nist-sp-800-86', '', 49, '62 This may not be true for some devices, such as consumer electronics that do not use standard filesystems.', 'kb-doc-04-nist-sp-800-86-p49-22', 0, 19, '04-nist-sp-800-86', 'retrieved', '59340A5F2C3BE4150954155A64990538D14D00220A77B4E6B12BDDD8D018A40E', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p49-24', 'doc-04-nist-sp-800-86', '', 49, 'The term memory filesystems refers to filesystems that reside only in a systems memory.', 'kb-doc-04-nist-sp-800-86-p49-24', 0, 14, '04-nist-sp-800-86', 'retrieved', 'FCEDC5FD546DB164F77CFAC9DD0B483EB8CA6EE467031E792E0FA5C2224637EE', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-04-nist-sp-800-86-p49-26', 'doc-04-nist-sp-800-86', '', 49, 'Filesystems, including an entire bootable OS implementation, may also reside on removable media such as flash drives.', 'kb-doc-04-nist-sp-800-86-p49-26', 0, 17, '04-nist-sp-800-86', 'retrieved', '5F02C83F6CBCA40E07C662C04FC98B26C8EE2A87E3C80D280D83F77675210AE8', 'v1', '{"source_id": "04-nist-sp-800-86", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
